(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("polybius-1-e", [{"sp": "HDR", "t": "Ἱστορίαι (Αʹ–Βʹ)"}, {"sp": "HDR", "t": "Βιβλίον Αʹ", "st": "1"}, {"sp": "N", "t": "εἰ μὲν τοῖς πρὸ ἡμῶν ἀναγράφουσι τὰς πράξεις παραλελεῖφθαι συνέβαινε τὸν ὑπὲρ αὐτῆς τῆς ἱστορίας ἔπαινον, ἴσως ἀναγκαῖον ἦν τὸ προτρέπεσθαι πάντας πρὸς τὴν αἵρεσιν καὶ παραδοχὴν τῶν τοιούτων ὑπομνημάτων διὰ τὸ μηδεμίαν ἑτοιμοτέραν εἶναι τοῖς ἀνθρώποις διόρθωσιν τῆς τῶν προγεγενημένων πράξεων ἐπιστήμης. ἐπεὶ δ’ οὐ τινὲς οὐδ’ ἐπὶ ποσόν, ἀλλὰ πάντες ὡς ἔπος εἰπεῖν ἀρχῇ καὶ τέλει κέχρηνται τούτῳ, φάσκοντες ἀληθινωτάτην μὲν εἶναι παιδείαν καὶ γυμνασίαν πρὸς τὰς πολιτικὰς πράξεις τὴν ἐκ τῆς ἱστορίας μάθησιν, ἐναργεστάτην δὲ καὶ μόνην διδάσκαλον τοῦ δύνασθαι τὰς τῆς τύχης μεταβολὰς γενναίως ὑποφέρειν τὴν τῶν ἀλλοτρίων περιπετειῶν ὑπόμνησιν, δῆλον ὡς οὐδενὶ μὲν ἂν δόξαι καθήκειν περὶ τῶν καλῶς καὶ πολλοῖς εἰρημένων ταυτολογεῖν, ἥκιστα δ’ ἡμῖν. αὐτὸ γὰρ τὸ παράδοξον τῶν πράξεων, ὑπὲρ ὧν προῃρήμεθα γράφειν, ἱκανόν ἐστι προκαλέσασθαι καὶ παρορμῆσαι πάντα καὶ νέον καὶ πρεσβύτερον πρὸς τὴν ἔντευξιν τῆς πραγματείας. τίς γὰρ οὕτως ὑπάρχει φαῦλος ἢ ῥᾴθυμος ἀνθρώπων ὃς οὐκ ἂν βούλοιτο γνῶναι πῶς καὶ τίνι γένει πολιτείας ἐπικρατηθέντα σχεδὸν ἅπαντα τὰ κατὰ τὴν οἰκουμένην οὐχ ὅλοις πεντήκοντα καὶ τρισὶν ἔτεσιν ὑπὸ μίαν ἀρχὴν ἔπεσε τὴν Ῥωμαίων, ὃ πρότερον οὐχ εὑρίσκεται γεγονός, τίς δὲ πάλιν οὕτως ἐκπαθὴς πρός τι τῶν ἄλλων θεαμάτων ἢ μαθημάτων ὃς προυργιαίτερον ἄν τι ποιήσαιτο τῆσδε τῆς ἐμπειρίας;", "st": "1.1"}, {"sp": "N", "t": "ὡς δ’ ἔστι παράδοξον καὶ μέγα τὸ περὶ τὴν ἡμετέραν ὑπόθεσιν θεώρημα γένοιτ’ ἂν οὕτως μάλιστ’ ἐμφανές, εἰ τὰς ἐλλογιμωτάτας τῶν προγεγενημένων δυναστειῶν, περὶ ἃς οἱ συγγραφεῖς τοὺς πλείστους διατέθεινται λόγους, παραβάλοιμεν καὶ συγκρίναιμεν πρὸς τὴν Ῥωμαίων ὑπεροχήν. εἰσὶ δ’ αἱ τῆς παραβολῆς ἄξιαι καὶ συγκρίσεως αὗται. Πέρσαι κατά τινας καιροὺς μεγάλην ἀρχὴν κατεκτήσαντο καὶ δυναστείαν· ἀλλ’ ὁσάκις ἐτόλμησαν ὑπερβῆναι τοὺς τῆς Ἀσίας ὅρους, οὐ μόνον ὑπὲρ τῆς ἀρχῆς, ἀλλὰ καὶ περὶ σφῶν ἐκινδύνευσαν. Λακεδαιμόνιοι πολλοὺς ἀμφισβητήσαντες χρόνους ὑπὲρ τῆς τῶν Ἑλλήνων ἡγεμονίας, ἐπειδή ποτ’ ἐκράτησαν, μόλις ἔτη δώδεκα κατεῖχον αὐτὴν ἀδήριτον. Μακεδόνες τῆς μὲν Εὐρώπης ἦρξαν ἀπὸ τῶν κατὰ τὸν Ἀδρίαν τόπων ἕως ἐπὶ τὸν Ἴστρον ποταμόν, ὃ βραχὺ παντελῶς ἂν φανείη μέρος τῆς προειρημένης χώρας· μετὰ δὲ ταῦτα προσέλαβον τὴν τῆς Ἀσίας ἀρχήν, καταλύσαντες τὴν τῶν Περσῶν δυναστείαν. ἀλλ’ ὅμως οὗτοι πλείστων δόξαντες καὶ τόπων καὶ πραγμάτων γενέσθαι κύριοι, τὸ πολὺ μέρος ἀκμὴν ἀπέλιπον τῆς οἰκουμένης ἀλλότριον. Σικελίας μὲν γὰρ καὶ Σαρδοῦς καὶ Λιβύης οὐδ’ ἐπεβάλοντο καθάπαξ ἀμφισβητεῖν, τῆς δ’ Εὐρώπης τὰ μαχιμώτατα γένη τῶν προσεσπερίων ἐθνῶν ἰσχνῶς εἰπεῖν οὐδ’ ἐγίνωσκον. Ῥωμαῖοί γε μὴν οὐ τινὰ μέρη, σχεδὸν δὲ πᾶσαν πεποιημένοι τὴν οἰκουμένην ὑπήκοον αὑτοῖς, ἀνυπόστατον μὲν τοῖς ὑπάρχουσι πᾶσιν, ἀνυπέρβλητον δὲ καὶ τοῖς ἐπιγινομένοις ὑπεροχὴν κατέλιπον τῆς αὑτῶν δυναστείας. περὶ δὲ τοῦ μεντολαδιατ … ἐκ τῆς γραφῆς ἐξέσται σαφέστερον κατανοεῖν· ὁμοίως δὲ καὶ περὶ τοῦ πόσα καὶ πηλίκα συμβάλλεσθαι πέφυκε τοῖς φιλομαθοῦσιν ὁ τῆς πραγματικῆς ἱστορίας τρόπος.", "st": "1.2"}, {"sp": "N", "t": "ἄρξει δὲ τῆς πραγματείας ἡμῖν τῶν μὲν χρόνων ὀλυμπιὰς ἑκατοστή τε καὶ τετταρακοστή, τῶν δὲ πράξεων παρὰ μὲν τοῖς Ἕλλησιν ὁ προσαγορευθεὶς συμμαχικὸς πόλεμος, ὃν πρῶτον ἐξήνεγκε μετ’ Ἀχαιῶν πρὸς Αἰτωλοὺς Φίλιππος, Δημητρίου μὲν υἱός, πατὴρ δὲ Περσέως, παρὰ δὲ τοῖς τὴν Ἀσίαν κατοικοῦσιν ὁ περὶ Κοίλης Συρίας, ὃν Ἀντίοχος καὶ Πτολεμαῖος ὁ Φιλοπάτωρ ἐπολέμησαν πρὸς ἀλλήλους· ἐν δὲ τοῖς κατὰ τὴν Ἰταλίαν καὶ Λιβύην τόποις ὁ συστὰς Ῥωμαίοις καὶ Καρχηδονίοις, ὃν οἱ πλεῖστοι προσαγορεύουσιν Ἀννιβιακόν. ταῦτα δ’ ἔστι συνεχῆ τοῖς τελευταίοις τῆς παρ’ Ἀράτου Σικυωνίου συντάξεως. ἐν μὲν οὖν τοῖς πρὸ τούτων χρόνοις ὡσανεὶ σποράδας εἶναι συνέβαινε τὰς τῆς οἰκουμένης πράξεις διὰ τὸ καὶ κατὰ τὰς ἐπιβολάς, ἔτι δὲ καὶ τὰς συντελείας αὐτῶν ὁμοίως δὲ καὶ κατὰ τοὺς τόπους διαφέρειν ἕκαστα τῶν πεπραγμένων. ἀπὸ δὲ τούτων τῶν καιρῶν οἱονεὶ σωματοειδῆ συμβαίνει γίνεσθαι τὴν ἱστορίαν, συμπλέκεσθαί τε τὰς Ἰταλικὰς καὶ Λιβυκὰς πράξεις ταῖς τε κατὰ τὴν Ἀσίαν καὶ ταῖς Ἑλληνικαῖς καὶ πρὸς ἓν γίνεσθαι τέλος τὴν ἀναφορὰν ἁπάντων. διὸ καὶ τὴν ἀρχὴν τῆς αὑτῶν πραγματείας ἀπὸ τούτων πεποιήμεθα τῶν καιρῶν. τῷ γὰρ προειρημένῳ πολέμῳ κρατήσαντες Ῥωμαῖοι Καρχηδονίων καὶ νομίσαντες τὸ κυριώτατον καὶ μέγιστον μέρος αὑτοῖς ἠνύσθαι πρὸς τὴν τῶν ὅλων ἐπιβολήν, οὕτως καὶ τότε πρῶτον ἐθάρσησαν ἐπὶ τὰ λοιπὰ τὰς χεῖρας ἐκτείνειν καὶ περαιοῦσθαι μετὰ δυνάμεως εἴς τε τὴν Ἑλλάδα καὶ τοὺς κατὰ τὴν Ἀσίαν τόπους. εἰ μὲν οὖν ἡμῖν ἦν συνήθη καὶ γνώριμα τὰ πολιτεύματα τὰ περὶ τῆς τῶν ὅλων ἀρχῆς ἀμφισβητήσαντα, ἴσως οὐδὲν ἂν ἡμᾶς ἔδει περὶ τῶν πρὸ τοῦ γράφειν ἀπὸ ποίας προθέσεως ἢ δυνάμεως ὁρμηθέντες ἐνεχείρησαν τοῖς τοιούτοις καὶ τηλικούτοις ἔργοις. ἐπεὶ δ’ οὔτε τοῦ Ῥωμαίων οὔτε τοῦ Καρχηδονίων πολιτεύματος πρόχειρός ἐστι τοῖς πολλοῖς τῶν Ἑλλήνων ἡ προγεγενημένη δύναμις οὐδ’ αἱ πράξεις αὐτῶν, ἀναγκαῖον ὑπελάβομεν εἶναι συντάξασθαι ταύτην καὶ τὴν ἑξῆς βύβλον πρὸ τῆς ἱστορίας, ἵνα μηδεὶς ἐπιστὰς ἐπ’ αὐτὴν τὴν τῶν πραγμάτων ἐξήγησιν τότε διαπορῇ καὶ ζητῇ ποίοις διαβουλίοις ἢ ποίαις δυνάμεσι καὶ χορηγίαις χρησάμενοι Ῥωμαῖοι πρὸς ταύτας ὥρμησαν τὰς ἐπιβολάς, δι’ ὧν καὶ τῆς γῆς καὶ τῆς θαλάττης τῆς καθ’ ἡμᾶς ἐγένοντο πάσης ἐγκρατεῖς, ἀλλ’ ἐκ τούτων τῶν βύβλων καὶ τῆς ἐν ταύταις προκατασκευῆς δῆλον ᾖ τοῖς ἐντυγχάνουσιν ὅτι καὶ λίαν εὐλόγοις ἀφορμαῖς χρησάμενοι πρός τε τὴν ἐπίνοιαν ὥρμησαν καὶ πρὸς τὴν συντέλειαν ἐξίκοντο τῆς τῶν ὅλων ἀρχῆς καὶ δυναστείας.", "st": "1.3"}, {"sp": "N", "t": "τὸ γὰρ τῆς ἡμετέρας πραγματείας ἴδιον καὶ τὸ θαυμάσιον τῶν καθ’ ἡμᾶς καιρῶν τοῦτ’ ἔστιν ὅτι, καθάπερ ἡ τύχη σχεδὸν ἅπαντα τὰ τῆς οἰκουμένης πράγματα πρὸς ἓν ἔκλινε μέρος καὶ πάντα νεύειν ἠνάγκασε πρὸς ἕνα καὶ τὸν αὐτὸν σκοπόν, οὕτως καὶ δεῖ διὰ τῆς ἱστορίας ὑπὸ μίαν σύνοψιν ἀγαγεῖν τοῖς ἐντυγχάνουσι τὸν χειρισμὸν τῆς τύχης, ᾧ κέχρηται πρὸς τὴν τῶν ὅλων πραγμάτων συντέλειαν. καὶ γὰρ τὸ προκαλεσάμενον ἡμᾶς καὶ παρορμῆσαν πρὸς τὴν ἐπιβολὴν τῆς ἱστορίας μάλιστα τοῦτο γέγονεν, σὺν δὲ τούτῳ καὶ τὸ μηδένα τῶν καθ’ ἡμᾶς ἐπιβεβλῆσθαι τῇ τῶν καθόλου πραγμάτων συντάξει· πολὺ γὰρ ἂν ἧττον ἔγωγε πρὸς τοῦτο τὸ μέρος ἐφιλοτιμήθην. νῦν δ’ ὁρῶν τοὺς μὲν κατὰ μέρος πολέμους καί τινας τῶν ἅμα τούτοις πράξεων καὶ πλείους πραγματευομένους, τὴν δὲ καθόλου καὶ συλλήβδην οἰκονομίαν τῶν γεγονότων πότε καὶ πόθεν ὡρμήθη καὶ πῶς ἔσχε τὴν συντέλειαν, ταύτην οὐδ’ ἐπιβαλόμενον οὐδένα βασανίζειν, ὅσον γε καὶ ἡμᾶς εἰδέναι, παντελῶς ὑπέλαβον ἀναγκαῖον εἶναι τὸ μὴ παραλιπεῖν μηδ’ ἐᾶσαι παρελθεῖν ἀνεπιστάτως τὸ κάλλιστον ἅμα δ’ ὠφελιμώτατον ἐπιτήδευμα τῆς τύχης. πολλὰ γὰρ αὕτη καινοποιοῦσα καὶ συνεχῶς ἐναγωνιζομένη τοῖς τῶν ἀνθρώπων βίοις οὐδέπω τοιόνδ’ ἁπλῶς οὔτ’ εἰργάσατ’ ἔργον οὔτ’ ἠγωνίσατ’ ἀγώνισμα, οἷον τὸ καθ’ ἡμᾶς. ὅπερ ἐκ μὲν τῶν κατὰ μέρος γραφόντων τὰς ἱστορίας οὐχ οἷόν τε συνιδεῖν, εἰ μὴ καὶ τὰς ἐπιφανεστάτας πόλεις τις κατὰ μίαν ἑκάστην ἐπελθὼν ἢ καὶ νὴ Δία γεγραμμένας χωρὶς ἀλλήλων θεασάμενος εὐθέως ὑπολαμβάνει κατανενοηκέναι καὶ τὸ τῆς ὅλης οἰκουμένης σχῆμα καὶ τὴν σύμπασαν αὐτῆς θέσιν καὶ τάξιν· ὅπερ ἐστὶν οὐδαμῶς εἰκός. καθόλου μὲν γὰρ ἔμοιγε δοκοῦσιν οἱ πεπεισμένοι διὰ τῆς κατὰ μέρος ἱστορίας μετρίως συνόψεσθαι τὰ ὅλα παραπλήσιόν τι πάσχειν, ὡς ἂν εἴ τινες ἐμψύχου καὶ καλοῦ σώματος γεγονότος διερριμμένα τὰ μέρη θεώμενοι νομίζοιεν ἱκανῶς αὐτόπται γίνεσθαι τῆς ἐνεργείας αὐτοῦ τοῦ ζῴου καὶ καλλονῆς. εἰ γάρ τις αὐτίκα μάλα συνθεὶς καὶ τέλειον αὖθις ἀπεργασάμενος τὸ ζῷον τῷ τ’ εἴδει καὶ τῇ τῆς ψυχῆς εὐπρεπείᾳ κἄπειτα πάλιν ἐπιδεικνύοι τοῖς αὐτοῖς ἐκείνοις, ταχέως ἂν οἶμαι πάντας αὐτοὺς ὁμολογήσειν διότι καὶ λίαν πολύ τι τῆς ἀληθείας ἀπελείποντο πρόσθεν καὶ παραπλήσιοι τοῖς ὀνειρώττουσιν ἦσαν. ἔννοιαν μὲν γὰρ λαβεῖν ἀπὸ μέρους τῶν ὅλων δυνατόν, ἐπιστήμην δὲ καὶ γνώμην ἀτρεκῆ σχεῖν ἀδύνατον. διὸ παντελῶς βραχύ τι νομιστέον συμβάλλεσθαι τὴν κατὰ μέρος ἱστορίαν πρὸς τὴν τῶν ὅλων ἐμπειρίαν καὶ πίστιν. ἐκ μέντοι γε τῆς ἁπάντων πρὸς ἄλληλα συμπλοκῆς καὶ παραθέσεως, ἔτι δ’ ὁμοιότητος καὶ διαφορᾶς, μόνως ἄν τις ἐφίκοιτο καὶ δυνηθείη κατοπτεύσας ἅμα καὶ τὸ χρήσιμον καὶ τὸ τερπνὸν ἐκ τῆς ἱστορίας ἀναλαβεῖν.", "st": "1.4"}, {"sp": "N", "t": "Ὑποθησόμεθα δὲ ταύτης ἀρχὴν τῆς βύβλου τὴν πρώτην διάβασιν ἐξ Ἰταλίας Ῥωμαίων. αὕτη δ’ ἔστιν συνεχὴς μὲν τοῖς ἀφ’ ὧν Τίμαιος ἀπέλιπεν, πίπτει δὲ κατὰ τὴν ἐνάτην καὶ εἰκοστὴν πρὸς ταῖς ἑκατὸν ὀλυμπιάδα. διὸ καὶ ῥητέον ἂν εἴη πῶς καὶ πότε συστησάμενοι τὰ κατὰ τὴν Ἰταλίαν καὶ τίσιν ἀφορμαῖς μετὰ ταῦτα χρησάμενοι διαβαίνειν ὥρμησαν εἰς Σικελίαν· ταύτῃ γὰρ τῇ γῇ πρῶτον ἐπέβησαν τῶν ἐκτὸς τόπων τῆς Ἰταλίας. καὶ ῥητέον αὐτὴν τὴν τῆς διαβάσεως αἰτίαν ψιλῶς, ἵνα μὴ τῆς αἰτίας αἰτίαν ἐπιζητούσης ἀνυπόστατος ἡ τῆς ὅλης ὑποθέσεως ἀρχὴ γένηται καὶ θεωρία. ληπτέον δὲ καὶ τοῖς καιροῖς ὁμολογουμένην καὶ γνωριζομένην ἀρχὴν παρ’ ἅπασι καὶ τοῖς πράγμασι δυναμένην αὐτὴν ἐξ αὑτῆς θεωρεῖσθαι, κἂν δέῃ τοῖς χρόνοις βραχὺ προσαναδραμόντας κεφαλαιώδη τῶν μεταξὺ πράξεων ποιήσασθαι τὴν ἀνάμνησιν. τῆς γὰρ ἀρχῆς ἀγνοουμένης ἢ καὶ νὴ Δί’ ἀμφισβητουμένης οὐδὲ τῶν ἑξῆς οὐδὲν οἷόν τε παραδοχῆς ἀξιωθῆναι καὶ πίστεως· ὅταν δ’ ἡ περὶ ταύτης ὁμολογουμένη παρασκευασθῇ δόξα, τότ’ ἤδη καὶ πᾶς ὁ συνεχὴς λόγος ἀποδοχῆς τυγχάνει παρὰ τοῖς ἀκούουσιν.", "st": "1.5"}, {"sp": "N", "t": "ἔτος μὲν οὖν ἐνειστήκει μετὰ μὲν τὴν ἐν Αἰγὸς ποταμοῖς ναυμαχίαν ἐννεακαιδέκατον, πρὸ δὲ τῆς ἐν Λεύκτροις μάχης ἑκκαιδέκατον, ἐν ᾧ Λακεδαιμόνιοι μὲν τὴν ἐπ’ Ἀνταλκίδου λεγομένην εἰρήνην πρὸς βασιλέα τῶν Περσῶν ἐκύρωσαν καὶ πρεσβύτερος Διονύσιος τῇ περὶ τὸν Ἐλλέπορον ποταμὸν μάχῃ νενικηκὼς τοὺς κατὰ τὴν Ἰταλίαν Ἕλληνας ἐπολιόρκει Ῥήγιον, Γαλάται δὲ κατὰ κράτος ἑλόντες αὐτὴν τὴν Ῥώμην κατεῖχον πλὴν τοῦ Καπετωλίου. πρὸς οὓς ποιησάμενοι Ῥωμαῖοι σπονδὰς καὶ διαλύσεις εὐδοκουμένας Γαλάταις καὶ γενόμενοι πάλιν ἀνελπίστως τῆς πατρίδος ἐγκρατεῖς καὶ λαβόντες οἷον ἀρχὴν τῆς συναυξήσεως ἐπολέμουν ἐν τοῖς ἑξῆς χρόνοις πρὸς τοὺς ἀστυγείτονας. γενόμενοι δ’ ἐγκρατεῖς ἁπάντων τῶν Λατίνων διά τε τὴν ἀνδρείαν καὶ τὴν ἐν ταῖς μάχαις ἐπιτυχίαν μετὰ ταῦτ’ ἐπολέμουν Τυρρηνοῖς, ἔπειτα Κελτοῖς, ἑξῆς δὲ Σαυνίταις τοῖς πρός τε τὰς ἀνατολὰς καὶ τὰς ἄρκτους συντερμονοῦσι τῇ τῶν Λατίνων χώρᾳ. μετὰ δέ τινα χρόνον Ταραντίνων διὰ τὴν εἰς τοὺς πρεσβευτὰς Ῥωμαίων ἀσέλγειαν καὶ τὸν διὰ ταῦτα φόβον ἐπισπασαμένων Πύρρον, τῷ πρότερον ἔτει τῆς τῶν Γαλατῶν ἐφόδου τῶν τε περὶ Δελφοὺς φθαρέντων καὶ περαιωθέντων εἰς τὴν Ἀσίαν, Ῥωμαῖοι Τυρρηνοὺς μὲν καὶ Σαυνίτας ὑφ’ αὑτοὺς πεποιημένοι, τοὺς δὲ κατὰ τὴν Ἰταλίαν Κελτοὺς πολλαῖς μάχαις ἤδη νενικηκότες, τότε πρῶτον ἐπὶ τὰ λοιπὰ μέρη τῆς Ἰταλίας ὥρμησαν, οὐχ ὡς ὑπὲρ ὀθνείων, ἐπὶ δὲ τὸ πλεῖον ὡς ὑπὲρ ἰδίων ἤδη καὶ καθηκόντων σφίσι πολεμήσοντες, ἀθληταὶ γεγονότες ἀληθινοὶ τῶν κατὰ τὸν πόλεμον ἔργων ἐκ τῶν πρὸς τοὺς Σαυνίτας καὶ Κελτοὺς ἀγώνων. ὑποστάντες δὲ γενναίως τὸν πόλεμον τοῦτον καὶ τὸ τελευταῖον τάς τε δυνάμεις καὶ Πύρρον ἐκβαλόντες ἐκ τῆς Ἰταλίας αὖθις ἐπολέμουν καὶ κατεστρέφοντο τοὺς κοινωνήσαντας Πύρρῳ τῶν πραγμάτων. γενόμενοι δὲ παραδόξως ἁπάντων ἐγκρατεῖς καὶ ποιησάμενοι τοὺς τὴν Ἰταλίαν οἰκοῦντας ὑφ’ αὑτοὺς πλὴν Κελτῶν μετὰ ταῦτα πολιορκεῖν ἐνεχείρησαν τοὺς τότε κατέχοντας τὸ Ῥήγιον Ῥωμαίους.", "st": "1.6"}, {"sp": "N", "t": "ἴδιον γάρ τι συνέβη καὶ παραπλήσιον ἑκατέραις ταῖς περὶ τὸν πορθμὸν ἐκτισμέναις πόλεσιν· εἰσὶ δ’ αὗται Μεσσήνη καὶ Ῥήγιον. Μεσσήνην μὲν γὰρ οὐ πολλοῖς ἀνώτερον χρόνοις τῶν νῦν λεγομένων καιρῶν Καμπανοὶ παρ’ Ἀγαθοκλεῖ μισθοφοροῦντες καὶ πάλαι περὶ τὸ κάλλος καὶ τὴν λοιπὴν εὐδαιμονίαν τῆς πόλεως ὀφθαλμιῶντες ἅμα τῷ λαβεῖν καιρὸν εὐθὺς ἐπεχείρησαν παρασπονδεῖν· παρεισελθόντες δ’ ὡς φίλιοι καὶ κατασχόντες τὴν πόλιν οὓς μὲν ἐξέβαλον τῶν πολιτῶν, οὓς δ’ ἀπέσφαξαν. πράξαντες δὲ ταῦτα τὰς μὲν γυναῖκας καὶ τὰ τέκνα τῶν ἠκληρηκότων, ὥς ποθ’ ἡ τύχη διένειμεν παρ’ αὐτὸν τὸν τῆς παρανομίας καιρὸν ἑκάστοις, οὕτως ἔσχον· τοὺς δὲ λοιποὺς βίους καὶ τὴν χώραν μετὰ ταῦτα διελόμενοι κατεῖχον. ταχὺ δὲ καὶ ῥᾳδίως καλῆς χώρας καὶ πόλεως ἐγκρατεῖς γενόμενοι παρὰ πόδας εὗρον μιμητὰς τῆς πράξεως. Ῥηγῖνοι γάρ, καθ’ ὃν καιρὸν Πύρρος εἰς Ἰταλίαν ἐπεραιοῦτο, καταπλαγεῖς γενόμενοι τὴν ἔφοδον αὐτοῦ, δεδιότες δὲ καὶ Καρχηδονίους θαλαττοκρατοῦντας ἐπεσπάσαντο φυλακὴν ἅμα καὶ βοήθειαν παρὰ Ῥωμαίων. οἱ δ’ εἰσελθόντες χρόνον μέν τινα διετήρουν τὴν πόλιν καὶ τὴν ἑαυτῶν πίστιν, ὄντες τετρακισχίλιοι τὸν ἀριθμόν, ὧν ἡγεῖτο Δέκιος Καμπανός· τέλος δὲ ζηλώσαντες τοὺς Μαμερτίνους, ἅμα δὲ καὶ συνεργοὺς λαβόντες αὐτοὺς παρεσπόνδησαν τοὺς Ῥηγίνους, ἐκπαθεῖς ὄντες ἐπί τε τῇ τῆς πόλεως εὐκαιρίᾳ καὶ τῇ τῶν Ῥηγίνων περὶ τοὺς ἰδίους βίους εὐδαιμονίᾳ· καὶ τοὺς μὲν ἐκβαλόντες, τοὺς δ’ ἀποσφάξαντες τῶν πολιτῶν τὸν αὐτὸν τρόπον τοῖς Καμπανοῖς κατέσχον τὴν πόλιν. οἱ δὲ Ῥωμαῖοι βαρέως μὲν ἔφερον τὸ γεγονός· οὐ μὴν εἶχόν γε ποιεῖν οὐδὲν διὰ τὸ συνέχεσθαι τοῖς προειρημένοις πολέμοις. ἐπεὶ δ’ ἀπὸ τούτων ἐγένοντο, συγκλείσαντες αὐτοὺς ἐπολιόρκουν τὸ Ῥήγιον, καθάπερ ἐπάνω προεῖπον. κρατήσαντες δὲ τοὺς μὲν πλείστους ἐν αὐτῇ τῇ καταλήψει διέφθειραν, ἐκθύμως ἀμυνομένους διὰ τὸ προορᾶσθαι τὸ μέλλον, ζωγρίᾳ δ’ ἐκυρίευσαν πλειόνων ἢ τριακοσίων. ὧν ἀναπεμφθέντων εἰς τὴν Ῥώμην, οἱ στρατηγοὶ προαγαγόντες εἰς τὴν ἀγορὰν καὶ μαστιγώσαντες ἅπαντας κατὰ τὸ παρ’ αὐτοῖς ἔθος ἐπελέκισαν, βουλόμενοι διὰ τῆς εἰς ἐκείνους τιμωρίας, καθ’ ὅσον οἷοί τ’ ἦσαν, διορθοῦσθαι παρὰ τοῖς συμμάχοις τὴν αὑτῶν πίστιν. τὴν δὲ χώραν καὶ τὴν πόλιν παραχρῆμα τοῖς Ῥηγίνοις ἀπέδοσαν.", "st": "1.7"}, {"sp": "N", "t": "οἱ δὲ Μαμερτῖνοι — τοῦτο γὰρ τοὔνομα κυριεύσαντες οἱ Καμπανοὶ τῆς Μεσσήνης προσηγόρευσαν σφᾶς αὐτούς — ἕως μὲν συνεχρῶντο τῇ τῶν Ῥωμαίων συμμαχίᾳ τῶν τὸ Ῥήγιον κατασχόντων, οὐ μόνον τῆς ἑαυτῶν πόλεως καὶ χώρας ἀσφαλῶς κατεκράτουν, ἀλλὰ καὶ περὶ τῆς συνορούσης οὐχ ὡς ἔτυχε παρηνώχλουν τοῖς τε Καρχηδονίοις καὶ τοῖς Συρακοσίοις καὶ πολλὰ μέρη τῆς Σικελίας ἐφορολόγουν. ἐπεὶ δ’ ἐστερήθησαν τῆς προειρημένης ἐπικουρίας, συγκλεισθέντων τῶν τὸ Ῥήγιον κατεχόντων εἰς τὴν πολιορκίαν, παρὰ πόδας ὑπὸ τῶν Συρακοσίων αὐτοὶ πάλιν συνεδιώχθησαν εἰς τὴν πόλιν διά τινας τοιαύτας αἰτίας. χρόνοις οὐ πολλοῖς πρότερον αἱ δυνάμεις τῶν Συρακοσίων διενεχθεῖσαι πρὸς τοὺς ἐν τῇ πόλει καὶ διατρίβουσαι περὶ τὴν Μεργάνην κατέστησαν ἐξ αὑτῶν ἄρχοντας, Ἀρτεμίδωρόν τε καὶ τὸν μετὰ ταῦτα βασιλεύσαντα τῶν Συρακοσίων Ἱέρωνα, νέον μὲν ὄντα κομιδῇ, πρὸς δέ τι γένος εὐφυῆ βασιλικῆς καὶ πραγματικῆς οἰκονομίας. ὁ δὲ παραλαβὼν τὴν ἀρχὴν καὶ παρεισελθὼν εἰς τὴν πόλιν διά τινων οἰκείων καὶ κύριος γενόμενος τῶν ἀντιπολιτευομένων οὕτως ἐχρήσατο πρᾴως καὶ μεγαλοψύχως τοῖς πράγμασιν, ὥστε τοὺς Συρακοσίους, καίπερ οὐδαμῶς εὐδοκουμένους ἐπὶ ταῖς τῶν στρατιωτῶν ἀρχαιρεσίαις, τότε πάντας ὁμοθυμαδὸν εὐδοκῆσαι στρατηγὸν αὑτῶν ὑπάρχειν Ἱέρωνα. ὃς ἐκ τῶν πρώτων ἐπινοημάτων εὐθέως δῆλος ἦν τοῖς ὀρθῶς σκοπουμένοις μειζόνων ὀρεγόμενος ἐλπίδων ἢ κατὰ τὴν στρατηγίαν.", "st": "1.8"}, {"sp": "N", "t": "θεωρῶν γὰρ τοὺς Συρακοσίους, ἐπειδὰν ἐκπέμψωσι τὰς δυνάμεις καὶ τοὺς ἄρχοντας μετὰ τῶν δυνάμεων, αὐτοὺς ἐν αὑτοῖς στασιάζοντας καὶ καινοτομοῦντας αἰεί τι, τὸν δὲ Λεπτίνην εἰδὼς καὶ τῇ προστασίᾳ καὶ τῇ πίστει πολὺ διαφέροντα τῶν ἄλλων πολιτῶν, εὐδοκιμοῦντα δὲ καὶ παρὰ τῷ πλήθει διαφερόντως, συνάπτεται κηδείαν πρὸς αὐτόν, βουλόμενος οἷον ἐφεδρείαν ἀπολιπεῖν ἐν τῇ πόλει τοῦτον, ὅτ’ αὐτὸν ἐξιέναι δέοι μετὰ τῶν δυνάμεων ἐπὶ τὰς πράξεις. γήμας δὲ τὴν θυγατέρα τοῦ προειρημένου καὶ συνθεωρῶν τοὺς ἀρχαίους μισθοφόρους καχέκτας ὄντας καὶ κινητικοὺς ἐξάγει στρατείαν ὡς ἐπὶ τοὺς βαρβάρους τοὺς τὴν Μεσσήνην κατασχόντας. ἀντιστρατοπεδεύσας δὲ περὶ Κεντόριπα καὶ παραταξάμενος περὶ τὸν Κυαμόσωρον ποταμὸν τοὺς μὲν πολιτικοὺς ἱππεῖς καὶ πεζοὺς αὐτὸς ἐν ἀποστήματι συνεῖχεν, ὡς κατ’ ἄλλον τόπον τοῖς πολεμίοις συμμίξων, τοὺς δὲ ξένους προβαλόμενος εἴασε πάντας ὑπὸ τῶν βαρβάρων διαφθαρῆναι· κατὰ δὲ τὸν τῆς ἐκείνων τροπῆς καιρὸν ἀσφαλῶς αὐτὸς ἀπεχώρησεν μετὰ τῶν πολιτῶν εἰς τὰς Συρακούσας. συντελεσάμενος δὲ τὸ προκείμενον πραγματικῶς καὶ παρῃρηκὼς πᾶν τὸ κινητικὸν καὶ στασιῶδες τῆς δυνάμεως, ξενολογήσας δι’ αὑτοῦ πλῆθος ἱκανὸν μισθοφόρων, ἀσφαλῶς ἤδη τὰ κατὰ τὴν ἀρχὴν διεξῆγεν. θεωρῶν δὲ τοὺς βαρβάρους ἐκ τοῦ προτερήματος θρασέως καὶ προπετῶς ἀναστρεφομένους, καθοπλίσας καὶ γυμνάσας ἐνεργῶς τὰς πολιτικὰς δυνάμεις ἐξῆγεν καὶ συμβάλλει τοῖς πολεμίοις ἐν τῷ Μυλαίῳ πεδίῳ περὶ τὸν Λογγανὸν καλούμενον ποταμόν. τροπὴν δὲ ποιήσας αὐτῶν ἰσχυρὰν καὶ τῶν ἡγεμόνων ἐγκρατὴς γενόμενος ζωγρίᾳ τὴν μὲν τῶν βαρβάρων κατέπαυσε τόλμαν, αὐτὸς δὲ παραγενόμενος εἰς τὰς Συρακούσας βασιλεὺς ὑπὸ πάντων προσηγορεύθη τῶν συμμάχων.", "st": "1.9"}, {"sp": "N", "t": "οἱ δὲ Μαμερτῖνοι πρότερον μὲν ἐστερημένοι τῆς ἐπικουρίας τῆς ἐκ τοῦ Ῥηγίου, καθάπερ ἀνώτερον εἶπον, τότε δὲ τοῖς ἰδίοις πράγμασιν ἐπταικότες ὁλοσχερῶς διὰ τὰς νῦν ῥηθείσας αἰτίας, οἱ μὲν ἐπὶ Καρχηδονίους κατέφευγον καὶ τούτοις ἐνεχείριζον σφᾶς αὐτοὺς καὶ τὴν ἄκραν, οἱ δὲ πρὸς Ῥωμαίους ἐπρέσβευον, παραδιδόντες τὴν πόλιν καὶ δεόμενοι βοηθήσειν σφίσιν αὐτοῖς ὁμοφύλοις ὑπάρχουσιν. Ῥωμαῖοι δὲ πολὺν μὲν χρόνον ἠπόρησαν διὰ τὸ δοκεῖν ἐξόφθαλμον εἶναι τὴν ἀλογίαν τῆς βοηθείας. τὸ γὰρ μικρῷ πρότερον τοὺς ἰδίους πολίτας μετὰ τῆς μεγίστης ἀνῃρηκότας τιμωρίας, ὅτι Ῥηγίνους παρεσπόνδησαν, παραχρῆμα Μαμερτίνοις βοηθεῖν ζητεῖν τοῖς τὰ παραπλήσια πεποιηκόσιν οὐ μόνον εἰς τὴν Μεσσηνίων, ἀλλὰ καὶ τὴν Ῥηγίνων πόλιν, δυσαπολόγητον εἶχε τὴν ἁμαρτίαν. οὐ μὴν ἀγνοοῦντές γε τούτων οὐδέν, θεωροῦντες δὲ τοὺς Καρχηδονίους οὐ μόνον τὰ κατὰ τὴν Λιβύην, ἀλλὰ καὶ τῆς Ἰβηρίας ὑπήκοα πολλὰ μέρη πεποιημένους, ἔτι δὲ τῶν νήσων ἁπασῶν ἐγκρατεῖς ὑπάρχοντας τῶν κατὰ τὸ Σαρδόνιον καὶ Τυρρηνικὸν πέλαγος, ἠγωνίων, εἰ Σικελίας ἔτι κυριεύσαιεν, μὴ λίαν βαρεῖς καὶ φοβεροὶ γείτονες αὐτοῖς ὑπάρχοιεν, κύκλῳ σφᾶς περιέχοντες καὶ πᾶσι τοῖς τῆς Ἰταλίας μέρεσιν ἐπικείμενοι. διότι δὲ ταχέως ὑφ’ αὑτοὺς ποιήσονται τὴν Σικελίαν, μὴ τυχόντων ἐπικουρίας τῶν Μαμερτίνων, προφανὲς ἦν. κρατήσαντες γὰρ ἐγχειριζομένης αὐτοῖς τῆς Μεσσήνης ἔμελλον ἐν ὀλίγῳ χρόνῳ τὰς Συρακούσας ἐπανελέσθαι διὰ τὸ πάσης σχεδὸν δεσπόζειν τῆς ἄλλης Σικελίας. ὃ προορώμενοι Ῥωμαῖοι καὶ νομίζοντες ἀναγκαῖον εἶναι σφίσι τὸ μὴ προέσθαι τὴν Μεσσήνην μηδ’ ἐᾶσαι Καρχηδονίους οἱονεὶ γεφυρῶσαι τὴν εἰς Ἰταλίαν αὑτοῖς διάβασιν,", "st": "1.10"}, {"sp": "N", "t": "πολὺν μὲν χρόνον ἐβουλεύσαντο, καὶ τὸ μὲν συνέδριον οὐδ’ εἰς τέλος ἐκύρωσε τὴν γνώμην διὰ τὰς ἄρτι ῥηθείσας αἰτίας. ἐδόκει γὰρ τὰ περὶ τὴν ἀλογίαν τῆς τοῖς Μαμερτίνοις ἐπικουρίας ἰσορροπεῖν τοῖς ἐκ τῆς βοηθείας συμφέρουσιν. οἱ δὲ πολλοὶ τετρυμένοι μὲν ὑπὸ τῶν προγεγονότων πολέμων καὶ προσδεόμενοι παντοδαπῆς ἐπανορθώσεως, ἅμα δὲ τοῖς ἄρτι ῥηθεῖσι περὶ τοῦ κοινῇ συμφέρειν τὸν πόλεμον καὶ κατ’ ἰδίαν ἑκάστοις ὠφελείας προδήλους καὶ μεγάλας ὑποδεικνυόντων τῶν στρατηγῶν, ἔκριναν βοηθεῖν. κυρωθέντος δὲ τοῦ δόγματος ὑπὸ τοῦ δήμου, προχειρισάμενοι τὸν ἕτερον τῶν ὑπάτων στρατηγὸν Ἄππιον Κλαύδιον ἐξαπέστειλαν, κελεύσαντες βοηθεῖν καὶ διαβαίνειν εἰς Μεσσήνην. οἱ δὲ Μαμερτῖνοι τὸν μὲν τῶν Καρχηδονίων στρατηγὸν ἤδη κατέχοντα τὴν ἄκραν ἐξέβαλον, τὰ μὲν καταπληξάμενοι, τὰ δὲ παραλογισάμενοι· τὸν δ’ Ἄππιον ἐπεσπῶντο καὶ τούτῳ τὴν πόλιν ἐνεχείριζον. Καρχηδόνιοι δὲ τὸν μὲν στρατηγὸν αὐτῶν ἀνεσταύρωσαν, νομίσαντες αὐτὸν ἀβούλως, ἅμα δ’ ἀνάνδρως προέσθαι τὴν ἀκρόπολιν· αὐτοὶ δὲ τῇ μὲν ναυτικῇ δυνάμει περὶ Πελωριάδα στρατοπεδεύσαντες, τῷ δὲ πεζῷ στρατεύματι περὶ τὰς Σύνεις καλουμένας ἐνεργῶς προσέκειντο τῇ Μεσσήνῃ. κατὰ δὲ τὸν καιρὸν τοῦτον Ἱέρων νομίσας εὐφυῶς ἔχειν τὰ παρόντα πρὸς τὸ τοὺς βαρβάρους τοὺς τὴν Μεσσήνην κατέχοντας ὁλοσχερῶς ἐκβαλεῖν ἐκ τῆς Σικελίας, τίθεται πρὸς τοὺς Καρχηδονίους συνθήκας. καὶ μετὰ ταῦτ’ ἀναζεύξας ἐκ τῶν Συρακουσῶν ἐποιεῖτο τὴν πορείαν ἐπὶ τὴν προειρημένην πόλιν· καταστρατοπεδεύσας δ’ ἐκ θατέρου μέρους περὶ τὸ Χαλκιδικὸν ὄρος καλούμενον ἀπέκλεισε καὶ ταύτης τῆς ἐξόδου τοὺς ἐν τῇ πόλει. ὁ δὲ στρατηγὸς τῶν Ῥωμαίων Ἄππιος νυκτὸς καὶ παραβόλως περαιωθεὶς τὸν πορθμὸν ἧκεν εἰς τὴν Μεσσήνην. ὁρῶν δὲ πανταχόθεν ἐνεργῶς προσηρεικότας τοὺς πολεμίους καὶ συλλογισάμενος ἅμα μὲν αἰσχράν, ἅμα δ’ ἐπισφαλῆ γίνεσθαι τὴν πολιορκίαν αὑτῷ, τῆς τε γῆς τῶν πολεμίων ἐπικρατούντων καὶ τῆς θαλάττης, τὸ μὲν πρῶτον διεπρεσβεύετο πρὸς ἀμφοτέρους, βουλόμενος ἐξελέσθαι τοῦ πολέμου τοὺς Μαμερτίνους· οὐδενὸς δὲ προσέχοντος αὐτῷ, τέλος ἐπαναγκαζόμενος ἔκρινε διακινδυνεύειν καὶ πρῶτον ἐγχειρεῖν τοῖς Συρακοσίοις. ἐξαγαγὼν δὲ τὴν δύναμιν παρέταξε πρὸς μάχην, ἑτοίμως εἰς τὸν ἀγῶνα συγκαταβάντος αὐτῷ καὶ τοῦ τῶν Συρακοσίων βασιλέως· ἐπὶ πολὺν δὲ χρόνον διαγωνισάμενος ἐπεκράτησεν τῶν πολεμίων καὶ κατεδίωξε τοὺς ὑπεναντίους ἕως εἰς τὸν χάρακα πάντας. Ἄππιος μὲν οὖν σκυλεύσας τοὺς νεκροὺς ἐπανῆλθεν πάλιν εἰς τὴν Μεσσήνην. ὁ δ’ Ἱέρων ὀττευσάμενός τι περὶ τῶν ὅλων πραγμάτων, ἐπιγενομένης τῆς νυκτὸς ἀνεχώρησε κατὰ σπουδὴν εἰς τὰς Συρακούσας.", "st": "1.11"}, {"sp": "N", "t": "τῇ δὲ κατὰ πόδας ἡμέρᾳ γνοὺς Ἄππιος τὴν ἀπόλυσιν τῶν προειρημένων καὶ γενόμενος εὐθαρσὴς ἔκρινε μὴ μέλλειν, ἀλλ’ ἐγχειρεῖν τοῖς Καρχηδονίοις. παραγγείλας οὖν τοῖς στρατιώταις ἐν ὥρᾳ γίνεσθαι τὴν θεραπείαν, ἅμα τῷ φωτὶ τὴν ἔξοδον ἐποιεῖτο. συμβαλὼν δὲ τοῖς ὑπεναντίοις πολλοὺς μὲν αὐτῶν ἀπέκτεινε, τοὺς δὲ λοιποὺς ἠνάγκασε φυγεῖν προτροπάδην εἰς τὰς παρακειμένας πόλεις. χρησάμενος δὲ τοῖς εὐτυχήμασι τούτοις καὶ λύσας τὴν πολιορκίαν, λοιπὸν ἐπιπορευόμενος ἀδεῶς ἐπόρθει τήν τε τῶν Συρακοσίων καὶ τὴν τῶν συμμαχούντων αὐτοῖς χώραν, οὐδενὸς ἀντιποιουμένου τῶν ὑπαίθρων· τὸ δὲ τελευταῖον προσκαθίσας αὐτὰς ἐπεβάλετο πολιορκεῖν τὰς Συρακούσας. ἡ μὲν οὖν πρώτη Ῥωμαίων ἐκ τῆς Ἰταλίας διάβασις μετὰ δυνάμεως ἥδε καὶ διὰ ταῦτα καὶ κατὰ τούτους ἐγένετο τοὺς καιρούς, ἣν οἰκειοτάτην κρίναντες ἀρχὴν εἶναι τῆς ὅλης προθέσεως, ἀπὸ ταύτης ἐποιησάμεθα τὴν ἐπίστασιν, ἀναδραμόντες ἔτι τοῖς χρόνοις τοῦ μηδὲν ἀπόρημα καταλιπεῖν ὑπὲρ τῶν κατὰ τὰς αἰτίας ἀποδείξεων. τῷ γὰρ πῶς καὶ πότε πταίσαντες αὐτῇ τῇ πατρίδι Ῥωμαῖοι τῆς ἐπὶ τὸ βέλτιον ἤρξαντο προκοπῆς καὶ πότε πάλιν καὶ πῶς κρατήσαντες τῶν κατὰ τὴν Ἰταλίαν τοῖς ἐκτὸς ἐπιχειρεῖν ἐπεβάλοντο πράγμασιν, ἀναγκαῖον ὑπελάβομεν εἶναι παρακολουθῆσαι τοῖς μέλλουσι καὶ τὸ κεφάλαιον αὐτῶν τῆς νῦν ὑπεροχῆς δεόντως συνόψεσθαι. διόπερ οὐ χρὴ θαυμάζειν οὐδ’ ἐν τοῖς ἑξῆς, ἐάν που προσανατρέχωμεν τοῖς χρόνοις περὶ τῶν ἐπιφανεστάτων πολιτευμάτων. τοῦτο γὰρ ποιήσομεν χάριν τοῦ λαμβάνειν ἀρχὰς τοιαύτας, ἐξ ὧν ἔσται σαφῶς κατανοεῖν ἐκ τίνων ἕκαστοι καὶ πότε καὶ πῶς ὁρμηθέντες εἰς ταύτας παρεγένοντο τὰς διαθέσεις, ἐν αἷς ὑπάρχουσι νῦν. ὃ δὴ καὶ περὶ Ῥωμαίων ἄρτι πεποιήκαμεν.", "st": "1.12"}, {"sp": "N", "t": "ἀφεμένους δὲ τούτων λέγειν ὥρα περὶ τῶν προκειμένων, ἐπὶ βραχὺ καὶ κεφαλαιωδῶς προεκθεμένους τὰς ἐν τῇ προκατασκευῇ πράξεις. ὧν εἰσι πρῶται κατὰ τὴν τάξιν αἱ γενόμεναι Ῥωμαίοις καὶ Καρχηδονίοις ἐν τῷ περὶ Σικελίας πολέμῳ. ταύταις συνεχὴς ὁ Λιβυκὸς πόλεμος· ᾧ συνάπτει τὰ κατ’ Ἰβηρίαν Ἀμίλκᾳ, μετὰ δὲ τοῦτον Ἀσδρούβᾳ πραχθέντα καὶ Καρχηδονίοις. οἷς ἐγένετο κατὰ τὸν αὐτὸν καιρὸν ἡ πρώτη Ῥωμαίων διάβασις εἰς τὴν Ἰλλυρίδα καὶ ταῦτα τὰ μέρη τῆς Εὐρώπης, ἐπὶ δὲ τοῖς προειρημένοις οἱ πρὸς τοὺς ἐν Ἰταλίᾳ Κελτοὺς ἀγῶνες. τούτοις δὲ κατὰ τὸν αὐτὸν καιρὸν παρὰ τοῖς Ἕλλησιν ὁ Κλεομενικὸς καλούμενος ἐνηργεῖτο πόλεμος, εἰς ὃν καὶ τὴν καταστροφὴν ἐποιησάμεθα τῆς ὅλης κατασκευῆς καὶ τῆς δευτέρας βύβλου. τὸ μὲν οὖν ἐξαριθμεῖσθαι τὰ κατὰ μέρος ὑπὲρ τῶν προειρημένων πράξεων οὐδὲν οὔθ’ ἡμῖν ἀναγκαῖον οὔτε τοῖς ἀκούουσι χρήσιμον. οὐ γὰρ ἱστορεῖν ὑπὲρ αὐτῶν προτιθέμεθα, μνησθῆναι δὲ κεφαλαιωδῶς προαιρούμεθα χάριν τῆς προκατασκευῆς τῶν μελλουσῶν ὑφ’ ἡμῶν ἱστορεῖσθαι πράξεων. διόπερ ἐπὶ κεφαλαίων ψαύοντες κατὰ τὸ συνεχὲς τῶν προειρημένων πειρασόμεθα συνάψαι τὴν τελευτὴν τῆς προκατασκευῆς τῇ τῆς ἡμετέρας ἱστορίας ἀρχῇ καὶ προθέσει. τοῦτον γὰρ τὸν τρόπον συνεχοῦς γινομένης τῆς διηγήσεως, ἡμεῖς τε δόξομεν εὐλόγως ἐφάπτεσθαι τῶν ἤδη προϊστορημένων ἑτέροις, τοῖς τε φιλομαθοῦσιν ἐκ τῆς τοιαύτης οἰκονομίας εὐμαθῆ καὶ ῥᾳδίαν ἐπὶ τὰ μέλλοντα ῥηθήσεσθαι παρασκευάσομεν τὴν ἔφοδον. βραχὺ δ’ ἐπιμελέστερον πειρασόμεθα διελθεῖν ὑπὲρ τοῦ πρώτου συστάντος πολέμου Ῥωμαίοις καὶ Καρχηδονίοις περὶ Σικελίας. οὔτε γὰρ πολυχρονιώτερον τούτου πόλεμον εὑρεῖν ῥᾴδιον οὔτε παρασκευὰς ὁλοσχερεστέρας οὔτε συνεχεστέρας πράξεις οὔτε πλείους ἀγῶνας οὔτε περιπετείας μείζους τῶν ἐν τῷ προειρημένῳ πολέμῳ συμβάντων ἑκατέροις. αὐτά τε τὰ πολιτεύματα κατ’ ἐκείνους τοὺς καιροὺς ἀκμὴν ἀκέραια μὲν ἦν τοῖς ἐθισμοῖς, μέτρια δὲ ταῖς τύχαις, πάρισα δὲ ταῖς δυνάμεσιν. διὸ καὶ τοῖς βουλομένοις καλῶς συνθεάσασθαι τὴν ἑκατέρου τοῦ πολιτεύματος ἰδιότητα καὶ δύναμιν οὐχ οὕτως ἐκ τῶν ἐπιγενομένων πολέμων ὡς ἐκ τούτου ποιητέον τὴν σύγκρισιν.", "st": "1.13"}, {"sp": "N", "t": "οὐχ ἧττον δὲ τῶν προειρημένων παρωξύνθην ἐπιστῆσαι τούτῳ τῷ πολέμῳ καὶ διὰ τὸ τοὺς ἐμπειρότατα δοκοῦντας γράφειν ὑπὲρ αὐτοῦ, Φιλῖνον καὶ Φάβιον, μὴ δεόντως ἡμῖν ἀπηγγελκέναι τὴν ἀλήθειαν. ἑκόντας μὲν οὖν ἐψεῦσθαι τοὺς ἄνδρας οὐχ ὑπολαμβάνω, στοχαζόμενος ἐκ τοῦ βίου καὶ τῆς αἱρέσεως αὐτῶν· δοκοῦσι δέ μοι πεπονθέναι τι παραπλήσιον τοῖς ἐρῶσι. διὰ γὰρ τὴν αἵρεσιν καὶ τὴν ὅλην εὔνοιαν Φιλίνῳ μὲν πάντα δοκοῦσιν οἱ Καρχηδόνιοι πεπρᾶχθαι φρονίμως, καλῶς, ἀνδρωδῶς, οἱ δὲ Ῥωμαῖοι τἀναντία, Φαβίῳ δὲ τοὔμπαλιν τούτων. ἐν μὲν οὖν τῷ λοιπῷ βίῳ τὴν τοιαύτην ἐπιείκειαν ἴσως οὐκ ἄν τις ἐκβάλλοι· καὶ γὰρ φιλόφιλον εἶναι δεῖ τὸν ἀγαθὸν ἄνδρα καὶ φιλόπατριν καὶ συμμισεῖν τοῖς φίλοις τοὺς ἐχθροὺς καὶ συναγαπᾶν τοὺς φίλους· ὅταν δὲ τὸ τῆς ἱστορίας ἦθος ἀναλαμβάνῃ τις, ἐπιλαθέσθαι χρὴ πάντων τῶν τοιούτων καὶ πολλάκις μὲν εὐλογεῖν καὶ κοσμεῖν τοῖς μεγίστοις ἐπαίνοις τοὺς ἐχθρούς, ὅταν αἱ πράξεις ἀπαιτῶσι τοῦτο, πολλάκις δ’ ἐλέγχειν καὶ ψέγειν ἐπονειδίστως τοὺς ἀναγκαιοτάτους, ὅταν αἱ τῶν ἐπιτηδευμάτων ἁμαρτίαι τοῦθ’ ὑποδεικνύωσιν. ὥσπερ γὰρ ζῴου τῶν ὄψεων ἀφαιρεθεισῶν ἀχρειοῦται τὸ ὅλον, οὕτως ἐξ ἱστορίας ἀναιρεθείσης τῆς ἀληθείας τὸ καταλειπόμενον αὐτῆς ἀνωφελὲς γίνεται διήγημα. διόπερ οὔτε τῶν φίλων κατηγορεῖν οὔτε τοὺς ἐχθροὺς ἐπαινεῖν ὀκνητέον, οὔτε δὲ τοὺς αὐτοὺς ψέγειν, ποτὲ δ’ ἐγκωμιάζειν εὐλαβητέον, ἐπειδὴ τοὺς ἐν πράγμασιν ἀναστρεφομένους οὔτ’ εὐστοχεῖν αἰεὶ δυνατὸν οὔθ’ ἁμαρτάνειν συνεχῶς εἰκός. ἀποστάντας οὖν τῶν πραττόντων αὐτοῖς τοῖς πραττομένοις ἐφαρμοστέον τὰς πρεπούσας ἀποφάσεις καὶ διαλήψεις ἐν τοῖς ὑπομνήμασιν. ὡς δ’ ἔστιν ἀληθῆ τὰ νῦν ὑφ’ ἡμῶν εἰρημένα σκοπεῖν ἐκ τούτων πάρεστιν.", "st": "1.14"}, {"sp": "N", "t": "ὁ γὰρ Φιλῖνος ἀρχόμενος ἅμα τῶν πραγμάτων καὶ τῆς δευτέρας βύβλου φησὶ προσκαθῆσθαι τῇ Μεσσήνῃ πολεμοῦντας τούς τε Καρχηδονίους καὶ τοὺς Συρακοσίους, παραγενομένους δὲ τοὺς Ῥωμαίους κατὰ θάλατταν εἰς τὴν πόλιν εὐθὺς ἐξελθεῖν ἐπὶ τοὺς Συρακοσίους· λαβόντας δὲ πολλὰς πληγὰς ἐπανελθεῖν εἰς τὴν Μεσσήνην· αὖθις δ’ ἐπὶ τοὺς Καρχηδονίους ἐκπορευθέντας οὐ μόνον πληγὰς λαβεῖν, ἀλλὰ καὶ ζωγρίᾳ τῶν στρατιωτῶν ἱκανοὺς ἀποβαλεῖν. ταῦτα δ’ εἰπὼν τὸν μὲν Ἱέρωνά φησι μετὰ τὴν γενομένην συμπλοκὴν οὕτως ἔξω γενέσθαι τοῦ φρονεῖν ὥστε μὴ μόνον παραχρῆμα τὸν χάρακα καὶ τὰς σκηνὰς ἐμπρήσαντα φυγεῖν νυκτὸς εἰς τὰς Συρακούσας, ἀλλὰ καὶ τὰ φρούρια πάντα καταλιπεῖν τὰ κείμενα κατὰ τῆς τῶν Μεσσηνίων χώρας· ὁμοίως δὲ καὶ τοὺς Καρχηδονίους μετὰ τὴν μάχην εὐθέως ἐκλιπόντας τὸν χάρακα διελεῖν σφᾶς εἰς τὰς πόλεις, τῶν δ’ ὑπαίθρων οὐδ’ ἀντιποιεῖσθαι τολμᾶν ἔτι· διὸ καὶ συνθεωρήσαντας τοὺς ἡγουμένους αὐτῶν ἀποδεδειλιακότας τοὺς ὄχλους βουλεύσασθαι μὴ κρίνειν διὰ μάχης τὰ πράγματα· τοὺς δὲ Ῥωμαίους ἑπομένους αὐτοῖς οὐ μόνον τὴν χώραν πορθεῖν τῶν Καρχηδονίων καὶ Συρακοσίων, ἀλλὰ καὶ τὰς Συρακούσας αὐτὰς προσκαθίσαντας ἐπιβαλέσθαι πολιορκεῖν. ταῦτα δ’, ὡς ἐμοὶ δοκεῖ, τῆς πάσης ἐστὶν ἀλογίας πλήρη καὶ διαστολῆς οὐ προσδεῖται τὸ παράπαν. οὓς μὲν γὰρ πολιορκοῦντας τὴν Μεσσήνην καὶ νικῶντας ἐν ταῖς συμπλοκαῖς ὑπέθετο, τούτους φεύγοντας καὶ τῶν ὑπαίθρων ἐκχωροῦντας καὶ τέλος πολιορκουμένους καὶ ταῖς ψυχαῖς ἀποδεδειλιακότας ἀπέφηνεν· οὓς δ’ ἡττωμένους καὶ πολιορκουμένους ὑπεστήσατο, τούτους διώκοντας καὶ παραχρῆμα κρατοῦντας τῶν ὑπαίθρων καὶ τέλος πολιορκοῦντας τὰς Συρακούσας ἀπέδειξε. ταῦτα δὲ συνᾴδειν ἀλλήλοις οὐδαμῶς δύναται· πῶς γάρ; ἀλλ’ ἀναγκαῖον ἢ τὰς ὑποθέσεις εἶναι τὰς πρώτας ψευδεῖς ἢ τὰς ὑπὲρ τῶν συμβαινόντων ἀποφάσεις. εἰσὶ δ’ αὗται μὲν ἀληθεῖς· καὶ γὰρ ἐξεχώρησαν οἱ Καρχηδόνιοι καὶ Συρακόσιοι τῶν ὑπαίθρων, καὶ τὰς Συρακούσας ἐπολέμουν οἱ Ῥωμαῖοι κατὰ πόδας, ὡς δ’ οὗτός φησι, καὶ τὴν Ἐχέτλαν, ἐν μέσῃ κειμένην τῇ τῶν Συρακοσίων καὶ Καρχηδονίων ἐπαρχίᾳ. λοιπὸν ἀνάγκη συγχωρεῖν τὰς ἀρχὰς καὶ τὰς ὑποθέσεις εἶναι ψευδεῖς, καὶ νικώντων εὐθέως τῶν Ῥωμαίων ἐν ταῖς περὶ τὴν Μεσσήνην συμπλοκαῖς ἡττημένους αὐτοὺς ἡμῖν ὑπὸ τοῦ συγγραφέως ἀπηγγέλθαι. Φιλῖνον μὲν οὖν παρ’ ὅλην ἄν τις τὴν πραγματείαν εὕροι τοιοῦτον ὄντα, παραπλησίως δὲ καὶ Φάβιον, ὡς ἐπ’ αὐτῶν δειχθήσεται τῶν καιρῶν. ἡμεῖς δ’ ἐπειδὴ τοὺς ἁρμόζοντας πεποιήμεθα λόγους ὑπὲρ τῆς παρεκβάσεως, ἐπανελθόντες ἐπὶ τὰς πράξεις πειρασόμεθα προστιθέντες ἀεὶ τὸν ἑξῆς λόγον εἰς ἀληθινὰς ἐννοίας ἄγειν διὰ βραχέων τοὺς ἐντυγχάνοντας ὑπὲρ τοῦ προειρημένου πολέμου.", "st": "1.15"}, {"sp": "N", "t": "προσπεσόντων γὰρ εἰς τὴν Ῥώμην ἐκ τῆς Σικελίας τῶν περὶ τὸν Ἄππιον καὶ τὰ στρατόπεδα προτερημάτων, καταστήσαντες ὑπάτους Μάνιον Ὀτακίλιον καὶ Μάνιον Οὐαλέριον τάς τε δυνάμεις ἁπάσας ἐξαπέστελλον καὶ τοὺς στρατηγοὺς ἀμφοτέρους εἰς τὴν Σικελίαν. ἔστι δὲ παρὰ Ῥωμαίοις τὰ πάντα τέτταρα στρατόπεδα Ῥωμαϊκὰ χωρὶς τῶν συμμάχων, ἃ κατ’ ἐνιαυτὸν προχειρίζονται· τούτων ἕκαστον ἀνὰ τετρακισχιλίους πεζούς, ἱππεῖς δὲ τριακοσίους. ὧν παραγενομένων ἀπό τε τῶν Καρχηδονίων αἱ πλείους ἀφιστάμεναι πόλεις προσετίθεντο τοῖς Ῥωμαίοις ἀπό τε τῶν Συρακοσίων. ὁ δ’ Ἱέρων θεωρῶν τὴν διατροπὴν καὶ κατάπληξιν τῶν Σικελιωτῶν, ἅμα δὲ τὸ πλῆθος καὶ τὸ βάρος τῶν Ῥωμαϊκῶν στρατοπέδων, ἐκ πάντων συνελογίζετο τούτων ἐπικυδεστέρας εἶναι τὰς τῶν Ῥωμαίων ἢ τὰς τῶν Καρχηδονίων ἐλπίδας. διόπερ ἐπὶ τοῦτο τὸ μέρος ὁρμήσας τοῖς λογισμοῖς διεπέμπετο πρὸς τοὺς στρατηγούς, ὑπὲρ εἰρήνης καὶ φιλίας ποιούμενος τοὺς λόγους. οἱ δὲ Ῥωμαῖοι προσεδέξαντο, καὶ μάλιστα διὰ τὰς χορηγίας· θαλαττοκρατούντων γὰρ τῶν Καρχηδονίων εὐλαβοῦντο μὴ πανταχόθεν ἀποκλεισθῶσι τῶν ἀναγκαίων διὰ τὸ καὶ περὶ τὰ πρὸ τοῦ διαβάντα στρατόπεδα πολλὴν ἔνδειαν γεγονέναι τῶν ἐπιτηδείων. διόπερ ὑπολαβόντες τὸν Ἱέρωνα μεγάλην εἰς τοῦτο τὸ μέρος αὑτοῖς παρέξεσθαι χρείαν ἀσμένως προσεδέξαντο τὴν φιλίαν. ποιησάμενοι δὲ συνθήκας ἐφ’ ᾧ τὰ μὲν αἰχμάλωτα χωρὶς λύτρων ἀποδοῦναι τὸν βασιλέα Ῥωμαίοις, ἀργυρίου δὲ προσθεῖναι τάλαντα τούτοις ἑκατόν, λοιπὸν ἤδη Ῥωμαῖοι μὲν ὡς φίλοις καὶ συμμάχοις ἐχρῶντο τοῖς Συρακοσίοις. ὁ δὲ βασιλεὺς Ἱέρων ὑποστείλας ἑαυτὸν ὑπὸ τὴν Ῥωμαίων σκέπην καὶ χορηγῶν ἀεὶ τούτοις εἰς τὰ κατεπείγοντα τῶν πραγμάτων ἀδεῶς ἐβασίλευε τῶν Συρακοσίων τὸν μετὰ ταῦτα χρόνον, φιλοστεφανῶν καὶ φιλοδοξῶν εἰς τοὺς Ἕλληνας. ἐπιφανέστατος γὰρ δὴ πάντων οὗτος δοκεῖ καὶ πλεῖστον χρόνον ἀπολελαυκέναι τῆς ἰδίας εὐβουλίας ἔν τε τοῖς κατὰ μέρος καὶ τοῖς καθόλου πράγμασιν.", "st": "1.16"}, {"sp": "N", "t": "Ἐπανενεχθεισῶν δὲ τῶν συνθηκῶν εἰς τὴν Ῥώμην, καὶ προσδεξαμένου τοῦ δήμου καὶ κυρώσαντος τὰς πρὸς Ἱέρωνα διαλύσεις, λοιπὸν οὐκέτι πάσας ἔκρινον ἐξαποστέλλειν οἱ Ῥωμαῖοι τὰς δυνάμεις, ἀλλὰ δύο μόνον στρατόπεδα, νομίζοντες ἅμα μὲν κεκουφίσθαι τὸν πόλεμον αὐτοῖς προσκεχωρηκότος τοῦ βασιλέως, ἅμα δὲ μᾶλλον ὑπολαμβάνοντες οὕτως εὐπορήσειν τὰς δυνάμεις τοῖς ἀναγκαίοις. οἱ δὲ Καρχηδόνιοι θεωροῦντες τὸν μὲν Ἱέρωνα πολέμιον αὑτοῖς γεγονότα, τοὺς δὲ Ῥωμαίους ὁλοσχερέστερον ἐμπλεκομένους εἰς τὰ κατὰ τὴν Σικελίαν ὑπέλαβον βαρυτέρας προσδεῖσθαι παρασκευῆς, δι’ ἧς ἀντοφθαλμεῖν δυνήσονται τοῖς πολεμίοις καὶ συνέχειν τὰ κατὰ τὴν Σικελίαν. διὸ καὶ ξενολογήσαντες ἐκ τῆς ἀντιπέρας χώρας πολλοὺς μὲν Λιγυστίνους καὶ Κελτούς, ἔτι δὲ πλείους τούτων Ἴβηρας, ἅπαντας εἰς τὴν Σικελίαν ἀπέστειλαν. ὁρῶντες δὲ τὴν τῶν Ἀκραγαντίνων πόλιν εὐφυεστάτην οὖσαν πρὸς τὰς παρασκευὰς καὶ βαρυτάτην ἅμα τῆς αὑτῶν ἐπαρχίας εἰς ταύτην συνήθροισαν τά τε χορήγια καὶ τὰς δυνάμεις, ὁρμητηρίῳ κρίνοντες χρῆσθαι ταύτῃ τῇ πόλει πρὸς τὸν πόλεμον. τῶν δὲ Ῥωμαίων οἱ μὲν πρὸς τὸν Ἱέρωνα ποιησάμενοι στρατηγοὶ τὰς συνθήκας ἀνακεχωρήκεισαν· οἱ δὲ μετὰ τούτους κατασταθέντες Λεύκιος Ποστόμιος καὶ Κόιντος Μαμίλιος ἧκον εἰς τὴν Σικελίαν μετὰ τῶν στρατοπέδων. θεωροῦντες δὲ τὴν τῶν Καρχηδονίων ἐπιβολὴν καὶ τὰς περὶ τὸν Ἀκράγαντα παρασκευὰς ἔγνωσαν τολμηρότερον ἐγχειρεῖν τοῖς πράγμασιν· διὸ καὶ τὰ μὲν ἄλλα μέρη τοῦ πολέμου παρῆκαν, φέροντες δὲ παντὶ τῷ στρατεύματι πρὸς αὐτὸν Ἀκράγαντα προσήρεισαν· καὶ στρατοπεδεύσαντες ἐν ὀκτὼ σταδίοις ἀπὸ τῆς πόλεως συνέκλεισαν ἐντὸς τειχῶν τοὺς Καρχηδονίους. ἀκμαζούσης δὲ τῆς τοῦ σίτου συναγωγῆς, καὶ προφαινομένης χρονίου πολιορκίας, ὥρμησαν ἐκθυμότερον τοῦ δέοντος οἱ στρατιῶται πρὸς τὸ σιτολογεῖν. οἱ δὲ Καρχηδόνιοι κατιδόντες τοὺς πολεμίους ἐσκεδασμένους κατὰ τῆς χώρας, ἐξελθόντες ἐπέθεντο τοῖς σιτολογοῦσιν. τρεψάμενοι δὲ τούτους ῥᾳδίως οἱ μὲν ἐπὶ τὴν τοῦ χάρακος ἁρπαγὴν ὥρμησαν, οἱ δ’ ἐπὶ τὰς ἐφεδρείας. ἀλλ’ ἡ τῶν ἐθισμῶν διαφορὰ καὶ τότε καὶ πολλάκις ἤδη σέσωκε τὰ Ῥωμαίων πράγματα. τὸ γὰρ πρόστιμον παρ’ αὐτοῖς θάνατός ἐστι τῷ προεμένῳ τὸν τόπον καὶ φυγόντι τὸ παράπαν ἐξ ἐφεδρείας. διὸ καὶ τότε πολλαπλασίους ὄντας τοὺς ὑπεναντίους ὑποστάντες γενναίως πολλοὺς μὲν τῶν ἰδίων ἀπέβαλον, ἔτι δὲ πλείους τῶν ἐχθρῶν ἀπέκτειναν. τέλος δὲ κυκλώσαντες τοὺς πολεμίους ὅσον οὔπω διασπῶντας τὸν χάρακα, τοὺς μὲν αὐτῶν διέφθειραν, τοὺς δὲ λοιποὺς ἐπικείμενοι καὶ φονεύοντες συνεδίωξαν εἰς τὴν πόλιν.", "st": "1.17"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα συνέβη τοὺς μὲν Καρχηδονίους εὐλαβέστερον διακεῖσθαι πρὸς τὰς ἐπιθέσεις, τοὺς δὲ Ῥωμαίους φυλακτικώτερον χρῆσθαι ταῖς προνομαῖς. ἐπεὶ δ’ οὐκ ἀντεξῄεσαν οἱ Καρχηδόνιοι πλὴν ἕως ἀκροβολισμοῦ, διελόντες οἱ στρατηγοὶ τῶν Ῥωμαίων εἰς δύο μέρη τὴν δύναμιν τῷ μὲν ἑνὶ περὶ τὸ πρὸ τῆς πόλεως Ἀσκληπιεῖον ἔμενον, θατέρῳ δὲ κατεστρατοπέδευσαν ἐν τοῖς πρὸς Ἡράκλειαν κεκλιμένοις μέρεσιν τῆς πόλεως. τὰ δὲ μεταξὺ τῶν στρατοπέδων ἐξ ἑκατέρου τοῦ μέρους τῆς πόλεως ὠχυρώσαντο καὶ τὴν μὲν ἐντὸς αὐτῶν τάφρον προεβάλοντο χάριν τῆς πρὸς τοὺς ἐξιόντας ἐκ τῆς πόλεως ἀσφαλείας, τὴν δ’ ἐκτὸς αὐτῶν περιεβάλοντο, φυλακὴν ποιούμενοι τῶν ἔξωθεν ἐπιθέσεων καὶ τῶν παρεισάγεσθαι καὶ παρεισπίπτειν εἰωθότων εἰς τὰς πολιορκουμένας πόλεις. τὰ δὲ μεταξὺ τῶν τάφρων καὶ τῶν στρατοπέδων διαστήματα φυλακαῖς διέλαβον, ὀχυροποιησάμενοι τοὺς εὐκαίρους τῶν τόπων ἐν διαστάσει. τὰ δὲ χορήγια καὶ τὴν ἄλλην παρασκευὴν οἱ μὲν ἄλλοι σύμμαχοι πάντες ἥθροιζον αὐτοῖς καὶ παρῆγον εἰς Ἑρβησόν, αὐτοὶ δ’ ἐκ ταύτης τῆς πόλεως οὐ μακρὰν ὑπαρχούσης ἄγοντες καὶ φέροντες συνεχῶς τὰς ἀγορὰς δαψιλῆ τἀναγκαῖα σφίσι παρεσκεύαζον. πέντε μὲν οὖν ἴσως μῆνας ἐπὶ τῶν αὐτῶν διέμενον, οὐδὲν ὁλοσχερὲς προτέρημα δυνάμενοι λαβεῖν κατ’ ἀλλήλων πλὴν τῶν ἐν αὐτοῖς τοῖς ἀκροβολισμοῖς συμβαινόντων. συναγομένων δὲ τῷ λιμῷ τῶν Καρχηδονίων διὰ τὸ πλῆθος τῶν ἐν τῇ πόλει συγκεκλεισμένων ἀνδρῶν — οὐ γὰρ ἐλάττους πέντε μυριάδων ὑπῆρχον — δυσχρηστούμενος Ἀννίβας ἤδη τοῖς πράγμασιν, ὁ τεταγμένος ἐπὶ τῶν πολιορκουμένων δυνάμεων, διεπέμπετο συνεχῶς εἰς τὴν Καρχηδόνα τήν τε περίστασιν διασαφῶν καὶ βοηθεῖν παρακαλῶν. οἱ δ’ ἐν τῇ Καρχηδόνι τῶν ἐπισυνηγμένων στρατιωτῶν καὶ θηρίων γεμίσαντες τὰς ναῦς ἐξέπεμψαν εἰς τὴν Σικελίαν πρὸς Ἄννωνα τὸν ἕτερον στρατηγόν. ὃς συναγαγὼν τὰς παρασκευὰς καὶ δυνάμεις εἰς Ἡράκλειαν πρῶτον μὲν πραξικοπήσας κατέσχε τὴν τῶν Ἑρβησέων πόλιν καὶ παρείλετο τὰς ἀγορὰς καὶ τὴν τῶν ἀναγκαίων χορηγίαν τοῖς τῶν ὑπεναντίων στρατοπέδοις. ἐξ οὗ συνέβη τοὺς Ῥωμαίους ἐπ’ ἴσου πολιορκεῖν καὶ πολιορκεῖσθαι τοῖς πράγμασιν. εἰς γὰρ τοῦτο συνήγοντο τῇ σιτοδείᾳ καὶ σπάνει τῶν ἀναγκαίων ὥστε πολλάκις βουλεύεσθαι περὶ τοῦ λύειν τὴν πολιορκίαν. ὃ δὴ καὶ τέλος ἂν ἐποίησαν, εἰ μὴ πᾶσαν σπουδὴν καὶ μηχανὴν προσφερόμενος Ἱέρων τὰ μέτρια καὶ τἀναγκαῖα σφίσι παρεσκεύαζε τῶν χορηγίων.", "st": "1.18"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα θεωρῶν ὁ προειρημένος ἀνὴρ τοὺς μὲν Ῥωμαίους ὑπό τε τῆς νόσου καὶ τῆς ἐνδείας ἀσθενῶς διακειμένους διὰ τὸ λοιμικὴν εἶναι παρ’ αὐτοῖς κατάστασιν, τὰ δὲ σφέτερα στρατόπεδα νομίζων ἀξιόχρεα πρὸς μάχην ὑπάρχειν, ἀναλαβὼν τά τε θηρία περὶ πεντήκοντα τὸν ἀριθμὸν ὄντα καὶ τὴν λοιπὴν δύναμιν ἅπασαν προῆγε κατὰ σπουδὴν ἐκ τῆς Ἡρακλείας, παραγγείλας τοῖς Νομαδικοῖς ἱππεῦσι προπορεύεσθαι καὶ συνεγγίσασι τῷ χάρακι τῶν ἐναντίων ἐρεθίζειν καὶ πειρᾶσθαι τοὺς ἱππεῖς αὐτῶν ἐκκαλεῖσθαι, κἄπειτα πάλιν ἐκκλίνασιν ἀποχωρεῖν, ἕως ἂν αὐτῷ συμμίξωσι. πραξάντων δὲ τὸ συνταχθὲν τῶν Νομάδων καὶ προσμιξάντων θατέρῳ τῶν στρατοπέδων, εὐθὺς οἱ τῶν Ῥωμαίων ἱππεῖς ἐξεχέοντο καὶ θρασέως ἐπέκειντο τοῖς Νομάσιν. οἱ δὲ Λίβυες ὑπεχώρουν κατὰ τὸ παράγγελμα, μέχρι συνέμιξαν τοῖς περὶ τὸν Ἄννωνα· λοιπόν τ’ ἐκ μεταβολῆς περιχυθέντες ἐπέκειντο τοῖς πολεμίοις καὶ πολλοὺς μὲν αὐτῶν ἀπέκτειναν, τοὺς δὲ λοιποὺς ἕως εἰς τὸν χάρακα συνεδίωξαν. γενομένων δὲ τούτων ἐπεστρατοπέδευσαν οἱ περὶ τὸν Ἄννωνα τοῖς Ῥωμαίοις, καταλαβόμενοι τὸν λόφον τὸν καλούμενον Τόρον, ὡς δέκα σταδίους ἀπέχοντες τῶν ὑπεναντίων. καὶ δύο μὲν μῆνας ἔμενον ἐπὶ τῶν ὑποκειμένων, οὐδὲν ὁλοσχερὲς πράττοντες πλὴν ἀκροβολιζόμενοι καθ’ ἑκάστην ἡμέραν. τοῦ δ’ Ἀννίβου διαπυρσευομένου καὶ διαπεμπομένου συνεχῶς ἐκ τῆς πόλεως πρὸς τὸν Ἄννωνα καὶ δηλοῦντος ὅτι τὰ πλήθη τὸν λιμὸν οὐχ ὑπομένει, πολλοὶ δὲ καὶ πρὸς τοὺς πολεμίους αὐτομολοῦσι διὰ τὴν ἔνδειαν, ἔγνω διακινδυνεύειν ὁ τῶν Καρχηδονίων στρατηγός, οὐχ ἧττον ἐπὶ τοῦτο φερομένων καὶ τῶν Ῥωμαίων διὰ τὰς προειρημένας αἰτίας. διόπερ ἐξαγαγόντες ἀμφότεροι τὰς δυνάμεις εἰς τὸν μεταξὺ τόπον τῶν στρατοπέδων συνέβαλλον ἀλλήλοις. ἐπὶ πολὺν δὲ χρόνον γενομένης τῆς μάχης τέλος ἐτρέψαντο τοὺς προκινδυνεύσαντας μισθοφόρους τῶν Καρχηδονίων οἱ Ῥωμαῖοι. τούτων δὲ πεσόντων εἰς τὰ θηρία καὶ τὰς λοιπὰς τάξεις τὰς ἐφεστηκυίας συνέβη πᾶν συνταραχθῆναι τὸ τῶν Φοινίκων στρατόπεδον. γενομένου δ’ ἐγκλίματος ὁλοσχεροῦς οἱ μὲν πλεῖστοι διεφθάρησαν αὐτῶν, τινὲς δ’ εἰς Ἡράκλειαν ἀπεχώρησαν· οἱ δὲ Ῥωμαῖοι τῶν τε πλείστων ἐκυρίευσαν θηρίων καὶ τῆς ἐπισκευῆς ἁπάσης. ἐπιγενομένης δὲ τῆς νυκτός, καὶ διὰ τὴν ἐκ τῶν κατορθωμάτων χαρὰν καὶ διὰ τὸν κόπον ῥᾳθυμότερον ταῖς φυλακαῖς αὐτῶν χρησαμένων, ἀπελπίσας Ἀννίβας τὰ πράγματα καὶ νομίσας ἔχειν εὐφυῆ καιρὸν πρὸς σωτηρίαν διὰ τὰς προειρημένας αἰτίας, ὥρμησε περὶ μέσας νύκτας ἐκ τῆς πόλεως, ἔχων τὰς ξενικὰς δυνάμεις. χώσας δὲ φορμοῖς ἀχύρων σεσαγμένοις τὰς τάφρους ἔλαθε τοὺς πολεμίους ἀπαγαγὼν ἀσφαλῶς τὴν δύναμιν. οἱ δὲ Ῥωμαῖοι τῆς ἡμέρας ἐπελθούσης συνέντες τὸ γεγονὸς καὶ τῆς οὐραγίας τῆς τῶν περὶ τὸν Ἀννίβαν ἐπὶ βραχὺ καθαψάμενοι μετὰ ταῦτα πάντες ὥρμησαν πρὸς τὰς πύλας. οὐδενὸς δ’ ἐμποδὼν αὐτοῖς ἱσταμένου, παρεισπεσόντες διήρπασαν τὴν πόλιν καὶ πολλῶν μὲν σωμάτων, πολλῆς δὲ καὶ παντοδαπῆς ἐγένοντο κατασκευῆς ἐγκρατεῖς.", "st": "1.19"}, {"sp": "N", "t": "τῆς δ’ ἀγγελίας ἀφικομένης εἰς τὴν σύγκλητον τῶν Ῥωμαίων ὑπὲρ τῶν κατὰ τὸν Ἀκράγαντα, περιχαρεῖς γενόμενοι καὶ ταῖς διανοίαις ἐπαρθέντες οὐκ ἔμενον ἐπὶ τῶν ἐξ ἀρχῆς λογισμῶν οὐδ’ ἠρκοῦντο σεσωκέναι τοὺς Μαμερτίνους οὐδὲ ταῖς ἐξ αὐτοῦ τοῦ πολέμου γενομέναις ὠφελείαις, ἐλπίσαντες δὲ καθόλου δυνατὸν εἶναι τοὺς Καρχηδονίους ἐκβαλεῖν ἐκ τῆς νήσου, τούτου δὲ γενομένου μεγάλην ἐπίδοσιν αὑτῶν λήψεσθαι τὰ πράγματα, πρὸς τούτοις ἦσαν τοῖς λογισμοῖς καὶ ταῖς περὶ τοῦτο τὸ μέρος ἐπινοίαις. τὰ μὲν οὖν περὶ τὰς πεζικὰς δυνάμεις ἑώρων κατὰ λόγον σφίσι προχωροῦντα· μετὰ γὰρ τοὺς τὸν Ἀκράγαντα πολιορκήσαντας οἱ κατασταθέντες στρατηγοὶ Λεύκιος Οὐαλέριος καὶ Τίτος Ὀτακίλιος ἐδόκουν ἐνδεχομένως χειρίζειν τὰ κατὰ τὴν Σικελίαν. τῆς δὲ θαλάττης ἀκονιτὶ τῶν Καρχηδονίων ἐπικρατούντων ἐζυγοστατεῖτ’ αὐτοῖς ὁ πόλεμος· ἐν γὰρ τοῖς ἑξῆς χρόνοις, κατεχόντων αὐτῶν ἤδη τὸν Ἀκράγαντα, πολλαὶ μὲν πόλεις προσετίθεντο τῶν μεσογαίων τοῖς Ῥωμαίοις, ἀγωνιῶσαι τὰς πεζικὰς δυνάμεις, ἔτι δὲ πλείους ἀφίσταντο τῶν παραθαλαττίων, καταπεπληγμέναι τὸν τῶν Καρχηδονίων στόλον. ὅθεν ὁρῶντες αἰεὶ καὶ μᾶλλον εἰς ἑκάτερα τὰ μέρη ῥοπὰς λαμβάνοντα τὸν πόλεμον διὰ τὰς προειρημένας αἰτίας, ἔτι δὲ τὴν μὲν Ἰταλίαν πορθουμένην πολλάκις ὑπὸ τῆς ναυτικῆς δυνάμεως, τὴν δὲ Λιβύην εἰς τέλος ἀβλαβῆ διαμένουσαν, ὥρμησαν ἐπὶ τὸ συνεμβαίνειν τοῖς Καρχηδονίοις εἰς τὴν θάλατταν. διὸ καὶ τοῦτο τὸ μέρος οὐχ ἥκιστά με παρώρμησεν ποιήσασθαι μνήμην ἐπὶ πλεῖον τοῦ προειρημένου πολέμου χάριν τοῦ μηδὲ ταύτην ἀγνοεῖσθαι τὴν ἀρχήν, πῶς καὶ πότε καὶ δι’ ἃς αἰτίας πρῶτον ἐνέβησαν εἰς θάλατταν Ῥωμαῖοι. θεωροῦντες δὲ τὸν πόλεμον αὑτοῖς τριβὴν λαμβάνοντα, τότε πρῶτον ἐπεβάλοντο ναυπηγεῖσθαι σκάφη, πεντηρικὰ μὲν ἑκατόν, εἴκοσι δὲ τριήρεις. τῶν δὲ ναυπηγῶν εἰς τέλος ἀπείρων ὄντων τῆς περὶ τὰς πεντήρεις ναυπηγίας διὰ τὸ μηδένα τότε τῶν κατὰ τὴν Ἰταλίαν κεχρῆσθαι τοιούτοις σκάφεσιν, πολλὴν αὐτοῖς παρεῖχεν τοῦτο τὸ μέρος δυσχέρειαν. ἐξ ὧν καὶ μάλιστα συνίδοι τις ἂν τὸ μεγαλόψυχον καὶ παράβολον τῆς Ῥωμαίων αἱρέσεως. οὐ γὰρ οἷον εὐλόγους ἀφορμὰς ἔχοντες, ἀλλ’ οὐδ’ ἀφορμὰς καθάπαξ οὐδ’ ἐπίνοιαν οὐδέποτε ποιησάμενοι τῆς θαλάττης, τότε δὴ πρῶτον ἐν νῷ λαμβάνοντες οὕτως τολμηρῶς ἐνεχείρησαν ὥστε πρὶν ἢ πειραθῆναι τοῦ πράγματος, εὐθὺς ἐπιβαλέσθαι Καρχηδονίοις ναυμαχεῖν τοῖς ἐκ προγόνων ἔχουσι τὴν κατὰ θάλατταν ἡγεμονίαν ἀδήριτον. μαρτυρίῳ δ’ ἄν τις χρήσαιτο πρὸς τὴν ἀλήθειαν τῶν νῦν ὑπ’ ἐμοῦ λεγομένων καὶ πρὸς τὸ παράδοξον αὐτῶν τῆς τόλμης· ὅτε γὰρ τὸ πρῶτον ἐπεχείρησαν διαβιβάζειν εἰς τὴν Μεσσήνην τὰς δυνάμεις, οὐχ οἷον κατάφρακτος αὐτοῖς ὑπῆρχεν ναῦς, ἀλλ’ οὐδὲ καθόλου μακρὸν πλοῖον οὐδὲ λέμβος οὐδ’ εἷς, ἀλλὰ παρὰ Ταραντίνων καὶ Λοκρῶν ἔτι δ’ Ἐλεατῶν καὶ Νεαπολιτῶν συγχρησάμενοι πεντηκοντόρους καὶ τριήρεις ἐπὶ τούτων παραβόλως διεκόμισαν τοὺς ἄνδρας. ἐν ᾧ δὴ καιρῷ τῶν Καρχηδονίων κατὰ τὸν πορθμὸν ἐπαναχθέντων αὐτοῖς, καὶ μιᾶς νεὼς καταφράκτου διὰ τὴν προθυμίαν προπεσούσης, ὥστ’ ἐποκείλασαν γενέσθαι τοῖς Ῥωμαίοις ὑποχείριον, ταύτῃ παραδείγματι χρώμενοι τότε πρὸς ταύτην ἐποιοῦντο τὴν τοῦ παντὸς στόλου ναυπηγίαν, ὡς εἰ μὴ τοῦτο συνέβη γενέσθαι, δῆλον ὡς διὰ τὴν ἀπειρίαν εἰς τέλος ἂν ἐκωλύθησαν τῆς ἐπιβολῆς.", "st": "1.20"}, {"sp": "N", "t": "οὐ μὲν ἀλλ’ οἷς μὲν ἐπιμελὲς ἦν τῆς ναυπηγίας, ἐγίνοντο περὶ τὴν τῶν πλοίων κατασκευήν, οἱ δὲ τὰ πληρώματα συναθροίσαντες ἐδίδασκον ἐν τῇ γῇ κωπηλατεῖν τὸν τρόπον τοῦτον· καθίσαντες ἐπὶ τῶν εἰρεσιῶν ἐν τῇ χέρσῳ τοὺς ἄνδρας τὴν αὐτὴν ἔχοντας τάξιν ταῖς ἐπ’ αὐτῶν τῶν πλοίων καθέδραις, μέσον δ’ ἐν αὐτοῖς στήσαντες τὸν κελευστήν, ἅμα πάντας ἀναπίπτειν ἐφ’ αὑτοὺς ἄγοντας τὰς χεῖρας καὶ πάλιν προνεύειν ἐξωθοῦντας ταύτας συνείθιζον ἄρχεσθαί τε καὶ λήγειν τῶν κινήσεων πρὸς τὰ τοῦ κελευστοῦ παραγγέλματα. προκατασκευασθέντων δὲ τούτων, ἅμα τῷ συντελεσθῆναι τὰς ναῦς καθελκύσαντες καὶ βραχὺν χρόνον ἐπ’ αὐτῆς τῆς ἀληθείας ἐν θαλάττῃ πειραθέντες ἔπλεον παρὰ τὴν Ἰταλίαν κατὰ τὸ πρόσταγμα τοῦ στρατηγοῦ. ὁ γὰρ ἐπὶ τῆς ναυτικῆς δυνάμεως τεταγμένος τοῖς Ῥωμαίοις Γνάιος Κορνήλιος ὀλίγαις ἡμέραις πρότερον, συντάξας τοῖς ναυάρχοις, ἐπειδὰν καταρτίσωσι τὸν στόλον, πλεῖν ὡς ἐπὶ τὸν πορθμόν, αὐτὸς ἀναχθεὶς μετὰ νεῶν ἑπτακαίδεκα προκατέπλευσεν ἐπὶ τὴν Μεσσήνην, σπουδάζων τὰ κατεπείγοντα πρὸς τὴν χρείαν παρασκευάσαι τῷ στόλῳ. προσπεσούσης δ’ αὐτῷ πράξεως ἐκεῖ περὶ τῆς τῶν Λιπαραίων πόλεως, δεξάμενος τὴν ἐλπίδα προχειρότερον τοῦ δέοντος ἔπλει ταῖς προειρημέναις ναυσὶ καὶ καθωρμίσθη πρὸς τὴν πόλιν. ὁ δὲ τῶν Καρχηδονίων στρατηγὸς Ἀννίβας, ἀκούσας ἐν τῷ Πανόρμῳ τὸ γεγονὸς ἐξαποστέλλει Βοώδη τῆς γερουσίας ὑπάρχοντα, ναῦς εἴκοσι δούς. ὃς ἐπιπλεύσας νυκτὸς ἐν τῷ λιμένι συνέκλεισε τοὺς περὶ τὸν Γνάιον. ἡμέρας δ’ ἐπιγενομένης τὰ μὲν πληρώματα πρὸς φυγὴν ὥρμησεν εἰς τὴν γῆν, ὁ δὲ Γνάιος ἐκπλαγὴς γενόμενος καὶ ποιεῖν ἔχων οὐδὲν τέλος παρέδωκεν αὑτὸν τοῖς πολεμίοις. οἱ δὲ Καρχηδόνιοι τάς τε ναῦς καὶ τὸν στρατηγὸν τῶν ὑπεναντίων ὑποχείριον ἔχοντες παραχρῆμα πρὸς τὸν Ἀννίβαν ἀπῆραν. μετ’ οὐ πολλὰς δ’ ἡμέρας, οὕτως ἐναργοῦς ὄντος καὶ προσφάτου τοῦ περὶ τὸν Γνάιον ἀτυχήματος, παρ’ ὀλίγον αὐτὸς Ἀννίβας εἰς τὸ παραπλήσιον ἁμάρτημα προφανῶς ἐνέπεσεν. ἀκούσας γὰρ τὸν τῶν Ῥωμαίων στόλον κομιζόμενον παρὰ τὴν Ἰταλίαν σύνεγγυς εἶναι, κατιδεῖν βουλόμενος τό τε πλῆθος καὶ τὴν ὅλην σύνταξιν τῶν ὑπεναντίων, λαβὼν πεντήκοντα ναῦς ἐπιπλεῖ. κάμπτων δὲ περὶ τὸ τῆς Ἰταλίας ἀκρωτήριον ἐμπίπτει τοῖς πολεμίοις ἐν κόσμῳ καὶ τάξει ποιουμένοις τὸν πλοῦν καὶ τὰς μὲν πλείους ἀπέβαλε τῶν νεῶν, αὐτὸς δὲ μετὰ τῶν ὑπολειφθεισῶν ἀνελπίστως καὶ παραδόξως διέφυγεν.", "st": "1.21"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι μετὰ ταῦτα συνεγγίσαντες τοῖς κατὰ τὴν Σικελίαν τόποις καὶ συνέντες τὸ γεγονὸς σύμπτωμα περὶ τὸν Γνάιον παραυτίκα μὲν διεπέμποντο πρὸς Γάιον Βίλιον τὸν ἡγούμενον τῆς πεζῆς δυνάμεως καὶ τοῦτον ἀνέμενον, ἅμα δ’ ἀκούοντες οὐ μακρὰν εἶναι τὸν τῶν πολεμίων στόλον ἐγίνοντο πρὸς παρασκευὴν τοῦ ναυμαχεῖν. ὄντων δὲ τῶν πλοίων φαύλων ταῖς κατασκευαῖς καὶ δυσκινήτων, ὑποτίθεταί τις αὐτοῖς βοήθημα πρὸς τὴν μάχην τοὺς ἐπικληθέντας μετὰ ταῦτα κόρακας ὧν συνέβαινε τὴν κατασκευὴν εἶναι τοιαύτην. στῦλος ἐν πρώρρᾳ στρογγύλος εἱστήκει, μῆκος μὲν ὀργυιῶν τεττάρων, κατὰ δὲ τὸ πλάτος τριῶν παλαιστῶν ἔχων τὴν διάμετρον. οὗτος αὐτὸς μὲν ἐπὶ τῆς κορυφῆς τροχιλίαν εἶχεν, περιετίθετο δ’ αὐτῷ κλῖμαξ ἐπικαρσίαις σανίσι καθηλωμένη, πλάτος μὲν ποδῶν τεττάρων, τὸ δὲ μῆκος ἓξ ὀργυιῶν. τὸ δὲ τρῆμα τοῦ σανιδώματος ἦν παράμηκες καὶ περιέβαινε περὶ τὸν στῦλον μετὰ τὰς πρώτας εὐθέως τῆς κλίμακος δύ’ ὀργυιάς. εἶχεν δὲ καὶ δρύφακτον αὕτη παρ’ ἑκατέραν τὴν ἐπιμήκη πλευρὰν εἰς γόνυ τὸ βάθος. ἐπὶ δὲ τοῦ πέρατος αὐτοῦ προσήρμοστο σιδηροῦν οἷον ὕπερον ἀπωξυσμένον, ἔχον δακτύλιον ἐπὶ τῆς κορυφῆς, ὡς τὸ ὅλον φαίνεσθαι παραπλήσιον ταῖς σιτοποιικαῖς μηχανήσεσιν. εἰς δὲ τοῦτον τὸν δακτύλιον ἐνεδέδετο κάλως, ᾧ κατὰ τὰς ἐμβολὰς τῶν πλοίων ἐξαίροντες τοὺς κόρακας διὰ τῆς ἐν τῷ στύλῳ τροχιλίας ἀφίεσαν ἐπὶ τὸ κατάστρωμα τῆς ἀλλοτρίας νεὼς ποτὲ μὲν κατὰ πρῶρραν, ποτὲ δ’ ἀντιπεριάγοντες τὰς ἐκ τῶν πλαγίων προσπιπτούσας ἐμβολάς. ὅτε δὲ ταῖς σανίσι τῶν καταστρωμάτων ἐμπαγέντες οἱ κόρακες ὁμοῦ συνδήσαιεν τὰς ναῦς, εἰ μὲν πλάγιαι παραβάλοιεν ἀλλήλαις, πανταχόθεν ἐπεπήδων, εἰ δὲ κατὰ πρῶρραν, δι’ αὐτοῦ τοῦ κόρακος ἐπὶ δύο συνεχεῖς ἐποιοῦντο τὴν ἔφοδον· ὧν οἱ μὲν ἡγούμενοι τὴν κατὰ πρόσωπον ἐπιφάνειαν ἐσκέπαζον ταῖς τῶν θυρεῶν προβολαῖς, οἱ δ’ ἑπόμενοι τὰς ἐκ τῶν πλαγίων ἠσφάλιζον πλευρὰς ὑπὲρ τὸν δρύφακτον ὑπερτιθέμενοι τὰς ἴτυς τῶν ὅπλων. οὗτοι μὲν οὖν τοιαύτῃ κεχρημένοι παρασκευῇ καιρὸν ἐπετήρουν πρὸς ναυμαχίαν·", "st": "1.22"}, {"sp": "N", "t": "ὁ δὲ Γάιος Βίλιος ὡς θᾶττον ἔγνω τὴν περιπέτειαν τοῦ τῆς ναυτικῆς δυνάμεως ἡγουμένου, παραδοὺς τὰ πεζικὰ στρατόπεδα τοῖς χιλιάρχοις αὐτὸς διεκομίσθη πρὸς τὸν στόλον. πυθόμενος δὲ τοὺς πολεμίους πορθεῖν τὴν Μυλαῗτιν χώραν ἐπιπλεῖ στόλῳ παντί. συνιδόντες δ’ οἱ Καρχηδόνιοι μετὰ χαρᾶς καὶ σπουδῆς ἀνήγοντο ναυσὶν ἑκατὸν καὶ τριάκοντα, καταφρονοῦντες τῆς ἀπειρίας τῶν Ῥωμαίων, καὶ πάντες ἔπλεον ἀντίπρωρροι τοῖς πολεμίοις, οὐδὲ τάξεως καταξιώσαντες τὸν κίνδυνον, ἀλλ’ ὡς ἐπὶ λείαν τινὰ πρόδηλον. ἡγεῖτο δ’ Ἀννίβας αὐτῶν — οὗτος δ’ ἦν ὁ τὰς δυνάμεις ἐκκλέψας νυκτὸς ἐκ τῆς τῶν Ἀκραγαντίνων πόλεως — ἔχων ἑπτήρη τὴν γενομένην Πύρρου τοῦ βασιλέως. ἅμα δὲ τῷ πλησιάζειν συνθεωροῦντες ἀνανενευκότας τοὺς κόρακας ἐν ταῖς ἑκάστων πρώρραις, ἐπὶ ποσὸν μὲν ἠπόρουν οἱ Καρχηδόνιοι, ξενιζόμενοι ταῖς τῶν ὀργάνων κατασκευαῖς· οὐ μὴν ἀλλὰ τελέως κατεγνωκότες τῶν ἐναντίων ἐνέβαλον οἱ πρῶτοι πλέοντες τετολμηκότως. τῶν δὲ συμπλεκομένων σκαφῶν ἀεὶ δεδεμένων τοῖς ὀργάνοις, καὶ τῶν ἀνδρῶν εὐθὺς ἐπιπορευομένων δι’ αὐτοῦ τοῦ κόρακος καὶ συμπλεκομένων ἐπὶ τοῖς καταστρώμασιν, οἱ μὲν ἐφονεύοντο τῶν Καρχηδονίων, οἱ δὲ παρεδίδοσαν ἑαυτοὺς ἐκπληττόμενοι τὸ γινόμενον· παραπλήσιον γὰρ πεζομαχίας συνέβαινε τὸν κίνδυνον ἀποτελεῖσθαι. διὸ καὶ τριάκοντα μὲν τὰς πρώτας συμβαλούσας ναῦς αὐτάνδρους ἀπέβαλον, σὺν αἷς ἐγένετ’ αἰχμάλωτον καὶ τὸ τοῦ στρατηγοῦ πλοῖον· Ἀννίβας δ’ ἀνελπίστως καὶ παραβόλως αὐτὸς ἐν τῇ σκάφῃ διέφυγεν. τὸ δὲ λοιπὸν πλῆθος τῶν Καρχηδονίων ἐποιεῖτο μὲν τὸν ἐπίπλουν ὡς εἰς ἐμβολήν, ἐν δὲ τῷ συνεγγίζειν θεωροῦντες τὸ συμβεβηκὸς περὶ τὰς προπλεούσας ναῦς ἐξέκλινον καὶ διένευον τὰς τῶν ὀργάνων ἐπιβολάς. πιστεύοντες δὲ τῷ ταχυναυτεῖν, οἱ μὲν ἐκ πλαγίων, οἱ δὲ κατὰ πρύμναν ἐκπεριπλέοντες ἀσφαλῶς ἤλπιζον ποιήσασθαι τὰς ἐμβολάς. πάντη δὲ καὶ πάντως ἀντιπεριισταμένων καὶ συνδιανευόντων τῶν ὀργάνων οὕτως ὥστε κατ’ ἀνάγκην τοὺς ἐγγίσαντας συνδεδέσθαι, τέλος ἐγκλίναντες ἔφυγον οἱ Καρχηδόνιοι, καταπλαγέντες τὴν καινοτομίαν τοῦ συμβαίνοντος, πεντήκοντα ναῦς ἀποβαλόντες.", "st": "1.23"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι παραδόξως ἀντιπεποιημένοι τῆς κατὰ θάλατταν ἐλπίδος, διπλασίως ἐπερρώσθησαν ταῖς ὁρμαῖς πρὸς τὸν πόλεμον. τότε μὲν οὖν προσσχόντες τῇ Σικελίᾳ τήν τ’ Αἰγεσταίων ἔλυσαν πολιορκίαν ἐσχάτως αὐτῶν ἤδη διακειμένων κατά τε τὴν ἐκ τῆς Αἰγέστης ἀναχώρησιν Μάκελλαν πόλιν κατὰ κράτος εἷλον. μετὰ δὲ τὴν ναυμαχίαν Ἀμίλκας, ὁ τῶν Καρχηδονίων στρατηγὸς ὁ τεταγμένος ἐπὶ τῶν πεζικῶν δυνάμεων, διατρίβων περὶ Πάνορμον, γνοὺς ἐν τοῖς Ῥωμαϊκοῖς στρατοπέδοις στασιάζοντας τοὺς συμμάχους πρὸς τοὺς Ῥωμαίους περὶ τῶν ἐν ταῖς μάχαις πρωτείων, καὶ πυνθανόμενος στρατοπεδεύειν αὐτοὺς καθ’ ἑαυτοὺς τοὺς συμμάχους μεταξὺ τοῦ Παρώπου καὶ τῶν Θερμῶν τῶν Ἱμεραίων, ἐπιπεσὼν αὐτοῖς αἰφνιδίως ἀναστρατοπεδεύουσι μετὰ πάσης τῆς δυνάμεως σχεδὸν εἰς τετρακισχιλίους ἀπέκτεινεν. μετὰ δὲ ταύτην τὴν πρᾶξιν ὁ μὲν Ἀννίβας ἔχων τὰς διασωθείσας ναῦς ἀπέπλευσεν εἰς τὴν Καρχηδόνα, μετ’ οὐ πολὺ δ’ ἐκεῖθεν εἰς Σαρδόνα διῆρε, προσλαβὼν ναῦς καί τινας τῶν ἐνδόξων τριηράρχων. χρόνοις δ’ οὐ πολλοῖς κατόπιν ἐν τῇ Σαρδόνι συγκλεισθεὶς ὑπὸ Ῥωμαίων ἔν τινι λιμένι καὶ πολλὰς ἀποβαλὼν τῶν νεῶν, παραυτίκα συλληφθεὶς ὑπὸ τῶν διασωθέντων Καρχηδονίων ἀνεσταυρώθη. Ῥωμαῖοι γὰρ ἅμα τῆς θαλάττης ἥψαντο καὶ τῶν κατὰ Σαρδόνα πραγμάτων εὐθέως ἀντείχοντο. τὰ δ’ ἐν τῇ Σικελίᾳ στρατόπεδα τῶν Ῥωμαίων κατὰ μὲν τὸν ἑξῆς ἐνιαυτὸν οὐδὲν ἄξιον ἔπραξαν λόγου, τότε δὲ προσδεξάμενοι τοὺς ἐπικαθεσταμένους ἄρχοντας Αὖλον Ἀτίλιον καὶ Γάιον Σολπίκιον ὥρμησαν ἐπὶ τὸν Πάνορμον διὰ τὸ τὰς τῶν Καρχηδονίων δυνάμεις ἐκεῖ παραχειμάζειν. οἱ δὲ στρατηγοὶ συνεγγίσαντες τῇ πόλει μετὰ πάσης τῆς δυνάμεως παρετάξαντο. τῶν δὲ πολεμίων οὐκ ἀντεξιόντων, πάλιν ἐντεῦθεν ἐποιήσαντο τὴν ὁρμὴν ἐπὶ πόλιν Ἱππάναν, καὶ ταύτην μὲν ἐξ ἐφόδου κατὰ κράτος ἔλαβον, εἷλον δὲ καὶ τὸ Μυττίστρατον, πολλοὺς χρόνους ὑπομεμενηκὸς τὴν πολιορκίαν διὰ τὴν ὀχυρότητα τοῦ τόπου. τὴν δὲ Καμαριναίων πόλιν μικρῷ πρότερον ἀπ’ αὐτῶν ἀποστᾶσαν, τότε προσενέγκαντες ἔργα καὶ καταβαλόντες τὰ τείχη κατέσχον· ὁμοίως δὲ καὶ τὴν Ἔνναν καὶ ἕτερα πλείω πολισμάτια τῶν Καρχηδονίων. ἀπὸ δὲ τούτων γενόμενοι Λιπαραίους ἐπεχείρησαν πολιορκεῖν.", "st": "1.24"}, {"sp": "N", "t": "τῷ δ’ ἑξῆς ἐνιαυτῷ Γάιος Ἀτίλιος ὁ στρατηγὸς τῶν Ῥωμαίων πρὸς Τυνδαρίδα καθορμισθεὶς καὶ συνθεασάμενος ἀτάκτως παραπλέοντα τὸν τῶν Καρχηδονίων στόλον, παραγγείλας τοῖς ἰδίοις πληρώμασιν ἕπεσθαι τοῖς ἡγουμένοις, αὐτὸς ὥρμησε πρὸ τῶν ἄλλων, ἔχων δέκα ναῦς ὁμοπλοούσας. οἱ δὲ Καρχηδόνιοι συνιδόντες τῶν ὑπεναντίων τοὺς μὲν ἀκμὴν ἐμβαίνοντας, τοὺς δ’ ἀναγομένους, τοὺς δὲ πρώτους πολὺ προειληφότας τῶν ἄλλων, ἐπιστρέψαντες αὐτοῖς ἀπήντων. καὶ κυκλώσαντες τὰς μὲν ἄλλας διέφθειραν, τὴν δὲ τοῦ στρατηγοῦ ναῦν παρ’ ὀλίγον αὔτανδρον ἔλαβον. οὐ μὴν ἀλλ’ αὕτη μὲν ταῖς ὑπηρεσίαις ἐξηρτυμένη καὶ ταχυναυτοῦσα διέφυγε παραδόξως τὸν κίνδυνον, αἱ δὲ λοιπαὶ τῶν Ῥωμαίων ἐπιπλέουσαι κατὰ βραχὺ συνηθροίζοντο. γενόμεναι δ’ ἐν μετώπῳ συνέβαλλον τοῖς πολεμίοις καὶ δέκα μὲν αὐτάνδρους ναῦς ἔλαβον, ὀκτὼ δὲ κατέδυσαν. αἱ δὲ λοιπαὶ τῶν Καρχηδονίων ἀπεχώρησαν εἰς τὰς Λιπαραίας καλουμένας νήσους. ἐκ δὲ ταύτης τῆς ναυμαχίας ἀμφότεροι νομίζοντες ἐφάμιλλον πεποιῆσθαι τὸν κίνδυνον, ὥρμησαν ὁλοσχερέστερον ἐπὶ τὸ συνίστασθαι ναυτικὰς δυνάμεις καὶ τῶν κατὰ θάλατταν ἀντέχεσθαι πραγμάτων. αἱ δὲ πεζικαὶ δυνάμεις ἐν τοῖς κατὰ ταῦτα καιροῖς οὐδὲν ἔπραξαν ἄξιον μνήμης, ἀλλὰ περὶ μικρὰς καὶ τὰς τυχούσας πράξεις κατέτριψαν τοὺς χρόνους. διὸ παρασκευασάμενοι, καθάπερ εἶπον, εἰς τὴν ἐπιφερομένην θερείαν ἀνήχθησαν Ῥωμαῖοι μὲν τριάκοντα καὶ τριακοσίαις μακραῖς ναυσὶ καταφράκτοις καὶ κατέσχον εἰς Μεσσήνην. ὅθεν ἀναχθέντες ἔπλεον δεξιὰν ἔχοντες τὴν Σικελίαν, κάμψαντες δὲ τὸν Πάχυνον ὑπερῆραν εἰς Ἔκνομον διὰ τὸ καὶ τὸ πεζὸν στράτευμα περὶ τούτους αὐτοὺς εἶναι τοὺς τόπους. Καρχηδόνιοι δὲ πεντήκοντα καὶ τριακοσίαις ναυσὶ καταφράκτοις ἀναπλεύσαντες Λιλυβαίῳ προσέσχον, ἐντεῦθεν δὲ πρὸς Ἡράκλειαν τὴν Μινῴαν καθωρμίσθησαν.", "st": "1.25"}, {"sp": "N", "t": "ἦν δὲ τῶν μὲν Ῥωμαίων πρόθεσις εἰς τὴν Λιβύην πλεῖν καὶ τὸν πόλεμον ἐκεῖ περισπᾶν, ἵνα τοῖς Καρχηδονίοις μὴ περὶ Σικελίας, ἀλλὰ περὶ σφῶν αὐτῶν καὶ τῆς ἰδίας χώρας ὁ κίνδυνος γίνηται. τοῖς δὲ Καρχηδονίοις τἀναντία τούτων ἐδόκει· συνιδόντες γὰρ ὡς εὐέφοδός ἐστιν ἡ Λιβύη καὶ πᾶς ὁ κατὰ τὴν χώραν λαὸς εὐχείρωτος τοῖς ἅπαξ εἰς αὐτὴν ἐμβαλοῦσιν, οὐχ οἷοί τ’ ἦσαν ἐπιτρέπειν, ἀλλὰ διακινδυνεύειν καὶ ναυμαχεῖν ἔσπευδον. ὄντων δὲ τῶν μὲν πρὸς τὸ κωλύειν, τῶν δὲ πρὸς τὸ βιάζεσθαι, προφανὴς ἦν ὁ μέλλων ἀγὼν ἐκ τῆς ἑκατέρων συνίστασθαι φιλοτιμίας. οἱ μὲν οὖν Ῥωμαῖοι πρὸς ἀμφότερα τὴν παρασκευὴν ἁρμόζουσαν ἐποιοῦντο πρός τε τὴν κατὰ θάλατταν χρείαν καὶ πρὸς τὴν ἀπόβασιν τὴν εἰς τὴν πολεμίαν. διόπερ ἐπιλέξαντες ἐκ τῶν πεζικῶν στρατοπέδων τὰς ἀρίστας χεῖρας διεῖλον τὴν πᾶσαν δύναμιν, ἣν ἤμελλον ἀναλαμβάνειν, εἰς τέτταρα μέρη. τὸ δὲ μέρος ἕκαστον διττὰς εἶχεν προσηγορίας· πρῶτον μὲν γὰρ ἐκαλεῖτο στρατόπεδον καὶ πρῶτος στόλος καὶ τὰ λοιπὰ κατὰ λόγον. τὸ δὲ τέταρτον καὶ τρίτην ἐπωνυμίαν ἔτι προσειλήφει· τριάριοι γὰρ ὠνομάζοντο κατὰ τὴν ἐν τοῖς πεζικοῖς στρατοπέδοις συνήθειαν. καὶ τὸ μὲν σύμπαν ἦν στράτευμα τούτων τῆς ναυτικῆς δυνάμεως περὶ τέτταρας καὶ δέκα μυριάδας, ὡς ἂν ἑκάστης νεὼς λαμβανούσης ἐρέτας μὲν τριακοσίους, ἐπιβάτας δ’ ἑκατὸν εἴκοσιν. οἱ δὲ Καρχηδόνιοι τὸ μὲν πλεῖον καὶ τὸ πᾶν ἡρμόζοντο πρὸς τὸν κατὰ θάλατταν κίνδυνον· τό γε μὴν πλῆθος αὐτῶν ἦν ὑπὲρ πεντεκαίδεκα μυριάδας κατὰ τὸν τῶν νεῶν λόγον. ἐφ’ οἷς οὐχ οἷον ἄν τις παρὼν καὶ θεώμενος ὑπὸ τὴν ὄψιν, ἀλλὰ κἂν ἀκούων καταπλαγείη τὸ τοῦ κινδύνου μέγεθος καὶ τὴν τῶν πολιτευμάτων ἀμφοτέρων μεγαλομερίαν καὶ δύναμιν, στοχαζόμενος ἔκ τε τοῦ τῶν ἀνδρῶν καὶ τοῦ τῶν νεῶν πλήθους. οἱ δὲ Ῥωμαῖοι συλλογιζόμενοι διότι τὸν μὲν πλοῦν εἶναι συμβαίνει πελάγιον, τοὺς δὲ πολεμίους ταχυναυτεῖν, πανταχόθεν ἐπειρῶντο ποιεῖσθαι τὴν τάξιν ἀσφαλῆ καὶ δυσπρόσοδον. τὰς μὲν οὖν ἑξήρεις δύ’ οὔσας, ἐφ’ ὧν ἔπλεον οἱ στρατηγοὶ Μάρκος Ἀτίλιος καὶ Λεύκιος Μάλιος, πρώτας ἐν μετώπῳ παραλλήλους ἔταξαν. τούτων δ’ ἑκατέρᾳ συνεχεῖς κατὰ μίαν ναῦν ἐπιτάττοντες τῇ μὲν τὸν πρῶτον, τῇ δὲ τὸν δεύτερον στόλον ἐπέστησαν, ἀεὶ καθ’ ἑκάστην ναῦν ἑκατέρου τοῦ στόλου μεῖζον τὸ μεταξὺ ποιοῦντες διάστημα. ταῖς δὲ πρώρραις ἔξω νεύοντα τὰ σκάφη τὴν ἐπίστασιν ἐπ’ ἀλλήλοις εἶχεν. ἐπειδὴ δὲ τὸν πρῶτον καὶ δεύτερον στόλον ἁπλῶς εἰς ἔμβολον ἔταξαν, ἐπέβαλον τούτοις ἐπὶ μίαν ναῦν ἐν μετώπῳ τὸ τρίτον στρατόπεδον· ὧν ἐπιστάντων ἀπετελέσθη τρίγωνον τὸ πᾶν εἶδος τῆς τάξεως. ἐπὶ δὲ τούτοις ἐπέστησαν τὰς ἱππηγούς, ῥύματα δόντες ἐξ αὐτῶν ταῖς τοῦ τρίτου στόλου ναυσίν. ταύταις δὲ κατόπιν ἐπέβαλον τὸν τέταρτον στόλον, τοὺς τριαρίους κληθέντας, ἐπὶ μίαν παρεκτείναντες ναῦν, ὡς ὑπερτείνειν ἐξ ἑκατέρου τοῦ μέρους τοὺς πρὸ ἑαυτῶν. καὶ συναρμοσθέντων πάντων κατὰ τὸν εἰρημένον τρόπον, τὸ μὲν ὅλον ἀπετελέσθη σχῆμα τῆς τάξεως ἔμβολον, οὗ τὸ μὲν ἐπὶ τὴν κορυφὴν μέρος ἦν κοῖλον, τὸ δὲ πρὸς τῇ βάσει στερεόν, τὸ δὲ σύμπαν ἐνεργὸν καὶ πρακτικόν, ἅμα δὲ καὶ δυσδιάλυτον.", "st": "1.26"}, {"sp": "N", "t": "οἱ δὲ τῶν Καρχηδονίων στρατηγοὶ κατὰ τὸν αὐτὸν καιρὸν παρακαλέσαντες τὰ πλήθη διὰ βραχέων καὶ συνυποδείξαντες αὐτοῖς ὅτι νικήσαντες μὲν τῇ ναυμαχίᾳ περὶ Σικελίας ποιήσονται τὸν πόλεμον, ἡττηθέντες δὲ περὶ τῆς σφετέρας πατρίδος κινδυνεύσουσιν καὶ τῶν ἀναγκαίων, οὕτως αὐτοῖς παρήγγειλαν ἐμβαίνειν εἰς τὰς ναῦς. προθύμως δὲ πάντων ποιούντων τὸ παραγγελλόμενον διὰ τὸ προορᾶσθαι τὸ μέλλον ἐκ τῶν εἰρημένων, εὐθαρσῶς ἀνήγοντο καὶ καταπληκτικῶς. θεωροῦντες δὲ τὴν τῶν πολεμίων τάξιν οἱ στρατηγοὶ καὶ πρὸς ταύτην ἁρμοζόμενοι τὰ μὲν τρία μέρη τῆς αὑτῶν δυνάμεως ἐπὶ μίαν ἔταττον ναῦν, πρὸς τὸ πέλαγος ἀνατείναντες τὸ δεξιὸν κέρας, ὡς κυκλώσοντες τοὺς ὑπεναντίους, πάσας ἱστάντες ἀντιπρώρρους τὰς ναῦς τοῖς πολεμίοις. τὸ δὲ τέταρτον εὐώνυμον τῆς ὅλης τάξεως ἐποίουν, ἐν ἐπικαμπίῳ νεῦον πρὸς τὴν γῆν. ἡγοῦντο δὲ τῶν Καρχηδονίων τοῦ μὲν δεξιοῦ κέρως, ἔχων ἐπίπλους καὶ πεντήρεις τὰς μάλιστα ταχυναυτούσας πρὸς τὴν ὑπερκέρασιν, Ἄννων ὁ περὶ τὸν Ἀκράγαντα λειφθεὶς τῇ παρατάξει· τῶν δ’ εὐωνύμων εἶχε τὴν ἐπιμέλειαν Ἀμίλκας ὁ περὶ τὴν Τυνδαρίδα ναυμαχήσας· ὃς τότε κατὰ μέσην τὴν τάξιν ποιούμενος τὸν κίνδυνον ἐχρήσατό τινι στρατηγήματι κατὰ τὸν ἀγῶνα τοιῴδε. τῶν γὰρ Ῥωμαίων συνθεασαμένων ἐπὶ λεπτὸν ἐκτεταμένους τοὺς Καρχηδονίους καὶ ποιησαμένων τὴν ὁρμὴν ἐπὶ μέσους, τὴν μὲν ἀρχὴν ὁ κίνδυνος ἔλαβε τοιαύτην. ταχὺ δὲ τῶν περὶ τὰ μέσα Καρχηδονίων ἐκ παραγγέλματος κλινάντων πρὸς φυγὴν χάριν τοῦ διασπάσαι τὴν τῶν Ῥωμαίων τάξιν, οὗτοι μὲν ὑπεχώρουν μετὰ σπουδῆς, οἱ δὲ Ῥωμαῖοι κατόπιν ἠκολούθουν ἐκθύμως. ὁ μὲν οὖν πρῶτος καὶ δεύτερος στόλος ἐπέκειτο τοῖς φεύγουσιν, τὸ δὲ τρίτον καὶ τὸ τέταρτον στρατόπεδον ἀπεσπᾶτο, τῶν μὲν ῥυμουλκούντων τὰς ἱππηγοὺς ναῦς, τῶν δὲ τριαρίων συμμενόντων καὶ συνεφεδρευόντων τούτοις. ἐπεὶ δὲ τὸν πρῶτον καὶ δεύτερον στόλον ἱκανὸν τῶν ἄλλων ἐδόκουν ἀπεσπακέναι τόπον οἱ Καρχηδόνιοι, συνθήματος ἀρθέντος ἐκ τῆς Ἀμίλκου νεὼς μετεβάλοντο πάντες ἅμα καὶ συνέβαλον τοῖς ἐπικειμένοις. ἀγῶνος δὲ συστάντος καρτεροῦ, τῷ μὲν ταχυναυτεῖν ἐκπεριπλέοντες καὶ ῥᾳδίως μὲν προσιόντες ὀξέως δ’ ἀποχωροῦντες πολὺ περιῆσαν οἱ Καρχηδόνιοι, τῷ δὲ βιαιομαχεῖν κατὰ τὰς συμπλοκὰς καὶ συνδεῖν τοῖς κόραξιν τοὺς ἅπαξ ἐγγίσαντας, ἅμα δὲ καὶ τῷ συναγωνιζομένων ἀμφοτέρων τῶν στρατηγῶν ἐν ὄψει τῶν ἡγουμένων ποιεῖσθαι τὸν κίνδυνον, οὐχ ἧττον ἐπικυδεστέρας εἶχον οἱ Ῥωμαῖοι τῶν Καρχηδονίων τὰς ἐλπίδας. ἡ μὲν οὖν κατὰ τούτους μάχη τοιαύτην εἶχε διάθεσιν.", "st": "1.27"}, {"sp": "N", "t": "κατὰ δὲ τὸν αὐτὸν καιρὸν τὸ μὲν δεξιὸν κέρας ἔχων Ἄννων, τὸ μεῖναν ἐν ἀποστάσει κατὰ τὴν πρώτην συμβολήν, τό τε πέλαγος ὑπεράρας ἐνέβαλε ταῖς τῶν τριαρίων ναυσὶ καὶ πολλὴν ἀπορίαν παρεῖχε καὶ δυσχρηστίαν αὐτοῖς. οἱ δὲ παρὰ τὴν γῆν τεταγμένοι τῶν Καρχηδονίων παραγεγονότες εἰς μέτωπον ἐκ τῆς προϋπαρχούσης τάξεως καὶ ποιήσαντες ἀντιπρώρρους τὰς ναῦς ἐνέβαλον τοῖς ῥυμουλκοῦσι τὰς ἱππηγούς· οἱ δ’ ἀφέμενοι τὰ ῥύματα συνεπλέκοντο καὶ διηγωνίζοντο τοῖς πολεμίοις. ἦν δὲ τρία μέρη τῆς ὅλης συμπλοκῆς, καὶ τρεῖς ναυμαχίαι συνέστησαν πολὺ κεχωρισμέναι τοῖς τόποις ἀλλήλων· τῷ δ’ ἑκατέρων πάρισα τὰ μέρη γενέσθαι κατὰ τὸν ἐξ ἀρχῆς χειρισμὸν ἐφάμιλλον εἶναι συνέβαινε καὶ τὸν κίνδυνον. οὐ μὴν ἀλλὰ τὸ κατὰ λόγον ἐν ἑκάστοις ἐπετελεῖτο περὶ τὴν μάχην, ὅπερ εἰκὸς ὅταν ᾖ παραπλήσια πάντα τὰ τῶν ἀγωνιζομένων. οἱ γὰρ πρῶτοι κινδυνεύσαντες πρῶτοι καὶ διεκρίθησαν· τέλος γὰρ ἐκβιασθέντες οἱ περὶ τὸν Ἀμίλκαν εἰς φυγὴν ὥρμησαν. ὁ μὲν οὖν Λεύκιος ἀνεδεῖτο τὰς αἰχμαλώτους ναῦς· ὁ δὲ Μάρκος συνορῶν τὸν περὶ τοὺς τριαρίους καὶ τὰς ἱππηγοὺς ἀγῶνα κατὰ σπουδὴν ἐβοήθει τούτοις, ἔχων τοῦ δευτέρου στόλου τὰς ἀκεραίους ναῦς. συνάψαντος δὲ καὶ προσμίξαντος αὐτοῦ τοῖς περὶ τὸν Ἄννωνα, ταχέως ἀναθαρρήσαντες οἱ τριάριοι, καίπερ ἤδη κακῶς ἀπαλλάττοντες, πάλιν ἐπερρώσθησαν πρὸς τὸν κίνδυνον. οἱ δὲ Καρχηδόνιοι, τῶν μὲν κατὰ πρόσωπον αὐτοῖς προσμαχομένων, τῶν δὲ κατὰ νώτου προσπιπτόντων, δυσχρηστούμενοι καὶ παραδόξως ὑπὸ τῶν βοηθησάντων κυκλούμενοι, κλίναντες πελαγίαν ἐποιοῦντο τὴν ὑποχώρησιν. κατὰ δὲ τὸν αὐτὸν καιρὸν ὅ τε Λεύκιος ἐπαναπλέων ἤδη καὶ θεωρῶν συγκεκλεισμένον πρὸς τῇ γῇ τὸν τρίτον στόλον ὑπὸ τοῦ τῶν Καρχηδονίων εὐωνύμου κέρατος, ὅ τε Μάρκος ἐν ἀσφαλεῖ καταλιπὼν τὰς ἱππηγοὺς καὶ τοὺς τριαρίους ὥρμησαν ἀμφότεροι βοηθεῖν τοῖς κινδυνεύουσι. παραπλήσιον γὰρ ἦν ἤδη τὸ γινόμενον πολιορκίᾳ· καὶ πάντες ἂν ἀπολώλεισαν οὗτοί γε προφανῶς, εἰ μὴ δεδιότες τοὺς κόρακας οἱ Καρχηδόνιοι περιφράξαντες μὲν αὐτοὺς πρὸς τῇ γῇ συνεῖχον, πρὸς δὲ τὰς ἐμβολὰς διὰ τὴν συμπλοκὴν εὐλαβῶς ἔχοντες οὐ προσῄεσαν. ταχέως δ’ ἐπιγενόμενοι καὶ κυκλώσαντες οἱ στρατηγοὶ τοὺς Καρχηδονίους αὐτάνδρους μὲν ἔλαβον πεντήκοντα ναῦς τῶν πολεμίων, ὀλίγαι δέ τινες παρὰ τὴν γῆν ἐξελίξασαι διέφυγον. ὁ μὲν οὖν κατὰ μέρος κίνδυνος τοιαύτην ἔσχε τὴν διάθεσιν, τὸ δὲ τέλος τῆς συμπάσης ναυμαχίας ἐγένετο κατὰ τοὺς Ῥωμαίους. διεφθάρη δὲ τούτων μὲν εἴκοσι καὶ τέτταρα σκάφη, τῶν δὲ Καρχηδονίων ὑπὲρ τριάκοντα. ναῦς δὲ τῶν μὲν Ῥωμαίων αὔτανδρος οὐδεμία τοῖς πολεμίοις ἐγένεθ’ ὑποχείριος, τῶν δὲ Καρχηδονίων ἑξήκοντα καὶ τέτταρες.", "st": "1.28"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα πάλιν οἱ Ῥωμαῖοι προσεπισιτισάμενοι καὶ τὰς αἰχμαλώτους ναῦς καταρτίσαντες, ἔτι δὲ τὴν ἁρμόζουσαν τοῖς προτερήμασιν ἐπιμέλειαν ποιησάμενοι τῶν πληρωμάτων ἀνήγοντο ποιούμενοι τὸν πλοῦν ὡς ἐπὶ τὴν Λιβύην. προσσχόντες δὲ ταῖς πρώταις πλεούσαις ναυσὶν ὑπὸ τὴν ἄκραν τὴν Ἑρμαίαν ἐπονομαζομένην, ἣ πρὸ παντὸς τοῦ περὶ τὴν Καρχηδόνα κόλπου κειμένη προτείνει πελάγιος ὡς πρὸς τὴν Σικελίαν, καὶ προσδεξάμενοι τὰς ἐπιπλεούσας ἐνταῦθα ναῦς καὶ πάντα συναθροίσαντες τὸν στόλον ἔπλεον παρὰ τὴν χώραν, ἕως ἐπὶ τὴν Ἀσπίδα καλουμένην πόλιν ἀφίκοντο. ποιησάμενοι δὲ τὴν ἀπόβασιν ἐνταῦθα καὶ νεωλκήσαντες, ἔτι δὲ τάφρῳ καὶ χάρακι περιλαβόντες τὰς ναῦς ἐγίνοντο πρὸς τὸ πολιορκεῖν αὐτήν, οὐ βουλομένων ἑκουσίως σφίσι προσχωρῆσαι τῶν κατεχόντων τὴν πόλιν. οἱ δὲ διαφυγόντες ἐκ τοῦ κατὰ τὴν ναυμαχίαν κινδύνου τῶν Καρχηδονίων καταπλεύσαντες καὶ πεπεισμένοι τοὺς ὑπεναντίους ἐκ τοῦ γεγονότος προτερήματος ἐπαρθέντας εὐθέως ποιήσεσθαι τὸν ἐπίπλουν ἐπ’ αὐτὴν τὴν Καρχηδόνα, παρετήρουν ταῖς πεζικαῖς καὶ ναυτικαῖς δυνάμεσι τοὺς προκειμένους τῆς πόλεως τόπους. ἐπιγνόντες δὲ τοὺς Ῥωμαίους ἀσφαλῶς ἀποβεβηκότας καὶ πολιορκοῦντας τὴν Ἀσπίδα, τοῦ μὲν παραφυλάττειν τὸν ἐπίπλουν ἀπέγνωσαν, συνήθροιζον δὲ τὰς δυνάμεις καὶ περὶ φυλακὴν ἐγίνοντο τῆς τε πόλεως καὶ τῆς χώρας. οἱ δὲ Ῥωμαῖοι κυριεύσαντες τῆς Ἀσπίδος καὶ φυλακὴν ἀπολιπόντες τῆς πόλεως καὶ χώρας, ἔτι δὲ πρεσβευτὰς εἰς τὴν Ῥώμην πέμψαντες τοὺς ἀπαγγελοῦντας μὲν περὶ τῶν γεγονότων, ἐρησομένους δὲ περὶ τῶν μελλόντων τί δεῖ ποιεῖν καὶ πῶς χρῆσθαι τοῖς πράγμασιν, μετὰ δὲ ταῦτα πάσῃ τῇ δυνάμει κατὰ σπουδὴν ἀναζεύξαντες ὥρμησαν ἐπὶ τὸ πορθεῖν τὴν χώραν. οὐδενὸς δ’ ἐμποδὼν ἱσταμένου, πολλὰς μὲν οἰκήσεις περιττῶς κατεσκευασμένας διέφθειραν, πολὺ δὲ πλῆθος τῆς τετραπόδου λείας περιεβάλοντο· σώματα δὲ πλείω τῶν δισμυρίων ἐπὶ τὰς ναῦς ἀνήγαγον. ἐν δὲ τούτῳ τῷ καιρῷ παρῆσαν ἐκ τῆς Ῥώμης οἱ διασαφοῦντες ὅτι δεῖ τὸν μὲν ἕνα τῶν στρατηγῶν μένειν ἔχοντα δυνάμεις τὰς ἀρκούσας, τὸν δ’ ἕτερον ἀποκομίζειν εἰς τὴν Ῥώμην τὸν στόλον. ὁ μὲν οὖν Μάρκος ἔμενεν, ὑπολειπόμενος ναῦς τετταράκοντα καὶ πεζοὺς μυρίους καὶ πεντακισχιλίους, ἱππεῖς δὲ πεντακοσίους· ὁ δὲ Λεύκιος ἀναλαβὼν τὰ πληρώματα καὶ τὸ τῶν αἰχμαλώτων πλῆθος καὶ κομισθεὶς παρὰ τὴν Σικελίαν ἀσφαλῶς ἧκεν εἰς τὴν Ῥώμην.", "st": "1.29"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι θεωροῦντες τὴν τῶν πολεμίων παρασκευὴν χρονιωτέραν οὖσαν, πρῶτον μὲν στρατηγοὺς ἑαυτῶν εἵλοντο δύο, τόν τ’ Ἄννωνος Ἀσδρούβαν καὶ Βώσταρον, μετὰ δὲ ταῦτα πρὸς τὸν Ἀμίλκαν ἔπεμπον εἰς τὴν Ἡράκλειαν, καλοῦντες κατὰ τάχος αὐτόν. ὁ δ’ ἀναλαβὼν ἱππεῖς πεντακοσίους καὶ πεζοὺς πεντακισχιλίους παρῆν εἰς τὴν Καρχηδόνα· καὶ κατασταθεὶς στρατηγὸς τρίτος ἐβουλεύετο μετὰ τῶν περὶ τὸν Ἀσδρούβαν πῶς δεῖ χρῆσθαι τοῖς παροῦσιν. ἔδοξεν οὖν αὐτοῖς βοηθεῖν τῇ χώρᾳ καὶ μὴ περιορᾶν αὐτὴν ἀδεῶς πορθουμένην. ὁ δὲ Μάρκος μετά τινας ἡμέρας ἐπεπορεύετο, τὰ μὲν ἀτείχιστα τῶν ἐρυμάτων ἐξ ἐφόδου διαρπάζων, τὰ δὲ τετειχισμένα πολιορκῶν. ἀφικόμενος δὲ πρὸς πόλιν Ἀδὺν ἀξιόχρεω, περιστρατοπεδεύσας ταύτην συνίστατο μετὰ σπουδῆς ἔργα καὶ πολιορκίαν. οἱ δὲ Καρχηδόνιοι τῇ τε πόλει σπουδάζοντες βοηθῆσαι καὶ τῶν ὑπαίθρων ἀντιποιεῖσθαι κρίνοντες ἐξῆγον τὴν δύναμιν. καὶ καταλαβόμενοι λόφον ὑπερδέξιον μὲν τῶν πολεμίων, ἀφυῆ δὲ ταῖς ἑαυτῶν δυνάμεσιν, ἐν τούτῳ κατεστρατοπέδευσαν. λοιπὸν ἔχοντες μὲν τὰς πλείστας ἐλπίδας ἐν τοῖς ἱππεῦσιν καὶ τοῖς θηρίοις, ἀφέμενοι δὲ τῶν ἐπιπέδων χωρίων καὶ συγκλείσαντες σφᾶς αὐτοὺς εἰς τόπους ἐρυμνοὺς καὶ δυσβάτους, ἔμελλον διδάξειν τοὺς πολεμίους ὃ δέον ἦν πράττειν κατ’ αὐτῶν. ὃ δὴ καὶ συνέβη γενέσθαι. συννοήσαντες γὰρ οἱ τῶν Ῥωμαίων ἡγεμόνες ἐμπείρως ὅτι τὸ πρακτικώτατον καὶ φοβερώτατον τῆς τῶν ὑπεναντίων δυνάμεως ἠχρείωται διὰ τοὺς τόπους, οὐκ ἀνέμειναν ἕως ἐκεῖνοι καταβάντες εἰς τὰ πεδία παρετάξαντο, χρώμενοι δὲ τοῖς ἰδίοις καιροῖς ἅμα τῷ φωτὶ προσέβαινον ἐξ ἑκατέρου τοῦ μέρους πρὸς τὸν λόφον. οἱ μὲν οὖν ἱππεῖς καὶ τὰ θηρία τοῖς Καρχηδονίοις ἦν ἄχρηστα τελέως· οἱ δὲ μισθοφόροι πάνυ γενναίως καὶ προθύμως ἐκβοηθήσαντες τὸ μὲν πρῶτον στρατόπεδον ἠνάγκασαν ἐκκλῖναι καὶ φυγεῖν· ἐπεὶ δὲ προπεσόντες καὶ κυκλωθέντες ὑπὸ τῶν ἐκ θατέρου μέρους προσβαινόντων ἐτράπησαν, μετὰ ταῦτα πάντες εὐθὺς ἐκ τῆς στρατοπεδείας ἐξέπεσον. τὰ μὲν οὖν θηρία μετὰ τῶν ἱππέων, ἐπεὶ τάχιστα τῶν ὁμαλῶν ἥψατο, μετ’ ἀσφαλείας ἐποιοῦντο τὴν ἀποχώρησιν· οἱ δὲ Ῥωμαῖοι τοὺς πεζοὺς βραχὺν ἐπιδιώξαντες τόπον καὶ τὸν χάρακα διαρπάσαντες, μετὰ δὲ ταῦτα πᾶσαν ἐπιπορευόμενοι τὴν χώραν καὶ τὰς πόλεις ἀδεῶς ἐπόρθουν. γενόμενοι δὲ τῆς προσαγορευομένης πόλεως Τύνητος ἐγκρατεῖς, εὐφυοῦς ὑπαρχούσης πρὸς τὰς προκειμένας ἐπιβολάς, ἔτι δὲ κειμένης εὐκαίρως κατά τε τῆς πόλεως καὶ τῆς σύνεγγυς ταύτῃ χώρας, κατεστρατοπέδευσαν εἰς αὐτήν.", "st": "1.30"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι μικρῷ μὲν πρότερον κατὰ θάλατταν, τότε δὲ κατὰ γῆν ἐπταικότες, οὐ διὰ τὴν τῶν πολλῶν ἀνανδρίαν, ἀλλὰ διὰ τὴν τῶν ἡγουμένων ἀβουλίαν, κατὰ πάντα τρόπον ἐνεπεπτώκεισαν εἰς δυσχερῆ διάθεσιν. ἅμα γὰρ τοῖς προειρημένοις καὶ τὸ τῶν Νομάδων ἔθνος συνεπιτιθέμενον αὐτοῖς οὐκ ἐλάττω, πλείω δὲ τῶν Ῥωμαίων εἰργάζετο κακὰ τὴν χώραν. ἐξ ὧν διὰ τὸν φόβον συμφευγόντων εἰς τὴν πόλιν τῶν ἀπὸ τῆς χώρας δυσθυμία καὶ λιμὸς ἦν ὁλοσχερής, τὰ μὲν διὰ τὸ πλῆθος, τὰ δὲ διὰ τὴν προσδοκίαν τῆς πολιορκίας. ὁ δὲ Μάρκος ὁρῶν τοὺς Καρχηδονίους καὶ κατὰ γῆν καὶ κατὰ θάλατταν ἐσφαλμένους καὶ νομίζων ὅσον οὔπω κρατήσειν τῆς πόλεως, ἀγωνιῶν δὲ μὴ συμβῇ τὸν ἐπιπαραγινόμενον στρατηγὸν ἐκ τῆς Ῥώμης φθάσαντα τὴν ἐπιγραφὴν τῶν πραγμάτων λαβεῖν, προυκαλεῖτο τοὺς Καρχηδονίους εἰς διαλύσεις. οἱ δ’ ἀσμένως ἀκούσαντες ἐξέπεμψαν αὑτῶν τοὺς πρώτους ἄνδρας· οἳ καὶ συμμίξαντες αὐτῷ τοσοῦτον ἀπέσχον τοῦ ῥέπειν ταῖς γνώμαις ἐπὶ τὸ ποιεῖν τι τῶν λεγομένων ὥστ’ οὐδ’ ἀκούοντες ὑπομένειν ἐδύναντο τὸ βάρος τῶν ἐπιταγμάτων. ὁ μὲν γὰρ Μάρκος ὡς ἤδη κεκρατηκὼς τῶν ὅλων, ὅ,τι ποτὲ συνεχώρει, πᾶν ᾤετο δεῖν αὐτοὺς ἐν χάριτι καὶ δωρεᾷ λαμβάνειν· οἱ δὲ Καρχηδόνιοι θεωροῦντες ὅτι καὶ γενομένοις αὐτοῖς ὑποχειρίοις οὐδὲν ἂν συνεξακολουθήσαι βαρύτερον τῶν τότε προσταγμάτων, οὐ μόνον δυσαρεστήσαντες τοῖς προτεινομένοις ἐπανῆλθον, ἀλλὰ καὶ προσκόψαντες τῇ βαρύτητι τοῦ Μάρκου. τὸ δὲ συνέδριον τῶν Καρχηδονίων διακοῦσαν τὰ προτεινόμενα παρὰ τοῦ στρατηγοῦ τῶν Ῥωμαίων, καίπερ σχεδὸν ἀπεγνωκὸς τὰς τῆς σωτηρίας ἐλπίδας, ὅμως οὕτως ἀνδρωδῶς ἔστη καὶ γενναίως ὥστε πᾶν ὑπομένειν εἵλετο καὶ παντὸς ἔργου καὶ καιροῦ πεῖραν λαμβάνειν ἐφ’ ᾧ μηδὲν ἀγεννὲς μηδ’ ἀνάξιον τῶν πρὸ τοῦ πράξεων ὑπομεῖναι.", "st": "1.31"}, {"sp": "N", "t": "περὶ δὲ τοὺς καιροὺς τούτους καταπλεῖ τις εἰς τὴν Καρχηδόνα ξενολόγος τῶν ἀπεσταλμένων εἰς τὴν Ἑλλάδα πρότερον [εἰς τὴν Καρχηδονίων], ἄγων στρατιώτας πλείστους, ἐν οἷς καὶ Ξάνθιππόν τινα Λακεδαιμόνιον, ἄνδρα τῆς Λακωνικῆς ἀγωγῆς μετεσχηκότα καὶ τριβὴν ἐν τοῖς πολεμικοῖς ἔχοντα σύμμετρον. ὃς διακούσας τὸ γεγονὸς ἐλάττωμα καὶ πῶς καὶ τίνι τρόπῳ γέγονεν, καὶ συνθεωρήσας τάς τε λοιπὰς παρασκευὰς τῶν Καρχηδονίων καὶ τὸ πλῆθος τῶν ἱππέων καὶ τῶν ἐλεφάντων παραυτίκα συνελογίσατο καὶ πρὸς τοὺς φίλους ἐνεφάνισε διότι συμβαίνει τοὺς Καρχηδονίους οὐχ ὑπὸ Ῥωμαίων, αὐτοὺς δ’ ὑφ’ αὑτῶν ἡττᾶσθαι διὰ τὴν ἀπειρίαν τῶν ἡγουμένων. ταχὺ δὲ διὰ τὴν περίστασιν τῶν τοῦ Ξανθίππου λόγων διαδοθέντων εἰς τὰ πλήθη καὶ τοὺς στρατηγούς, ἔγνωσαν οἱ προεστῶτες ἀνακαλεῖσθαι καὶ πεῖραν αὐτοῦ λαμβάνειν. ὁ δὲ παραγενόμενος εἰς τὰς χεῖρας ἔφερε τοῖς ἄρχουσι τοὺς ἀπολογισμοὺς καὶ παρὰ τί νῦν σφαλείησαν, καὶ διότι πεισθέντες αὐτῷ καὶ χρησάμενοι τοῖς ἐπιπέδοις τῶν τόπων ἔν τε ταῖς πορείαις καὶ στρατοπεδείαις καὶ παρατάξεσιν εὐχερῶς ἑαυτοῖς τε τὴν ἀσφάλειαν δυνήσονται παρασκευάζειν καὶ τοὺς ὑπεναντίους νικᾶν. οἱ δὲ στρατηγοὶ δεξάμενοι τὰ λεγόμενα καὶ πεισθέντες αὐτῷ παραχρῆμα τὰς δυνάμεις ἐνεχείρισαν. ἦν μὲν οὖν καὶ κατὰ ταύτην τὴν παρὰ τοῦ Ξανθίππου διαδιδομένην φωνὴν ὁ θροῦς καὶ λαλιά τις εὔελπις παρὰ τοῖς πολλοῖς· ὡς δ’ ἐξαγαγὼν πρὸ τῆς πόλεως τὴν δύναμιν ἐν κόσμῳ παρενέβαλε καί τι καὶ κινεῖν τῶν μερῶν ἐν τάξει καὶ παραγγέλλειν κατὰ νόμους ἤρξατο, τηλικαύτην ἐποίει διαφορὰν παρὰ τὴν τῶν πρότερον στρατηγῶν ἀπειρίαν ὥστε μετὰ κραυγῆς ἐπισημαίνεσθαι τοὺς πολλοὺς καὶ σπεύδειν ὡς τάχιστα συμβαλεῖν τοῖς πολεμίοις, πεπεισμένους μηδὲν ἂν παθεῖν δεινὸν ἡγουμένου Ξανθίππου. τούτων δὲ γινομένων οἱ στρατηγοὶ συνιδόντες τοὺς ὄχλους ἀνατεθαρρηκότας παραδόξως ταῖς ψυχαῖς, παρακαλέσαντες αὐτοὺς τὰ πρέποντα τῷ καιρῷ μετ’ ὀλίγας ἡμέρας ὥρμησαν ἀναλαβόντες τὴν δύναμιν. αὕτη δ’ ἦν πεζοὶ μὲν εἰς μυρίους καὶ δισχιλίους, ἱππεῖς δὲ τετρακισχίλιοι, τὸ δὲ τῶν ἐλεφάντων πλῆθος ἔγγιστά που τῶν ἑκατόν.", "st": "1.32"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι θεωροῦντες τοὺς Καρχηδονίους τάς τε πορείας ποιουμένους διὰ τῶν ὁμαλῶν τόπων καὶ τὰς στρατοπεδείας τιθέντας ἐν τοῖς ἐπιπέδοις τῶν χωρίων, κατ’ αὐτὸ μὲν τοῦτο ξενιζόμενοι διετρέποντο, τοῖς γε μὴν ὅλοις ἔσπευδον ἐγγίσαι τοῖς πολεμίοις. συνάψαντες δὲ τὴν μὲν πρώτην ἡμέραν κατεστρατοπέδευσαν ὡς δέκα σταδίους ἀποσχόντες τῶν ὑπεναντίων. τῇ δὲ κατὰ πόδας οἱ μὲν προεστῶτες τῶν Καρχηδονίων ἐβουλεύοντο πῶς καὶ τί πρακτέον εἴη κατὰ τὸ παρόν· οἱ δὲ πολλοὶ προθύμως ἔχοντες πρὸς τὸν κίνδυνον, συστρεφόμενοι κατὰ μέρη καὶ κατ’ ὄνομα τὸν Ξάνθιππον ἀναβοῶντες ἐξάγειν σφᾶς ᾤοντο δεῖν τὴν ταχίστην. οἱ δὲ στρατηγοὶ τήν τε τῶν ὄχλων ὁρμὴν καὶ προθυμίαν θεωροῦντες, ἅμα δὲ καὶ τοῦ Ξανθίππου διαμαρτυρομένου μὴ παριέναι τὸν καιρόν, παρήγγειλαν τῷ μὲν πλήθει διασκευάζεσθαι, τῷ δὲ Ξανθίππῳ χρῆσθαι τοῖς πράγμασιν ἐπέτρεψαν ὥς ποτ’ αὐτῷ δοκεῖ συμφέρειν. ὁ δὲ λαβὼν τὴν ἐξουσίαν, τοὺς μὲν ἐλέφαντας ἐξαγαγὼν ἐφ’ ἕνα πρὸ πάσης τῆς δυνάμεως ἐν μετώπῳ κατέστησε, τὴν δὲ φάλαγγα τῶν Καρχηδονίων ἐν ἀποστήματι συμμέτρῳ τούτοις κατόπιν ἐπέστησε. τῶν δὲ μισθοφόρων τοὺς μὲν ἐπὶ τὸ δεξιὸν κέρας παρενέβαλεν, τοὺς δ’ εὐκινητοτάτους ὁμοῦ τοῖς ἱππεῦσιν ἑκατέρου τοῦ κέρατος προέστησεν. οἱ δὲ Ῥωμαῖοι συνιδόντες παραταττομένους τοὺς ὑπεναντίους ἀντεξῄεσαν ἑτοίμως. καταπληττόμενοι δὲ καὶ προορώμενοι τὴν τῶν ἐλεφάντων ἔφοδον, προθέμενοι τοὺς γροσφομάχους πολλὰς ἐπ’ ἀλλήλαις κατόπιν ἵστασαν σημείας, τοὺς δ’ ἱππεῖς ἐμέρισαν ἐφ’ ἑκάτερον τὸ κέρας. τὴν δὲ σύμπασαν τάξιν βραχυτέραν μὲν ἢ πρόσθεν, βαθυτέραν δὲ ποιήσαντες τῆς μὲν πρὸς τὰ θηρία μάχης δεόντως ἦσαν ἐστοχασμένοι, τῆς δὲ πρὸς τοὺς ἱππεῖς, πολλαπλασίους ὄντας τῶν παρ’ αὐτοῖς, ὁλοσχερῶς ἠστόχησαν. ἐπεὶ δ’ ἀμφότεροι κατὰ τὰς ἑαυτῶν προαιρέσεις καὶ καθόλου καὶ κατὰ μέρος ἑκάστους ἔθηκαν εἰς τὰς ἁρμοζούσας τάξεις, ἔμενον ἐν κόσμῳ, καραδοκοῦντες τὸν καιρὸν τῆς ἀλλήλων ἐπιθέσεως.", "st": "1.33"}, {"sp": "N", "t": "ἅμα δὲ τῷ τὸν Ξάνθιππον τοῖς μὲν ἐπὶ τῶν θηρίων παραγγεῖλαι προάγειν καὶ διασπᾶν τὰς τῶν ὑπεναντίων τάξεις, τοῖς δ’ ἱππεῦσιν ἐφ’ ἑκατέρου τοῦ κέρατος κυκλοῦν καὶ προσβάλλειν τοῖς πολεμίοις, τότε δὴ καὶ τὸ τῶν Ῥωμαίων στρατόπεδον κατὰ τὰ παρ’ αὐτοῖς ἔθη συνεψόφησαν τοῖς ὅπλοις καὶ συναλαλάξαντες ὥρμησαν ἐπὶ τοὺς πολεμίους. οἱ μὲν οὖν ἱππεῖς τῶν Ῥωμαίων ταχέως ἀφ’ ἑκατέρων τῶν κεράτων ἔφυγον διὰ τὸ πολλαπλασίους εἶναι τοὺς Καρχηδονίους. τῶν δὲ πεζῶν οἱ ταχθέντες ἐπὶ τοῦ λαιοῦ κέρως, ἅμα μὲν ἐκκλίνοντες τὴν τῶν θηρίων ἔφοδον, ἅμα δὲ καταφρονοῦντες τῶν μισθοφόρων ὥρμησαν ἐπὶ τὸ δεξιὸν κέρας τῶν Καρχηδονίων· τρεψάμενοι δὲ τούτους ἐπέκειντο καὶ κατεδίωκον αὐτοὺς ἕως εἰς τὸν χάρακα. τῶν δὲ κατὰ τοὺς ἐλέφαντας ταχθέντων οἱ μὲν πρῶτοι συμπεσόντες ὑπὸ τῆς βίας τῶν ζῴων ἐξωθούμενοι καὶ καταπατούμενοι σωρηδὸν ἐν χειρῶν νόμῳ διεφθείροντο, τῆς γε μὴν ὅλης τάξεως τὸ σύστημα διὰ τὸ βάθος τῶν ἐφεστώτων ἕως τινὸς ἀδιάσπαστον ἔμεινεν. ἐπεὶ δ’ οἱ μὲν τὰς ἐσχάτας ἔχοντες τάξεις κυκλούμενοι πανταχόθεν ὑπὸ τῶν ἱππέων ἠναγκάζοντο πρὸς τούτους στρεφόμενοι κινδυνεύειν, οἱ δὲ διὰ μέσων τῶν ἐλεφάντων εἰς τὸ πρόσθεν ἐκβιαζόμενοι καὶ κατὰ νώτου παριστάμενοι τῶν θηρίων εἰς ἀκέραιον καὶ συντεταγμένην ἐμπίπτοντες τὴν τῶν Καρχηδονίων φάλαγγα διεφθείροντο, τότε δὴ πανταχόθεν πονοῦντες οἱ μὲν πλεῖστοι τῶν Ῥωμαίων συνεπατήθησαν ὑπὸ τῆς ὑπερφυοῦς βίας τῶν ζῴων, οἱ δὲ λοιποὶ συνηκοντίσθησαν ὑπὸ τοῦ πλήθους τῶν ἱππέων ἐν αὐτῷ τῷ τῆς παρατάξεως τόπῳ, τελέως δέ τινες ὀλίγοι πρὸς φυγὴν ὥρμησαν. οὐσῶν δὲ πεδινῶν τῶν ὑποχωρήσεων, καὶ τούτων οἱ μὲν ὑπὸ τῶν θηρίων καὶ τῶν ἱππέων ἀπώλλυντο, πεντακόσιοι δ’ ἴσως οἱ μετὰ Μάρκου τοῦ στρατηγοῦ φυγόντες μετ’ ὀλίγον ὑποχείριοι γενόμενοι σὺν αὐτῷ ’κείνῳ πάντες ἐζωγρήθησαν. τῶν μὲν οὖν παρὰ τοῖς Καρχηδονίοις μισθοφόρων ἔπεσον εἰς ὀκτακοσίους οἱ κατὰ τὸ λαιὸν τῶν Ῥωμαίων ταχθέντες, τῶν δὲ Ῥωμαίων ἐσώθησαν μὲν εἰς δισχιλίους οἱ κατὰ τὸ δίωγμα τῶν προειρημένων ἐκτὸς γενόμενοι τοῦ κινδύνου, τὸ δὲ λοιπὸν πλῆθος διεφθάρη πλὴν Μάρκου τοῦ στρατηγοῦ καὶ τῶν ἅμα τούτῳ φυγόντων. αἱ μὲν οὖν σημεῖαι τῶν Ῥωμαίων αἱ σωθεῖσαι διέπεσον εἰς τὴν Ἀσπίδα παραδόξως· οἱ δὲ Καρχηδόνιοι τοὺς νεκροὺς σκυλεύσαντες καὶ τὸν στρατηγὸν ἅμα μετὰ τῶν αἰχμαλώτων ἄγοντες ἐπανῆλθον περιχαρεῖς τοῖς παροῦσιν εἰς τὴν πόλιν.", "st": "1.34"}, {"sp": "N", "t": "ἐν ᾧ καιρῷ πολλά τις ἂν ὀρθῶς ἐπισημαινόμενος εὕροι πρὸς ἐπανόρθωσιν τοῦ τῶν ἀνθρώπων βίου συντελεσθέντα. καὶ γὰρ τὸ διαπιστεῖν τῇ τύχῃ, καὶ μάλιστα κατὰ τὰς εὐπραγίας, ἐναργέστατον ἐφάνη πᾶσιν τότε διὰ τῶν Μάρκου συμπτωμάτων· ὁ γὰρ μικρῷ πρότερον οὐ διδοὺς ἔλεον οὐδὲ συγγνώμην τοῖς πταίουσιν παρὰ πόδας αὐτὸς ἤγετο δεησόμενος τούτων περὶ τῆς ἑαυτοῦ σωτηρίας. καὶ μὴν τὸ παρ’ Εὐριπίδῃ πάλαι καλῶς εἰρῆσθαι δοκοῦν ὡς ἓν σοφὸν βούλευμα τὰς πολλὰς χεῖρας νικᾷ τότε δι’ αὐτῶν τῶν ἔργων ἔλαβε τὴν πίστιν. εἷς γὰρ ἄνθρωπος καὶ μία γνώμη τὰ μὲν ἀήττητα πλήθη καὶ πραγματικὰ δοκοῦντ’ εἶναι καθεῖλεν, τὸ δὲ προφανῶς πεπτωκὸς ἄρδην πολίτευμα καὶ τὰς ἀπηλγηκυίας ψυχὰς τῶν δυνάμεων ἐπὶ τὸ κρεῖττον ἤγαγεν. ἐγὼ δὲ τούτων ἐπεμνήσθην χάριν τῆς τῶν ἐντυγχανόντων τοῖς ὑπομνήμασι διορθώσεως. δυεῖν γὰρ ὄντων τρόπων πᾶσιν ἀνθρώποις τῆς ἐπὶ τὸ βέλτιον μεταθέσεως, τοῦ τε διὰ τῶν ἰδίων συμπτωμάτων καὶ τοῦ διὰ τῶν ἀλλοτρίων, ἐναργέστερον μὲν εἶναι συμβαίνει τὸν διὰ τῶν οἰκείων περιπετειῶν, ἀβλαβέστερον δὲ τὸν διὰ τῶν ἀλλοτρίων. διὸ τὸν μὲν οὐδέποθ’ ἑκουσίως αἱρετέον, ἐπεὶ μετὰ μεγάλων πόνων καὶ κινδύνων ποιεῖ τὴν διόρθωσιν, τὸν δ’ ἀεὶ θηρευτέον, ἐπεὶ χωρὶς βλάβης ἔστιν συνιδεῖν ἐν αὐτῷ τὸ βέλτιον. ἐξ ὧν συνιδόντι καλλίστην παιδείαν ἡγητέον πρὸς ἀληθινὸν βίον τὴν ἐκ τῆς πραγματικῆς ἱστορίας περιγινομένην ἐμπειρίαν· μόνη γὰρ αὕτη χωρὶς βλάβης ἐπὶ παντὸς καιροῦ καὶ περιστάσεως κριτὰς ἀληθινοὺς ἀποτελεῖ τοῦ βελτίονος. ταῦτα μὲν οὖν ἡμῖν ἐπὶ τοσοῦτον εἰρήσθω.", "st": "1.35"}, {"sp": "N", "t": "Καρχηδόνιοι δέ, κατὰ νοῦν ἁπάντων σφίσι κεχωρηκότων, ὑπερβολὴν χαρᾶς οὐκ ἀπέλιπον διά τε τῆς πρὸς τὸν θεὸν εὐχαριστίας καὶ διὰ τῆς μετ’ ἀλλήλων φιλοφροσύνης. Ξάνθιππος δὲ τηλικαύτην ἐπίδοσιν καὶ ῥοπὴν ποιήσας τοῖς Καρχηδονίων πράγμασιν μετ’ οὐ πολὺν χρόνον ἀπέπλευσεν πάλιν, φρονίμως καὶ συνετῶς βουλευσάμενος. αἱ γὰρ ἐπιφανεῖς καὶ παράδοξοι πράξεις βαρεῖς μὲν τοὺς φθόνους, ὀξείας δὲ τὰς διαβολὰς γεννῶσιν· ἃς οἱ μὲν ἐγχώριοι διά τε τὰς συγγενείας καὶ τὸ τῶν φίλων πλῆθος οἷοί τ’ ἂν εἶεν ἐπὶ πολὺν χρόνον ἀναφέρειν, οἱ δὲ ξένοι ταχέως ἐφ’ ἑκατέρων τούτων ἡττῶνται καὶ κινδυνεύουσι. λέγεται δὲ καὶ ἕτερος ὑπὲρ τῆς ἀπαλλαγῆς τῆς Ξανθίππου λόγος, ὃν πειρασόμεθα διασαφεῖν οἰκειότερον λαβόντες τοῦ παρόντος καιρόν. Ῥωμαῖοι δέ, προσπεσόντων σφίσι παρ’ ἐλπίδα τῶν ἐν Λιβύῃ συμβεβηκότων, εὐθέως ἐγίνοντο πρὸς τὸ καταρτίζειν τὸν στόλον καὶ τοὺς ἄνδρας ἐξαιρεῖσθαι τοὺς ἐν τῇ Λιβύῃ διασεσωσμένους. οἱ δὲ Καρχηδόνιοι μετὰ ταῦτα στρατοπεδεύσαντες ἐπολιόρκουν τὴν Ἀσπίδα, σπουδάζοντες ἐγκρατεῖς γενέσθαι τῶν ἐκ τῆς μάχης διαφυγόντων. διὰ δὲ τὴν γενναιότητα καὶ τόλμαν τῶν ἀνδρῶν οὐδαμῶς ἑλεῖν δυνάμενοι τέλος ἀπέστησαν τῆς πολιορκίας. προσπεσόντος δ’ αὐτοῖς ἐξαρτύειν τὸν στόλον τοὺς Ῥωμαίους καὶ μέλλειν αὖθις ἐπὶ τὴν Λιβύην ποιεῖσθαι τὸν πλοῦν, τὰ μὲν ἐπεσκεύαζον σκάφη, τὰ δ’ ἐκ καταβολῆς ἐναυπηγοῦντο. ταχὺ δὲ συμπληρώσαντες ναῦς διακοσίας ἀνήχθησαν καὶ παρεφύλαττον τὸν ἐπίπλουν τῶν ὑπεναντίων. οἱ δὲ Ῥωμαῖοι τῆς θερείας ἀρχομένης καθελκύσαντες τριακόσια καὶ πεντήκοντα σκάφη καὶ στρατηγοὺς ἐπιστήσαντες Μάρκον Αἰμίλιον καὶ Σερούιον Φόλουιον ἐξαπέστελλον. οἱ δ’ ἀναχθέντες ἔπλεον παρὰ τὴν Σικελίαν ὡς ἐπὶ τῆς Λιβύης. συμμίξαντες δὲ περὶ τὴν Ἑρμαίαν τῷ τῶν Καρχηδονίων στόλῳ, τούτους μὲν ἐξ ἐφόδου καὶ ῥᾳδίως τρεψάμενοι ναῦς ἔλαβον αὐτάνδρους ἑκατὸν δεκατέτταρας· τοὺς δ’ ἐν Λιβύῃ διαμείναντας νεανίσκους ἀναλαβόντες ἐκ τῆς Ἀσπίδος ἔπλεον αὖθις ἐπὶ τῆς Σικελίας.", "st": "1.36"}, {"sp": "N", "t": "διάραντες δὲ τὸν πόρον ἀσφαλῶς καὶ προσμίξαντες τῇ τῶν Καμαριναίων χώρᾳ τηλικούτῳ περιέπεσον χειμῶνι καὶ τηλικαύταις συμφοραῖς ὥστε μηδ’ ἂν εἰπεῖν ἀξίως δύνασθαι διὰ τὴν ὑπερβολὴν τοῦ συμβάντος. τῶν γὰρ ἑξήκοντα καὶ τεττάρων πρὸς ταῖς τριακοσίαις ναυσὶν ὀγδοήκοντα μόνον συνέβη περιλειφθῆναι σκάφη, τῶν δὲ λοιπῶν τὰ μὲν ὑποβρύχια γενέσθαι, τὰ δ’ ὑπὸ τῆς ῥαχίας πρὸς ταῖς σπιλάσι καὶ τοῖς ἀκρωτηρίοις καταγνύμενα πλήρη ποιῆσαι σωμάτων τὴν παραλίαν καὶ ναυαγίων. ταύτης δὲ μείζω περιπέτειαν ἐν ἑνὶ καιρῷ κατὰ θάλατταν οὐδ’ ἱστορῆσθαι συμβέβηκεν. ἧς τὴν αἰτίαν οὐχ οὕτως εἰς τὴν τύχην ὡς εἰς τοὺς ἡγεμόνας ἐπανοιστέον· πολλὰ γὰρ τῶν κυβερνητῶν διαμαρτυραμένων μὴ πλεῖν παρὰ τὴν ἔξω πλευρὰν τῆς Σικελίας τὴν πρὸς τὸ Λιβυκὸν πέλαγος ἐστραμμένην διὰ τὸ τραχεῖαν εἶναι καὶ δυσπροσόρμιστον, ἅμα δὲ καὶ τὴν μὲν οὐδέπω καταλήγειν ἐπισημασίαν, τὴν δ’ ἐπιφέρεσθαι· μεταξὺ γὰρ ἐποιοῦντο τὸν πλοῦν τῆς Ὠρίωνος καὶ κυνὸς ἐπιτολῆς οὐθενὶ προσσχόντες τῶν λεγομένων ἔπλεον ἔξω πελάγιοι, σπουδάζοντές τινας τῶν ἐν τῷ παράπλῳ πόλεις τῇ τοῦ γεγονότος εὐτυχήματος φαντασίᾳ καταπληξάμενοι προσλαβέσθαι. πλὴν οὗτοι μὲν μικρῶν ἐλπίδων ἕνεκα μεγάλοις περιτυχόντες ἀτυχήμασι τότε τὴν αὑτῶν ἀβουλίαν ἔγνωσαν. καθόλου δὲ Ῥωμαῖοι πρὸς πάντα χρώμενοι τῇ βίᾳ καὶ τὸ προτεθὲν οἰόμενοι δεῖν κατ’ ἀνάγκην ἐπιτελεῖν καὶ μηδὲν ἀδύνατον εἶναι σφίσι τῶν ἅπαξ δοξάντων, ἐν πολλοῖς μὲν κατορθοῦσι διὰ τὴν τοιαύτην ὁρμήν, ἐν τισὶ δὲ προφανῶς σφάλλονται, καὶ μάλιστ’ ἐν τοῖς κατὰ θάλατταν. ἐπὶ μὲν γὰρ τῆς γῆς πρὸς ἀνθρώπους καὶ τὰ τούτων ἔργα ποιούμενοι τὰς ἐπιβολὰς τὰ μὲν πολλὰ κατορθοῦσι διὰ τὸ πρὸς παραπλησίους δυνάμεις χρῆσθαι τῇ βίᾳ, ποτὲ δὲ καὶ σπανίως ἀποτυγχάνουσι· πρὸς δὲ τὴν θάλατταν καὶ πρὸς τὸ περιέχον ὅταν παραβάλλωνται καὶ βιαιομαχῶσι, μεγάλοις ἐλαττώμασι περιπίπτουσιν. ὃ καὶ τότε καὶ πλεονάκις αὐτοῖς ἤδη συνέβη καὶ συμβήσεται πάσχειν, ἕως ἄν ποτε διορθώσωνται τὴν τοιαύτην τόλμαν καὶ βίαν, καθ’ ἣν οἴονται δεῖν αὑτοῖς πάντα καιρὸν εἶναι πλωτὸν καὶ πορευτόν.", "st": "1.37"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι, συνέντες τὸν γεγονότα φθόρον τοῦ τῶν Ῥωμαίων στόλου καὶ νομίσαντες κατὰ μὲν γῆν ἀξιόχρεως σφᾶς εἶναι διὰ τὸ προγεγονὸς εὐτύχημα, κατὰ δὲ θάλατταν διὰ τὴν εἰρημένην τῶν Ῥωμαίων περιπέτειαν, ὥρμησαν προθυμότερον ἐπί τε τὰς ναυτικὰς καὶ πεζικὰς παρασκευάς. καὶ τὸν μὲν Ἀσδρούβαν εὐθὺς ἐξαπέστελλον εἰς τὴν Σικελίαν, δόντες αὐτῷ τούς τε προϋπάρχοντας καὶ τοὺς ἐκ τῆς Ἡρακλείας παραγεγονότας στρατιώτας, ἅμα δὲ τούτοις ἐλέφαντας ἑκατὸν καὶ τετταράκοντα. τοῦτον δ’ ἐκπέμψαντες διακοσίας κατεσκευάζοντο ναῦς καὶ τἄλλα τὰ πρὸς τὸν πλοῦν ἡτοίμαζον. ὁ δ’ Ἀσδρούβας διακομισθεὶς εἰς τὸ Λιλύβαιον ἀσφαλῶς τά τε θηρία καὶ τὰς δυνάμεις ἐγύμναζεν καὶ δῆλος ἦν ἀντιποιησόμενος τῶν ὑπαίθρων. Ῥωμαῖοι δὲ τῶν ἐκ τῆς ναυαγίας ἀνακομισθέντων διακούσαντες τὸ κατὰ μέρος βαρέως μὲν ἤνεγκαν τὸ γεγονός· οὐ βουλόμενοι δὲ καθάπαξ εἴκειν, αὖθις ἔγνωσαν ἐκ δρυόχων εἴκοσι καὶ διακόσια ναυπηγεῖσθαι σκάφη. τούτων δὲ τὴν συντέλειαν ἐν τριμήνῳ λαβόντων, ὅπερ οὐδὲ πιστεῦσαι ῥᾴδιον, εὐθέως οἱ κατασταθέντες ἄρχοντες Αὖλος Ἀτίλιος καὶ Γνάιος Κορνήλιος καταρτίσαντες τὸν στόλον ἀνήχθησαν, καὶ πλεύσαντες διὰ πορθμοῦ προσέλαβον ἐκ τῆς Μεσσήνης τὰ διασωθέντα τῶν πλοίων ἐκ τῆς ναυαγίας καὶ κατάραντες εἰς Πάνορμον τῆς Σικελίας τριακοσίαις ναυσίν, ἥπερ ἦν βαρυτάτη πόλις τῆς Καρχηδονίων ἐπαρχίας, ἐνεχείρησαν αὐτὴν πολιορκεῖν. συστησάμενοι δὲ κατὰ διττοὺς τόπους ἔργα καὶ τἄλλα παρασκευασάμενοι προσήγαγον τὰς μηχανάς. ῥᾳδίως δὲ τοῦ παρὰ θάλατταν πύργου πεσόντος, καὶ βιασαμένων ταύτῃ τῶν στρατιωτῶν, ἡ μὲν καλουμένη Νέα πόλις ἑαλώκει κατὰ κράτος· ἡ δὲ Παλαιὰ προσαγορευομένη τούτου συμβάντος ἐκινδύνευσεν. διὸ καὶ ταχέως ἐνέδωκαν αὐτὴν οἱ κατοικοῦντες. γενόμενοι δ’ ἐγκρατεῖς οὗτοι μὲν ἀπέπλευσαν εἰς τὴν Ῥώμην, ἀπολιπόντες φυλακὴν τῆς πόλεως.", "st": "1.38"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τῆς θερείας ἐπιγενομένης οἱ κατασταθέντες ἄρχοντες Γνάιος Σερουίλιος καὶ Γάιος Σεμπρώνιος ἀνέπλευσαν παντὶ τῷ στόλῳ καὶ διάραντες εἰς τὴν Σικελίαν ἀφώρμησαν ἐντεῦθεν εἰς τὴν Λιβύην. κομιζόμενοι δὲ παρὰ τὴν χώραν ἐποιοῦντο καὶ πλείστας ἀποβάσεις. ἐν αἷς οὐδὲν ἀξιόλογον πράττοντες παρεγίνοντο πρὸς τὴν τῶν Λωτοφάγων νῆσον, ἣ καλεῖται μὲν Μῆνιγξ, οὐ μακρὰν δ’ ἀπέχει τῆς μικρᾶς Σύρτεως. ἐν ᾗ προσπεσόντες εἴς τινα βράχεα διὰ τὴν ἀπειρίαν, γενομένης ἀμπώτεως καὶ καθισάντων τῶν πλοίων εἰς πᾶσαν ἦλθον ἀπορίαν. οὐ μὴν ἀλλὰ πάλιν ἀνελπίστως μετά τινα χρόνον ἐπενεχθείσης τῆς θαλάττης, ἐκρίψαντες ἐκ τῶν πλοίων πάντα τὰ βάρη μόλις ἐκούφισαν τὰς ναῦς. οὗ γενομένου φυγῇ παραπλήσιον ἐποιήσαντο τὸν ἀπόπλουν. ἁψάμενοι δὲ τῆς Σικελίας καὶ κάμψαντες τὸ Λιλύβαιον καθωρμίσθησαν εἰς Πάνορμον. ἐντεῦθεν δὲ ποιούμενοι παραβόλως καὶ διὰ πόρου τὸν πλοῦν εἰς τὴν Ῥώμην πάλιν περιέπεσον χειμῶνι τηλικούτῳ τὸ μέγεθος ὥστε πλείω τῶν ἑκατὸν καὶ πεντήκοντα πλοίων ἀποβαλεῖν. οἱ δ’ ἐν τῇ Ῥώμῃ τούτων συμβάντων, καίπερ ὄντες ἐν παντὶ φιλότιμοι διαφερόντως, ὅμως τότε διὰ τὸ μέγεθος καὶ τὸ πλῆθος τῶν συμπτωμάτων τοῦ μὲν ἔτι στόλον ἁθροίζειν ἀναγκασθέντες ὑπὸ τῶν πραγμάτων ἀπέστησαν, ἐν δὲ ταῖς πεζικαῖς δυνάμεσι τὰς ὑπολοίπους ἔχοντες ἐλπίδας, τοὺς μὲν στρατηγοὺς ἀπέστελλον Λεύκιον Καικίλιον καὶ Γάιον Φούριον καὶ στρατόπεδα μετὰ τούτων εἰς τὴν Σικελίαν, ἑξήκοντα δὲ μόνον ἐπλήρωσαν ναῦς χάριν τοῦ τὰς ἀγορὰς κομίζειν τοῖς στρατοπέδοις. ἐκ δὲ τῶν εἰρημένων περιπετειῶν συνέβη πάλιν ἐπικυδέστερα γενέσθαι τὰ τῶν Καρχηδονίων πράγματα. τῆς μὲν γὰρ θαλάττης ἀδεῶς ἐπεκράτουν ἐκκεχωρηκότων τῶν Ῥωμαίων, ἐν δὲ ταῖς πεζικαῖς δυνάμεσι μεγάλας εἶχον ἐλπίδας. καὶ τοῦτ’ ἔπασχον οὐκ ἀλόγως· οἱ γὰρ Ῥωμαῖοι, διαδοθείσης φήμης περὶ τῆς ἐν τῇ Λιβύῃ μάχης ὅτι τὰ θηρία τάς τε τάξεις αὐτῶν διασπάσαι καὶ τοὺς πλείστους διαφθείραι τῶν ἀνδρῶν, οὕτως ἦσαν κατάφοβοι τοὺς ἐλέφαντας ὡς ἐπὶ δύ’ ἐνιαυτοὺς τοὺς ἑξῆς τῶν προειρημένων καιρῶν πολλάκις μὲν ἐν τῇ Λιλυβαιίτιδι χώρᾳ, πολλάκις δ’ ἐν τῇ Σελινουντίᾳ παραταττόμενοι τοῖς πολεμίοις ἐν ἓξ καὶ πέντε σταδίοις οὐκ ἐθάρρησαν οὐδέποτε κατάρξαι τῆς μάχης οὐδ’ εἰς τοὺς ὁμαλοὺς καθόλου συγκαταβῆναι τόπους, δεδιότες τὴν τῶν ἐλεφάντων ἔφοδον. Θέρμαν δὲ μόνον καὶ Λιπάραν ἐξεπολιόρκησαν ἐν τούτοις τοῖς καιροῖς, ἀντεχόμενοι τῶν ὀρεινῶν καὶ δυσδιαβάτων τόπων. διὸ καὶ θεωροῦντες οἱ Ῥωμαῖοι τὴν ἐν τοῖς πεζικοῖς στρατοπέδοις πτοίαν καὶ δυσελπιστίαν αὖθις ἔγνωσαν ἐκ μεταμελείας ἀντιλαμβάνεσθαι τῆς θαλάττης. καὶ καταστήσαντες στρατηγοὺς Γάιον Ἀτίλιον καὶ Λεύκιον Μάλιον ναυπηγοῦνται πεντήκοντα σκάφη καὶ κατέγραφον καὶ συνήθροιζον στόλον ἐνεργῶς.", "st": "1.39"}, {"sp": "N", "t": "ὁ δὲ προεστὼς τῶν Καρχηδονίων Ἀσδρούβας, ὁρῶν ἀποδειλιῶντας τοὺς Ῥωμαίους ἐν ταῖς προγεγενημέναις παρατάξεσιν, πυθόμενος τὸν μὲν ἕνα τῶν στρατηγῶν μετὰ τῆς ἡμισείας δυνάμεως εἰς τὴν Ἰταλίαν ἀπηλλάχθαι, τὸν δὲ Καικίλιον ἐν τῷ Πανόρμῳ διατρίβειν τὸ λοιπὸν μέρος ἔχοντα τῆς στρατιᾶς, βουλόμενον ἐφεδρεῦσαι τοῖς τῶν συμμάχων καρποῖς ἀκμαζούσης τῆς συγκομιδῆς, ἀναλαβὼν ἐκ τοῦ Λιλυβαίου τὴν δύναμιν ὥρμησεν καὶ κατεστρατοπέδευσεν πρὸς τοῖς ὅροις τῆς χώρας τῆς Πανορμίτιδος. ὁ δὲ Καικίλιος, θεωρῶν αὐτὸν κατατεθαρρηκότα, καὶ σπουδάζων ἐκκαλεῖσθαι τὴν ὁρμὴν αὐτοῦ, συνεῖχε τοὺς στρατιώτας ἐντὸς τῶν πυλῶν. οἷς ἐπαιρόμενος Ἀσδρούβας, ὡς οὐ τολμῶντος ἀντεξιέναι τοῦ Καικιλίου, θρασέως ὁρμήσας παντὶ τῷ στρατεύματι κατῆρε διὰ τῶν στενῶν εἰς τὴν Πανορμῖτιν. φθείροντος δὲ τοὺς καρποὺς αὐτοῦ μέχρι τῆς πόλεως, ἔμενεν ἐπὶ τῆς ὑποκειμένης γνώμης ὁ Καικίλιος, ἕως αὐτὸν ἐξεκαλέσατο διαβῆναι τὸν πρὸ τῆς πόλεως ποταμόν. ἐπεὶ δὲ τὰ θηρία διεβίβασαν οἱ Καρχηδόνιοι καὶ τὴν δύναμιν, τὸ τηνικαῦτα δὲ τοὺς εὐζώνους ἐξαποστέλλων ἠρέθιζε, μέχρι πᾶν αὐτοὺς ἐκτάξαι τὸ στρατόπεδον ἠνάγκασε. συνθεασάμενος δὲ γινόμενον ὃ προέθετο, τινὰς μὲν τῶν εὐκινήτων πρὸ τοῦ τείχους καὶ τάφρου παρενέβαλε, προστάξας, ἂν ἐγγίζῃ τὰ θηρία πρὸς αὐτούς, χρῆσθαι τοῖς βέλεσιν ἀφθόνως, ὅταν δ’ ἐκπιέζωνται, καταφεύγειν εἰς τὴν τάφρον καὶ πάλιν ἐκ ταύτης ὁρμωμένους εἰσακοντίζειν εἰς τὰ προσπίπτοντα τῶν ζῴων· τοῖς δ’ ἐκ τῆς ἀγορᾶς βαναύσοις φέρειν προσέταξε τὰ βέλη καὶ παραβάλλειν ἔξω παρὰ τὸν θεμέλιον τοῦ τείχους. αὐτὸς δὲ τὰς σημείας ἔχων ἐπὶ τῆς κατὰ τὸ λαιὸν κέρας τῶν ὑπεναντίων κειμένης πύλης ἐφεστήκει, πλείους ἀεὶ καὶ πλείους ἐπαποστέλλων τοῖς ἀκροβολιζομένοις. ἅμα δὲ τῷ τούτων ὁλοσχερεστέραν γενέσθαι τὴν συμπλοκὴν ἀντιφιλοδοξοῦντες οἱ τῶν ἐλεφάντων ἐπιστάται πρὸς τὸν Ἀσδρούβαν καὶ βουλόμενοι δι’ αὑτῶν ποιῆσαι τὸ προτέρημα πάντες ὥρμησαν ἐπὶ τοὺς προκινδυνεύοντας· τρεψάμενοι δὲ τούτους ῥᾳδίως συνεδίωξαν εἰς τὴν τάφρον. προσπεσόντων δὲ τῶν θηρίων καὶ τιτρωσκομένων μὲν ὑπὸ τῶν ἐκ τοῦ τείχους τοξευόντων, συνακοντιζομένων δ’ ἐνεργοῖς καὶ πυκνοῖς τοῖς ὑσσοῖς καὶ τοῖς γρόσφοις ὑπ’ ἀκεραίων τῶν πρὸ τῆς τάφρου διατεταγμένων, συμβελῆ γινόμενα καὶ κατατραυματιζόμενα ταχέως διεταράχθη καὶ στραφέντα κατὰ τῶν ἰδίων ἐφέρετο, τοὺς μὲν ἄνδρας καταπατοῦντα καὶ διαφθείροντα, τὰς δὲ τάξεις συγχέοντα καὶ κατασπῶντα τὰς αὑτῶν. ἃ καὶ κατιδὼν ὁ Καικίλιος ἐξῆγε τὴν δύναμιν ἐνεργῶς· καὶ συμπεσὼν ἐκ πλαγίου κατὰ κέρας τεταραγμένοις τοῖς πολεμίοις ἀκεραίους ἔχων καὶ συντεταγμένους τροπὴν ἐποίει τῶν ὑπεναντίων ἰσχυρὰν καὶ πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, τοὺς δὲ λοιποὺς ἠνάγκασε φεύγειν προτροπάδην. θηρία δὲ σὺν αὐτοῖς μὲν Ἰνδοῖς ἔλαβε δέκα, τῶν δὲ λοιπῶν τοὺς Ἰνδοὺς ἀπερριφότων μετὰ τὴν μάχην περιελασάμενος ἐκυρίευσε πάντων. ταῦτα δ’ ἐπιτελεσάμενος ὁμολογουμένως αἴτιος ἐδόκει γεγονέναι τοῖς Ῥωμαίων πράγμασι τοῦ πάλιν ἀναθαρρῆσαι τὰς πεζικὰς δυνάμεις καὶ κρατῆσαι τῶν ὑπαίθρων.", "st": "1.40"}, {"sp": "N", "t": "τοῦ δὲ προτερήματος τούτου προσπεσόντος εἰς τὴν Ῥώμην, περιχαρεῖς ἦσαν οὐχ οὕτως ἐπὶ τῷ τοὺς πολεμίους ἠλαττῶσθαι τῶν θηρίων ἐστερημένους, ὡς ἐπὶ τῷ τοὺς ἰδίους τεθαρρηκέναι τῶν ἐλεφάντων κεκρατηκότας. διὸ καὶ πάλιν ἐπερρώσθησαν διὰ ταῦτα κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν εἰς τὸ μετὰ στόλου καὶ ναυτικῆς δυνάμεως τοὺς στρατηγοὺς ἐπὶ τὰς πράξεις ἐκπέμπειν, σπουδάζοντες εἰς δύναμιν πέρας ἐπιθεῖναι τῷ πολέμῳ. παρασκευασθέντων δὲ τῶν ἐπιτηδείων πρὸς τὴν ἐξαποστολὴν ἔπλεον οἱ στρατηγοὶ διακοσίαις ναυσὶν ὡς ἐπὶ τῆς Σικελίας. ἔτος δ’ ἦν τῷ πολέμῳ τετταρεσκαιδέκατον. καθορμισθέντες δὲ πρὸς τὸ Λιλύβαιον, ἅμα καὶ τῶν πεζικῶν ἐκεῖ στρατοπέδων αὐτοῖς ἀπηντηκότων, ἐνεχείρουν πολιορκεῖν, ὅτι κρατήσαντες ταύτης ῥᾳδίως μεταβιβάσουσι τὸν πόλεμον εἰς τὴν Λιβύην. σχεδὸν δὲ περί γε τούτου τοῦ μέρους καὶ τῶν Καρχηδονίων οἱ προεστῶτες ὡμοδόξουν καὶ τοὺς αὐτοὺς εἶχον λογισμοὺς τοῖς Ῥωμαίοις. διὸ καὶ τἄλλα πάρεργα ποιησάμενοι περὶ τὸ βοηθεῖν ἐγίνοντο καὶ παραβάλλεσθαι καὶ πᾶν ὑπομένειν ὑπὲρ τῆς προειρημένης πόλεως διὰ τὸ μηδεμίαν ἀφορμὴν καταλείπεσθαι σφίσιν, πάσης δὲ τῆς ἄλλης Σικελίας ἐπικρατεῖν Ῥωμαίους πλὴν Δρεπάνων. ἵνα δὲ μὴ τοῖς ἀγνοοῦσι τοὺς τόπους ἀσαφῆ τὰ λεγόμενα γίνηται, πειρασόμεθα διὰ βραχέων ἀγαγεῖν εἰς ἔννοιαν τῆς εὐκαιρίας καὶ θέσεως αὐτῶν τοὺς ἐντυγχάνοντας.", "st": "1.41"}, {"sp": "N", "t": "τὴν μὲν οὖν σύμπασαν Σικελίαν τῇ θέσει τετάχθαι συμβαίνει πρὸς τὴν Ἰταλίαν καὶ τἀκείνης πέρατα παραπλησίως τῇ τῆς Πελοποννήσου θέσει πρὸς τὴν λοιπὴν Ἑλλάδα καὶ τὰ ταύτης ἄκρα, τούτῳ δ’ αὐτῷ διαφέρειν ἀλλήλων, ᾗ ’κείνη μὲν χερρόνησός ἐστιν, αὕτη δὲ νῆσος· ἧς μὲν γὰρ ὁ μεταξὺ τόπος ἐστὶ πορευτός, ἧς δὲ πλωτός. τὸ δὲ σχῆμα τῆς Σικελίας ἐστὶ μὲν τρίγωνον, αἱ δὲ κορυφαὶ τῶν γωνιῶν ἑκάστης ἀκρωτηρίων λαμβάνουσι τάξεις, ὧν τὸ μὲν πρὸς μεσημβρίαν νεῦον, εἰς δὲ τὸ Σικελικὸν πέλαγος ἀνατεῖνον Πάχυνος καλεῖται, τὸ δ’ εἰς τὰς ἄρκτους κεκλιμένον ὁρίζει μὲν τοῦ πορθμοῦ τὸ πρὸς δύσεις μέρος, ἀπέχει δὲ τῆς Ἰταλίας ὡς δεκαδύο στάδια, προσαγορεύεται δὲ Πελωριάς. τὸ δὲ τρίτον τέτραπται μὲν εἰς αὐτὴν τὴν Λιβύην, ἐπίκειται δὲ τοῖς προκειμένοις τῆς Καρχηδόνος ἀκρωτηρίοις εὐκαίρως, διέχον ὡς χιλίους σταδίους, νεύει δ’ εἰς χειμερινὰς δύσεις, διαιρεῖ δὲ τὸ Λιβυκὸν καὶ τὸ Σαρδῷον πέλαγος, προσαγορεύεται δὲ Λιλύβαιον. ἐπὶ δὲ τούτῳ πόλις ὁμώνυμος κεῖται τῷ τόπῳ, περὶ ἣν τότε συνέβαινε τοὺς Ῥωμαίους συνίστασθαι τὴν πολιορκίαν, τείχεσί τε διαφερόντως ἠσφαλισμένην καὶ πέριξ τάφρῳ βαθείᾳ καὶ τενάγεσιν ἐκ θαλάττης, δι’ ὧν ἐστιν εἰς τοὺς λιμένας εἴσπλους πολλῆς δεόμενος ἐμπειρίας καὶ συνηθείας. ταύτῃ δὲ προσστρατοπεδεύσαντες ἐξ ἑκατέρου μέρους οἱ Ῥωμαῖοι καὶ τὰ μεταξὺ τῶν στρατοπέδων τάφρῳ καὶ χάρακι καὶ τείχει διαλαβόντες ἤρξαντο προσάγειν ἔργα κατὰ τὸν ἔγγιστα κείμενον τῆς θαλάττης πύργον ὡς πρὸς τὸ Λιβυκὸν πέλαγος. προσκατασκευάζοντες δ’ ἀεὶ τοῖς ὑποκειμένοις καὶ παρεκτείνοντες τῶν ἔργων τὰς κατασκευὰς τέλος ἓξ πύργους τοὺς συνεχεῖς τῷ προειρημένῳ κατέβαλον, τοὺς δὲ λοιποὺς πάντας ἅμα κριοκοπεῖν ἐνεχείρησαν. γινομένης δ’ ἐνεργοῦ καὶ καταπληκτικῆς τῆς πολιορκίας, καὶ τῶν πύργων τῶν μὲν πονούντων ἀν’ ἑκάστην ἡμέραν, τῶν δ’ ἐρειπομένων, ἅμα δὲ καὶ τῶν ἔργων ἐπιβαινόντων ἀεὶ καὶ μᾶλλον ἐντὸς τῆς πόλεως, ἦν ἰσχυρὰ διατροπὴ καὶ κατάπληξις παρὰ τοῖς πολιορκουμένοις, καίπερ ὄντων ἐν τῇ πόλει χωρὶς τοῦ πολιτικοῦ πλήθους αὐτῶν τῶν μισθοφόρων εἰς μυρίους. οὐ μὴν ἀλλ’ ὅ γε στρατηγὸς αὐτῶν Ἰμίλκων οὐδὲν παρέλειπε τῶν δυνατῶν, ἀλλὰ τὰ μὲν ἀντοικοδομῶν, τὰ δ’ ἀντιμεταλλεύων οὐ τὴν τυχοῦσαν ἀπορίαν παρεῖχε τοῖς ὑπεναντίοις. ἔτι δὲ καθ’ ἑκάστην ἡμέραν ἐπιπορευόμενος καὶ τοῖς ἔργοις ἐγχειρῶν, εἴ πως δύναιτο πῦρ ἐμβαλεῖν, πολλοὺς ὑπὲρ τούτου τοῦ μέρους καὶ παραβόλους ἀγῶνας δὴ συνίστατο καὶ μεθ’ ἡμέραν καὶ νύκτωρ, ὥστε πλείους ἐνίοτε γίνεσθαι νεκροὺς ἐν ταῖς τοιαύταις συμπλοκαῖς τῶν εἰωθότων πίπτειν ἐν ταῖς παρατάξεσι.", "st": "1.42"}, {"sp": "N", "t": "κατὰ δὲ τοὺς καιροὺς τούτους τῶν ἡγεμόνων τινὲς τῶν τὰς μεγίστας χώρας ἐχόντων ἐν τοῖς μισθοφόροις συλλαλήσαντες ἑαυτοῖς ὑπὲρ τοῦ τὴν πόλιν ἐνδοῦναι τοῖς Ῥωμαίοις καὶ πεπεισμένοι πειθαρχήσειν σφίσι τοὺς ὑποτεταγμένους, ἐξεπήδησαν νυκτὸς ἐκ τῆς πόλεως ἐπὶ τὸ στρατόπεδον καὶ διελέγοντο τῷ τῶν Ῥωμαίων στρατηγῷ περὶ τούτων. ὁ δ’ Ἀχαιὸς Ἀλέξων ὁ καὶ τοῖς Ἀκραγαντίνοις κατὰ τοὺς ἐπάνω χρόνους αἴτιος γενόμενος τῆς σωτηρίας, καθ’ ὃν καιρὸν ἐπεβάλοντο παρασπονδεῖν αὐτοὺς οἱ τῶν Συρακοσίων μισθοφόροι, καὶ τότε πρῶτος συνεὶς τὴν πρᾶξιν ἀνήγγειλε τῷ στρατηγῷ τῶν Καρχηδονίων. ὁ δὲ διακούσας παραχρῆμα συνῆγε τοὺς καταλειπομένους τῶν ἡγεμόνων καὶ παρεκάλει μετὰ δεήσεως, μεγάλας δωρεὰς καὶ χάριτας ὑπισχνούμενος, ἐὰν ἐμμείνωσι τῇ πρὸς αὐτὸν πίστει καὶ μὴ κοινωνήσωσι τοῖς ἐξεληλυθόσι τῆς ἐπιβολῆς. δεχομένων δὲ προθύμως τοὺς λόγους, εὐθέως μετ’ αὐτῶν ἀπέστειλε πρὸς μὲν τοὺς Κελτοὺς Ἀννίβαν τὸν υἱὸν τὸν Ἀννίβου τοῦ μεταλλάξαντος ἐν Σαρδόνι διὰ τὴν προγεγενημένην ἐν τῇ στρατείᾳ πρὸς αὐτοὺς συνήθειαν, ἐπὶ δὲ τοὺς ἄλλους μισθοφόρους Ἀλέξωνα διὰ τὴν παρ’ ἐκείνοις ἀποδοχὴν αὐτοῦ καὶ πίστιν· οἳ καὶ συναγαγόντες τὰ πλήθη καὶ παρακαλέσαντες, ἔτι δὲ πιστωσάμενοι τὰς προτεινομένας ἑκάστοις δωρεὰς ὑπὸ τοῦ στρατηγοῦ, ῥᾳδίως ἔπεισαν αὐτοὺς μένειν ἐπὶ τῶν ὑποκειμένων. διὸ καὶ μετὰ ταῦτα, τῶν ἐκπηδησάντων ἐκ τοῦ προφανοῦς ἐρχομένων πρὸς τὰ τείχη καὶ βουλομένων παρακαλεῖν καὶ λέγειν τι περὶ τῆς τῶν Ῥωμαίων ἐπαγγελίας, οὐχ οἷον προσεῖχον αὐτοῖς, ἀλλ’ ἁπλῶς οὐδ’ ἀκούειν ἠξίουν, βάλλοντες δὲ τοῖς λίθοις καὶ συνακοντίζοντες ἀπεδίωξαν ἀπὸ τοῦ τείχους. Καρχηδόνιοι μὲν οὖν διὰ τὰς προειρημένας αἰτίας παρὰ μικρὸν ἦλθον ἀπολέσαι τὰ πράγματα, παρασπονδηθέντες ὑπὸ τῶν μισθοφόρων· Ἀλέξων δὲ πρότερον Ἀκραγαντίνοις ἔσωσε διὰ τὴν πίστιν οὐ μόνον τὴν πόλιν καὶ τὴν χώραν, ἀλλὰ καὶ τοὺς νόμους καὶ τὴν ἐλευθερίαν, τότε δὲ Καρχηδονίοις αἴτιος ἐγένετο τοῦ μὴ σφαλῆναι τοῖς ὅλοις.", "st": "1.43"}, {"sp": "N", "t": "οἱ δ’ ἐν τῇ Καρχηδόνι τούτων μὲν οὐδὲν εἰδότες, συλλογιζόμενοι δὲ τὰς ἐν ταῖς πολιορκίαις χρείας, πληρώσαντες στρατιωτῶν πεντήκοντα ναῦς καὶ παρακαλέσαντες τοῖς ἁρμόζουσι λόγοις τῆς πράξεως τὸν ἐπὶ τούτοις τεταγμένον Ἀννίβαν, ὃς ἦν Ἀμίλκου μὲν υἱὸς τριήραρχος δὲ καὶ φίλος Ἀτάρβου πρῶτος, ἐξαπέστειλαν κατὰ σπουδήν, ἐντειλάμενοι μὴ καταμελλῆσαι, χρησάμενον δὲ σὺν καιρῷ τῇ τόλμῃ βοηθῆσαι τοῖς πολιορκουμένοις. ὁ δ’ ἀναχθεὶς μετὰ μυρίων στρατιωτῶν καὶ καθορμισθεὶς ἐν ταῖς καλουμέναις Αἰγούσσαις, μεταξὺ δὲ κειμέναις Λιλυβαίου καὶ Καρχηδόνος, ἐπετήρει τὸν πλοῦν. λαβὼν δ’ οὔριον καὶ λαμπρὸν ἄνεμον, ἐκπετάσας πᾶσι τοῖς ἀρμένοις καὶ κατουρώσας ἐπ’ αὐτὸ τὸ στόμα τοῦ λιμένος ἐποιεῖτο τὸν πλοῦν, ἔχων καθωπλισμένους καὶ πρὸς μάχην ἑτοίμους τοὺς ἄνδρας ἐπὶ τῶν καταστρωμάτων. οἱ δὲ Ῥωμαῖοι τὰ μὲν αἰφνιδίου γενομένης τῆς ἐπιφανείας, τὰ δὲ φοβούμενοι μὴ σὺν τοῖς πολεμίοις ὑπὸ τῆς βίας τοῦ πνεύματος συγκατενεχθῶσιν εἰς τὸν λιμένα τῶν ὑπεναντίων, τὸ μὲν διακωλύειν τὸν ἐπίπλουν τῆς βοηθείας ἀπέγνωσαν, ἐπὶ δὲ τῆς θαλάττης ἔστησαν καταπεπληγμένοι τὴν τῶν πολεμίων τόλμαν. τὸ δ’ ἐκ τῆς πόλεως πλῆθος ἡθροισμένον ἐπὶ τὰ τείχη πᾶν ἅμα μὲν ἠγωνία τὸ συμβησόμενον, ἅμα δ’ ἐπὶ τῷ παραδόξῳ τῆς ἐλπίδος ὑπερχαρὲς ὑπάρχον μετὰ κρότου καὶ κραυγῆς παρεκάλει τοὺς εἰσπλέοντας. Ἀννίβας δὲ παραβόλως καὶ τεθαρρηκότως εἰσδραμὼν καὶ καθορμισθεὶς εἰς τὸν λιμένα μετ’ ἀσφαλείας ἀπεβίβασε τοὺς στρατιώτας. οἱ δ’ ἐν τῇ πόλει πάντες οὐχ οὕτως ἦσαν ἐπὶ τῇ τῆς βοηθείας παρουσίᾳ περιχαρεῖς, καίπερ μεγάλην ἐλπίδα καὶ χεῖρα προσειληφότες, ὡς ἐπὶ τῷ μὴ τετολμηκέναι τοὺς Ῥωμαίους κωλῦσαι τὸν ἐπίπλουν τῶν Καρχηδονίων.", "st": "1.44"}, {"sp": "N", "t": "Ἰμίλκων δ’ ὁ τεταγμένος ἐπὶ τῆς πόλεως στρατηγός, θεωρῶν τὴν ὁρμὴν καὶ προθυμίαν τῶν μὲν ἐν τῇ πόλει διὰ τὴν παρουσίαν τῆς βοηθείας τῶν δὲ παραγεγονότων διὰ τὴν ἀπειρίαν τῶν περιεστώτων κακῶν, βουλόμενος ἀκεραίοις ἀποχρήσασθαι ταῖς ἑκατέρων ὁρμαῖς πρὸς τὴν διὰ τοῦ πυρὸς ἐπίθεσιν τοῖς ἔργοις, συνῆγε πάντας εἰς ἐκκλησίαν· παρακαλέσας δὲ τῷ καιρῷ τὰ πρέποντα διὰ πλειόνων καὶ παραστήσας ὁρμὴν ὑπερβάλλουσαν διά τε τὸ μέγεθος τῶν ἐπαγγελιῶν τοῖς κατ’ ἰδίαν ἀνδραγαθήσασι καὶ τὰς κατὰ κοινὸν ἐσομένας χάριτας αὐτοῖς καὶ δωρεὰς παρὰ Καρχηδονίων, ὁμοθυμαδὸν ἐπισημαινομένων καὶ βοώντων μὴ μέλλειν, ἀλλ’ ἄγειν αὐτούς, τότε μὲν ἐπαινέσας καὶ δεξάμενος τὴν προθυμίαν ἀφῆκε, παραγγείλας ἀναπαύεσθαι καθ’ ὥραν καὶ πειθαρχεῖν τοῖς ἡγουμένοις· μετ’ οὐ πολὺ δὲ συγκαλέσας τοὺς προεστῶτας αὐτῶν διένειμε τοὺς ἁρμόζοντας πρὸς τὴν ἐπίθεσιν ἑκάστοις τόπους καὶ τὸ σύνθημα καὶ τὸν καιρὸν τῆς ἐπιθέσεως ἐδήλωσε καὶ παρήγγειλε τοῖς ἡγεμόσι μετὰ πάντων τῶν ὑποτεταγμένων ἐπὶ τοῖς τόποις ἑωθινῆς εἶναι φυλακῆς. τῶν δὲ πειθαρχησάντων, ἐξαγαγὼν τὴν δύναμιν ἅμα τῷ φωτὶ κατὰ πλείους τόπους ἐνεχείρει τοῖς ἔργοις. οἱ δὲ Ῥωμαῖοι διὰ τὸ προορᾶσθαι τὸ μέλλον οὐκ ἀργῶς οὐδ’ ἀπαρασκεύως εἶχον, ἀλλ’ ἑτοίμως ἐβοήθουν πρὸς τὸ δεόμενον καὶ διεμάχοντο τοῖς πολεμίοις ἐρρωμένως. πάντων δ’ ἐν βραχεῖ χρόνῳ συμπεσόντων ἀλλήλοις ἦν ἀγὼν παράβολος πέριξ τοῦ τείχους· οἱ μὲν γὰρ ἐκ τῆς πόλεως ἦσαν οὐκ ἐλάττους δισμυρίων, οἱ δ’ ἔξωθεν ἔτι πλείους τούτων. ὅσῳ δὲ συνέβαινε τοὺς ἄνδρας ἐκτὸς τάξεως ποιεῖσθαι τὴν μάχην ἀναμὶξ κατὰ τὰς αὑτῶν προαιρέσεις, τοσούτῳ λαμπρότερος ἦν ὁ κίνδυνος, ὡς ἂν ἐκ τοσούτου πλήθους κατ’ ἄνδρα καὶ κατὰ ζυγὸν οἱονεὶ μονομαχικῆς συνεστώσης περὶ τοὺς ἀγωνιζομένους τῆς φιλοτιμίας. οὐ μὴν ἀλλ’ ἥ τε κραυγὴ καὶ τὸ σύστρεμμα διαφέρον ἦν πρὸς αὐτοῖς τοῖς ἔργοις. οἱ γὰρ ἀρχῆθεν ἐπ’ αὐτῷ τούτῳ παρ’ ἀμφοῖν ταχθέντες, οἱ μὲν ἐπὶ τῷ τρέψασθαι τοὺς ἐπὶ τῶν ἔργων οἱ δ’ ἐπὶ τῷ μὴ προέσθαι ταῦτα, τηλικαύτην ἐποιοῦντο φιλοτιμίαν καὶ σπουδήν, οἱ μὲν ἐξῶσαι σπεύδοντες, οἱ δ’ οὐδαμῶς εἶξαι τούτοις τολμῶντες, ὥστε διὰ τὴν προθυμίαν τέλος ἐν αὐταῖς μένοντες ταῖς ἐξ ἀρχῆς χώραις ἀπέθνησκον. οἵ γε μὴν ἅμα τούτοις ἀναμεμιγμένοι, δᾷδα καὶ στυππίον καὶ πῦρ ἔχοντες, οὕτω τολμηρῶς καὶ πανταχόθεν ἅμα προσπίπτοντες ἐνέβαλλον ταῖς μηχαναῖς ὥστε τοὺς Ῥωμαίους εἰς τὸν ἔσχατον παραγενέσθαι κίνδυνον, μὴ δυναμένους κατακρατῆσαι τῆς τῶν ἐναντίων ἐπιβολῆς. ὁ δὲ τῶν Καρχηδονίων στρατηγὸς θεωρῶν ἐν μὲν τῷ κινδύνῳ πολλοὺς ἀποθνήσκοντας, οὗ δ’ ἕνεκα ταῦτ’ ἔπραττεν, οὐ δυναμένους κρατῆσαι τῶν ἔργων, ἀνακαλεῖσθαι τοὺς ἑαυτοῦ παρήγγειλε τοῖς σαλπισταῖς. οἱ δὲ Ῥωμαῖοι παρ’ οὐδὲν ἐλθόντες τοῦ πάσας ἀποβαλεῖν τὰς παρασκευάς, τέλος ἐκράτησαν τῶν ἔργων καὶ πάντα διετήρησαν ἀσφαλῶς.", "st": "1.45"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀννίβας μετὰ τὴν χρείαν ταύτην ἐξέπλευσε νύκτωρ ἔτι μετὰ τῶν νεῶν λαθὼν τοὺς πολεμίους εἰς τὰ Δρέπανα πρὸς Ἀτάρβαν τὸν τῶν Καρχηδονίων στρατηγόν. διὰ γὰρ τὴν εὐκαιρίαν τοῦ τόπου καὶ τὸ κάλλος τοῦ περὶ τὰ Δρέπανα λιμένος ἀεὶ μεγάλην ἐποιοῦντο σπουδὴν οἱ Καρχηδόνιοι περὶ τὴν φυλακὴν αὐτοῦ. συμβαίνει δὲ τοῦ Λιλυβαίου τοῦτον ἀπέχειν τὸν τόπον ὡς ἂν ἑκατὸν καὶ εἴκοσι στάδια. τοῖς δ’ ἐν τῇ Καρχηδόνι βουλομένοις μὲν εἰδέναι τὰ περὶ τὸ Λιλύβαιον, οὐ δυναμένοις δὲ διὰ τὸ τοὺς μὲν συγκεκλεῖσθαι τοὺς δὲ παραφυλάττεσθαι φιλοτίμως, ἐπηγγείλατό τις ἀνὴρ τῶν ἐνδόξων, Ἀννίβας ἐπικαλούμενος Ῥόδιος, εἰσπλεύσας εἰς τὸ Λιλύβαιον καὶ γενόμενος αὐτόπτης ἅπαντα διασαφήσειν. οἱ δὲ τῆς ἐπαγγελίας μὲν ἀσμένως ἤκουσαν, οὐ μὴν ἐπίστευόν γε διὰ τὸ τῷ στόλῳ τοὺς Ῥωμαίους ἐπὶ τοῦ κατὰ τὸν εἴσπλουν στόματος ἐφορμεῖν. ὁ δὲ καταρτίσας τὴν ἰδίαν ναῦν ἀνήχθη· καὶ διάρας εἴς τινα τῶν πρὸ τοῦ Λιλυβαίου κειμένων νήσων, τῇ κατὰ πόδας ἡμέρᾳ λαβὼν εὐκαίρως ἄνεμον οὔριον περὶ τετάρτην ὥραν ἁπάντων τῶν πολεμίων ὁρώντων καὶ καταπεπληγμένων τὴν τόλμαν εἰσέπλευσεν. καὶ τὴν κατόπιν εὐθέως ἐγίνετο περὶ ἀναγωγήν. ὁ δὲ τῶν Ῥωμαίων στρατηγὸς βουλόμενος ἐπιμελέστερον τὸν κατὰ τὸν εἴσπλουν τόπον τηρεῖν, ἐξηρτυκὼς ἐν τῇ νυκτὶ δέκα ναῦς τὰς ἄριστα πλεούσας, αὐτὸς μὲν ἐπὶ τοῦ λιμένος ἑστὼς ἐθεώρει τὸ συμβαῖνον, ὁμοίως δὲ καὶ πᾶν τὸ στρατόπεδον· αἱ δὲ νῆες τοῦ στόματος ἐξ ἀμφοῖν τοῖν μεροῖν, ἐφ’ ὅσον ἦν δυνατὸν ἔγγιστα τοῖς τενάγεσι προσάγειν, ἐπεῖχον ἐπτερωκυῖαι πρὸς τὴν ἐμβολὴν καὶ σύλληψιν τῆς ἐκπλεῖν μελλούσης νεώς. ὁ δὲ Ῥόδιος ἐκ τοῦ προφανοῦς τὴν ἀναγωγὴν ποιησάμενος οὕτως κατανέστη τῶν πολεμίων τῇ τε τόλμῃ καὶ τῷ ταχυναυτεῖν ὥστ’ οὐ μόνον ἄτρωτον ἐξέπλευσε τὴν ναῦν ἔχων καὶ τοὺς ἄνδρας, οἷον ἑστῶτα παραδραμὼν τὰ σκάφη τῶν ὑπεναντίων, ἀλλὰ καὶ βραχὺ προπλεύσας ἐπέστη πτερώσας τὴν ναῦν, ὡσανεὶ προκαλούμενος τοὺς πολεμίους. οὐδενὸς δὲ τολμῶντος ἐπ’ αὐτὸν ἀντανάγεσθαι διὰ τὸ τάχος τῆς εἰρεσίας, ἀπέπλευσε καταναστὰς μιᾷ νηὶ παντὸς τοῦ τῶν ἐναντίων στόλου. καὶ τὸ λοιπὸν ἤδη πλεονάκις ποιῶν ταὐτὸ τοῦτο μεγάλην χρείαν παρείχετο, τοῖς μὲν Καρχηδονίοις ἀεὶ τὰ κατεπείγοντα διασαφῶν, τοὺς δὲ πολιορκουμένους εὐθαρσεῖς παρασκευάζων, τοὺς δὲ Ῥωμαίους καταπληττόμενος τῷ παραβόλῳ.", "st": "1.46"}, {"sp": "N", "t": "μέγιστα δὲ συνεβάλλετο πρὸς τὴν τόλμαν αὐτοῦ τὸ διὰ τῶν προβραχέων ἐκ τῆς ἐμπειρίας ἀκριβῶς σεσημειῶσθαι τὸν εἴσπλουν· ὑπεράρας γὰρ καὶ φαινόμενος ἔπειτ’ ἂν ἀπὸ τῶν κατὰ τὴν Ἰταλίαν μερῶν ἐλάμβανε τὸν ἐπὶ τῆς θαλάττης πύργον κατὰ πρῶρραν οὕτως ὥστε τοῖς πρὸς τὴν Λιβύην τετραμμένοις πύργοις τῆς πόλεως ἐπιπροσθεῖν ἅπασι· δι’ οὗ τρόπου μόνως ἐστὶ δυνατὸν ἐξ οὐρίας τοῦ κατὰ τὸν εἴσπλουν στόματος εὐστοχεῖν. τῇ δὲ τοῦ Ῥοδίου τόλμῃ πιστεύσαντες καὶ πλείους ἀπεθάρρησαν τῶν εἰδότων τοὺς τόπους τὸ παραπλήσιον ποιεῖν· ἐξ ὧν οἱ Ῥωμαῖοι δυσχρηστούμενοι τῷ συμβαίνοντι χωννύειν τὸ στόμα τοῦ λιμένος ἐπεχείρησαν. κατὰ μὲν οὖν τὸ πλεῖστον μέρος τῆς ἐπιβολῆς οὐδὲν ἤνυον διὰ τὸ βάθος τῆς θαλάττης καὶ διὰ τὸ μηθὲν δύνασθαι τῶν ἐμβαλλομένων στῆναι μηδὲ συμμεῖναι τὸ παράπαν, ἀλλ’ ὑπό τε τοῦ κλύδωνος καὶ τῆς τοῦ ῥοῦ βίας τὸ ῥιπτούμενον εὐθέως ἐν τῇ καταφορᾷ παρωθεῖσθαι καὶ διασκορπίζεσθαι, κατὰ δέ τινα τόπον ἔχοντα βράχεα συνέστη χῶμα μετὰ πολλῆς ταλαιπωρίας, ἐφ’ ᾧ τετρήρης ἐκτρέχουσα νυκτὸς ἐκάθισε καὶ τοῖς πολεμίοις ὑποχείριος ἐγένετο, διαφέρουσα τῇ κατασκευῇ τῆς ναυπηγίας. ἧς οἱ Ῥωμαῖοι κρατήσαντες καὶ πληρώματι καταρτίσαντες ἐπιλέκτῳ πάντας τοὺς εἰσπλέοντας, μάλιστα δὲ τὸν Ῥόδιον, ἐπετήρουν. ὁ δὲ κατὰ τύχην εἰσπλεύσας νυκτὸς μετὰ ταῦτα πάλιν ἀνήγετο φανερῶς. θεωρῶν δ’ ἐκ καταβολῆς αὑτῷ τὴν τετρήρη συνεξορμήσασαν, γνοὺς τὴν ναῦν διετράπη. τὸ μὲν οὖν πρῶτον ὥρμησεν ὡς καταταχήσων· τῇ δὲ τοῦ πληρώματος παρασκευῇ καταλαμβανόμενος, τέλος ἐπιστρέψας ἠναγκάσθη συμβαλεῖν τοῖς πολεμίοις. καταπροτερούμενος δὲ τοῖς ἐπιβατικοῖς διά τε τὸ πλῆθος καὶ διὰ τὴν ἐκλογὴν τῶν ἀνδρῶν ἐγένετο τοῖς ἐχθροῖς ὑποχείριος. οἱ δὲ Ῥωμαῖοι, κυριεύσαντες καὶ ταύτης τῆς νεὼς εὖ κατεσκευασμένης καὶ καταρτίσαντες αὐτὴν τοῖς πρὸς τὴν χρείαν, οὕτως ἐκώλυσαν τοὺς κατατολμῶντας καὶ πλέοντας εἰς τὸ Λιλύβαιον.", "st": "1.47"}, {"sp": "N", "t": "τῶν δὲ πολιορκουμένων ταῖς μὲν ἀντοικοδομίαις ἐνεργῶς χρωμένων, τοῦ δὲ λυμαίνεσθαι καὶ διαφθείρειν τὰς τῶν ὑπεναντίων παρασκευὰς ἀπεγνωκότων, γίνεταί τις ἀνέμου στάσις ἔχουσα τηλικαύτην βίαν καὶ φορὰν εἰς αὐτὰς τὰς τῶν μηχανημάτων προσαγωγὰς ὥστε καὶ τὰς στοὰς διασαλεύειν καὶ τοὺς προκειμένους τούτων πύργους τῇ βίᾳ βαστάζειν. ἐν ᾧ καιρῷ συννοήσαντές τινες τῶν Ἑλληνικῶν μισθοφόρων τὴν ἐπιτηδειότητα τῆς περιστάσεως πρὸς τὴν τῶν ἔργων διαφθορὰν προσφέρουσι τῷ στρατηγῷ τὴν ἐπίνοιαν. τοῦ δὲ δεξαμένου καὶ ταχέως ἑτοιμάσαντος πᾶν τὸ πρὸς τὴν χρείαν ἁρμόζον, συστραφέντες οἱ νεανίσκοι κατὰ τριττοὺς τόπους ἐνέβαλον πῦρ τοῖς ἔργοις. ὡς δ’ ἂν τῶν μὲν κατασκευασμάτων διὰ τὸν χρόνον εὖ παρεσκευασμένων πρὸς τὸ ῥᾳδίως ἐμπρησθῆναι, τῆς δὲ τοῦ πνεύματος βίας φυσώσης κατ’ αὐτῶν τῶν πύργων καὶ μηχανημάτων, τὴν μὲν νομὴν τοῦ πυρὸς ἐνεργὸν συνέβαινε γίνεσθαι καὶ πρακτικήν, τὴν δ’ ἐπάρκειαν καὶ βοήθειαν τοῖς Ῥωμαίοις εἰς τέλος ἄπρακτον καὶ δυσχερῆ. τοιαύτην γὰρ ἔκπληξιν παρίστα τὸ συμβαῖνον τοῖς βοηθοῦσιν ὥστε μήτε συννοῆσαι μήτε συνιδεῖν δύνασθαι τὸ γινόμενον, ἀλλ’ ἀποσκοτουμένους ὑπὸ τῆς εἰς αὐτοὺς φερομένης λιγνύος καὶ τῶν φεψαλύγων, ἔτι δὲ τῆς τοῦ καπνοῦ πολυπληθίας, οὐκ ὀλίγους ἀπόλλυσθαι καὶ πίπτειν, μὴ δυναμένους ἐγγίσαι πρὸς αὐτὴν τὴν τοῦ πυρὸς βοήθειαν. ὅσῳ δὲ μείζω συνέβαινε γίνεσθαι τὴν δυσχρηστίαν περὶ τοὺς ὑπεναντίους διὰ τὰς προειρημένας αἰτίας, τοσούτῳ πλείων εὐχρηστία περὶ τοὺς ἐνιέντας ἦν τὸ πῦρ. τὸ μὲν γὰρ ἐπισκοτοῦν καὶ βλάπτειν δυνάμενον πᾶν ἐξεφυσᾶτο καὶ προωθεῖτο κατὰ τῶν ὑπεναντίων, τὸ δὲ βαλλόμενον ἢ ῥιπτούμενον ἐπί τε τοὺς βοηθοῦντας καὶ τὴν τῶν ἔργων διαφθορὰν εὔστοχον μὲν ἐπεγίνετο διὰ τὸ συνορᾶν τοὺς ἀφιέντας τὸν πρὸ αὑτῶν τόπον, πρακτικὸν δὲ διὰ τὸ γίνεσθαι σφοδρὰν τὴν πληγήν, συνεργούσης τοῖς βάλλουσι τῆς τοῦ πνεύματος βίας. τὸ δὲ πέρας τοιαύτην συνέβη γενέσθαι τὴν παντέλειαν τῆς καταφθορᾶς ὥστε καὶ τὰς βάσεις τῶν πύργων καὶ τὰ στύπη τῶν κριῶν ὑπὸ τοῦ πυρὸς ἀχρειωθῆναι. τούτων δὲ συμβάντων τὸ μὲν ἔτι διὰ τῶν ἔργων πολιορκεῖν ἀπέγνωσαν οἱ Ῥωμαῖοι· περιταφρεύσαντες δὲ καὶ χάρακι περιλαβόντες κύκλῳ τὴν πόλιν, ἔτι δὲ τῆς ἰδίας στρατοπεδείας τεῖχος προβαλόμενοι τῷ χρόνῳ παρέδοσαν τὴν πρᾶξιν. οἱ δ’ ἐν τῷ Λιλυβαίῳ τὸ πεπτωκὸς ἐξοικοδομησάμενοι τεῖχος εὐθαρσῶς ὑπέμενον ἤδη τὴν πολιορκίαν.", "st": "1.48"}, {"sp": "N", "t": "εἰς δὲ τὴν Ῥώμην προσπεσόντων τούτων, καὶ μετὰ ταῦτα πλειόνων ἀναγγελλόντων διότι συμβαίνει τῶν ἀπὸ τοῦ στόλου πληρωμάτων τὸ πλεῖστον μέρος ἔν τε τοῖς ἔργοις καὶ τῇ καθόλου πολιορκίᾳ διεφθάρθαι, σπουδῇ κατέγραφον ναύτας καὶ συναθροίσαντες εἰς μυρίους ἐξέπεμψαν εἰς τὴν Σικελίαν. ὧν διὰ τοῦ πορθμοῦ περαιωθέντων καὶ πεζῇ παραγενομένων εἰς τὸ στρατόπεδον, συναγαγὼν τοὺς χιλιάρχους ὁ στρατηγὸς τῶν Ῥωμαίων Πόπλιος Κλαύδιος ἔφη καιρὸν εἶναι πλεῖν ἐπὶ τὰ Δρέπανα παντὶ τῷ στόλῳ. τὸν γὰρ στρατηγὸν τῶν Καρχηδονίων Ἀτάρβαν τὸν τεταγμένον ἐπ’ αὐτῶν ἀπαράσκευον εἶναι πρὸς τὸ μέλλον, ἀγνοοῦντα μὲν τὴν παρουσίαν τῶν πληρωμάτων, πεπεισμένον δὲ μὴ δύνασθαι πλεῖν τὸν αὑτῶν στόλον διὰ τὴν γεγενημένην ἐν τῇ πολιορκίᾳ καταφθορὰν τῶν ἀνδρῶν. προχείρως δ’ αὐτῶν συγκατατιθεμένων, εὐθέως ἐνεβίβαζε τά τε προϋπάρχοντα καὶ τὰ προσφάτως παραγεγονότα πληρώματα, τοὺς δ’ ἐπιβάτας ἐκ παντὸς ἐπέλεξε τοῦ στρατεύματος ἐθελοντὴν τοὺς ἀρίστους, ἅτε δὴ τοῦ μὲν πλοῦ σύνεγγυς ὄντος, τῆς δ’ ὠφελείας ἑτοίμου προφαινομένης. ταῦτα δὲ παρασκευασάμενος ἀνήχθη περὶ μέσας νύκτας, λαθὼν τοὺς πολεμίους. καὶ τὰς μὲν ἀρχὰς ἅθρους ἔπλει, δεξιὰν ἔχων τὴν γῆν. ἅμα δὲ τῷ φωτὶ τῶν πρώτων ἐπὶ τὰ Δρέπανα νεῶν ἐπιφαινομένων, κατιδὼν Ἀτάρβας τὸ μὲν πρῶτον ἐξενίσθη διὰ τὸ παράδοξον· ταχὺ δ’ ἐν αὑτῷ γενόμενος καὶ νοήσας τὸν ἐπίπλουν τῶν ὑπεναντίων ἔκρινε παντὸς ἔργου πεῖραν λαμβάνειν καὶ πᾶν ὑπομένειν χάριν τοῦ μὴ περιιδεῖν σφᾶς εἰς πρόδηλον συγκλεισθέντας πολιορκίαν. διόπερ εὐθέως τὰ μὲν πληρώματα συνῆγε πρὸς τὸν αἰγιαλόν, τοὺς δ’ ἐκ τῆς πόλεως μισθοφόρους ἥθροιζε μετὰ κηρύγματος. τῶν δὲ συλλεχθέντων, ἐπεβάλετο διὰ βραχέων εἰς ἔννοιαν αὐτοὺς ἄγειν τῆς τε τοῦ νικᾶν ἐλπίδος, ἐὰν τολμήσωσι ναυμαχεῖν, καὶ τῆς ἐν τῇ πολιορκίᾳ δυσχρηστίας, ἐὰν καταμελλήσωσι προϊδόμενοι τὸν κίνδυνον. ἑτοίμως δ’ αὐτῶν παρορμηθέντων πρὸς τὴν ναυμαχίαν καὶ βοώντων ἄγειν καὶ μὴ μέλλειν, ἐπαινέσας καὶ δεξάμενος τὴν ὁρμὴν παρήγγειλε κατὰ τάχος ἐμβαίνειν καὶ βλέποντας πρὸς τὴν αὑτοῦ ναῦν ἕπεσθαι ταύτῃ κατὰ πρύμναν. διασαφήσας δὲ τὰ προειρημένα κατὰ σπουδὴν πρῶτος ἐποιεῖτο τὸν ἀνάπλουν, ὑπ’ αὐτὰς τὰς πέτρας ἐπὶ θάτερα μέρη τοῦ λιμένος ἐξάγων τοῦ τῶν πολεμίων εἴσπλου.", "st": "1.49"}, {"sp": "N", "t": "Πόπλιος δ’ ὁ τῶν Ῥωμαίων στρατηγὸς θεωρῶν τοὺς μὲν πολεμίους παρὰ τὴν αὑτοῦ δόξαν οὔτ’ εἴκοντας οὔτε καταπεπληγμένους τὸν ἐπίπλουν ἀλλὰ πρὸς τῷ ναυμαχεῖν ὄντας, τῶν δὲ σφετέρων νεῶν τὰς μὲν ἐντὸς ἤδη τοῦ λιμένος οὔσας τὰς δ’ ἐν αὐτῷ τῷ στόματι, τὰς δὲ φερομένας ἐπὶ τὸν εἴσπλουν, πάσαις ἀναστρέφειν παρήγγειλε καὶ ποιεῖσθαι τὸν πλοῦν ἔξω πάλιν. ἔνθα δὴ τῶν μὲν ἐν τῷ λιμένι τῶν δὲ κατὰ τὸν εἴσπλουν ἐκ τῆς μεταβολῆς συμπιπτουσῶν, οὐ μόνον θόρυβος ἦν ἐκ τῶν ἀνδρῶν ἄπλετος, ἀλλὰ καὶ τοὺς ταρσοὺς ἐθραύονθ’ αἱ νῆες ἀλλήλαις συγκρούουσαι. ὅμως δ’ οὖν ἀεὶ τοὺς ἀνατρέχοντας ἐκτάττοντες οἱ τριήραρχοι παρ’ αὐτὴν τὴν γῆν ταχέως ἐποίουν ἀντιπρώρρους τοῖς πολεμίοις. ὁ δὲ Πόπλιος αὐτὸς ἐπέπλει μὲν ἀρχῆθεν κατόπιν ἐπὶ παντὶ τῷ στόλῳ, τότε δ’ ἐπιστρέψας κατ’ αὐτὸν τὸν πλοῦν πρὸς τὸ πέλαγος ἔλαβε τὴν εὐώνυμον τῆς ὅλης δυνάμεως τάξιν. Ἀτάρβας δὲ κατὰ τὸν αὐτὸν καιρὸν ὑπεράρας τὸ λαιὸν τῶν πολεμίων [Ῥωμαίων], ἔχων πέντε ναῦς ἐπίπλους, ὑπέστησε τὴν ἑαυτοῦ ναῦν ἀντίπρωρρον τοῖς πολεμίοις ἀπὸ τοῦ κατὰ τὸ πέλαγος μέρους· ἅμα δὲ καὶ τῶν ἐπιπλεόντων ἀεὶ τοῖς συνάπτουσι προσεπιταττομένοις ταὐτὸ ποιεῖν παραγγείλας διὰ τῶν ὑπηρετῶν, καταστάντων δὲ πάντων εἰς μέτωπον σημήνας διὰ τῶν συνθημάτων τὰς μὲν ἀρχὰς ἐποιεῖτο τὸν ἐπίπλουν ἐν τάξει, μενόντων πρὸς τῇ γῇ τῶν Ῥωμαίων διὰ τὸ προσδέχεσθαι τὰς ἐκ τοῦ λιμένος ἀνατρεχούσας ναῦς. ἐξ οὗ συνέβαινε μεγάλα τοὺς Ῥωμαίους ἐλαττωθῆναι πρὸς αὐτῇ τῇ γῇ ποιησαμένους τὴν συμπλοκήν.", "st": "1.50"}, {"sp": "N", "t": "ἐπειδὴ δὲ σύνεγγυς αὑτῶν ἦσαν, ἀρθέντων τῶν συνθημάτων ἐφ’ ἑκατέρας τῆς ναυαρχίδος συνέβαλλον ἀλλήλοις. τὸ μὲν οὖν πρῶτον ἰσόρροπος ἦν ὁ κίνδυνος, ὡς ἂν ἀμφοτέρων τοῖς ἀρίστοις ἐκ τῆς πεζικῆς δυνάμεως ἐπιβάταις χρωμένων· ἀεὶ δὲ μᾶλλον ὑπερεῖχον οἱ Καρχηδόνιοι διὰ τὸ πολλὰ προτερήματα παρ’ ὅλον ἔχειν τὸν ἀγῶνα. τῷ τε γὰρ ταχυναυτεῖν πολὺ περιῆσαν διὰ τὴν διαφορὰν τῆς ναυπηγίας καὶ τὴν τῶν πληρωμάτων ἕξιν, ἥ τε χώρα μεγάλα συνεβάλλετ’ αὐτοῖς, ἅτε πεποιημένων τὴν ἔκταξιν ἀπὸ τῶν κατὰ τὸ πέλαγος τόπων. εἴτε γὰρ πιέζοιντό τινες ὑπὸ τῶν πολεμίων, κατόπιν ἀνεχώρουν ἀσφαλῶς διὰ τὸ ταχυναυτεῖν εἰς τὸν ἀναπεπταμένον τόπον· κἄπειτ’ ἐκ μεταβολῆς τοῖς προπίπτουσι τῶν διωκόντων, τοτὲ μὲν περιπλέοντες τοτὲ δὲ πλάγιοι προσπίπτοντες στρεφομένοις καὶ δυσχρηστοῦσι διὰ τὸ βάρος τῶν πλοίων καὶ διὰ τὴν ἀπειρίαν τῶν πληρωμάτων, ἐμβολάς τε συνεχεῖς ἐδίδοσαν καὶ πολλὰ τῶν σκαφῶν ἐβάπτιζον· εἴτε κινδυνεύοι τις τῶν συμμάχων, ἑτοίμως παρεβοήθουν ἔξω τοῦ δεινοῦ καὶ μετ’ ἀσφαλείας, παρὰ τὰς πρύμνας κατὰ τὸ πέλαγος ποιούμενοι τὸν πλοῦν. τοῖς γε μὴν Ῥωμαίοις τἀναντία τούτων συνέβαινε· τοῖς τε γὰρ πιεζομένοις οὐκ ἦν εἰς τοὔπισθεν δυνατὸν ἀποχωρεῖν, πρὸς τῇ γῇ ποιουμένοις τὸν κίνδυνον, ἀεὶ δὲ τὸ θλιβόμενον ὑπὸ τῶν κατὰ πρόσωπον σκάφος ἢ τοῖς βραχέσι περιπῖπτον ἐκάθιζε κατὰ πρύμναν ἢ πρὸς τὴν γῆν φερόμενον ἐπώκελλε. διεκπλεῖν μὲν οὖν διὰ τῶν πολεμίων νεῶν καὶ κατόπιν ἐπιφαίνεσθαι τοῖς ἤδη πρὸς ἑτέρους διαμαχομένοις, ὅπερ ἐν τῷ ναυμαχεῖν ἐστι πρακτικώτατον, ἀδυνάτως εἶχον διά τε τὴν βαρύτητα τῶν πλοίων, προσέτι δὲ καὶ τὴν ἀπειρίαν τῶν πληρωμάτων. οὐδὲ μὴν ἐπιβοηθεῖν τοῖς δεομένοις κατὰ πρύμναν ἐδύναντο διὰ τὸ συγκεκλεῖσθαι πρὸς τῇ γῇ καὶ μηδὲ μικρὸν ἀπολείπεσθαι τόπον τοῖς βουλομένοις ἐπαρκεῖν τῷ δεομένῳ. τοιαύτης δὲ δυσχρηστίας ὑπαρχούσης περὶ τὸν ὅλον ἀγῶνα, καὶ τῶν μὲν καθιζόντων ἐν τοῖς βράχεσι, τῶν δ’ ἐκπιπτόντων σκαφῶν, κατιδὼν ὁ στρατηγὸς τῶν Ῥωμαίων τὸ συμβαῖνον ὥρμησε πρὸς φυγήν, ἀπὸ τῶν εὐωνύμων παρὰ τὴν γῆν ἐξελίξας, καὶ σὺν αὐτῷ περὶ τριάκοντα νῆας, αἵπερ ἔτυχον ἐγγὺς οὖσαι. τῶν δὲ λοιπῶν σκαφῶν, ὄντων ἐνενήκοντα καὶ τριῶν, ἐκυρίευσαν οἱ Καρχηδόνιοι καὶ τῶν πληρωμάτων, ὅσοι μὴ τῶν ἀνδρῶν τὰς ναῦς εἰς τὴν γῆν ἐκβαλόντες ἀπεχώρησαν.", "st": "1.51"}, {"sp": "N", "t": "γενομένης δὲ τῆς ναυμαχίας τοιαύτης Ἀτάρβας μὲν εὐδοκίμει παρὰ τοῖς Καρχηδονίοις, ὡς δι’ αὑτὸν καὶ διὰ τὴν ἰδίαν πρόνοιαν καὶ τόλμαν κατωρθωκώς, Πόπλιος δὲ παρὰ τοῖς Ῥωμαίοις ἠδόξει καὶ διεβέβλητο μεγάλως, ὡς εἰκῇ καὶ ἀλογίστως τοῖς πράγμασι κεχρημένος καὶ τὸ καθ’ αὑτὸν οὐ μικροῖς ἐλαττώμασι περιβεβληκὼς τὴν Ῥώμην· διὸ καὶ μετὰ ταῦτα μεγάλαις ζημίαις καὶ κινδύνοις κριθεὶς περιέπεσεν. οὐ μὴν οἵ γε Ῥωμαῖοι, καίπερ τοιούτων συμβεβηκότων, διὰ τὴν ὑπὲρ τῶν ὅλων φιλοτιμίαν οὐδὲν ἀπέλειπον τῶν ἐνδεχομένων, ἀλλ’ εἴχοντο τῶν ἑξῆς πραγμάτων. διὸ καὶ συνάψαντος τοῦ κατὰ τὰς ἀρχαιρεσίας χρόνου, στρατηγοὺς ὑπάτους καταστήσαντες παραυτίκα τὸν ἕτερον αὐτῶν ἐξέπεμπον Λεύκιον Ἰούνιον, τάς τε σιταρχίας παρακομίζοντα τοῖς τὸ Λιλύβαιον πολιορκοῦσι καὶ τὰς ἄλλας ἀγορὰς καὶ χορηγίας τῷ στρατοπέδῳ· πρὸς δὲ καὶ παραπομποὺς τούτοις ἐπλήρωσαν ἑξήκοντα ναῦς. ὁ δ’ Ἰούνιος ἀφικόμενος εἰς τὴν Μεσσήνην καὶ προσλαβὼν τὰ συνηντηκότα τῶν πλοίων ἀπό τε τοῦ στρατοπέδου καὶ τῆς ἄλλης Σικελίας παρεκομίσθη κατὰ σπουδὴν εἰς τὰς Συρακούσας, ἔχων ἑκατὸν εἴκοσι σκάφη καὶ τὴν ἀγορὰν σχεδὸν ἐν ὀκτακοσίαις ναυσὶ φορτηγοῖς. ἐντεῦθεν δὲ παραδοὺς τοῖς ταμίαις τὰς ἡμισείας φορτηγοὺς καί τινα τῶν μακρῶν πλοίων ἐξαπέστειλε, διακομισθῆναι σπουδάζων τῷ στρατοπέδῳ τὰ πρὸς τὴν χρείαν. αὐτὸς δ’ ἐν ταῖς Συρακούσαις ὑπέμενε, τούς τε κατὰ πλοῦν ἀφυστεροῦντας ἐκ τῆς Μεσσήνης ἀναδεχόμενος καὶ παρὰ τῶν ἐκ τῆς μεσογαίου συμμάχων σῖτον προσαναλαμβάνων.", "st": "1.52"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Ἀτάρβας μὲν ἄνδρας τοὺς ἐν τῇ ναυμαχίᾳ ληφθέντας καὶ τὰς αἰχμαλώτους νῆας ἐξαπέστειλεν εἰς τὴν Καρχηδόνα, Καρθάλωνα δὲ τὸν συνάρχοντα δοὺς τριάκοντα ναῦς ἐξέπεμψε πρὸς αἷς ἔχων αὐτὸς ἑβδομήκοντα κατέπλευσεν, προστάξας ἄφνω προσπεσόντα ταῖς ὁρμούσαις παρὰ τὸ Λιλύβαιον τῶν πολεμίων ναυσίν, ὧν μὲν ἂν δυνατὸς ᾖ κυριεῦσαι, ταῖς δὲ λοιπαῖς πῦρ ἐμβαλεῖν. πεισθέντος δὲ τοῦ Καρθάλωνος καὶ ποιησαμένου τὸν ἐπίπλουν ὑπὸ τὴν ἑωθινὴν καὶ τὰ μὲν ἐμπιπρῶντος τὰ δ’ ἀποσπῶντος τῶν πλοίων, μεγάλην συνέπεσε γενέσθαι ταραχὴν περὶ τὸ τῶν Ῥωμαίων στρατόπεδον. προσβοηθούντων γὰρ αὐτῶν ἐπὶ τὰς ναῦς καὶ γινομένης κραυγῆς, συννοήσας Ἰμίλκων ὁ τὸ Λιλύβαιον τηρῶν καὶ θεωρῶν ἤδη τῆς ἡμέρας ὑποφαινούσης τὸ συμβαῖνον, ἐπαποστέλλει τοὺς ἐκ τῆς πόλεως μισθοφόρους. οἱ δὲ Ῥωμαῖοι, τοῦ δεινοῦ πανταχόθεν αὐτοὺς περιστάντος, οὐκ εἰς μικρὰν οὐδ’ εἰς τὴν τυχοῦσαν ἦλθον διατροπήν. ὁ δὲ τῶν Καρχηδονίων ναύαρχος ὀλίγα τῶν σκαφῶν τὰ μὲν ἀποσπάσας τὰ δὲ συντρίψας, μετὰ ταῦτα μικρὸν ἀπὸ τοῦ Λιλυβαίου παρακομισθεὶς ὡς ἐφ’ Ἡρακλείας ἐτήρει, βουλόμενος διακωλύειν τοὺς ἐπὶ τὸ στρατόπεδον πλέοντας. προσαγγειλάντων δὲ τῶν σκοπῶν πλῆθος ἱκανὸν πλοίων προσφέρεσθαι παντοδαπῶν καὶ συνεγγίζειν, ἀναχθεὶς ἔπλει, συμμῖξαι σπεύδων διὰ τὸ καταφρονεῖν τῶν Ῥωμαίων ἐκ τοῦ προγεγενημένου προτερήματος. ὁμοίως δὲ καὶ τοῖς ἐκ τῶν Συρακουσῶν προαπεσταλμένοις ταμίαις ἀνήγγειλαν οἱ προπλεῖν εἰθισμένοι λέμβοι τὸν ἐπίπλουν τῶν ὑπεναντίων. οἱ δὲ νομίσαντες οὐκ ἀξιόχρεως σφᾶς αὐτοὺς εἶναι πρὸς ναυμαχίαν, καθωρμίσθησαν πρός τι πολισμάτιον τῶν ὑπ’ αὐτοὺς ταττομένων, ἀλίμενον μέν, σάλους δ’ ἔχον καὶ προβολὰς περικλειούσας ἐκ τῆς γῆς εὐφυεῖς. οὗ ποιησάμενοι τὴν ἀπόβασιν καὶ τούς τε καταπέλτας καὶ τοὺς πετροβόλους τοὺς ἐκ τῆς πόλεως ἐπιστήσαντες προσεδόκων τὸν ἐπίπλουν τῶν ὑπεναντίων. οἱ δὲ Καρχηδόνιοι συνεγγίσαντες τὸ μὲν πρῶτον ἐπεβάλοντο πολιορκεῖν τούτους, ὑπολαβόντες τοὺς μὲν ἄνδρας καταπλαγέντας εἰς τὸ πολισμάτιον ἀποχωρήσειν, τῶν δὲ πλοίων ἀσφαλῶς κυριεύσειν· οὐ προχωρούσης δὲ τῆς ἐλπίδος, ἀλλὰ τοὐναντίον ἀμυνομένων γενναίως, καὶ τοῦ τόπου πολλὰς ἔχοντος καὶ παντοδαπὰς δυσχρηστίας, ὀλίγα τῶν τὰς ἀγορὰς ἐχόντων πλοίων ἀποσπάσαντες ἀπέπλευσαν πρός τινα ποταμόν, ἐν ᾧ καθορμισθέντες ἐπετήρουν τὸν ἀνάπλουν αὐτῶν.", "st": "1.53"}, {"sp": "N", "t": "ὁ δ’ ἐν ταῖς Συρακούσαις ὑπολειφθεὶς στρατηγός, ἐπεὶ τὰ κατὰ τὴν πρόθεσιν ἐπετέλεσεν, κάμψας τὸν Πάχυνον ἐποιεῖτο τὸν πλοῦν ὡς ἐπὶ τὸ Λιλύβαιον, οὐδὲν εἰδὼς τῶν περὶ τοὺς προπλέοντας συμβεβηκότων. ὁ δὲ τῶν Καρχηδονίων ναύαρχος, σημηνάντων τῶν σκοπῶν αὐτῷ πάλιν τὴν ἐπιφάνειαν τῶν ὑπεναντίων, ἀναχθεὶς ἔπλει μετὰ σπουδῆς, βουλόμενος αὐτοῖς ὡς πλεῖστον ἀπέχουσι τῶν οἰκείων νεῶν συμβαλεῖν. ὁ δ’ Ἰούνιος κατιδὼν ἐκ πολλοῦ τὸν στόλον τὸν τῶν Καρχηδονίων καὶ τὸ πλῆθος τῶν σκαφῶν, οὔτε συμβαλεῖν τολμῶν οὔτ’ ἐκφυγεῖν ἔτι δυνατὸς ὢν διὰ τὸ σύνεγγυς εἶναι τοὺς πολεμίους, ἐγκλίνας εἰς τόπους τραχεῖς καὶ κατὰ πάντα τρόπον ἐπισφαλεῖς καθωρμίσθη, κρίνων αἱρετώτερον ὑπάρχειν ὅ,τι δέοι παθεῖν μᾶλλον ἢ τοῖς πολεμίοις αὔτανδρον τὸ σφέτερον στρατόπεδον ὑποχείριον ποιῆσαι. συνιδὼν δὲ καὶ τὸ περὶ τούτου γεγονὸς ὁ τῶν Καρχηδονίων ναύαρχος τὸ μὲν παραβάλλεσθαι καὶ προσάγειν τοιούτοις τόποις ἀπεδοκίμασε, λαβὼν δ’ ἄκραν τινὰ καὶ προσορμισθεὶς ταύτῃ μεταξὺ τῶν στόλων ἐτήρει καὶ προσεῖχε τὸν νοῦν ἀμφοτέροις. ἐπιγενομένου δὲ χειμῶνος καὶ περιστάσεως προφαινομένης ἐκ τοῦ πελάγους ὁλοσχερεστέρας, οἱ μὲν τῶν Καρχηδονίων κυβερνῆται διά τε τὴν τῶν τόπων καὶ τὴν τοῦ πράγματος ἐμπειρίαν προορώμενοι τὸ μέλλον καὶ προλέγοντες τὸ συμβησόμενον ἔπεισαν τὸν Καρθάλωνα φυγεῖν τὸν χειμῶνα καὶ κάμψαι τὴν ἄκραν τοῦ Παχύνου. πεισθέντος δὲ νουνεχῶς, οὗτοι μὲν πολλὰ μοχθήσαντες καὶ μόλις ὑπεράραντες τὴν ἄκραν ἐν ἀσφαλεῖ καθωρμίσθησαν, οἱ δὲ τῶν Ῥωμαίων στόλοι, τοῦ χειμῶνος ἐπιγενομένου καὶ τῶν τόπων εἰς τέλος ὑπαρχόντων ἀλιμένων, οὕτως διεφθάρησαν ὥστε μηδὲ τῶν ναυαγίων μηδὲν γενέσθαι χρήσιμον, ἀλλ’ ἀμφοτέρους αὐτοὺς ἄρδην καὶ παραλόγως ἀχρειωθῆναι.", "st": "1.54"}, {"sp": "N", "t": "τούτου δὲ συμβάντος τὰ μὲν τῶν Καρχηδονίων αὖθις ἀνέκυψε καὶ πάλιν ἐπιρρεπεστέρας εἶχε τὰς ἐλπίδας, οἱ δὲ Ῥωμαῖοι πρότερον μὲν ἐπὶ ποσὸν ἠτυχηκότες τότε δ’ ὁλοσχερῶς ἐκ μὲν τῆς θαλάττης ἐξέβησαν, τῶν δ’ ὑπαίθρων ἐπεκράτουν· Καρχηδόνιοι δὲ τῆς μὲν θαλάττης ἐκυρίευον, τῆς δὲ γῆς οὐχ ὅλως ἀπήλπιζον. μετὰ δὲ ταῦτα πάντες ἐπὶ μὲν τοῖς ὅλοις ἐσχετλίαζον, οἵ τ’ ἐν τῇ Ῥώμῃ καὶ τὰ περὶ τὸ Λιλύβαιον στρατόπεδα, διὰ τὰ προειρημένα συμπτώματα· τῆς γε μὴν προθέσεως οὐκ ἀφίσταντο τῆς κατὰ τὴν πολιορκίαν, ἀλλ’ οἱ μὲν ἐχορήγουν κατὰ γῆν ἀπροφασίστως, οἱ δὲ προσεκαρτέρουν ταύτῃ κατὰ τὸ δυνατόν. ὁ δ’ Ἰούνιος ἀνακομισθεὶς ἐπὶ τὸ στρατόπεδον ἐκ τῆς ναυαγίας καὶ περιπαθὴς ὤν, ἐγένετο πρὸς τὸ καινοτομῆσαί τι καὶ πρᾶξαι τῶν δεόντων, σπουδάζων ἀναμαχέσασθαι τὴν γεγενημένην περιπέτειαν. διὸ καὶ βραχείας αὐτῷ παραπεσούσης ἀφορμῆς, καταλαμβάνει πραξικοπήσας τὸν Ἔρυκα καὶ γίνεται τοῦ τε τῆς Ἀφροδίτης ἱεροῦ καὶ τῆς πόλεως ἐγκρατής. ὁ δ’ Ἔρυξ ἔστι μὲν ὄρος παρὰ θάλατταν τῆς Σικελίας ἐν τῇ παρὰ τὴν Ἰταλίαν κειμένῃ πλευρᾷ μεταξὺ Δρεπάνων καὶ Πανόρμου, μᾶλλον δ’ ὅμορον καὶ συνάπτον πρὸς τὰ Δρέπανα, μεγέθει δὲ παρὰ πολὺ διαφέρον τῶν κατὰ τὴν Σικελίαν ὀρῶν πλὴν τῆς Αἴτνης. τούτου δ’ ἐπ’ αὐτῆς μὲν τῆς κορυφῆς, οὔσης ἐπιπέδου, κεῖται τὸ τῆς Ἀφροδίτης τῆς Ἐρυκίνης ἱερόν, ὅπερ ὁμολογουμένως ἐπιφανέστατόν ἐστι τῷ τε πλούτῳ καὶ τῇ λοιπῇ προστασίᾳ τῶν κατὰ τὴν Σικελίαν ἱερῶν· ἡ δὲ πόλις ὑπ’ αὐτὴν τὴν κορυφὴν τέτακται, πάνυ μακρὰν ἔχουσα καὶ προσάντη πανταχόθεν τὴν ἀνάβασιν. ἐπί τε δὴ τὴν κορυφὴν ἐπιστήσας φυλακήν, ὁμοίως δὲ καὶ τὴν ἀπὸ Δρεπάνων πρόσβασιν ἐτήρει φιλοτίμως ἀμφοτέρους τοὺς τόπους καὶ μᾶλλον ἔτι τὸν τῆς ἀναβολῆς, πεπεισμένος οὕτως καὶ τὴν πόλιν ἀσφαλῶς καὶ τὸ σύμπαν ὄρος ὑφ’ αὑτὸν ἕξειν.", "st": "1.55"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι μετὰ ταῦτα στρατηγὸν καταστήσαντες αὑτῶν Ἀμίλκαν τὸν Βάρκαν ἐπικαλούμενον, τούτῳ τὰ κατὰ τὸν στόλον ἐνεχείρισαν· ὃς παραλαβὼν τὰς ναυτικὰς δυνάμεις ὥρμησεν πορθήσων τὴν Ἰταλίαν. ἔτος δ’ ἦν ὀκτωκαιδέκατον τῷ πολέμῳ. κατασύρας δὲ τὴν Λοκρίδα καὶ τὴν Βρεττιανὴν χώραν, ἀποπλέων ἐντεῦθεν κατῆρε παντὶ τῷ στόλῳ πρὸς τὴν Πανορμῖτιν καὶ καταλαμβάνει τὸν ἐπὶ τῆς Εἱρκτῆς λεγόμενον τόπον, ὃς κεῖται μὲν Ἔρυκος καὶ Πανόρμου μεταξὺ πρὸς θαλάττῃ, πολὺ δέ τι τῶν ἄλλων δοκεῖ διαφέρειν τόπων ἐπιτηδειότητι πρὸς ἀσφάλειαν στρατοπέδων καὶ χρονισμόν. ἔστι γὰρ ὄρος περίτομον ἐξανεστηκὸς ἐκ τῆς περικειμένης χώρας εἰς ὕψος ἱκανόν. τούτου δ’ ἡ περίμετρος τῆς ἄνω στεφάνης οὐ λείπει τῶν ἑκατὸν σταδίων, ὑφ’ ἧς ὁ περιεχόμενος τόπος εὔβοτος ὑπάρχει καὶ γεωργήσιμος, πρὸς μὲν τὰς πελαγίους πνοιὰς εὐφυῶς κείμενος, θανασίμων δὲ θηρίων εἰς τέλος ἄμοιρος. περιέχεται δὲ κρημνοῖς ἀπροσίτοις ἔκ τε τοῦ κατὰ θάλατταν μέρους καὶ τοῦ παρὰ τὴν μεσόγαιαν παρήκοντος, τὰ δὲ μεταξὺ τούτων ἐστὶν ὀλίγης καὶ βραχείας δεόμενα κατασκευῆς. ἔχει δ’ ἐν αὑτῷ καὶ μαστόν, ὃς ἅμα μὲν ἀκροπόλεως, ἅμα δὲ σκοπῆς εὐφυοῦς λαμβάνει τάξιν κατὰ τῆς ὑποκειμένης χώρας. κρατεῖ δὲ καὶ λιμένος εὐκαίρου πρὸς τὸν ἀπὸ Δρεπάνων καὶ Λιλυβαίου δρόμον ἐπὶ τὴν Ἰταλίαν, ἐν ᾧ πλῆθος ὕδατος ἄφθονον ὑπάρχει. προσόδους δὲ τὰς πάσας ἔχει τριττὰς δυσχερεῖς, δύο μὲν ἀπὸ τῆς χώρας, μίαν δ’ ἀπὸ τῆς θαλάττης. ἐν ᾧ καταστρατοπεδεύσας παραβόλως Ἀμίλκας, ὡς ἂν μήτε πόλεως οἰκείας μήτ’ ἄλλης ἐλπίδος μηδεμιᾶς ἀντεχόμενος, εἰς μέσους δὲ τοὺς πολεμίους ἑαυτὸν δεδωκώς, ὅμως οὐ μικροὺς οὐδὲ τοὺς τυχόντας Ῥωμαίοις ἀγῶνας καὶ κινδύνους παρεσκεύασεν. πρῶτον μὲν γὰρ ἐντεῦθεν ὁρμώμενος κατὰ θάλατταν τὴν παραλίαν τῆς Ἰταλίας ἐπόρθει μέχρι τῆς Κυμαίων χώρας, δεύτερον δὲ κατὰ γῆν παραστρατοπεδευσάντων αὐτῷ Ῥωμαίων πρὸ τῆς Πανορμιτῶν πόλεως ἐν ἴσως πέντε σταδίοις πολλοὺς καὶ ποικίλους ἀγῶνας συνεστήσατο κατὰ γῆν σχεδὸν ἐπὶ τρεῖς ἐνιαυτούς. περὶ ὧν οὐχ οἷόν τε διὰ τῆς γραφῆς τὸν κατὰ μέρος ἀποδοῦναι λόγον·", "st": "1.56"}, {"sp": "N", "t": "καθάπερ γὰρ ἐπὶ τῶν διαφερόντων πυκτῶν καὶ ταῖς γενναιότησι καὶ ταῖς εὐεξίαις, ὅταν εἰς τὸν ὑπὲρ αὐτοῦ τοῦ στεφάνου συγκαταστάντες καιρὸν διαμάχωνται πληγὴν ἐπὶ πληγῇ τιθέντες ἀδιαπαύστως, λόγον μὲν ἢ πρόνοιαν ἔχειν ὑπὲρ ἑκάστης ἐπιβολῆς καὶ πληγῆς οὔτε τοῖς ἀγωνιζομένοις οὔτε τοῖς θεωμένοις ἐστὶ δυνατόν, ἐκ δὲ τῆς καθόλου τῶν ἀνδρῶν ἐνεργείας καὶ τῆς ἑκατέρου φιλοτιμίας ἔστι καὶ τῆς ἐμπειρίας αὐτῶν καὶ τῆς δυνάμεως, πρὸς δὲ καὶ τῆς εὐψυχίας, ἱκανὴν ἔννοιαν λαβεῖν, οὕτως δὲ καὶ περὶ τῶν νῦν λεγομένων στρατηγῶν. τὰς μὲν γὰρ αἰτίας ἢ τοὺς τρόπους, δι’ ὧν ἀν’ ἑκάστην ἡμέραν ἐποιοῦντο κατ’ ἀλλήλων ἐνέδρας, ἀντενέδρας, ἐπιθέσεις, προσβολάς, οὔτ’ ἂν ὁ γράφων ἐξαριθμούμενος ἐφίκοιτο, τοῖς τ’ ἀκούουσιν ἀπέραντος ἅμα δ’ ἀνωφελὴς ἂν ἐκ τῆς ἀναγνώσεως γίνοιτο χρεία· ἐκ δὲ τῆς καθολικῆς ἀποφάσεως περὶ αὐτῶν καὶ τοῦ τέλους τῆς φιλοτιμίας μᾶλλον ἄν τις εἰς ἔννοιαν ἔλθοι τῶν προειρημένων. οὔτε γὰρ τῶν ἐξ ἱστορίας στρατηγημάτων οὔτε τῶν ἐκ τοῦ καιροῦ καὶ τῆς ὑποκειμένης περιστάσεως ἐπινοημάτων οὔτε τῶν εἰς παράβολον καὶ βίαιον ἀνηκόντων τόλμαν οὐδὲν παρελείφθη. κρίσιν γε μὴν ὁλοσχερῆ γενέσθαι διὰ πλείους αἰτίας οὐχ οἷόν τ’ ἦν· αἵ τε γὰρ δυνάμεις ἀμφοτέρων ἦσαν ἐφάμιλλοι, τά τε κατὰ τοὺς χάρακας ὁμοίως ἀπρόσιτα διὰ τὴν ὀχυρότητα, τό τε διάστημα τῶν στρατοπέδων βραχὺ παντελῶς. ὅπερ αἴτιον ἦν μάλιστα τοῦ τὰς μὲν κατὰ μέρος συμπτώσεις ἀπαύστους γίνεσθαι καθ’ ἡμέραν, ὁλοσχερὲς δὲ συντελεῖσθαι μηδέν. τούτους γὰρ αὐτοὺς ἀεὶ συνέβαινε διαφθείρεσθαι κατὰ τὰς συμπλοκάς, τοὺς ἐν χειρῶν νόμῳ περιπεσόντας· οἱ δ’ ἅπαξ ἐγκλίναντες εὐθέως ἐκτὸς τοῦ δεινοῦ πάντες ἦσαν ὑπὸ ταῖς αὑτῶν ἀσφαλείαις καὶ πάλιν ἐκ μεταβολῆς ἐκινδύνευον.", "st": "1.57"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὥσπερ ἀγαθὸς βραβευτὴς ἡ τύχη μεταβιβάσασα παραβόλως αὐτοὺς ἐκ τοῦ προειρημένου τόπου καὶ τοῦ προϋπάρχοντος ἀθλήματος εἰς παραβολώτερον ἀγώνισμα καὶ τόπον ἐλάττω συνέκλεισεν. ὁ γὰρ Ἀμίλκας, τῶν Ῥωμαίων τὸν Ἔρυκα τηρούντων ἐπί τε τῆς κορυφῆς καὶ παρὰ τὴν ῥίζαν, καθάπερ εἴπομεν, κατελάβετο τὴν πόλιν τῶν Ἐρυκίνων, ἥτις ἦν μεταξὺ τῆς τε κορυφῆς καὶ τῶν πρὸς τῇ ῥίζῃ στρατοπεδευσάντων. ἐξ οὗ συνέβαινε παραβόλως μὲν ὑπομένειν καὶ διακινδυνεύειν πολιορκουμένους τοὺς τὴν κορυφὴν κατέχοντας τῶν Ῥωμαίων, ἀπίστως δὲ τοὺς Καρχηδονίους ἀντέχειν, τῶν τε πολεμίων πανταχόθεν προσκειμένων καὶ τῶν χορηγιῶν οὐ ῥᾳδίως αὐτοῖς παρακομιζομένων, ὡς ἂν τῆς θαλάττης καθ’ ἕνα τόπον καὶ μίαν πρόσοδον ἀντεχομένοις. οὐ μὴν ἀλλὰ πάλιν ἐνταῦθα πάσαις μὲν ἀμφότεροι ταῖς πολιορκητικαῖς ἐπινοίαις καὶ βίαις χρησάμενοι κατ’ ἀλλήλων, πᾶν δὲ γένος ἐνδείας ἀνασχόμενοι, πάσης δ’ ἐπιθέσεως καὶ μάχης πεῖραν λαβόντες, τέλος οὐχ, ὡς Φάβιός φησιν, ἐξαδυνατοῦντες καὶ περικακοῦντες, ἀλλ’ ὡς ἂν ἀπαθεῖς καὶ ἀήττητοί τινες ἄνδρες ἱερὸν ἐποίησαν τὸν στέφανον. πρότερον γὰρ ἢ ’κείνους ἀλλήλων ἐπικρατῆσαι, καίπερ δύ’ ἔτη πάλιν ἐν τούτῳ τῷ τόπῳ διαγωνισαμένους, δι’ ἄλλου τρόπου συνέβη λαβεῖν τὸν πόλεμον τὴν κρίσιν. τὰ μὲν οὖν περὶ τὸν Ἔρυκα καὶ τὰς πεζικὰς δυνάμεις τοιαύτην ἔσχε διάθεσιν. τὰ δὲ πολιτεύματ’ ἦν ἀμφοτέρων παραπλήσια τοῖς ψυχομαχοῦσι τῶν εὐγενῶν ὀρνίθων. ἐκεῖνοί τε γὰρ πολλάκις ἀπολωλεκότες τὰς πτέρυγας διὰ τὴν ἀδυναμίαν, αὐτῇ δὲ τῇ ψυχῇ μένοντες ἐκβάλλουσι τὰς πληγάς, ἕως ἂν αὐτομάτως ποτὲ περιπεσόντες αὑτοῖς καιρίως ἀλλήλων διαδράξωνται, κἄπειτα τούτου γενομένου συμβῇ τὸν ἕτερον αὐτῶν προπεσεῖν· οἵ τε Ῥωμαῖοι καὶ Καρχηδόνιοι κάμνοντες ἤδη τοῖς πόνοις διὰ τὴν συνέχειαν τῶν κινδύνων εἰς τέλος ἀπήλγουν τήν τε δύναμιν παρελέλυντο καὶ παρεῖντο διὰ τὰς πολυχρονίους εἰσφορὰς καὶ δαπάνας.", "st": "1.58"}, {"sp": "N", "t": "ὁμοίως δὲ Ῥωμαῖοι ψυχομαχοῦντες, καίπερ ἔτη σχεδὸν ἤδη πέντε τῶν κατὰ θάλατταν πραγμάτων ὁλοσχερῶς ἀφεστηκότες διά τε τὰς περιπετείας καὶ διὰ τὸ πεπεῖσθαι δι’ αὐτῶν τῶν πεζικῶν δυνάμεων κρινεῖν τὸν πόλεμον, τότε συνορῶντες οὐ προχωροῦν αὑτοῖς τοὔργον κατὰ τοὺς ἐκλογισμοὺς καὶ μάλιστα διὰ τὴν τόλμαν τοῦ τῶν Καρχηδονίων ἡγεμόνος, ἔκριναν τὸ τρίτον ἀντιποιήσασθαι τῶν ἐν ταῖς ναυτικαῖς δυνάμεσιν ἐλπίδων, ὑπολαμβάνοντες διὰ τῆς ἐπινοίας ταύτης, εἰ καιρίως ἅψαιντο τῆς ἐπιβολῆς, μόνως ἂν οὕτως πέρας ἐπιθεῖναι τῷ πολέμῳ συμφέρον. ὃ καὶ τέλος ἐποίησαν. τὸ μὲν γὰρ πρῶτον ἐξεχώρησαν τῆς θαλάττης εἴξαντες τοῖς ἐκ τῆς τύχης συμπτώμασιν, τὸ δὲ δεύτερον ἐλαττωθέντες τῇ περὶ τὰ Δρέπανα ναυμαχίᾳ· τότε δὲ τρίτην ἐποιοῦντο ταύτην τὴν ἐπιβολήν, δι’ ἧς νικήσαντες καὶ τὰ περὶ τὸν Ἔρυκα στρατόπεδα τῶν Καρχηδονίων ἀποκλείσαντες τῆς κατὰ θάλατταν χορηγίας τέλος ἐπέθηκαν τοῖς ὅλοις. ἦν δὲ τῆς ἐπιβολῆς τὸ πλεῖον ψυχομαχία. χορηγία μὲν γὰρ οὐχ ὑπῆρχε πρὸς τὴν πρόθεσιν ἐν τοῖς κοινοῖς, οὐ μὴν ἀλλὰ διὰ τὴν τῶν προεστώτων ἀνδρῶν εἰς τὰ κοινὰ φιλοτιμίαν καὶ γενναιότητα προσευρέθη πρὸς τὴν συντέλειαν. κατὰ γὰρ τὰς τῶν βίων εὐκαιρίας καθ’ ἕνα καὶ δύο καὶ τρεῖς ὑφίσταντο παρέξειν πεντήρη κατηρτισμένην, ἐφ’ ᾧ τὴν δαπάνην κομιοῦνται, κατὰ λόγον τῶν πραγμάτων προχωρησάντων. τῷ δὲ τοιούτῳ τρόπῳ ταχέως ἑτοιμασθέντων διακοσίων πλοίων πεντηρικῶν, ὧν ἐποιήσαντο τὴν ναυπηγίαν πρὸς [παράδειγμα] τὴν τοῦ Ῥοδίου ναῦν, μετὰ ταῦτα στρατηγὸν καταστήσαντες Γάϊον Λυτάτιον ἐξέπεμψαν ἀρχομένης τῆς θερείας. ὃς καὶ παραδόξως ἐπιφανεὶς τοῖς κατὰ τὴν Σικελίαν τόποις τόν τε περὶ τὰ Δρέπανα λιμένα κατέσχε καὶ τοὺς περὶ τὸ Λιλύβαιον ὅρμους, παντὸς ἀνακεχωρηκότος εἰς τὴν οἰκείαν τοῦ τῶν Καρχηδονίων ναυτικοῦ. συστησάμενος δὲ περὶ τὴν ἐν τοῖς Δρεπάνοις πόλιν ἔργα καὶ τἄλλα πρὸς τὴν πολιορκίαν παρασκευασάμενος, ἅμα μὲν ταύτῃ προσεκαρτέρει τὰ δυνατὰ ποιῶν, ἅμα δὲ προορώμενος τὴν παρουσίαν τοῦ Καρχηδονίων στόλου καὶ μνημονεύων τῆς ἐξ ἀρχῆς προθέσεως ὅτι μόνως δύναται διὰ τοῦ κατὰ θάλατταν κινδύνου κρίσεως τὰ ὅλα τυχεῖν, οὐκ ἀχρεῖον οὐδ’ ἀργὸν εἴα γίνεσθαι τὸν χρόνον, ἀλλ’ ἀν’ ἑκάστην ἡμέραν ἀναπείρας καὶ μελέτας ποιῶν τοῖς πληρώμασιν οἰκείως τῆς ἐπιβολῆς τῇ τε λοιπῇ τῇ κατὰ τὴν δίαιταν ἐπιμελείᾳ προσκαρτερῶν ἀθλητὰς ἀπετέλεσεν πρὸς τὸ προκείμενον ἐν πάνυ βραχεῖ χρόνῳ τοὺς ναύτας.", "st": "1.59"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι, παρὰ τὴν ὑπόνοιαν προσπεσόντος αὐτοῖς τοῦ πεπλευκέναι στόλῳ τοὺς Ῥωμαίους καὶ πάλιν ἀντιποιεῖσθαι τῆς θαλάττης, παραυτίκα κατήρτιζον τὰς ναῦς, καὶ πληρώσαντες σίτου καὶ τῶν ἄλλων ἐπιτηδείων ἐξέπεμπον τὸν στόλον, βουλόμενοι μηδὲν ἐλλείπειν τὰ περὶ τὸν Ἔρυκα στρατόπεδα τῶν ἀναγκαίων. κατέστησαν δὲ καὶ στρατηγὸν ἐπὶ τῆς ναυτικῆς δυνάμεως Ἄννωνα· ὃς ἀναχθεὶς καὶ κατάρας ἐπὶ τὴν Ἱερὰν καλουμένην νῆσον ἔσπευδε τοὺς πολεμίους λαθὼν διακομισθῆναι πρὸς τὸν Ἔρυκα καὶ τὰς μὲν ἀγορὰς ἀποθέσθαι καὶ κουφίσαι τὰς ναῦς, προσλαβὼν δ’ ἐπιβάτας ἐκ τῶν μισθοφόρων τοὺς ἐπιτηδείους καὶ Βάρκαν μετ’ αὐτῶν, οὕτως συμμίσγειν τοῖς ὑπεναντίοις. ὁ δὲ Λυτάτιος συνεὶς τὴν παρουσίαν τῶν περὶ τὸν Ἄννωνα καὶ συλλογισάμενος τὴν ἐπίνοιαν αὐτῶν, ἀναλαβὼν ἀπὸ τοῦ πεζοῦ στρατεύματος τοὺς ἀρίστους ἄνδρας ἔπλευσε πρὸς τὴν Αἰγοῦσσαν νῆσον τὴν πρὸ τοῦ Λιλυβαίου κειμένην. κἀνταῦθα παρακαλέσας τὰ πρέποντα τῷ καιρῷ τὰς δυνάμεις διεσάφει τοῖς κυβερνήταις ὡς ἐσομένης εἰς τὴν αὔριον ναυμαχίας. ὑπὸ δὲ τὴν ἑωθινήν, ἤδη τῆς ἡμέρας ὑποφαινούσης, ὁρῶν τοῖς μὲν ἐναντίοις φορὸν ἄνεμον καταρρέοντα καὶ λαμπρόν, σφίσι δὲ δυσχερῆ γινόμενον τὸν ἀνάπλουν πρὸς ἀντίον τὸ πνεῦμα, κοίλης καὶ τραχείας οὔσης τῆς θαλάττης, τὸ μὲν πρῶτον διηπόρει τί δεῖ χρῆσθαι τοῖς παροῦσι. συλλογιζόμενος δ’ ὡς ἐὰν μὲν παραβάλληται χειμῶνος ὄντος, πρὸς Ἄννωνα ποιήσεται τὸν ἀγῶνα καὶ πρὸς αὐτὰς τὰς ναυτικὰς δυνάμεις καὶ πρὸς ἔτι γέμοντα τὰ σκάφη, ἐὰν δὲ τηρῶν εὐδίαν καὶ καταμέλλων ἐάσῃ διᾶραι καὶ συμμῖξαι τοῖς στρατοπέδοις τοὺς πολεμίους, πρός τε τὰς ναῦς εὐκινήτους καὶ κεκουφισμένας ἀγωνιεῖται πρός τε τοὺς ἀρίστους ἄνδρας τῶν ἐκ τοῦ πεζοῦ στρατευμάτων, τὸ δὲ μέγιστον, πρὸς τὴν Ἀμίλκου τόλμαν, ἧς οὐδὲν ἦν τότε φοβερώτερον· διόπερ ἔκρινε μὴ παρεῖναι τὸν ἐνεστῶτα καιρόν· συνιδὼν δὲ τὰς τῶν πολεμίων ναῦς ἱστιοδρομούσας ἀνήγετο μετὰ σπουδῆς. τῶν δὲ πληρωμάτων εὐχερῶς ἀναφερόντων τὸν κλύδωνα ταῖς εὐεξίαις, ταχέως ἐπὶ μίαν ἐκτείνας ναῦν ἀντίπρωρρον κατέστησε τοῖς πολεμίοις τὸν στόλον.", "st": "1.60"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι κατιδόντες τὸν διάπλουν αὐτῶν προκατέχοντας τοὺς Ῥωμαίους, καθελόμενοι τοὺς ἱστοὺς καὶ παρακαλέσαντες κατὰ ναῦν σφᾶς αὐτοὺς συνέβαλλον τοῖς ὑπεναντίοις. τῆς δ’ ἑκατέρων παρασκευῆς τὴν ἐναντίαν ἐχούσης διάθεσιν τῇ περὶ τὰ Δρέπανα γενομένῃ ναυμαχίᾳ, καὶ τὸ τέλος ἑκατέροις τῆς μάχης εἰκότως ἐναντίον ἀπέβη. Ῥωμαῖοι μὲν γὰρ τήν τε ναυπηγίαν μετειλήφεσαν καὶ τὰ βάρη πάντα χωρὶς τῶν πρὸς τὴν ναυμαχίαν ἐπιτηδείων ἐξετέθειντο· τά τε πληρώματα συγκεκροτημένα διαφέρουσαν αὐτοῖς τὴν χρείαν παρείχετο, τούς τ’ ἐπιβάτας κατ’ ἐκλογὴν ἄνδρας ἀπαραχωρήτους ἐκ τῶν πεζικῶν στρατοπέδων εἶχον. περὶ δὲ τοὺς Καρχηδονίους τἀναντία τούτοις ὑπῆρχεν. αἱ μὲν γὰρ νῆες γέμουσαι δυσχρήστως διέκειντο πρὸς τὸν κίνδυνον, τὰ δὲ πληρώματα τελέως ἦν ἀνάσκητα καὶ πρὸς καιρὸν ἐμβεβλημένα, τὰ δ’ ἐπιβατικὰ νεοσύλλογα καὶ πρωτόπειρα πάσης κακοπαθείας καὶ παντὸς δεινοῦ. διὰ γὰρ τὸ μηδέποτ’ ἂν ἔτι τοὺς Ῥωμαίους ἐλπίσαι τῆς θαλάττης ἀντιποιήσασθαι καταφρονήσαντες ὠλιγώρουν τῶν ναυτικῶν δυνάμεων. τοιγαροῦν ἅμα τῷ συμβαλεῖν κατὰ πολλὰ μέρη τῆς μάχης ἐλαττούμενοι ταχέως ἐλείφθησαν, καὶ πεντήκοντα μὲν αὐτῶν ναῦς κατέδυσαν, ἑβδομήκοντα δ’ ἑάλωσαν αὔτανδροι· τὸ δὲ λοιπὸν πλῆθος ἐπαράμενον τοὺς ἱστοὺς καὶ κατουρῶσαν αὖθις ἀπεχώρει πρὸς τὴν Ἱερὰν νῆσον, εὐτυχῶς καὶ παραδόξως ἐκ μεταβολῆς αὐτοῖς πρὸς τὸν δέοντα καιρὸν τοῦ πνεύματος συνεργήσαντος. ὁ μὲν οὖν τῶν Ῥωμαίων στρατηγὸς ἀποπλεύσας πρὸς τὸ Λιλύβαιον καὶ τὰ στρατόπεδα περὶ τὴν τῶν αἰχμαλώτων πλοίων καὶ τῶν σωμάτων οἰκονομίαν ἐγίνετο, μεγάλην οὖσαν· οὐ γὰρ πολὺ τῶν μυρίων ἔλειπε σωμάτων τὰ ληφθέντα ζωγρίᾳ κατὰ τὸν κίνδυνον.", "st": "1.61"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι, προσπεσούσης αὐτοῖς ἀπροσδοκήτως τῆς ἥττης, ταῖς μὲν ὁρμαῖς καὶ ταῖς φιλοτιμίαις ἀκμὴν ἕτοιμοι πολεμεῖν ἦσαν, τοῖς δὲ λογισμοῖς ἐξηπόρουν. οὔτε γὰρ χορηγεῖν ἔτι ταῖς ἐν τῇ Σικελίᾳ δυνάμεσιν οἷοί τ’ ἦσαν, κρατούντων τῆς θαλάττης τῶν ὑπεναντίων· ἀπογνόντες δὲ ταύτας καὶ προδόται τρόπον τινὰ γενόμενοι, ποίαις χερσὶν ἢ ποίοις ἡγεμόσιν πολεμήσειαν οὐκ εἶχον. διόπερ ὀξέως διαπεμψάμενοι πρὸς τὸν Βάρκαν ἐπέτρεψαν ἐκείνῳ περὶ τῶν ὅλων. ὁ δὲ καὶ λίαν ἐποίησεν ἔργον ἡγεμόνος ἀγαθοῦ καὶ φρονίμου. μέχρι μὲν γὰρ ἐκ τῶν κατὰ λόγον ἦν τις ἐλπὶς ἐν τοῖς ὑποκειμένοις, οὐδὲν τῶν παραβόλων ἢ δεινῶν δοκούντων εἶναι παρέλιπεν, ἀλλὰ πάσας τὰς τοῦ νικᾶν ἐν τῷ πολεμεῖν ἐλπίδας, εἰ καί τις ἄλλος ἡγεμόνων, ἐξήλεγξεν. ἐπειδὴ δὲ περιέστη τὰ πράγματα, καὶ τῶν κατὰ λόγον οὐδὲν ἔτι κατελείπετο πρὸς τὸ σῴζειν τοὺς ὑποταττομένους, πάνυ νουνεχῶς καὶ πραγματικῶς εἴξας τοῖς παροῦσιν ὑπὲρ σπονδῶν καὶ διαλύσεων ἐξαπέστελλε πρεσβευτάς. τοῦ γὰρ αὐτοῦ νομιστέον ἡγεμόνος εἶναι τὸ δύνασθαι βλέπειν τόν τε τοῦ νικᾶν, ὁμοίως δὲ καὶ τὸν τοῦ λείπεσθαι καιρόν. τοῦ δὲ Λυτατίου προθύμως δεξαμένου τὰ παρακαλούμενα διὰ τὸ συνειδέναι τοῖς σφετέροις πράγμασι τετρυμένοις καὶ κάμνουσιν ἤδη τῷ πολέμῳ, συνέβη τέλος ἐπιθεῖναι τῇ διαφορᾷ τοιούτων τινῶν συνθηκῶν διαγραφεισῶν· ‘ἐπὶ τοῖσδε φιλίαν εἶναι Καρχηδονίοις καὶ Ῥωμαίοις, ἐὰν καὶ τῷ δήμῳ τῶν Ῥωμαίων συνδοκῇ. ἐκχωρεῖν Σικελίας ἁπάσης Καρχηδονίους καὶ μὴ πολεμεῖν Ἱέρωνι μηδ’ ἐπιφέρειν ὅπλα Συρακοσίοις μηδὲ τῶν Συρακοσίων συμμάχοις. ἀποδοῦναι Καρχηδονίους Ῥωμαίοις χωρὶς λύτρων ἅπαντας τοὺς αἰχμαλώτους. ἀργυρίου κατενεγκεῖν Καρχηδονίους Ῥωμαίοις ἐν ἔτεσιν εἴκοσι δισχίλια καὶ διακόσια τάλαντα Εὐβοϊκά.’", "st": "1.62"}, {"sp": "N", "t": "τούτων δ’ ἐπανενεχθέντων εἰς τὴν Ῥώμην, οὐ προσεδέξατο τὰς συνθήκας ὁ δῆμος. ἀλλ’ ἐξαπέστειλεν ἄνδρας δέκα τοὺς ἐπισκεψομένους ὑπὲρ τῶν πραγμάτων. οἳ καὶ παραγενόμενοι τῶν μὲν ὅλων οὐδὲν ἔτι μετέθηκαν, βραχέα δὲ προσεπέτειναν τοὺς Καρχηδονίους. τόν τε γὰρ χρόνον τῶν φόρων ἐποίησαν ἥμισυν, χίλια τάλαντα προσθέντες, τῶν τε νήσων ἐκχωρεῖν Καρχηδονίους προσεπέταξαν, ὅσαι μεταξὺ τῆς Ἰταλίας κεῖνται καὶ τῆς Σικελίας. ὁ μὲν οὖν Ῥωμαίοις καὶ Καρχηδονίοις συστὰς περὶ Σικελίας πόλεμος ἐπὶ τοιούτοις καὶ τοιοῦτον ἔσχε τὸ τέλος, ἔτη πολεμηθεὶς εἴκοσι καὶ τέτταρα συνεχῶς, πόλεμος ὧν ἡμεῖς ἴσμεν ἀκοῇ μαθόντες πολυχρονιώτατος καὶ συνεχέστατος καὶ μέγιστος. ἐν ᾧ χωρὶς τῶν λοιπῶν ἀγώνων καὶ παρασκευῶν, καθάπερ εἴπομεν ἀνώτερον, ἅπαξ μὲν οἱ συνάμφω πλείοσιν ἢ πεντακοσίοις, πάλιν δὲ μικρῷ λείπουσιν ἑπτακοσίοις σκάφεσι πεντηρικοῖς ἐναυμάχησαν πρὸς ἀλλήλους. ἀπέβαλόν γε μὴν Ῥωμαῖοι μὲν ἐν τῷ πολέμῳ τούτῳ πεντήρεις μετὰ τῶν ἐν ταῖς ναυαγίαις διαφθαρεισῶν εἰς ἑπτακοσίας, Καρχηδόνιοι δ’ εἰς πεντακοσίας. ὥστε τοὺς θαυμάζοντας τὰς Ἀντιγόνου καὶ Πτολεμαίου καὶ Δημητρίου ναυμαχίας καὶ τοὺς στόλους εἰκότως ἂν περὶ τούτων ἱστορήσαντας ἐκπεπλῆχθαι τὴν ὑπερβολὴν τῶν πράξεων. εἰ δέ τις βουληθείη συλλογίσασθαι τὴν διαφορὰν τῶν πεντηρικῶν πλοίων πρὸς τὰς τριήρεις, αἷς οἵ τε Πέρσαι πρὸς τοὺς Ἕλληνας καὶ πάλιν Ἀθηναῖοι καὶ Λακεδαιμόνιοι πρὸς ἀλλήλους ἐναυμάχουν, οὐδ’ ἂν καθόλου δυνηθείη τηλικαύτας δυνάμεις εὑρεῖν ἐν θαλάττῃ διηγωνισμένας. ἐξ ὧν δῆλον τὸ προτεθὲν ἡμῖν ἐξ ἀρχῆς ὡς οὐ τύχῃ Ῥωμαῖοι, καθάπερ ἔνιοι δοκοῦσι τῶν Ἑλλήνων, οὐδ’ αὐτομάτως, ἀλλὰ καὶ λίαν εἰκότως ἐν τοιούτοις καὶ τηλικούτοις πράγμασιν ἐνασκήσαντες οὐ μόνον ἐπεβάλοντο τῇ τῶν ὅλων ἡγεμονίᾳ καὶ δυναστείᾳ τολμηρῶς, ἀλλὰ καὶ καθίκοντο τῆς προθέσεως.", "st": "1.63"}, {"sp": "N", "t": "καὶ τί δήποτ’ ἔστι τὸ αἴτιον, ἀπορήσαι τις ἄν, ὅτι κεκρατηκότες τῶν ὅλων καὶ πολλαπλασίαν ἔχοντες ὑπεροχὴν νῦν ἢ πρόσθεν οὔτ’ ἂν πληρῶσαι τοσαύτας ναῦς οὔτ’ ἀναπλεῦσαι τηλικούτοις στόλοις δυνηθεῖεν; οὐ μὴν ἀλλὰ περὶ μὲν ταύτης τῆς ἀπορίας σαφῶς ἐξέσται τὰς αἰτίας κατανοεῖν, ὅταν ἐπὶ τὴν ἐξήγησιν αὐτῶν τῆς πολιτείας ἔλθωμεν· ὑπὲρ ἧς οὔθ’ ἡμῖν ἐν παρέργῳ ῥητέον οὔτε τοῖς ἀκούουσιν ἀργῶς προσεκτέον. τὸ μὲν γὰρ θέαμα καλόν, σχεδὸν δ’ ὡς ἔπος εἰπεῖν ἄγνωστον ἕως τοῦ νῦν χάριν τῶν περὶ αὐτῆς συγγεγραφότων. οἱ μὲν γὰρ ἠγνοήκασιν, οἱ δ’ ἀσαφῆ καὶ τελέως ἀνωφελῆ πεποίηνται τὴν ἐξήγησιν. πλὴν ἔν γε τῷ προειρημένῳ πολέμῳ τὰς μὲν τῶν πολιτευμάτων ἀμφοτέρων προαιρέσεις ἐφαμίλλους εὕροι τις ἂν γεγενημένας οὐ μόνον ταῖς ἐπιβολαῖς ἀλλὰ καὶ ταῖς μεγαλοψυχίαις, μάλιστα δὲ τῇ περὶ τῶν πρωτείων φιλοτιμίᾳ, τούς γε μὴν ἄνδρας οὐ μικρῷ πολλῷ δὲ γενναιοτέρους ἐν παντὶ Ῥωμαίους· ἡγεμόνα δὲ καὶ γνώμῃ καὶ τόλμῃ θετέον ἄριστον Ἀμίλκαν τῶν τότε γεγονέναι τὸν Βάρκαν ἐπικαλούμενον, πατέρα δὲ κατὰ φύσιν Ἀννίβου τοῦ μετὰ ταῦτα πολεμήσαντος Ῥωμαίοις.", "st": "1.64"}, {"sp": "N", "t": "μετὰ δὲ τὰς διαλύσεις ταύτας ἴδιόν τι καὶ παραπλήσιον ἀμφοτέροις συνέβη παθεῖν. ἐξεδέξατο γὰρ πόλεμος ἐμφύλιος Ῥωμαίους μὲν ὁ πρὸς τοὺς Φαλίσκους καλουμένους, ὃν ταχέως καὶ συμφερόντως ἐπετέλεσαν, ἐν ὀλίγαις ἡμέραις ἐγκρατεῖς γενόμενοι τῆς πόλεως αὐτῶν, Καρχηδονίους δὲ κατὰ τὸν αὐτὸν καιρὸν οὐ μικρὸς οὐδ’ εὐκαταφρόνητος ὁ πρὸς τοὺς ξένους καὶ τοὺς Νομάδας καὶ τοὺς ἅμα τούτοις ἀποστάντας Λίβυας, ἐν ᾧ πολλοὺς καὶ μεγάλους ὑπομείναντες φόβους τέλος οὐ μόνον ὑπὲρ τῆς χώρας ἐκινδύνευσαν, ἀλλὰ καὶ περὶ σφῶν αὐτῶν καὶ τοῦ τῆς πατρίδος ἐδάφους. ἐπὶ δὲ τὸν πόλεμον τοῦτον ἐπιστῆσαι μὲν ἄξιον διὰ πλείους αἰτίας, ἐπὶ κεφαλαίου δὲ καὶ διὰ βραχέων αὐτοῦ ποιήσασθαι τὴν ἐξήγησιν κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν. τόν τε γὰρ παρὰ τοῖς πολλοῖς λεγόμενον ἄσπονδον πόλεμον, τίνα φύσιν ἔχει καὶ διάθεσιν, μάλιστ’ ἄν τις ἐκ τῶν τότε γεγονότων ἐπιγνοίη, τούς τε χρωμένους μισθοφορικαῖς δυνάμεσι τίνα δεῖ προορᾶσθαι καὶ φυλάττεσθαι μακρόθεν, ἐναργέστατ’ ἂν ἐκ τῆς τότε περιστάσεως συνθεωρήσειεν, πρὸς δὲ τούτοις τί διαφέρει καὶ κατὰ πόσον ἤθη σύμμικτα καὶ βάρβαρα τῶν ἐν παιδείαις καὶ νόμοις καὶ πολιτικοῖς ἔθεσιν ἐκτεθραμμένων· τὸ δὲ μέγιστον, τὰς αἰτίας ἐκ τῶν ἐν ἐκείνοις τοῖς καιροῖς πεπραγμένων κατανοήσειεν, δι’ ἃς ὁ κατ’ Ἀννίβαν συνέστη Ῥωμαίοις καὶ Καρχηδονίοις πόλεμος. ὑπὲρ οὗ διὰ τὸ μὴ μόνον παρὰ τοῖς συγγραφεῦσιν, ἀλλὰ καὶ παρὰ τοῖς πεπολεμηκόσιν ἔτι νῦν ἀμφισβητεῖσθαι τὰς αἰτίας, χρήσιμόν ἐστι τὴν ἀληθινωτάτην παραστῆσαι διάληψιν τοῖς φιλομαθοῦσιν.", "st": "1.65"}, {"sp": "N", "t": "ὡς γὰρ θᾶττον ἐπιτελεσθεισῶν τῶν προειρημένων διαλύσεων ἀποκατέστησε τὰς περὶ τὸν Ἔρυκα δυνάμεις εἰς τὸ Λιλύβαιον ὁ Βάρκας, εὐθέως αὐτὸς μὲν ἀπέθετο τὴν ἀρχήν, ὁ δ’ ἐπὶ τῆς πόλεως στρατηγὸς Γέσκων ἐγίνετο περὶ τὸ περαιοῦν τοὺς στρατιώτας εἰς τὴν Λιβύην. προϊδόμενος δὲ τὸ μέλλον ἐμφρόνως ἐνεβίβαζε κατὰ μέρη διαιρῶν αὐτοὺς καὶ διαλείμματα ποιῶν τῆς ἐξαποστολῆς, βουλόμενος ἀναστροφὴν διδόναι τοῖς Καρχηδονίοις εἰς τὸ τοὺς καταπλεύσαντας καὶ μισθοδοτηθέντας τὰ προσοφειλόμενα τῶν ὀψωνίων φθάνειν ἀπαλλαττομένους ἐκ τῆς Καρχηδόνος εἰς τὴν οἰκείαν πρὶν ἢ τοὺς ἑξῆς περαιουμένους ἐπικαταλαβεῖν. ὁ μὲν οὖν Γέσκων ἐχόμενος ταύτης τῆς ἐννοίας οὕτως ἐχείριζε τὰ κατὰ τὴν ἐξαποστολήν. οἱ δὲ Καρχηδόνιοι τὰ μὲν οὐκ εὐπορούμενοι χρημάτων διὰ τὰς προγεγενημένας δαπάνας, τὰ δὲ καὶ πεπεισμένοι παραιτήσεσθαι τοὺς μισθοφόρους μέρος τι τῶν προσοφειλομένων ὀψωνίων, ἐὰν καὶ συναθροίσωσι καὶ δέξωνται πάντας εἰς τὴν Καρχηδόνα, παρακατεῖχον ἐκεῖ τοὺς καταπλέοντας διὰ ταύτην τὴν ἐλπίδα καὶ συνεῖχον ἐν τῇ πόλει. γινομένων δὲ πλειόνων ἀδικημάτων καὶ νύκτωρ καὶ μεθ’ ἡμέραν, τὸ μὲν πρῶτον ὑπιδόμενοι τὸν ὄχλον καὶ τὴν συμβαίνουσαν ἀκρασίαν ἠξίωσαν τοὺς ἡγεμόνας, ἕως ἂν ἑτοιμασθῇ μὲν τὰ κατὰ τὰς σιταρχίας αὐτοῖς, προσδέξωνται δὲ τοὺς ἀπολειπομένους, ἀναχωρῆσαι πάντας εἴς τινα πόλιν τὴν προσαγορευομένην Σίκκαν, λαβόντας εἰς τὰ κατεπείγοντα χρυσοῦν ἕκαστον. προθύμως δὲ συνυπακουσάντων πρὸς τὴν ἔξοδον καὶ βουλομένων αὐτοῦ καταλιπεῖν τὰς ἀποσκευάς, καθάπερ καὶ τὸν πρῶτον χρόνον ὑπῆρχον, ὡς θᾶττον ἐσομένης τῆς ἐπανόδου πρὸς τοὺς ὀψωνιασμούς, ἀγωνιῶντες οἱ Καρχηδόνιοι μή ποτε διὰ χρόνου παραγεγονότες, καὶ τινὲς μὲν τέκνων ἔνιοι δὲ καὶ γυναικῶν ἱμείροντες, οἱ μὲν οὐκ ἐκπορευθῶσι τὸ παράπαν, οἱ δ’ ἐκπορευθέντες αὖθις ἀνακάμπτωσι πρὸς ταῦτα, καὶ τῷ τοιούτῳ τρόπῳ μηδὲν ἧττον ἀδίκημα γίνηται κατὰ τὴν πόλιν, ταῦτα προορώμενοι μετὰ πολλῆς ἀπεχθείας οὐδαμῶς βουλομένους τοὺς ἀνθρώπους ἠνάγκασαν τὰς ἀποσκευὰς μεθ’ αὑτῶν ἀπαγαγεῖν. οἱ δὲ μισθοφόροι συναναχθέντες εἰς τὴν Σίκκαν καὶ διὰ πολλοῦ χρόνου τετευχότες ἀνέσεως καὶ σχολῆς, ὅπερ ἀφυέστατον ὑπάρχει ξενικαῖς δυνάμεσι καὶ σχεδὸν ὡς εἰπεῖν ἀρχηγὸν καὶ μόνον αἴτιον γίνεται στάσεως, διῆγον ἀδεῶς. ἅμα δὲ ῥᾳθυμοῦντες, τινὲς μὲν αὐτῶν ἐξελογίζοντο τὰ προσοφειλόμενα σφίσι τῶν ὀψωνίων ἐπὶ τὸ πλεῖον καὶ συγκεφαλαιούμενοι πολλαπλάσια τῶν καθηκόντων ταῦτ’ ἔφασαν δεῖν ἀπαιτεῖν τοὺς Καρχηδονίους· πάντες δ’ ἀναμιμνησκόμενοι τῶν ἐπαγγελιῶν, ὧν οἱ στρατηγοὶ κατὰ τοὺς ἐπισφαλεῖς τῶν καιρῶν παρακαλοῦντες σφᾶς ἐπεποίηντο, μεγάλας εἶχον ἐλπίδας καὶ μεγάλην προσδοκίαν τῆς ἐσομένης περὶ αὐτοὺς ἐπανορθώσεως.", "st": "1.66"}, {"sp": "N", "t": "διόπερ ἅμα τῷ συλλεχθῆναι πάντας εἰς τὴν Σίκκαν, καὶ παραγενόμενον Ἄννωνα τὸν ὑπάρχοντα στρατηγὸν ἐν τῇ Λιβύῃ τότε τῶν Καρχηδονίων μὴ οἷον τὰς ἐλπίδας καὶ τὰς ἐπαγγελίας ἐκπληροῦν, ἀλλὰ τοὐναντίον λέγοντα τὸ βάρος τῶν φόρων καὶ τὴν καθόλου στενοχωρίαν τῆς πόλεως ἐγχειρεῖν παραιτεῖσθαι μέρος τι τῶν ἐξ ὁμολόγου προσοφειλομένων ὀψωνίων, εὐθέως διαφορὰ καὶ στάσις ἐγεννᾶτο καὶ συνδρομαὶ συνεχεῖς ἐγίνοντο, ποτὲ μὲν κατὰ γένη, ποτὲ δ’ ὁμοῦ πάντων. ὡς δ’ ἂν μήθ’ ὁμοεθνῶν μήθ’ ὁμογλώττων ὑπαρχόντων, ἦν ἀμιξίας καὶ θορύβου καὶ τῆς λεγομένης τύρβης πλῆρες τὸ στρατόπεδον. Καρχηδόνιοι γὰρ ἀεὶ χρώμενοι ποικίλαις καὶ μισθοφορικαῖς δυνάμεσιν, πρὸς μὲν τὸ μὴ ταχέως συμφρονήσαντας ἀπειθεῖν μηδὲ δυσκαταπλήκτους εἶναι τοῖς ἡγουμένοις ὀρθῶς στοχάζονται, ποιοῦντες ἐκ πολλῶν γενῶν τὴν δύναμιν, πρὸς δὲ τὸ γενομένης ὀργῆς ἢ διαβολῆς ἢ στάσεως διδάξαι καὶ πραῧναι καὶ μεταθεῖναι τοὺς ἠγνοηκότας ὁλοσχερῶς ἀστοχοῦσιν. οὐ γὰρ οἷον ἀνθρωπίνῃ χρῆσθαι κακίᾳ συμβαίνει τὰς τοιαύτας δυνάμεις, ὅταν ἅπαξ εἰς ὀργὴν καὶ διαβολὴν ἐμπέσωσι πρός τινας, ἀλλ’ ἀποθηριοῦσθαι τὸ τελευταῖον καὶ παραστατικὴν λαμβάνειν διάθεσιν. ὃ καὶ τότε συνέβη γενέσθαι περὶ αὐτούς· ἦσαν γὰρ οἱ μὲν Ἴβηρες, οἱ δὲ Κελτοί, τινὲς δὲ Λιγυστῖνοι καὶ Βαλιαρεῖς, οὐκ ὀλίγοι δὲ μιξέλληνες, ὧν οἱ πλείους αὐτόμολοι καὶ δοῦλοι· τὸ δὲ μέγιστον μέρος αὐτῶν ἦν Λίβυες. διόπερ οὔτ’ ἐκκλησιάσαι συναθροίσαντα πάντας ὁμοῦ δυνατὸν ἦν οὔτ’ ἄλλην οὐδεμίαν εὑρέσθαι πρὸς τοῦτο μηχανήν. πῶς γὰρ οἷόν τε; τὸν μὲν γὰρ στρατηγὸν εἰδέναι τὰς ἑκάστων διαλέκτους ἀδύνατον· διὰ πλειόνων δ’ ἑρμηνέων ἐκκλησιάζειν, ἅμα τετράκις καὶ πεντάκις περὶ ταὐτοῦ λέγοντα πράγματος, σχεδὸν ὡς εἰπεῖν ἔτι τοῦ πρόσθεν ἀδυνατώτερον. λοιπὸν ἦν διὰ τῶν ἡγεμόνων ποιεῖσθαι τὰς ἀξιώσεις καὶ παρακλήσεις· ὅπερ ἐπειρᾶτο τότε συνεχῶς ποιεῖν [ὁ] Ἄννων. ἀκμὴν δὲ καὶ τούτους συνέβαινεν ἃ μὲν οὐκ αἰσθάνεσθαι τῶν λεγομένων, ἃ δὲ καὶ συναινέσαντας ἐνίοτε τῷ στρατηγῷ τἀναντία πρὸς τοὺς πολλοὺς ἀναγγέλλειν, τοὺς μὲν δι’ ἄγνοιαν, τοὺς δὲ διὰ κακίαν· ἐξ ὧν ἦν ἀσαφείας, ἀπιστίας, ἀμιξίας ἅπαντα πλήρη. πρὸς γὰρ τοῖς ἄλλοις ᾤοντο καὶ τοὺς Καρχηδονίους ἐπίτηδες τοὺς μὲν εἰδότας στρατηγοὺς τὰς γεγενημένας χρείας κατὰ Σικελίαν ἐξ αὐτῶν καὶ πεποιημένους σφίσι τὰς ἐπαγγελίας οὐκ ἐξαποστέλλειν ὡς αὐτούς, τὸν δὲ μηδενὶ τούτων παρηκολουθηκότα τοῦτον ἐκπεπομφέναι. τέλος δ’ οὖν ἀπαξιώσαντες μὲν τὸν Ἄννωνα, διαπιστήσαντες δὲ τοῖς κατὰ μέρος ἡγεμόσιν, ἐξοργισθέντες δὲ πρὸς τοὺς Καρχηδονίους ὥρμησαν πρὸς τὴν πόλιν· καὶ κατεστρατοπέδευσαν ἀπέχοντες ὡς ἂν ἑκατὸν καὶ εἴκοσι στάδια τῆς Καρχηδόνος ἐπὶ τῷ καλουμένῳ Τύνητι, πλείους ὄντες τῶν δισμυρίων.", "st": "1.67"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι τότε πρὸ ὀφθαλμῶν ἐλάμβανον τὴν αὑτῶν ἄγνοιαν, ὅτ’ ἦν οὐδὲν ὄφελος. μεγάλα μὲν γὰρ ἥμαρτον, εἰς ἕνα τόπον ἁθροίσαντες τοσοῦτο πλῆθος μισθοφόρων, ἔχοντες οὐδεμίαν ἐλπίδα πολεμικῆς χρείας ἐν ταῖς πολιτικαῖς δυνάμεσι· τούτου δὲ μεῖζον ἔτι, προέμενοι τὰ τέκνα καὶ τὰς γυναῖκας καὶ σὺν τούτοις τὰς ἀποσκευάς· οἷς ἐξῆν ὁμήροις χρησαμένους ἀσφαλέστερον μὲν αὐτοὺς βουλεύσασθαι περὶ τῶν ὑποπιπτόντων, εὐπειθεστέροις δ’ ἐκείνοις χρῆσθαι πρὸς τὸ παρακαλούμενον, οὐ μὴν ἀλλὰ καὶ καταπλαγέντες τὴν στρατοπεδείαν πᾶν ὑπέμενον, σπουδάζοντες ἐξιλάσασθαι τὴν ὀργὴν αὐτῶν, καὶ τάς τε τῶν ἐπιτηδείων ἀγορὰς ἐκπέμποντες δαψιλεῖς ἐπώλουν, καθὼς ἐκεῖνοι βούλοιντο καὶ τάττοιεν τὰς τιμάς, τῶν τε τῆς γερουσίας ἀεί τινας ἐξαπέστελλον πρέσβεις, ὑπισχνούμενοι ποιήσειν πᾶν ὅ,τι ποτ’ ἂν αὐτοὺς ἀξιώσαιεν εἰ κατὰ δύναμιν. ἦν δὲ πολὺ τὸ καθ’ ἑκάστην ἡμέραν παρὰ τοῖς μισθοφόροις ἐπινοούμενον, ἅτε δὴ κατατεθαρρηκότων μὲν καὶ συντεθεωρηκότων τὴν κατάπληξιν καὶ πτοίαν τῶν Καρχηδονίων, πεφρονηματισμένων δὲ καὶ πεπεισμένων διὰ τοὺς προγεγονότας αὐτοῖς ἐν Σικελίᾳ πρὸς τὰ Ῥωμαϊκὰ στρατόπεδα κινδύνους μὴ οἷον Καρχηδονίους ἀντοφθαλμῆσαί ποτ’ ἂν πρὸς αὐτοὺς ἐν τοῖς ὅπλοις, ἀλλὰ μηδὲ τῶν λοιπῶν ἀνθρώπων μηδένα ῥᾳδίως. διόπερ ἅμα τῷ συγχωρῆσαι τὰ περὶ τῶν ὀψωνίων αὐτοῖς τοὺς Καρχηδονίους εὐθέως ἐπέβαινον καὶ τῶν τεθνεώτων ἵππων ἀπῄτουν τὰς ἀξίας. προσδεξαμένων δὲ καὶ τοῦτο, πάλιν τῆς προσοφειλομένης σιτομετρίας ἐκ πλείονος χρόνου τὴν μεγίστην γεγονυῖαν ἐν τῷ πολέμῳ τιμὴν ἔφασκον αὑτοὺς δεῖν κομίζεσθαι. καθόλου δ’ ἀεί τι νέον καὶ καινὸν προσεξεύρισκον, εἰς ἀδύνατον ἐκβάλλοντες τὴν διάλυσιν διὰ τὸ πολλοὺς καχέκτας καὶ στασιώδεις ἐν αὐτοῖς ὑπάρχειν. οὐ μὴν ἀλλὰ πᾶν τὸ δυνατὸν ὑπισχνουμένων τῶν Καρχηδονίων, κατένευσαν ἐπιτρέψειν περὶ τῶν ἀμφισβητουμένων ἑνὶ τῶν ἐν Σικελίᾳ γεγονότων στρατηγῶν. πρὸς μὲν οὖν Ἀμίλκαν τὸν Βάρκαν, μεθ’ οὗ συγκεκινδυνεύκεσαν ἐν τῇ Σικελίᾳ, δυσχερῶς εἶχον, δοκοῦντες οὐχ ἥκιστα δι’ ἐκεῖνον ὀλιγωρεῖσθαι τῷ μήτε πρεσβεύειν πρὸς αὐτοὺς τήν τε στρατηγίαν ἑκουσίως δοκεῖν ἀποτεθεῖσθαι· πρὸς δὲ Γέσκωνα πάνυ διέκειντο φιλανθρώπως, ὃς ἐγεγόνει μὲν ἐν Σικελίᾳ στρατηγός, ἐπεποίητο δ’ αὐτῶν πρόνοιαν τὴν ἐνδεχομένην ἔν τε τοῖς ἄλλοις καὶ μάλιστα περὶ τὴν ἀνακομιδήν. διόπερ ἐπέτρεψαν τούτῳ περὶ τῶν ἀμφισβητουμένων.", "st": "1.68"}, {"sp": "N", "t": "ὃς παραγενόμενος κατὰ θάλατταν μετὰ τῶν χρημάτων καὶ προσπλεύσας πρὸς τὸν Τύνητα, τὸ μὲν πρῶτον λαμβάνων τοὺς ἡγεμόνας, μετὰ δὲ ταῦτα συναθροίζων κατὰ γένη τοὺς πολλούς, ἃ μὲν ἐπετίμα περὶ τῶν γεγονότων, ἃ δὲ διδάσκειν ἐπειρᾶτο περὶ τῶν παρόντων· τὸ δὲ πλεῖον παρεκάλει πρὸς τὸ μέλλον, ἀξιῶν αὐτοὺς εὔνους ὑπάρχειν τοῖς ἐξ ἀρχῆς μισθοδόταις. τέλος δ’ ὥρμησε πρὸς τὸ διαλύειν τὰ προσοφειλόμενα τῶν ὀψωνίων, κατὰ γένη ποιούμενος τὴν μισθοδοσίαν. ἦν δέ τις Καμπανὸς ηὐτομοληκὼς παρὰ τῶν Ῥωμαίων δοῦλος, ἔχων σωματικὴν δύναμιν καὶ τόλμαν ἐν τοῖς πολεμικοῖς παράβολον, ὄνομα Σπένδιος. οὗτος εὐλαβούμενος μὴ παραγενόμενος αὐτὸν ὁ δεσπότης κομίσηται, καὶ κατὰ τοὺς Ῥωμαίων νόμους αἰκισθεὶς διαφθαρῇ, πᾶν ἐτόλμα καὶ λέγειν καὶ πράττειν, σπουδάζων διακόψαι τὰς διαλύσεις τὰς πρὸς Καρχηδονίους. ἅμα δὲ τούτῳ καὶ Λίβυς τις Μάθως, ὃς ἦν μὲν ἐλεύθερος καὶ τῶν συνεστρατευμένων, πλεῖστα δὲ κεκινηκὼς κατὰ τὰς προειρημένας ταραχάς. ἀγωνιῶν οὖν μὴ τίσῃ καὶ τὴν ὑπὲρ τῶν λοιπῶν δίκην, ἐπὶ τῆς αὐτῆς ἐγένετο γνώμης τοῖς περὶ τὸν Σπένδιον. καὶ λαμβάνων τοὺς Λίβυας ὑπεδείκνυε διότι μετὰ τὸν ὀψωνιασμὸν χωρισθέντων τῶν ἄλλων γενῶν εἰς τὰς πατρίδας ἀπερείσονται καὶ τὴν ὑπὲρ ἐκείνων ὀργὴν εἰς αὐτοὺς οἱ Καρχηδόνιοι καὶ βουλήσονται διὰ τῆς εἰς σφᾶς τιμωρίας ἅπαντας καταπλήξασθαι τοὺς ἐν τῇ Λιβύῃ. ταχὺ δὲ προσανασεισθέντες οἱ πολλοὶ τοῖς τοιούτοις λόγοις καὶ λαμβανόμενοι βραχείας ἀφορμῆς ἐκ τοῦ τὸν Γέσκωνα τὰ μὲν ὀψώνια διαλύειν τὰς δὲ τιμὰς τοῦ τε σίτου καὶ τῶν ἵππων ὑπερτίθεσθαι, συνέτρεχον εὐθέως εἰς ἐκκλησίαν. καὶ τοῦ μὲν Σπενδίου καὶ τοῦ Μάθω διαβαλλόντων καὶ κατηγορούντων τοῦ τε Γέσκωνος καὶ τῶν Καρχηδονίων ἤκουον καὶ προσεῖχον ἐπιμελῶς τὸν νοῦν τοῖς λεγομένοις. εἰ δέ τις ἕτερος προπορευθείη συμβουλεύσων, οὐδ’ αὐτὸ τοῦτο περιμείναντες ἕως τοῦ γνῶναι πότερον ἀντερῶν ἢ συνηγορήσων πάρεστι τοῖς περὶ τὸν Σπένδιον, παραχρῆμα βάλλοντες τοῖς λίθοις ἀπέκτεινον. καὶ πολλοὺς δὴ τῷ τοιούτῳ τρόπῳ κατὰ τὰς συνδρομὰς καὶ τῶν ἡγεμόνων καὶ τῶν ἰδιωτῶν διέφθειρον. καὶ μόνον τὸ ῥῆμα τοῦτο κοινῇ συνίεσαν τὸ βάλλε διὰ τὸ συνεχῶς αὐτὸ πράττειν. μάλιστα δὲ τοῦτ’ ἐποίουν, ὁπότε μεθυσθέντες ἀπὸ τῶν ἀρίστων συνδράμοιεν. διόπερ ὅτε τις ἄρξαιτο βάλλε λέγειν, οὕτως ἐγίνετο πανταχόθεν ἅμα καὶ ταχέως ὥστε μηδένα δύνασθαι διαφυγεῖν τῶν ἅπαξ προελθόντων. πλὴν οὐδενὸς ἔτι τολμῶντος συμβουλεύειν διὰ ταύτην τὴν αἰτίαν, κατέστησαν αὑτῶν στρατηγοὺς Μάθω καὶ Σπένδιον.", "st": "1.69"}, {"sp": "N", "t": "ὁ δὲ Γέσκων ἑώρα μὲν τὴν ὅλην ἀκαταστασίαν καὶ ταραχήν, περὶ πλείστου δὲ ποιούμενος τὸ τῇ πατρίδι συμφέρον καὶ θεωρῶν ὅτι τούτων ἀποθηριωθέντων κινδυνεύουσι προφανῶς οἱ Καρχηδόνιοι τοῖς ὅλοις πράγμασι, παρεβάλλετο καὶ προσεκαρτέρει, ποτὲ μὲν τοὺς προεστῶτας αὐτῶν εἰς τὰς χεῖρας λαμβάνων, ποτὲ δὲ κατὰ γένη συναθροίζων καὶ παρακαλῶν. οὐ μὴν ἀλλὰ τῶν Λιβύων οὐδέπω κεκομισμένων τὰς σιταρχίας, οἰομένων δὲ δεῖν ἀποδεδόσθαι σφίσι καὶ προσιόντων θρασέως, βουλόμενος ὁ Γέσκων ἐπιπλῆξαι τὴν προπέτειαν αὐτῶν, Μάθω τὸν στρατηγὸν ἀπαιτεῖν ἐκέλευεν. οἱ δ’ ἐπὶ τοσοῦτον διωργίσθησαν ὥστ’ οὐδὲ τὸν τυχόντα χρόνον ἀναστροφὴν δόντες ὥρμησαν τὸ μὲν πρῶτον ἐπὶ τὸ διαρπάζειν τὰ πρόχειρα τῶν χρημάτων, μετὰ δὲ ταῦτα συλλαμβάνειν τόν τε Γέσκωνα καὶ τοὺς μετ’ αὐτοῦ Καρχηδονίους. οἱ δὲ περὶ τὸν Μάθω καὶ τὸν Σπένδιον ὑπολαμβάνοντες τάχιστ’ ἂν οὕτως ἐκκαυθῆναι τὸν πόλεμον, εἰ παράνομόν τι πράξειαν καὶ παράσπονδον, συνήργουν ταῖς τῶν ὄχλων ἀπονοίαις καὶ τὴν μὲν ἀποσκευὴν τῶν Καρχηδονίων ἅμα τοῖς χρήμασι διήρπαζον, τὸν δὲ Γέσκωνα καὶ τοὺς σὺν αὐτῷ δήσαντες ὑβριστικῶς εἰς φυλακὴν παρεδίδοσαν. καὶ τὸ λοιπὸν ἐπολέμουν ἤδη φανερῶς πρὸς τοὺς Καρχηδονίους, συνωμοσίας ἀσεβεῖς καὶ παρὰ τὰ κοινὰ τῶν ἀνθρώπων ἔθη ποιησάμενοι. ὁ μὲν οὖν πρὸς τοὺς ξένους καὶ Λιβυκὸς ἐπικληθεὶς πόλεμος διὰ ταῦτα καὶ τοιαύτην ἔλαβε τὴν ἀρχήν. οἱ δὲ περὶ τὸν Μάθω συντελεσάμενοι τὰ προειρημένα παραυτίκα μὲν ἐξαπέστελλον πρέσβεις ἐπὶ τὰς κατὰ τὴν Λιβύην πόλεις, παρακαλοῦντες ἐπὶ τὴν ἐλευθερίαν καὶ δεόμενοι σφίσι βοηθεῖν καὶ συνεπιλαμβάνεσθαι τῶν πραγμάτων. μετὰ δὲ ταῦτα πάντων σχεδὸν τῶν κατὰ τὴν Λιβύην ἑτοίμως συνυπακουσάντων αὐτοῖς πρὸς τὴν ἀπὸ τῶν Καρχηδονίων ἀπόστασιν καὶ τάς τε χορηγίας καὶ τὰς βοηθείας προθύμως ἐξαποστελλόντων, διελόντες σφᾶς πολιορκεῖν ἐνεχείρησαν οἱ μὲν τὴν Ἰτύκην, οἱ δὲ τοὺς Ἱππακρίτας, διὰ τὸ ταύτας τὰς πόλεις μὴ βούλεσθαι μετασχεῖν αὐτοῖς τῆς ἀποστάσεως.", "st": "1.70"}, {"sp": "N", "t": "Καρχηδόνιοι δὲ τοὺς μὲν κατ’ ἰδίαν βίους ἀεὶ διεξαγαγόντες ἀπὸ τῶν ἐκ τῆς χώρας γεννημάτων, τὰς δὲ κοινὰς παρασκευὰς καὶ χορηγίας ἁθροίζοντες ἐκ τῶν κατὰ τὴν Λιβύην προσόδων, ἔτι δὲ πολεμεῖν εἰθισμένοι ξενικαῖς δυνάμεσι, τότε πάντων ἅμα τούτων οὐ μόνον ἐστερημένοι παραλόγως, ἀλλὰ καὶ καθ’ αὑτῶν ὁρῶντες ἕκαστα τῶν προειρημένων ἐπιστρέφοντα, τελέως ἐν μεγάλῃ δυσθυμίᾳ καὶ δυσελπιστίᾳ καθέστασαν, ἅτε παρὰ τὴν προσδοκίαν αὐτοῖς τῶν πραγμάτων ἀποβεβηκότων. τετρυμένοι γὰρ ἐν τῷ περὶ Σικελίας πολέμῳ συνεχῶς ἤλπιζον ἐπιτελεσθεισῶν τῶν διαλύσεων ἀναπνοῆς τινος τεύξεσθαι καὶ καταστάσεως εὐδοκουμένης. συνέβαινε δ’ αὐτοῖς τἀναντία· μείζονος γὰρ ἐνίστατο πολέμου καταρχὴ καὶ φοβερωτέρου. πρόσθεν μὲν γὰρ ὑπὲρ Σικελίας ἠμφισβήτουν Ῥωμαίοις, τότε δὲ περὶ σφῶν αὐτῶν καὶ τῆς πατρίδος ἔμελλον κινδυνεύσειν, πόλεμον ἀναλαμβάνοντες ἐμφύλιον. πρὸς δὲ τούτοις οὐχ ὅπλων πλῆθος, οὐ ναυτικὴ δύναμις, οὐ πλοίων κατασκευὴ παρ’ αὐτοῖς ἦν, ὡς ἂν τοσαύταις ναυμαχίαις περιπεπτωκότων· καὶ μὴν οὐδὲ χορηγιῶν διάθεσις οὐδὲ φίλων οὐδὲ συμμάχων τῶν βοηθησόντων ἔξωθεν ἐλπὶς οὐδ’ ἡτισοῦν ὑπῆρχεν. διὸ καὶ τότε σαφῶς ἔγνωσαν ἡλίκην ἔχει διαφορὰν ξενικὸς καὶ διαπόντιος πόλεμος ἐμφυλίου στάσεως καὶ ταραχῆς. οὐχ ἥκιστα δ’ αὐτοὶ σφίσι τῶν τοιούτων καὶ τηλικούτων κακῶν ἐγεγόνεισαν αἴτιοι.", "st": "1.71"}, {"sp": "N", "t": "κατὰ γὰρ τὸν προγεγονότα πόλεμον εὐλόγους ἀφορμὰς ἔχειν ὑπολαμβάνοντες πικρῶς ἐπεστάτησαν τῶν κατὰ τὴν Λιβύην ἀνθρώπων, παραιρούμενοι μὲν τῶν ἄλλων πάντων τῶν καρπῶν τοὺς ἡμίσεις, διπλασίους δὲ ταῖς πόλεσι τοὺς φόρους ἢ πρὶν ἐπιτάττοντες, συγγνώμην δὲ τοῖς ἀπόροις ἢ συμπεριφορὰν οὐδ’ ἡντινοῦν ἐπ’ οὐδενὶ τῶν πραττομένων διδόντες, θαυμάζοντες δὲ καὶ τιμῶντες τῶν ἀεὶ στρατηγῶν οὐ τοὺς πρᾴως καὶ φιλανθρώπως τῷ πλήθει χρωμένους, ἀλλὰ τοὺς αὐτοῖς μὲν ἑτοιμάζοντας πλείστας χορηγίας καὶ ἐπισκευάς, τοῖς δὲ κατὰ τὴν χώραν πικρότατα χρωμένους, ὧν εἷς ἦν Ἄννων. τοιγαροῦν οἱ μὲν ἄνδρες οὐχ οἷον παρακλήσεως πρὸς τὴν ἀπόστασιν, ἀλλ’ ἀγγέλου μόνον ἐδεήθησαν· αἱ δὲ γυναῖκες αἱ τὸν πρὸ τοῦ χρόνον ἀπαγομένους περιορῶσαι τοὺς σφετέρους ἄνδρας καὶ γονεῖς πρὸς τὰς εἰσφοράς, τότε συνομνύουσαι κατὰ πόλεις ἐφ’ ᾧ μηδὲν κρύψειν τῶν ὑπαρχόντων αὐταῖς, ἀφαιρούμεναι τὸν κόσμον εἰσέφερον ἀπροφασίστως εἰς τοὺς ὀψωνιασμούς. καὶ τοιαύτην παρεσκεύασαν εὐπορίαν τοῖς περὶ τὸν Μάθω καὶ Σπένδιον ὥστε μὴ μόνον διαλῦσαι τὰ προσοφειλόμενα τῶν ὀψωνίων τοῖς μισθοφόροις κατὰ τὰς ἐπαγγελίας, ἃς ἐποιήσαντο πρὸς τὴν ἀπόστασιν, ἀλλὰ καὶ πρὸς τὸ συνεχὲς εὐπορῆσαι χορηγίας. οὕτως οὐδέποτε δεῖ πρὸς τὸ παρὸν μόνον, ἔτι δὲ μᾶλλον πρὸς τὸ μέλλον ἀποβλέπειν ἀεὶ τοὺς ὀρθῶς βουλευομένους.", "st": "1.72"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καίπερ ἐν τοιούτοις κακοῖς ὄντες οἱ Καρχηδόνιοι, προστησάμενοι τὸν Ἄννωνα στρατηγὸν διὰ τὸ δοκεῖν τοῦτον καὶ πρότερον αὐτοῖς τὰ κατὰ τὴν Ἑκατοντάπυλον τῆς Λιβύης καταστρέψασθαι, συνήθροιζον μὲν μισθοφόρους, καθώπλιζον δὲ τοὺς ἐν ταῖς ἡλικίαις τῶν πολιτῶν· ἐγύμναζον δὲ καὶ συνέταττον τοὺς πολιτικοὺς ἱππεῖς· παρεσκεύαζον δὲ καὶ τὰ περιλιπῆ τῶν πλοίων, τριήρεις καὶ πεντηκοντόρους καὶ τὰ μέγιστα τῶν ἀκατίων. οἱ δὲ περὶ τὸν Μάθω, παραγενομένων αὐτοῖς εἰς ἑπτὰ μυριάδας Λιβύων, ἐπιδιελόντες τούτους, ἀσφαλῶς ἐπολιόρκουν τοὺς Ἰτυκαίους καὶ τοὺς Ἱππακρίτας, βεβαίως δὲ τὴν ἐν τῷ Τύνητι στρατοπεδείαν κατεῖχον, ἀποκεκλείκεσαν δὲ τοὺς Καρχηδονίους ἁπάσης τῆς ἐκτὸς Λιβύης. ἡ γὰρ Καρχηδὼν αὐτὴ μὲν ἐν κόλπῳ κεῖται, προτείνουσα καὶ χερρονησίζουσα τῇ θέσει, τὸ μὲν τῇ θαλάττῃ τὸ δέ τι καὶ λίμνῃ περιεχομένη κατὰ τὸ πλεῖστον· ὁ δὲ συνάπτων ἰσθμὸς αὐτὴν τῇ Λιβύῃ τὸ πλάτος ὡς εἴκοσι καὶ πέντε σταδίων ἐστιν. τούτου δ’ ἐπὶ μὲν τοῦ πρὸς τὸ πέλαγος νεύοντος μέρους οὐ μακρὰν ἡ τῶν Ἰτυκαίων κεῖται πόλις, ἐπὶ δὲ θατέρου παρὰ τὴν λίμνην ὁ Τύνης. ἐφ’ ὧν ἑκατέρων τότε στρατοπεδεύσαντες οἱ μισθοφόροι καὶ διακλείσαντες ἀπὸ τῆς χώρας τοὺς Καρχηδονίους λοιπὸν ἐπεβούλευον αὐτῇ τῇ πόλει, καὶ ποτὲ μὲν ἡμέρας, ποτὲ δὲ καὶ νύκτωρ παραγινόμενοι πρὸς τὸ τεῖχος εἰς φόβους καὶ θορύβους ὁλοσχερεῖς ἐνέβαλλον τοὺς ἔνδον.", "st": "1.73"}, {"sp": "N", "t": "Ἄννων δὲ περὶ μὲν τὰς παρασκευὰς ἐνδεχομένως ἐγίνετο· καὶ γὰρ ἦν πρὸς τοῦτο τὸ μέρος εὐφυής· ἐξορμήσας δὲ μετὰ τῆς δυνάμεως ἕτερος ἦν· καὶ γὰρ τοῖς καιροῖς ἀστόχως ἐχρῆτο καὶ τοῖς ὅλοις πράγμασιν ἀπείρως καὶ νωθρῶς. διὸ καὶ τὸ μὲν πρῶτον εἰς Ἰτύκην παραβοηθήσας τοῖς πολιορκουμένοις καὶ καταπληξάμενος τοὺς ὑπεναντίους τῷ πλήθει τῶν θηρίων· εἶχεν γὰρ οὐκ ἐλάττους ἑκατὸν ἐλεφάντων· καὶ μετὰ ταῦτα λαβὼν προτερήματος ἀρχὴν ὁλοσχεροῦς οὕτως ἐχρήσατο κακῶς ὥστε κινδυνεῦσαι προσαπολέσαι καὶ τοὺς πολιορκουμένους. κομίσας γὰρ ἐκ τῆς πόλεως τοὺς καταπέλτας καὶ τὰ βέλη καὶ συλλήβδην ἁπάσας τὰς πρὸς τὴν πολιορκίαν παρασκευὰς καὶ στρατοπεδεύσας πρὸ τῆς πόλεως ἐνεχείρησε προσβάλλειν πρὸς τὸν τῶν ὑπεναντίων χάρακα. τῶν δὲ θηρίων βιασαμένων εἰς τὴν παρεμβολήν, οὐ δυνάμενοι τὸ βάρος οὐδὲ τὴν ἔφοδον οἱ πολέμιοι μεῖναι πάντες ἐξέπεσον ἐκ τῆς στρατοπεδείας. καὶ πολλοὶ μὲν αὐτῶν ἀπέθανον τρωθέντες ὑπὸ τῶν θηρίων, τὸ δὲ διασῳζόμενον μέρος πρός τινα λόφον ἐρυμνὸν καὶ σύμφυτον ἔμενεν, πιστεῦον ταῖς ἐξ αὐτῶν τῶν τόπων ἀσφαλείαις. ὁ δ’ Ἄννων εἰθισμένος Νομάσι καὶ Λίβυσι πολεμεῖν, οἵτινες ὅταν ἅπαξ ἐγκλίνωσι ποιοῦνται τὴν φυγὴν ἐπὶ δύ’ ἡμέρας καὶ τρεῖς ἐκτοπίζοντες αὑτούς, ὑπολαβὼν καὶ τότε πέρας ἔχειν τοῦ πολέμου καὶ νενικηκέναι τοῖς ὅλοις, τῶν μὲν στρατιωτῶν ὠλιγώρησε καὶ καθόλου τῆς παρεμβολῆς, αὐτὸς δ’ εἰσελθὼν εἰς τὴν πόλιν ἐγίνετο περὶ τὴν τοῦ σώματος θεραπείαν. οἱ δὲ συμπεφευγότες τῶν μισθοφόρων εἰς τὸν λόφον, σύντροφοι μὲν γεγονότες τῆς Βάρκα τόλμης, συνήθεις δ’ ἐκ τῶν κατὰ Σικελίαν ἀγώνων πολλάκις τῆς αὐτῆς ἡμέρας ποτὲ μὲν ὑποχωρεῖν, ποτὲ δὲ πάλιν ἐκ μεταβολῆς ἐγχειρεῖν τοῖς πολεμίοις, καὶ τότε συνιδόντες τὸν μὲν στρατηγὸν ἀπηλλαγμένον εἰς τὴν πόλιν, τοὺς δὲ πολλοὺς διὰ τὸ προτέρημα ῥᾳθυμοῦντας καὶ διαρρέοντας ἐκ τῆς στρατοπεδείας, συστραφέντες ἐπιτίθενται τῷ χάρακι καὶ πολλοὺς μὲν αὐτῶν ἀπέκτειναν, τοὺς δὲ λοιποὺς ἠνάγκασαν φυγεῖν αἰσχρῶς ὑπὸ τὰ τείχη καὶ τὰς πύλας· ἐκυρίευσαν δὲ τῆς ἀποσκευῆς ἁπάσης καὶ τῆς τῶν πολιορκουμένων παρασκευῆς, ἣν Ἄννων πρὸς τοῖς ἄλλοις ἐκκομίσας ἐκ τῆς πόλεως ἐποίησε τοῖς ἐχθροῖς ὑποχείριον. οὐ μόνον δὲ περὶ τοῦτον τὸν καιρὸν οὕτως ἀνεστράφη νωθρῶς, ἀλλὰ καὶ μετ’ ὀλίγας ἡμέρας περὶ τὴν καλουμένην Γόρζαν ἀντιστρατοπεδευσάντων αὐτῷ τῶν πολεμίων, λαβὼν καιροὺς δὶς μὲν ἐκ παρατάξεως εἰς τὸ νικᾶν δὶς δ’ ἐξ ἐπιθέσεως, ἅτε καὶ στρατοπεδευόντων σύνεγγυς αὐτῷ τῶν ὑπεναντίων, ἀμφοτέρους δοκεῖ τούτους εἰκῇ καὶ παραλόγως προέσθαι.", "st": "1.74"}, {"sp": "N", "t": "διόπερ οἱ Καρχηδόνιοι θεωροῦντες αὐτὸν κακῶς χειρίζοντα τὰς πράξεις, Ἀμίλκαν τὸν ἐπικαλούμενον Βάρκαν αὖθις προεστήσαντο, καὶ τοῦτον ἐξέπεμπον εἰς τὸν ἐνεστῶτα πόλεμον στρατηγόν, δόντες ἑβδομήκοντα μὲν ἐλέφαντας καὶ τοὺς ἐπισυνηγμένους τῶν μισθοφόρων καὶ τοὺς ηὐτομοληκότας ἀπὸ τῶν πολεμίων, ἅμα δὲ τούτοις πολιτικοὺς ἱππεῖς καὶ πεζούς, ὥστε τοὺς σύμπαντας εἰς μυρίους ὑπάρχειν. ὃς κατὰ τὴν πρώτην εὐθέως ἔξοδον καταπληξάμενος τῷ παραδόξῳ τῆς ἐπιβολῆς ἥττησε μὲν τὰς ψυχὰς τῶν ὑπεναντίων, ἔλυσε δὲ τὴν τῆς Ἰτύκης πολιορκίαν, ἐφάνη δ’ ἄξιος τῶν προγεγονότων ἔργων καὶ τῆς παρὰ τῷ πλήθει προσδοκίας. τὸ δὲ πραχθὲν ἦν ὑπ’ αὐτοῦ περὶ τὴν χρείαν ταύτην τοιοῦτον. τῶν γεωλόφων τῶν ἐπιζευγνύντων τὸν αὐχένα τὸν συνάπτοντα τὴν Καρχηδόνα πρὸς τὴν Λιβύην ὄντων δυσβάτων καὶ χειροποιήτους ἐχόντων διεκβολὰς ἐπὶ τὴν χώραν, συνέβαινε τοὺς περὶ τὸν Μάθω πάντας τοὺς διὰ τῶν προειρημένων λόφων εὐκαίρως κειμένους τόπους φυλακαῖς διειληφέναι, πρὸς δὲ τούτοις τοῦ προσαγορευομένου Μακάρα ποταμοῦ διείργοντος κατά τινας τόπους παραπλησίως τὴν ἐπὶ τὴν χώραν τοῖς ἐκ τῆς πόλεως ἔξοδον καὶ διὰ τὸ πλῆθος τοῦ ῥεύματος ἀβάτου κατὰ τὸ πλεῖστον ὑπάρχοντος, μιᾶς δ’ οὔσης ἐπ’ αὐτῷ γεφύρας, καὶ ταύτην τηρεῖν τὴν δίοδον ἀσφαλῶς, πόλιν ἐπ’ αὐτῆς ᾠκοδομηκότας. ἐξ ὧν συνέβαινε τοὺς Καρχηδονίους μὴ οἷον στρατοπέδῳ τῆς χώρας ἐπιβαίνειν, ἀλλὰ μηδὲ τοὺς κατ’ ἰδίαν θέλοντας διαπεσεῖν ῥᾳδίως ἂν δύνασθαι λαθεῖν τοὺς ὑπεναντίους. εἰς ἃ βλέπων Ἀμίλκας καὶ παντὸς πράγματος καὶ καιροῦ πεῖραν λαμβάνων διὰ τὸ δυσχρηστεῖν περὶ τὴν ἔξοδον διενοήθη τι τοιοῦτον. τοῦ προειρημένου ποταμοῦ κατὰ τὴν εἰς θάλατταν ἐκβολὴν συνθεωρήσας κατά τινας ἀνέμων στάσεις ἀποθινούμενον τὸ στόμα καὶ τεναγώδη γινομένην τὴν παρ’ αὐτὸ τὸ στόμα πάροδον, ποιήσας εὐτρεπῆ τῷ στρατοπέδῳ τὰ πρὸς τὴν ἔξοδον καὶ κρύπτων ἐν αὑτῷ τὴν ἐπιβολὴν ἐτήρει τὸ προειρημένον σύμπτωμα. παραπεσόντος δὲ τοῦ καιροῦ, νυκτὸς ἐξορμήσας ἔλαθε πάντας ἅμα τῷ φωτὶ τὸν προειρημένον τόπον διαβιβάσας τὴν δύναμιν. παραδόξου δὲ τοῦ πράγματος φανέντος καὶ τοῖς ἐν τῇ πόλει καὶ τοῖς ὑπεναντίοις, ὁ μὲν Ἀμίλκας προῆγεν διὰ τοῦ πεδίου, ποιούμενος τὴν πορείαν ἐπὶ τοὺς τὴν γέφυραν φυλάττοντας.", "st": "1.75"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Σπένδιον συνέντες τὸ γεγονὸς ἀπήντων εἰς τὸ πεδίον καὶ παρεβοήθουν ἀλλήλοις, οἱ μὲν ἐκ τῆς περὶ τὴν γέφυραν πόλεως ὄντες οὐκ ἐλάττους μυρίων, οἱ δ’ ἀπὸ τῆς Ἰτύκης ὑπὲρ τοὺς μυρίους καὶ πεντακισχιλίους. ἐπεὶ δ’ εἰς σύνοπτον ἧκον ἀλλήλοις, νομίσαντες ἐν μέσῳ τοὺς Καρχηδονίους ἀπειληφέναι, σπουδῇ παρηγγύων ἅμα παρακαλοῦντες σφᾶς αὐτοὺς καὶ συνῆπτον τοῖς πολεμίοις. ὁ δ’ Ἀμίλκας ἦγε μὲν τὴν πορείαν πρώτους ἔχων τοὺς ἐλέφαντας, ἐπὶ δὲ τούτοις τοὺς ἱππεῖς καὶ τοὺς εὐζώνους, τελευταῖα δὲ τὰ βαρέα τῶν ὅπλων. κατιδὼν δὲ προχειρότερον ἐπιφερομένους τοὺς ὑπεναντίους, ἀναστρέφειν παρήγγειλε πᾶσι τοῖς ἑαυτοῦ. καὶ τοὺς μὲν ἀπὸ τῆς πρωτοπορείας ἀναστρέψαντας σπουδῇ ποιεῖσθαι τὴν ἀποχώρησιν ἐκέλευσε· τοὺς δ’ ἐπὶ τῆς οὐραγίας ἐξ ἀρχῆς ὑπάρχοντας ἐξ ἐπιστροφῆς περισπῶν ἐξέταττε πρὸς τὴν τῶν πολεμίων ἐπιφάνειαν. οἱ δὲ Λίβυες καὶ μισθοφόροι νομίσαντες αὐτοὺς καταπεπληγμένους φυγεῖν, λύσαντες τὴν τάξιν ἐπέκειντο καὶ συνῆπτον εἰς τὰς χεῖρας ἐρρωμένως. ἅμα δὲ τῷ τοὺς ἱππεῖς συνεγγίσαντας τοῖς παρατεταγμένοις ἐκ μεταβολῆς ὑποστῆναι, τὴν δὲ λοιπὴν δύναμιν ἐπάγειν, ἐκπλαγεῖς γινόμενοι διὰ τὸ παράδοξον οἱ Λίβυες ἐγκλίναντες εὐθέως ἔφευγον, ὡς ἂν εἰκῇ καὶ σποράδην ἐπικείμενοι. λοιπὸν οἱ μὲν τοῖς κατόπιν ἐπιφερομένοις περιπίπτοντες ἐσφάλλοντο καὶ διέφθειρον αὑτούς τε καὶ τοὺς οἰκείους· οἱ δὲ πλείους συνεπατήθησαν, ἐκ χειρὸς τῶν ἱππέων ἐπικειμένων αὐτοῖς καὶ τῶν θηρίων. ἀπώλοντο μὲν οὖν εἰς ἑξακισχιλίους τῶν Λιβύων καὶ τῶν ξένων, ἑάλωσαν δὲ περὶ δισχιλίους· οἱ δὲ λοιποὶ διέφυγον, οἱ μὲν εἰς τὴν πρὸς τῇ γεφύρᾳ πόλιν, οἱ δ’ ἐπὶ τὴν πρὸς Ἰτύκῃ παρεμβολήν. Ἀμίλκας δὲ ποιήσας τὸ προτέρημα τὸν προειρημένον τρόπον, εἵπετο κατὰ πόδας τοῖς πολεμίοις καὶ τὴν μὲν ἐπὶ τῆς γεφύρας πόλιν ἐξ ἐφόδου κατέσχεν, προεμένων καὶ φευγόντων εἰς τὸν Τύνητα τῶν ἐν αὐτῇ πολεμίων, τὴν δὲ λοιπὴν χώραν ἐπιπορευόμενος τὰς μὲν προσήγετο, πλείστας δὲ κατὰ κράτος ἐξῄρει. τοῖς δὲ Καρχηδονίοις βραχύ τι θάρσους ἐνειργάσατο καὶ τόλμης, ἐπὶ ποσὸν αὐτοὺς ἀπαλλάξας τῆς προγεγενημένης δυσελπιστίας.", "st": "1.76"}, {"sp": "N", "t": "ὁ δὲ Μάθως αὐτὸς μὲν ἐπὶ τῆς τῶν Ἱππακριτῶν πολιορκίας ἐπέμενεν, τοῖς δὲ περὶ τὸν Αὐτάριτον τὸν τῶν Γαλατῶν ἡγεμόνα καὶ Σπένδιον ἔχεσθαι τῶν ὑπεναντίων συνεβούλευε, τὰ μὲν πεδία φεύγοντας διὰ τὸ πλῆθος τῶν παρὰ τοῖς ὑπεναντίοις ἱππέων καὶ θηρίων, ταῖς δ’ ὑπωρείαις ἀντιπαράγοντας καὶ συνεπιτιθεμένους κατὰ τὰς ὑποπιπτούσας ἀεὶ δυσχερείας. ἅμα δὲ ταῖς ἐπινοίαις ταύταις καὶ πρὸς τοὺς Νομάδας καὶ τοὺς Λίβυας ἐξέπεμπε, δεόμενος βοηθεῖν σφίσι καὶ μὴ καταπροΐεσθαι τοὺς ὑπὲρ τῆς ἐλευθερίας καιρούς. ὁ δὲ Σπένδιος προσλαβὼν ἐκ τοῦ Τύνητος ἀφ’ ἑκάστου τῶν γενῶν τοὺς πάντας εἰς ἑξακισχιλίους προῆγε, ταῖς ὑπωρείαις ἀντιπαράγων τοῖς Καρχηδονίοις, ἔχων ἅμα τοῖς προειρημένοις καὶ τοὺς μετ’ Αὐταρίτου Γαλάτας, ὄντας εἰς δισχιλίους. τὸ γὰρ λοιπὸν μέρος αὐτῶν τοῦ κατ’ ἀρχὰς συστήματος ηὐτομολήκει πρὸς τοὺς Ῥωμαίους ἐν ταῖς περὶ τὸν Ἔρυκα στρατοπεδείαις. τοῦ δ’ Ἀμίλκου παρεμβεβληκότος ἔν τινι πεδίῳ πανταχόθεν ὄρεσι περιεχομένῳ, συνέβη τὰς παρὰ τῶν Νομάδων καὶ Λιβύων βοηθείας εἰς τὸν καιρὸν τοῦτον συνάψαι τοῖς περὶ τὸν Σπένδιον. γενομένης δὲ τοῖς Καρχηδονίοις τῆς μὲν τῶν Λιβύων ἐπιστρατοπεδείας αἰφνιδίου καὶ κατὰ πρόσωπον, τῆς δὲ τῶν Νομάδων ἀπ’ οὐρᾶς, τῆς δὲ περὶ τὸν Σπένδιον ἐκ πλαγίου, μεγάλην αὐτοῖς ἀπορίαν συνέβη περιστῆναι καὶ δυσέκφευκτον.", "st": "1.77"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον Ναραύας, ὃς ἦν μὲν Νομὰς τῶν ἐνδοξοτάτων εἷς, ἦν δὲ καὶ πλήρης ὁρμῆς πολεμικῆς, οὗτος ἀεὶ μὲν οἰκείως διέκειτο πρὸς τοὺς Καρχηδονίους πατρικὴν ἔχων σύστασιν, τότε δὲ μᾶλλον παρωρμήθη διὰ τὴν Ἀμίλκου τοῦ στρατηγοῦ καταξίωσιν. διὸ καὶ νομίσας ἔχειν εὐφυῆ καιρὸν πρὸς ἔντευξιν αὐτῷ καὶ σύστασιν, ἧκεν εἰς τὴν στρατοπεδείαν ἔχων περὶ αὑτὸν Νομάδας εἰς ἑκατόν. καὶ συνεγγίσας τῷ χάρακι τολμηρῶς ἔμενε, κατασείων τῇ χειρί. τοῦ δ’ Ἀμίλκου θαυμάσαντος τὴν ἐπιβολὴν καὶ προπέμψαντός τινα τῶν ἱππέων, εἰς λόγους ἔφη βούλεσθαι συνελθεῖν τῷ στρατηγῷ. διαποροῦντος δ’ ἀκμὴν καὶ διαπιστοῦντος τοῦ τῶν Καρχηδονίων ἡγεμόνος, παραδοὺς ὁ Ναραύας τὸν ἵππον καὶ τὰς λόγχας τοῖς μεθ’ αὑτοῦ παρῆν ἄνοπλος εὐθαρσῶς εἰς τὴν παρεμβολήν. οἱ δὲ τὰ μὲν ἐθαύμαζον, τὰ δὲ κατεπλήττοντο τὴν τόλμαν· ὅμως δὲ προσεδέξαντο καὶ συνῆλθον εἰς τὰς χεῖρας. ὁ δὲ παραγενόμενος εἰς λόγους ἔφη πᾶσι μὲν Καρχηδονίοις εὐνοεῖν, μάλιστα δ’ ἐπιθυμεῖν Βάρκᾳ γενέσθαι φίλος· διὸ καὶ νῦν παρεῖναι συσταθησόμενος αὐτῷ καὶ κοινωνήσων ἀδόλως παντὸς ἔργου καὶ πάσης ἐπιβολῆς. Ἀμίλκας δὲ ταῦτ’ ἀκούσας οὕτως ἥσθη μεγάλως ἐπί τε τῷ κατὰ τὴν παρουσίαν θάρσει καὶ τῇ κατὰ τὴν ἔντευξιν ἁπλότητι τοῦ νεανίσκου, ὡς οὐ μόνον εὐδόκησε κοινωνὸν αὐτὸν προσλαβέσθαι τῶν πράξεων, ἀλλὰ καὶ τὴν θυγατέρα δώσειν ἐπηγγείλατο μεθ’ ὅρκου, διαφυλάξαντος αὐτοῦ τὴν πρὸς Καρχηδονίους πίστιν. γενομένων δὲ τῶν ὁμολογιῶν, ὁ μὲν Ναραύας ἧκε τοὺς ὑφ’ αὑτὸν τεταγμένους ἔχων Νομάδας, ὄντας εἰς δισχιλίους, ὁ δ’ Ἀμίλκας προσγενομένης αὐτῷ τῆς χειρὸς ταύτης παρετάξατο τοῖς πολεμίοις. οἱ δὲ περὶ τὸν Σπένδιον συνάψαντες ἐπὶ ταὐτὸ τοῖς Λίβυσι καὶ καταβάντες εἰς τὸ πεδίον συνέβαλλον τοῖς Καρχηδονίοις. γενομένης δὲ μάχης ἰσχυρᾶς ἐνίκων οἱ περὶ τὸν Ἀμίλκαν, καλῶς μὲν τῶν θηρίων ἀγωνισαμένων, ἐπιφανεστάτην δὲ τοῦ Ναραύα παρασχομένου χρείαν. ὁ μὲν οὖν Αὐτάριτος καὶ Σπένδιος διέφυγον, τῶν δὲ λοιπῶν ἔπεσον μὲν εἰς μυρίους, ἑάλωσαν δ’ εἰς τετρακισχιλίους. ἐπιτελεσθέντος δὲ τοῦ κατορθώματος, Ἀμίλκας τοῖς μὲν βουλομένοις τῶν αἰχμαλώτων μεθ’ ἑαυτοῦ συστρατεύειν ἐξουσίαν ἔδωκε καὶ καθώπλιζε τοῖς ἀπὸ τῶν πολεμίων σκύλοις, τοὺς δὲ μὴ βουλομένους ἁθροίσας παρεκάλει φάσκων, ἕως μὲν τοῦ νῦν συγγνώμην αὐτοῖς ἔχειν τῶν ἡμαρτημένων· διὸ καὶ συγχωρεῖν τρέπεσθαι κατὰ τὰς ἰδίας ὁρμὰς οὗ ποτ’ ἂν ἕκαστος αὐτῶν προαιρῆται. μετὰ δὲ ταῦτα διηπειλήσατο μηθένα φέρειν ὅπλον πολέμιον κατ’ αὐτῶν, ὡς, ἐὰν ἁλῷ τις, ἀπαραιτήτου τευξόμενον τιμωρίας.", "st": "1.78"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς οἱ τὴν Σαρδόνα [τὴν νῆσον] παραφυλάττοντες τῶν μισθοφόρων, ζηλώσαντες τοὺς περὶ τὸν Μάθω καὶ Σπένδιον, ἐπιτίθενται τοῖς ἐν τῇ νήσῳ Καρχηδονίοις. καὶ τὸν μὲν τότε παρ’ αὐτοῖς ὄντα βοήθαρχον Βώσταρον συγκλείσαντες εἰς τὴν ἀκρόπολιν μετὰ τῶν ἑαυτοῦ πολιτῶν ἀπέκτειναν. αὖθις δὲ τῶν Καρχηδονίων στρατηγὸν ἐξαποστειλάντων μετὰ δυνάμεως Ἄννωνα, κἄπειτα καὶ τούτων τῶν δυνάμεων ἐγκαταλιπουσῶν τὸν Ἄννωνα καὶ μεταθεμένων πρὸς σφᾶς, γενόμενοι ζωγρίᾳ κύριοι τοῦ προειρημένου, παραυτίκα τοῦτον μὲν ἀνεσταύρωσαν, μετὰ δὲ ταῦτα παρηλλαγμένας ἐπινοοῦντες τιμωρίας πάντας τοὺς ἐν τῇ νήσῳ Καρχηδονίους στρεβλοῦντες ἀπέκτειναν· καὶ τὸ λοιπὸν ἤδη ποιησάμενοι τὰς πόλεις ὑφ’ ἑαυτοὺς εἶχον ἐγκρατῶς τὴν νῆσον, ἕως οὗ στασιάσαντες πρὸς τοὺς Σαρδονίους ἐξέπεσον ὑπ’ ἐκείνων εἰς τὴν Ἰταλίαν. ἡ μὲν οὖν Σαρδὼ τοῦτον τὸν τρόπον ἀπηλλοτριώθη Καρχηδονίων, νῆσος καὶ τῷ μεγέθει καὶ τῇ πολυανθρωπίᾳ καὶ τοῖς γεννήμασι διαφέρουσα. τῷ δὲ πολλοὺς καὶ πολὺν ὑπὲρ αὐτῆς πεποιῆσθαι λόγον οὐκ ἀναγκαῖον ἡγούμεθ’ εἶναι ταυτολογεῖν ὑπὲρ τῶν ὁμολογουμένων. Μάθως δὲ καὶ Σπένδιος, ἅμα δὲ τούτοις Αὐτάριτος ὁ Γαλάτης ὑπιδόμενοι τὴν Ἀμίλκου φιλανθρωπίαν εἰς τοὺς αἰχμαλώτους καὶ φοβηθέντες μὴ τῷ τοιούτῳ τρόπῳ ψυχαγωγηθέντες ὁρμήσωσι πρὸς τὴν ὑποδεικνυμένην ἀσφάλειαν οἵ τε Λίβυες καὶ τὸ τῶν μισθοφόρων πλῆθος, ἐβουλεύοντο πῶς ἂν καινοτομήσαντές τι τῶν πρὸς ἀσέβειαν εἰς τέλος ἀποθηριώσειαν τὰ πλήθη πρὸς τοὺς Καρχηδονίους. ἔδοξεν οὖν αὐτοῖς συναθροῖσαι τοὺς πολλούς. γενομένου δὲ τούτου γραμματοφόρον εἰσήγαγον, ὡς ἀπεσταλμένον ὑπὸ τῶν ἐκ τῆς Σαρδόνος αἱρετιστῶν. ἡ δ’ ἐπιστολὴ διεσάφει τόν τε Γέσκωνα καὶ τοὺς μετ’ αὐτοῦ πάντας, οὓς παρεσπόνδησαν ἐν τῷ Τύνητι, καθάπερ ἐπάνω προεῖπον, φυλάττειν ἐπιμελῶς, ὡς πραττόντων τινῶν ἐκ τοῦ στρατοπέδου τοῖς Καρχηδονίοις ὑπὲρ τῆς τούτων σωτηρίας. λαβόμενος δὲ τῆς ἀφορμῆς ταύτης ὁ Σπένδιος πρῶτον μὲν παρεκάλει μὴ πιστεύειν τὴν ὑπὸ τοῦ στρατηγοῦ τοῦ τῶν Καρχηδονίων γεγενημένην φιλανθρωπίαν πρὸς τοὺς αἰχμαλώτους· οὐ γὰρ σῶσαι προαιρούμενον αὐτὸν ταῦτα βεβουλεῦσθαι περὶ τῶν ἁλόντων, ἀλλὰ διὰ τῆς ἐκείνων ἀφέσεως ἡμῶν ἐγκρατῆ γενέσθαι σπουδάζοντα, πρὸς τὸ μὴ τινὰς ἀλλὰ πάντας ἡμᾶς ἅμα τιμωρήσασθαι πιστεύσαντας αὐτῷ. πρὸς δὲ τούτοις φυλάττεσθαι παρῄνει μὴ προέμενοι τοὺς περὶ τὸν Γέσκωνα καταφρονηθῶσι μὲν ὑπὸ τῶν ἐχθρῶν, μεγάλα δὲ βλάψωσι τὰς ἰδίας πράξεις, ἄνδρα τοιοῦτον καὶ στρατηγὸν ἀγαθὸν ἐάσαντες διαφυγεῖν, ὃν εἰκὸς ἐχθρὸν αὐτοῖς ἔσεσθαι φοβερώτατον. ἔτι δὲ ταῦτα λέγοντος αὐτοῦ παρῆν ἄλλος γραμματοφόρος, ὡς ἀπὸ τῶν ἐκ τοῦ Τύνητος ἀπεσταλμένος, παραπλήσια τοῖς ἐκ τῆς Σαρδόνος διασαφῶν.", "st": "1.79"}, {"sp": "N", "t": "ἐφ’ ὃν Αὐτάριτος ὁ Γαλάτης ἐπιβαλὼν μίαν ἔφη σωτηρίαν εἶναι τοῖς ἑαυτῶν πράγμασι τὸ πάσας ἀπογνῶναι τὰς ἐν Καρχηδονίοις ἐλπίδας· ἕως δ’ ἂν ἀντέχηταί τις τῆς ἐκείνων φιλανθρωπίας, οὐ δυνατὸν αὐτοῖς ἀληθινὸν γενέσθαι τὸν τοιοῦτον σύμμαχον. διόπερ ἠξίου τούτοις πιστεύειν, τούτοις ἀκούειν, τοῖς τοιούτοις προσέχειν τὸν νοῦν, οἵτινες ἂν ἀεί τι τῶν ἀπεχθεστάτων καὶ πικροτάτων εἰσαγγέλλωσι κατὰ Καρχηδονίων· τοὺς δ’ ἐναντία τούτοις λέγοντας προδότας καὶ πολεμίους ἡγεῖσθαι παρῄνει. ταῦτα δ’ εἰπὼν συνεβούλευε τόν τε Γέσκωνα καὶ τοὺς μετ’ αὐτοῦ συλληφθέντας καὶ τοὺς ὕστερον γενομένους αἰχμαλώτους τῶν Καρχηδονίων αἰκισαμένους ἀποκτεῖναι. πρακτικώτατος δ’ ἦν οὗτος ἐν ταῖς συμβουλίαις διὰ τὸ πολλοὺς τὴν φωνὴν αὐτοῦ συνιέναι. πάλαι γὰρ στρατευόμενος ᾔδει διαλέγεσθαι Φοινικιστί· ταύτῃ δέ πως οἱ πλεῖστοι συνεσαίνοντο τῇ διαλέκτῳ διὰ τὸ μῆκος τῆς προγεγενημένης στρατείας. διόπερ ἐπαινέσαντος αὐτὸν ὁμοθυμαδὸν τοῦ πλήθους, οὗτος μὲν εὐδοκιμῶν ἀνεχώρησεν. πολλῶν δὲ προπορευομένων ἀφ’ ἑκάστου γένους ἅμα καὶ βουλομένων αὐτὴν παραιτεῖσθαι τὴν αἰκίαν διὰ τὰς γεγενημένας ἐκ τοῦ Γέσκωνος εἰς αὐτοὺς εὐεργεσίας, οὔτε μὴν τῶν λεγομένων οὐθὲν ἦν συνετόν, ὡς ἂν ἅμα πολλῶν, ἑκάστου δὲ κατὰ τὴν ἰδίαν διάλεκτον συμβουλεύοντος· ἐπεὶ δὲ καὶ παρεγυμνώθη διότι τὴν τιμωρίαν παραιτοῦνται, καί τις ἐκ τῶν καθημένων εἶπεν βάλλε, πάντας ἅμα κατέλευσαν τοὺς προπορευθέντας. καὶ τούτους μὲν ὥσπερ ὑπὸ θηρίων διεφθαρμένους ἐξέφερον οἱ προσήκοντες. τοὺς δὲ περὶ τὸν Γέσκωνα λαβόντες, ὄντας εἰς ἑπτακοσίους, ἦγον ἐκ τοῦ χάρακος οἱ περὶ τὸν Σπένδιον· καὶ προαγαγόντες βραχὺ πρὸ τῆς στρατοπεδείας πρῶτον μὲν ἀπέκοπτον τὰς χεῖρας, ποιούμενοι τὴν ἀρχὴν ἀπὸ τοῦ Γέσκωνος, ὃν βραχεῖ χρόνῳ πρότερον ἐκ πάντων Καρχηδονίων προκρίναντες ἀνέδειξαν μὲν εὐεργέτην αὑτῶν, ἐπέτρεψαν δὲ περὶ τῶν ἀμφισβητουμένων. ἐπειδὴ δὲ τὰς χεῖρας ἀπέκοψαν, ἠκρωτηρίαζον τοὺς ταλαιπώρους· κολοβώσαντες δὲ καὶ τὰ σκέλη συντρίψαντες ἔτι ζῶντας ἔρριψαν εἴς τινα τάφρον.", "st": "1.80"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι τοῦ δυστυχήματος αὐτοῖς ἀναγγελθέντος ποιεῖν μὲν οὐδὲν εἶχον, ἐσχετλίαζον δὲ καὶ περιπαθεῖς γινόμενοι τῇ συμφορᾷ πρὸς μὲν Ἀμίλκαν καὶ τὸν ἕτερον τῶν στρατηγῶν Ἄννωνα πρεσβευτὰς ἐξέπεμπον, δεόμενοι βοηθεῖν καὶ τιμωρεῖν τοῖς ἠτυχηκόσι. πρὸς δὲ τοὺς ἠσεβηκότας κήρυκας ἐξαπέστελλον περὶ τῆς τῶν νεκρῶν ἀναιρέσεως. οἱ δ’ οὔτ’ ἔδοσαν, προεῖπόν τε τοῖς παροῦσιν μήτε κήρυκα πέμπειν πρὸς σφᾶς μήτε πρεσβευτήν, ὡς τῆς αὐτῆς κολάσεως ὑπομενούσης τοὺς παραγενομένους ἧς νῦν Γέσκων τέτευχε. πρὸς δὲ τὸ λοιπὸν ἐδογματοποίησαν καὶ παρῄνεσαν αὑτοῖς, ὃν μὲν ἂν λάβωσιν Καρχηδονίων, τιμωρησαμένους ἀποκτείνειν· ὃν δ’ ἂν τῶν συμμαχούντων αὐτοῖς, ἀποκόψαντας τὰς χεῖρας αὖθις εἰς Καρχηδόν’ ἀποπέμπειν. ὃ δὴ καὶ διετέλεσαν ἐπιμελῶς ποιοῦντες. διόπερ εἰς ταῦτα βλέπων οὐκ ἄν τις εἰπεῖν ὀκνήσειεν ὡς οὐ μόνον τὰ σώματα τῶν ἀνθρώπων καί τινα τῶν ἐν αὐτοῖς γεννωμένων ἑλκῶν καὶ φυμάτων ἀποθηριοῦσθαι συμβαίνει καὶ τελέως ἀβοήθητα γίνεσθαι, πολὺ δὲ μάλιστα τὰς ψυχάς. ἐπί τε γὰρ τῶν ἑλκῶν, ἐὰν μὲν θεραπείαν τοῖς τοιούτοις προσάγῃ τις, ὑπ’ αὐτῆς ἐνίοτε ταύτης ἐρεθιζόμενα θᾶττον ποιεῖται τὴν νομήν· ἐὰν δὲ πάλιν ἀφῇ, κατὰ τὴν ἐξ αὑτῶν φύσιν φθείροντα τὸ συνεχὲς οὐκ ἴσχει παῦλαν, ἕως ἂν ἀφανίσῃ τὸ ὑποκείμενον· ταῖς τε ψυχαῖς παραπλησίως τοιαῦται πολλάκις ἐπιφύονται μελανίαι καὶ σηπεδόνες ὥστε μηδὲν ἀσεβέστερον ἀνθρώπου μηδ’ ὠμότερον ἀποτελεῖσθαι τῶν ζῴων. οἷς ἐὰν μὲν συγγνώμην τινὰ προσάγῃς καὶ φιλανθρωπίαν, ἐπιβουλὴν καὶ παραλογισμὸν ἡγούμενοι τὸ συμβαῖνον ἀπιστότεροι καὶ δυσμενέστεροι γίνονται πρὸς τοὺς φιλανθρωποῦντας· ἐὰν δ’ ἀντιτιμωρῇ, διαμιλλώμενοι τοῖς θυμοῖς οὐκ ἔστι τι τῶν ἀπειρημένων ἢ δεινῶν ὁποῖον οὐκ ἀναδέχονται, σὺν καλῷ τιθέμενοι τὴν τοιαύτην τόλμαν· τέλος δ’ ἀποθηριωθέντες ἐξέστησαν τῆς ἀνθρωπίνης φύσεως. τῆς δὲ διαθέσεως ἀρχηγὸν μὲν καὶ μεγίστην μερίδα νομιστέον ἔθη μοχθηρὰ καὶ τροφὴν ἐκ παίδων κακήν, συνεργὰ δὲ καὶ πλείω, μέγιστα δὲ τῶν συνεργῶν τὰς ἀεὶ τῶν προεστώτων ὕβρεις καὶ πλεονεξίας. ἃ δὴ τότε συνέβαινε καὶ περὶ μὲν τὸ σύστημα τῶν μισθοφόρων, ἔτι δὲ μᾶλλον περὶ τοὺς ἡγεμόνας αὐτῶν ὑπάρχειν.", "st": "1.81"}, {"sp": "N", "t": "Ἀμίλκας δὲ δυσχρηστούμενος τῇ τῶν πολεμίων ἀπονοίᾳ τὸν μὲν Ἄννωνα πρὸς ἑαυτὸν ἐκάλει, πεπεισμένος ἁθροισθέντων ὁμοῦ τῶν στρατοπέδων θᾶττον ἐπιθήσειν τέλος τοῖς ὅλοις. τῶν δὲ πολεμίων οὕς ποτε κρατήσειε, τοὺς μὲν ἐν χειρῶν νόμῳ διέφθειρεν, τοὺς δὲ ζωγρίᾳ πρὸς αὐτὸν εἰσαναχθέντας ὑπέβαλλε τοῖς θηρίοις, μίαν ὁρῶν λύσιν ταύτην, εἰ δυνηθείη τοὺς ἐχθροὺς ἄρδην ἀφανίσαι. δοκούντων δὲ τῶν Καρχηδονίων ἐπικυδεστέρας ἐλπίδας ἔχειν ἤδη κατὰ τὸν πόλεμον, γίνεταί τις ὁλοσχερὴς καὶ παράδοξος περὶ αὐτοὺς παλίρροια τῶν πραγμάτων. οἵ τε γὰρ στρατηγοὶ συνελθόντες ἐπὶ ταὐτὸ διεστασίασαν πρὸς σφᾶς ἐπὶ τοσοῦτον ὥστε μὴ μόνον τοὺς κατὰ τῶν ἐχθρῶν παραλείπειν καιρούς, ἀλλὰ καὶ κατὰ σφῶν αὐτῶν πολλὰς ἀφορμὰς διδόναι τοῖς ὑπεναντίοις διὰ τὴν πρὸς ἀλλήλους φιλονικίαν. ἃ δὴ καὶ συνέντες οἱ Καρχηδόνιοι τῷ μὲν ἑνὶ τῶν στρατηγῶν ἀπαλλάττεσθαι προσέταξαν, τῷ δ’ ἑτέρῳ μένειν, ὃν ἂν αἱ δυνάμεις προκρίνωσιν. ἅμα δὲ τούτοις καὶ τὰς παρακομιζομένας ἀγορὰς ἐκ τῶν παρ’ αὐτοῖς καλουμένων Ἐμπορίων, ἐφ’ αἷς εἶχον τὰς μεγίστας ἐλπίδας περί τε τῆς τροφῆς καὶ τῶν ἄλλων ἐπιτηδείων, διαφθαρῆναι συνέβη κατὰ θάλατταν ὁλοσχερῶς ὑπὸ χειμῶνος. τὰ δὲ κατὰ τὴν Σαρδόνα, καθάπερ ἐπάνω προεῖπον, ἐτύγχανεν ἀπηλλοτριωμένα, μεγάλας αὐτοῖς αἰεί ποτε χρείας παρεχομένης τῆς νήσου ταύτης κατὰ τὰς περιστάσεις. τὸ δὲ μέγιστον, ἡ τῶν Ἱππακριτῶν καὶ τῶν Ἰτυκαίων ἀπέστη πόλις, αἵτινες ἐτύγχανον μόναι τῶν κατὰ τὴν Λιβύην οὐ μόνον τὸν ἐνεστῶτα πόλεμον ἀναδεδεγμέναι γενναίως, ἀλλὰ καὶ τοὺς κατ’ Ἀγαθοκλέα καιροὺς καὶ τὴν Ῥωμαίων ἔφοδον εὐγενῶς ὑπομεμενηκυῖαι καὶ συλλήβδην οὐδέποτε βεβουλευμέναι Καρχηδονίοις οὐδὲν ὑπεναντίον. τότε δὲ χωρὶς τῆς ἀλόγου πρὸς τοὺς Λίβυας ἀποστάσεως καὶ διὰ τῆς μεταθέσεως εὐθέως τούτοις μὲν τὴν μεγίστην οἰκειότητα καὶ πίστιν ἐναπεδείξαντο, πρὸς δὲ τοὺς Καρχηδονίους ἀπαραίτητον ὀργὴν ἐνεστήσαντο καὶ μῖσος. τοὺς μὲν γὰρ παραβεβοηθηκότας αὐτοῖς παρ’ ἐκείνων, ὄντας εἰς πεντακοσίους, καὶ τὸν ἡγεμόνα τούτων ἀποκτείναντες ἅπαντας ἔρριψαν κατὰ τοῦ τείχους, τὴν δὲ πόλιν ἐνεχείρισαν τοῖς Λίβυσι· τοῖς γε μὴν Καρχηδονίοις οὐδὲ θάψαι συνεχώρησαν τοὺς ἠτυχηκότας αἰτουμένοις. τούτων δὲ συμβαινόντων οἱ μὲν περὶ τὸν Μάθω καὶ Σπένδιον ἐπαρθέντες τοῖς συμβεβηκόσιν πολιορκεῖν ἐνεχείρησαν αὐτὴν τὴν Καρχηδόνα. Βάρκας δὲ παραλαβὼν Ἀννίβαν τὸν στρατηγόν· τοῦτον γὰρ ἐξαπέστειλαν οἱ πολῖται πρὸς τὰς δυνάμεις, ἐπεὶ τὸν Ἄννωνα τὸ στρατόπεδον ἔκρινε δεῖν ἀπαλλάττεσθαι κατὰ τὴν ὑπὸ τῶν Καρχηδονίων αὐτοῖς δοθεῖσαν ἐπιτροπὴν περὶ τὰς γενομένας τῶν στρατηγῶν στάσεις πρὸς ἀλλήλους· διόπερ Ἀμίλκας ἔχων τοῦτόν τε καὶ Ναραύαν ἐπῄει τὴν χώραν, διακλείων τὰς χορηγίας τοῖς περὶ τὸν Μάθω καὶ Σπένδιον, μεγίστην αὐτῷ παρεχομένου χρείαν περί τε ταῦτα καὶ τἄλλα Ναραύα τοῦ Νομάδος. τὰ μὲν οὖν περὶ τὰς ὑπαίθρους δυνάμεις ἐν τούτοις ἦν.", "st": "1.82"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι περικλειόμενοι πανταχόθεν ἠναγκάζοντο καταφεύγειν ἐπὶ τὰς συμμαχίδων πόλεων ἐλπίδας. Ἱέρων δ’ ἀεὶ μέν ποτε κατὰ τὸν ἐνεστῶτα πόλεμον μεγάλην ἐποιεῖτο σπουδὴν εἰς πᾶν τὸ παρακαλούμενον ὑπ’ αὐτῶν, τότε δὲ καὶ μᾶλλον ἐφιλοτιμεῖτο, πεπεισμένος συμφέρειν ἑαυτῷ καὶ πρὸς τὴν ἐν Σικελίᾳ δυναστείαν καὶ πρὸς τὴν Ῥωμαίων φιλίαν τὸ σῴζεσθαι Καρχηδονίους, ἵνα μὴ παντάπασιν ἐξῇ τὸ προτεθὲν ἀκονιτὶ συντελεῖσθαι τοῖς ἰσχύουσι, πάνυ φρονίμως καὶ νουνεχῶς λογιζόμενος. οὐδέποτε γὰρ χρὴ τὰ τοιαῦτα παρορᾶν οὐδὲ τηλικαύτην οὐδενὶ συγκατασκευάζειν δυναστείαν, πρὸς ἣν οὐδὲ περὶ τῶν ὁμολογουμένων ἐξέσται δικαίων ἀμφισβητεῖν. οὐ μὴν ἀλλὰ καὶ Ῥωμαῖοι τηροῦντες τὰ κατὰ τὰς συνθήκας δίκαια προθυμίας οὐδὲν ἀπέλειπον. ἐν ἀρχαῖς μὲν γὰρ ἐγένετό τις ἀμφισβήτησις ἐξ ἀμφοῖν διά τινας τοιαύτας αἰτίας. τῶν Καρχηδονίων τοὺς πλέοντας ἐξ Ἰταλίας εἰς Λιβύην καὶ χορηγοῦντας τοῖς πολεμίοις καταγόντων ὡς αὑτούς, καὶ σχεδὸν ἁθροισθέντων τούτων εἰς τὴν φυλακὴν εἰς τοὺς πεντακοσίους, ἠγανάκτησαν οἱ Ῥωμαῖοι. μετὰ δὲ ταῦτα διαπρεσβευσάμενοι καὶ κομισάμενοι διὰ λόγου πάντας ἐπὶ τοσοῦτον εὐδόκησαν ὥστε παραχρῆμα τοῖς Καρχηδονίοις ἀντιδωρήσασθαι τοὺς ὑπολειπομένους παρ’ αὐτοῖς αἰχμαλώτους ἐκ τοῦ περὶ Σικελίαν πολέμου. ἀπὸ δὲ τούτου τοῦ καιροῦ πρὸς ἕκαστα τῶν παρακαλουμένων ἑτοίμως καὶ φιλανθρώπως ὑπήκουον. διὸ καὶ πρὸς μὲν τοὺς Καρχηδονίους ἐπέτρεψαν τοῖς ἐμπόροις ἐξαγαγεῖν αἰεὶ τὸ κατεπεῖγον, πρὸς δὲ τοὺς πολεμίους ἐκώλυσαν. μετὰ δὲ ταῦτα τῶν μὲν ἐν τῇ Σαρδόνι μισθοφόρων, καθ’ ὃν καιρὸν ἀπὸ τῶν Καρχηδονίων ἀπέστησαν, ἐπισπωμένων αὐτοὺς ἐπὶ τὴν νῆσον οὐχ ὑπήκουσαν· τῶν δ’ Ἰτυκαίων ἐγχειριζόντων σφᾶς, οὐ προσεδέξαντο, τηροῦντες τὰ κατὰ τὰς συνθήκας δίκαια. Καρχηδόνιοι μὲν οὖν τῆς παρὰ τῶν προειρημένων φίλων τυγχάνοντες ἐπικουρίας ὑπέμενον τὴν πολιορκίαν.", "st": "1.83"}, {"sp": "N", "t": "τοῖς δὲ περὶ τὸν Μάθω καὶ Σπένδιον οὐχ ἧττον πολιορκεῖσθαι συνέβαινεν ἢ πολιορκεῖν. εἰς τοιαύτην γὰρ αὐτοὺς οἱ περὶ τὸν Ἀμίλκαν ἔνδειαν καθίστασαν τῶν ἐπιτηδείων ὥστ’ ἀναγκασθῆναι τέλος αὐτοὺς διαλῦσαι τὴν πολιορκίαν. μετὰ δέ τινα χρόνον ἁθροίσαντες τῶν τε μισθοφόρων τοὺς ἀρίστους καὶ Λιβύων, τοὺς ἅπαντας εἰς πεντακισμυρίους, μεθ’ ὧν ἦν καὶ Ζάρζας ὁ Λίβυς ἔχων τοὺς ὑφ’ αὑτὸν ταττομένους, ὥρμησαν αὖθις ἀντιπαράγειν ἐν τοῖς ὑπαίθροις καὶ τηρεῖν τοὺς περὶ τὸν Ἀμίλκαν. τῶν μὲν οὖν πεδινῶν τόπων ἀπείχοντο, καταπεπληγμένοι τὰ θηρία καὶ τοὺς περὶ τὸν Ναραύαν ἱππεῖς, τοὺς δ’ ὀρεινοὺς καὶ στενοὺς ἐπειρῶντο προκαταλαμβάνειν. ἐν οἷς καιροῖς συνέβη ταῖς μὲν ἐπιβολαῖς καὶ τόλμαις μηδὲν αὐτοὺς λείπεσθαι τῶν ὑπεναντίων, διὰ δὲ τὴν ἀπειρίαν πολλάκις ἐλαττοῦσθαι. τότε γὰρ ἦν, ὡς ἔοικε, συνιδεῖν ἐπ’ αὐτῆς τῆς ἀληθείας πηλίκην ἔχει διαφορὰν ἐμπειρία μεθοδικὴ καὶ στρατηγικὴ δύναμις ἀπειρίας καὶ τριβῆς ἀλόγου καὶ στρατιωτικῆς. πολλοὺς μὲν γὰρ αὐτῶν ἐν ταῖς κατὰ μέρος χρείαις ἀποτεμνόμενος καὶ συγκλείων ὥσπερ ἀγαθὸς πεττευτὴς ἀμαχεὶ διέφθειρε, πολλοὺς δ’ ἐν τοῖς ὁλοσχερέσι κινδύνοις τοὺς μὲν εἰς ἐνέδρας ἀνυπονοήτους ἐπαγόμενος ἀνῄρει, τοῖς δ’ ἀνελπίστως καὶ παραδόξως ποτὲ μὲν μεθ’ ἡμέραν ποτὲ δὲ νύκτωρ ἐπιφαινόμενος ἐξέπληττεν· ὧν ὅσους λάβοι ζωγρίᾳ, πάντας παρέβαλλε τοῖς θηρίοις. τέλος δ’ ἐπιστρατοπεδεύσας αὐτοῖς ἀνυπονοήτως ἐν τόποις ἀφυέσι μὲν πρὸς τὴν ἐκείνων χρείαν εὐφυέσι δὲ πρὸς τὴν ἑαυτοῦ δύναμιν εἰς τοῦτ’ ἤγαγε περιστάσεως ὥστε μήτε διακινδυνεύειν τολμῶντας μήτ’ ἀποδρᾶναι δυναμένους διὰ τὸ τάφρῳ καὶ χάρακι περιειλῆφθαι πανταχόθεν τέλος ὑπὸ τῆς λιμοῦ συναγομένους ἐσθίειν ἀλλήλων ἀναγκασθῆναι, τοῦ δαιμονίου τὴν οἰκείαν ἀμοιβὴν αὐτοῖς ἐπιφέροντος τῇ πρὸς τοὺς πέλας ἀσεβείᾳ καὶ παρανομίᾳ. πρὸς μὲν γὰρ τὸν κίνδυνον οὐκ ἐτόλμων ἐξιέναι, προδήλου τῆς ἥττης καὶ τῆς τιμωρίας τοῖς ἁλισκομένοις ὑπαρχούσης, περὶ δὲ διαλύσεως οὐδ’ ὑπενόουν ποιεῖσθαι μνήμην, συνειδότες σφίσι τὰ πεπραγμένα. προσανέχοντες δ’ ἀεὶ ταῖς ἐκ τοῦ Τύνητος βοηθείαις διὰ τὰς τῶν ἡγουμένων ἐπαγγελίας πᾶν ὑπέμενον ποιεῖν κατὰ σφῶν αὐτῶν.", "st": "1.84"}, {"sp": "N", "t": "ἐπεὶ δὲ κατεχρήσαντο μὲν ἀσεβῶς τοὺς αἰχμαλώτους, τροφῇ ταύτῃ χρώμενοι, κατεχρήσαντο δὲ τὰ δουλικὰ τῶν σωμάτων, ἐβοήθει δ’ ἐκ τοῦ Τύνητος οὐδείς, τότε προδήλου τῆς αἰκίας διὰ τὴν περικάκησιν ἐκ τῶν πολλῶν τοῖς ἡγεμόσιν ὑπαρχούσης, ἔκριναν οἱ περὶ τὸν Αὐτάριτον καὶ Ζάρζαν καὶ Σπένδιον ἐγχειρίζειν ἑαυτοὺς τοῖς πολεμίοις καὶ διαλαλεῖν περὶ διαλύσεως Ἀμίλκᾳ. πέμψαντες οὖν κήρυκα καὶ λαβόντες συγχώρημα περὶ πρεσβείας ἧκον, ὄντες δέκα, πρὸς τοὺς Καρχηδονίους. πρὸς οὓς Ἀμίλκας ὁμολογίας ἐποιήσατο τοιαύτας· ἐξεῖναι Καρχηδονίοις ἐκλέξασθαι τῶν πολεμίων οὓς ἂν αὐτοὶ βούλωνται δέκα· τοὺς δὲ λοιποὺς ἀφιέναι μετὰ χιτῶνος. γενομένων δὲ τούτων εὐθέως Ἀμίλκας ἔφη τοὺς παρόντας ἐκλέγεσθαι κατὰ τὰς ὁμολογίας. τῶν μὲν οὖν περὶ τὸν Αὐτάριτον καὶ Σπένδιον καὶ τῶν ἄλλων τῶν ἐπιφανεστάτων ἡγεμόνων τοῦτον τὸν τρόπον ἐκυρίευσαν οἱ Καρχηδόνιοι. τῶν δὲ Λιβύων, ἐπεὶ τὴν σύλληψιν ᾔσθοντο τῶν ἡγεμόνων, νομισάντων αὑτοὺς παρεσπονδῆσθαι διὰ τὸ τὰς συνθήκας ἀγνοεῖν, καὶ διὰ ταύτην τὴν αἰτίαν ὁρμησάντων ἐπὶ τὰ ὅπλα, περιστήσας αὐτοῖς Ἀμίλκας τά τε θηρία καὶ τὴν λοιπὴν δύναμιν ἅπαντας διέφθειρε, πλείους ὄντας τῶν τετρακισμυρίων, περὶ τὸν τόπον τὸν Πρίονα καλούμενον· ὃν συμβαίνει διὰ τὴν ὁμοιότητα τοῦ σχήματος πρὸς τὸ νῦν εἰρημένον ὄργανον ταύτης τετευχέναι τῆς προσηγορίας.", "st": "1.85"}, {"sp": "N", "t": "πράξας δὲ τὰ προδεδηλωμένα τοῖς μὲν Καρχηδονίοις αὖθις ἐλπίδα παρέστησε μεγάλην πρὸς τὸ βέλτιον, καίπερ ἀπεγνωκόσιν ἤδη τὴν σωτηρίαν· αὐτὸς δὲ μετὰ Ναραύα καὶ μετ’ Ἀννίβου τὴν χώραν ἐπῄει καὶ τὰς πόλεις. προσχωρούντων δὲ καὶ μετατιθεμένων πρὸς αὐτοὺς τῶν Λιβύων διὰ τὸ γεγονὸς εὐτύχημα, ποιησάμενοι τὰς πλείστας πόλεις ὑφ’ ἑαυτοὺς ἧκον ἐπὶ τὸν Τύνητα καὶ πολιορκεῖν ἐνεχείρησαν τοὺς περὶ τὸν Μάθω. κατὰ μὲν οὖν τὴν ἀπὸ Καρχηδόνος πλευρὰν προσεστρατοπέδευσεν Ἀννίβας, κατὰ δὲ τὴν ἀπέναντι ταύτης Ἀμίλκας. μετὰ δὲ ταῦτα προσαγαγόντες πρὸς τὰ τείχη τοὺς περὶ τὸν Σπένδιον αἰχμαλώτους ἐσταύρωσαν ἐπιφανῶς. οἱ δὲ περὶ τὸν Μάθω κατανοήσαντες τὸν Ἀννίβαν ῥᾳθύμως καὶ κατατεθαρρηκότως ἀναστρεφόμενον, ἐπιθέμενοι τῷ χάρακι πολλοὺς μὲν τῶν Καρχηδονίων ἀπέκτειναν, πάντας δ’ ἐξέβαλον ἐκ τῆς στρατοπεδείας, ἐκυρίευσαν δὲ καὶ τῆς ἀποσκευῆς ἁπάσης, ἔλαβον δὲ καὶ τὸν στρατηγὸν Ἀννίβαν ζωγρίᾳ. τοῦτον μὲν οὖν παραχρῆμα πρὸς τὸν τοῦ Σπενδίου σταυρὸν ἀγαγόντες καὶ τιμωρησάμενοι πικρῶς ἐκεῖνον μὲν καθεῖλον, τοῦτον δ’ ἀνέθεσαν ζῶντα καὶ περικατέσφαξαν τριάκοντα τῶν Καρχηδονίων τοὺς ἐπιφανεστάτους περὶ τὸ τοῦ Σπενδίου σῶμα, τῆς τύχης ὥσπερ ἐπίτηδες ἐκ παραθέσεως ἀμφοτέροις ἐναλλὰξ διδούσης ἀφορμὰς εἰς ὑπερβολὴν τῆς κατ’ ἀλλήλων τιμωρίας. ὁ δὲ Βάρκας ὀψὲ μὲν συνῆκε τὴν ἐπίθεσιν τῶν ἐκ τῆς πόλεως διὰ τὴν ἀπόστασιν τῶν στρατοπέδων· οὐδὲ μὴν συνεὶς οὐδ’ οὕτως κατετάχει πρὸς τὴν βοήθειαν διὰ τὰς μεταξὺ δυσχωρίας. διόπερ ἀναζεύξας ἀπὸ τοῦ Τύνητος καὶ παρελθὼν ἐπὶ τὸν Μακάραν ποταμὸν κατεστρατοπέδευσε πρὸς τῷ στόματι τοῦ ποταμοῦ καὶ τῇ θαλάττῃ.", "st": "1.86"}, {"sp": "N", "t": "οἱ δὲ Καρχηδόνιοι παραδόξου τῆς περιπετείας αὐτοῖς φανείσης δυσθύμως καὶ δυσελπίστως εἶχον πάλιν· ἄρτι γὰρ ἀναθαρροῦντες ταῖς ψυχαῖς παρὰ πόδας ἔπιπτον αὖθις ταῖς ἐλπίσιν. οὐ μὴν ἀφίσταντο τοῦ ποιεῖν τὰ πρὸς τὴν σωτηρίαν. διὸ καὶ τριάκοντα μὲν τῆς γερουσίας προχειρισάμενοι καὶ μετὰ τούτων τὸν πρότερον μὲν ἀπελθόντα στρατηγὸν Ἄννωνα, τότε δ’ ἐπαναγαγόντα, σὺν δὲ τούτοις τοὺς ὑπολοίπους τῶν ἐν ταῖς ἡλικίαις καθοπλίσαντες, οἷον ἐσχάτην τρέχοντες ταύτην, ἐξαπέστελλον πρὸς τὸν Βάρκαν, ἐντειλάμενοι πολλὰ τοῖς τῆς γερουσίας κατὰ πάντα τρόπον διαλῦσαι τοὺς στρατηγοὺς ἐκ τῆς προγεγενημένης διαφορᾶς καὶ συμφρονεῖν σφᾶς ἀναγκάσαι, βλέψαντας εἰς τὰ παρόντα τῶν πραγμάτων. ὧν πολλοὺς καὶ ποικίλους διαθεμένων λόγους, ἐπειδὴ συνήγαγον ὁμόσε τοὺς στρατηγούς, ἠναγκάσθησαν συγχωρεῖν καὶ πείθεσθαι τοῖς λεγομένοις οἱ περὶ τὸν Ἄννωνα καὶ τὸν Βάρκαν, καὶ τὸ λοιπὸν ἤδη συμφρονήσαντες μιᾷ γνώμῃ πάντα κατὰ νοῦν ἔπραττον τοῖς Καρχηδονίοις, ὥστε τοὺς περὶ τὸν Μάθω δυσχρηστουμένους ἐν τοῖς κατὰ μέρος κινδύνοις — πολλοὺς γὰρ ἐποιήσαντο περί τε τὴν Λέπτιν προσαγορευομένην καί τινας τῶν ἄλλων πόλεων — τέλος ἐπὶ τὸ διὰ μάχης κρίνειν ὁρμῆσαι τὰ πράγματα, προθύμως ἐχόντων πρὸς τοῦτο τὸ μέρος καὶ τῶν Καρχηδονίων. διόπερ ἀμφότεροι τοῦτο προθέμενοι παρεκάλουν μὲν πάντας τοὺς συμμάχους πρὸς τὸν κίνδυνον, συνῆγον δὲ τὰς φρουρὰς ἐκ τῶν πόλεων, ὡς ἂν μέλλοντες ἐκκυβεύειν ὑπὲρ τῶν ὅλων. ἐπειδὴ δ’ ἑκατέροις ἦν τὰ πρὸς τὴν ἐπιβολὴν ἕτοιμα, παραταξάμενοι συνέβαλλον ἀλλήλοις ἐξ ὁμολόγου. γενομένου δὲ τοῦ νικήματος κατὰ τοὺς Καρχηδονίους, οἱ μὲν πλεῖστοι τῶν Λιβύων ἐν αὐτῷ τῷ κινδύνῳ διεφθάρησαν, οἱ δὲ πρός τινα πόλιν συμφυγόντες μετ’ οὐ πολὺ παρέδοσαν ἑαυτούς, ὁ δὲ Μάθως ὑποχείριος ἐγένετο τοῖς ἐχθροῖς ζωγρίᾳ.", "st": "1.87"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα μέρη τῆς Λιβύης μετὰ τὴν μάχην εὐθέως ὑπήκουσε τοῖς Καρχηδονίοις· ἡ δὲ τῶν Ἱππακριτῶν καὶ τῶν Ἰτυκαίων πόλις ἔμενον, οὐδεμίαν ἀφορμὴν ἔχουσαι πρὸς διάλυσιν διὰ τὸ μὴ καταλείπεσθαι σφίσι τόπον ἐλέους μηδὲ συγγνώμης κατὰ τὰς πρώτας ἐπιβολάς. οὕτως καὶ κατὰ ταύτας τὰς ἁμαρτίας μεγάλην ἔχει διαφορὰν ἡ μετριότης καὶ τὸ μηδὲν ἀνήκεστον ἐπιτηδεύειν ἑκουσίως. οὐ μὴν ἀλλὰ παραστρατοπεδεύσαντες ᾗ μὲν Ἄννων ᾗ δὲ Βάρκας ταχέως ἠνάγκασαν αὐτοὺς ὁμολογίας ποιήσασθαι καὶ διαλύσεις εὐδοκουμένας Καρχηδονίοις. ὁ μὲν οὖν Λιβυκὸς πόλεμος εἰς τοιαύτην ἀγαγὼν περίστασιν Καρχηδονίους τοιοῦτον ἔσχε τὸ τέλος ὥστε μὴ μόνον κυριεῦσαι πάλιν τῆς Λιβύης τοὺς Καρχηδονίους, ἀλλὰ καὶ τοὺς αἰτίους τῆς ἀποστάσεως τιμωρήσασθαι καταξίως· τὸ γὰρ πέρας, ἀγαγόντες οἱ νέοι τὸν θρίαμβον διὰ τῆς πόλεως πᾶσαν αἰκίαν ἐναπεδείξαντο τοῖς περὶ τὸν Μάθω. τρία μὲν οὖν ἔτη καὶ τέτταράς που μῆνας ἐπολέμησαν οἱ μισθοφόροι πρὸς τοὺς Καρχηδονίους πόλεμον, ὧν ἡμεῖς ἴσμεν ἀκοῇ μαθόντες, πολύ τι τοὺς ἄλλους ὠμότητι καὶ παρανομίᾳ διενηνοχότα. Ῥωμαῖοι δὲ κατὰ τὸν καιρὸν τοῦτον ὑπὸ τῶν ἐκ τῆς Σαρδόνος αὐτομολησάντων μισθοφόρων πρὸς σφᾶς ἐκκληθέντες ἐπεβάλοντο πλεῖν ἐπὶ τὴν προειρημένην νῆσον. τῶν δὲ Καρχηδονίων ἀγανακτούντων, ὡς αὐτοῖς καθηκούσης μᾶλλον τῆς τῶν Σαρδῴων δυναστείας, καὶ παρασκευαζομένων μεταπορεύεσθαι τοὺς ἀποστήσαντας αὐτῶν τὴν νῆσον, λαβόμενοι τῆς ἀφορμῆς ταύτης οἱ Ῥωμαῖοι πόλεμον ἐψηφίσαντο πρὸς τοὺς Καρχηδονίους, φάσκοντες αὐτοὺς οὐκ ἐπὶ Σαρδονίους, ἀλλ’ ἐπὶ σφᾶς ποιεῖσθαι τὴν παρασκευήν. οἱ δὲ παραδόξως διαπεφευγότες τὸν προειρημένον πόλεμον, κατὰ πάντα τρόπον ἀφυῶς διακείμενοι κατὰ τὸ παρὸν πρὸς τὸ πάλιν ἀναλαμβάνειν τὴν πρὸς Ῥωμαίους ἀπέχθειαν, εἴξαντες τοῖς καιροῖς οὐ μόνον ἀπέστησαν τῆς Σαρδόνος, ἀλλὰ καὶ χίλια τάλαντα καὶ διακόσια προσέθηκαν τοῖς Ῥωμαίοις ἐφ’ ᾧ μὴ κατὰ τὸ παρὸν ἀναδέξασθαι τὸν πόλεμον. ταῦτα μὲν οὕτως ἐπράχθη.", "st": "1.88"}, {"sp": "HDR", "t": "Βιβλίον Βʹ", "st": "2"}, {"sp": "N", "t": "ἐν μὲν τῇ πρὸ ταύτης βύβλῳ διεσαφήσαμεν πότε Ῥωμαῖοι συστησάμενοι τὰ κατὰ τὴν Ἰταλίαν τοῖς ἐκτὸς ἐγχειρεῖν ἤρξαντο πράγμασιν, ἐπὶ δὲ τούτοις πῶς εἰς Σικελίαν διέβησαν καὶ δι’ ἃς αἰτίας τὸν περὶ τῆς προειρημένης νήσου συνεστήσαντο πόλεμον πρὸς Καρχηδονίους, μετὰ δὲ ταῦτα πότε πρῶτον συνίστασθαι ναυτικὰς ἤρξαντο δυνάμεις, καὶ τὰ συμβάντα κατὰ τὸν πόλεμον ἑκατέροις ἕως τοῦ τέλους, ἐν ᾧ Καρχηδόνιοι μὲν ἐξεχώρησαν πάσης Σικελίας, Ῥωμαῖοι δ’ ἐπεκράτησαν τῆς ὅλης νήσου πλὴν τῶν ὑφ’ Ἱέρωνι ταττομένων μερῶν. ἑξῆς δὲ τούτοις ἐπεβαλόμεθα λέγειν πῶς στασιάσαντες οἱ μισθοφόροι πρὸς τοὺς Καρχηδονίους τὸν προσαγορευθέντα Λιβυκὸν πόλεμον ἐξέκαυσαν, καὶ τὰ συμβάντα κατὰ τοῦτον ἀσεβήματα μέχρι τίνος προύβη, καὶ τίνα διέξοδον ἔλαβεν τὰ παράλογα τῶν ἔργων ἕως τοῦ τέλους καὶ τῆς Καρχηδονίων ἐπικρατείας. νυνὶ δὲ τὰ συνεχῆ τούτοις πειρασόμεθα δηλοῦν, κεφαλαιωδῶς ἑκάστων ἐπιψαύοντες κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν. Καρχηδόνιοι γὰρ ὡς θᾶττον κατεστήσαντο τὰ κατὰ τὴν Λιβύην, εὐθέως Ἀμίλκαν ἐξαπέστελλον, δυνάμεις συστήσαντες, εἰς τοὺς κατὰ τὴν Ἰβηρίαν τόπους. ὁ δ’ ἀναλαβὼν τὰ στρατόπεδα καὶ τὸν υἱὸν Ἀννίβαν, ὄντα τότε κατὰ τὴν ἡλικίαν ἐτῶν ἐννέα, καὶ διαβὰς κατὰ τὰς Ἡρακλέους στήλας ἀνεκτᾶτο τὰ κατὰ τὴν Ἰβηρίαν πράγματα τοῖς Καρχηδονίοις. διατρίψας δ’ ἐν τοῖς τόποις τούτοις ἔτη σχεδὸν ἐννέα καὶ πολλοὺς μὲν πολέμῳ, πολλοὺς δὲ πειθοῖ ποιήσας Ἰβήρων ὑπηκόους Καρχηδόνι κατέστρεψε τὸν βίον ἀξίως τῶν προγεγενημένων πράξεων. πρὸς γὰρ τοὺς ἀνδρωδεστάτους καὶ μεγίστην δύναμιν ἔχοντας παραταττόμενος καὶ χρώμενος τολμηρῶς καὶ παραβόλως ἑαυτῷ κατὰ τὸν τοῦ κινδύνου καιρὸν ἐρρωμένως τὸν βίον μετήλλαξεν. τὴν δὲ στρατηγίαν οἱ Καρχηδόνιοι παρέδοσαν Ἀσδρούβᾳ, τῷ ’κείνου κηδεστῇ καὶ τριηράρχῳ.", "st": "2.1"}, {"sp": "N", "t": "κατὰ δὲ τοὺς καιροὺς τούτους Ῥωμαῖοι τὴν πρώτην διάβασιν εἰς τὴν Ἰλλυρίδα καὶ ταῦτα τὰ μέρη τῆς Εὐρώπης ἐπεβάλοντο ποιεῖσθαι μετὰ δυνάμεως. ἅπερ οὐ παρέργως, ἀλλὰ μετ’ ἐπιστάσεως θεωρητέον τοῖς βουλομένοις ἀληθινῶς τήν τε πρόθεσιν τὴν ἡμετέραν συνθεάσασθαι καὶ τὴν αὔξησιν καὶ κατασκευὴν τῆς Ῥωμαίων δυναστείας. ἔγνωσαν δὲ διαβαίνειν διά τινας τοιαύτας αἰτίας. Ἄγρων ὁ τῶν Ἰλλυριῶν βασιλεὺς ἦν μὲν υἱὸς Πλευράτου, δύναμιν δὲ πεζὴν καὶ ναυτικὴν μεγίστην ἔσχε τῶν πρὸ αὐτοῦ βεβασιλευκότων ἐν Ἰλλυριοῖς. οὗτος ὑπὸ Δημητρίου τοῦ Φιλίππου πατρὸς πεισθεὶς χρήμασιν ὑπέσχετο βοηθήσειν Μεδιωνίοις ὑπ’ Αἰτωλῶν πολιορκουμένοις. Αἰτωλοὶ γὰρ οὐδαμῶς δυνάμενοι πεῖσαι Μεδιωνίους μετέχειν σφίσι τῆς αὐτῆς πολιτείας, ἐπεβάλοντο κατὰ κράτος ἑλεῖν αὐτούς. στρατεύσαντες οὖν πανδημεὶ καὶ περιστρατοπεδεύσαντες αὐτῶν τὴν πόλιν κατὰ τὸ συνεχὲς ἐπολιόρκουν, πᾶσαν βίαν προσφέροντες καὶ μηχανήν. συνάψαντος δὲ τοῦ χρόνου τῶν ἀρχαιρεσίων, καὶ δέον στρατηγὸν ἕτερον αἱρεῖσθαι, καὶ τῶν πολιορκουμένων ἤδη κακῶς διακειμένων καὶ δοκούντων ἀν’ ἑκάστην ἡμέραν ἐνδώσειν ἑαυτούς, ὁ προϋπάρχων στρατηγὸς προσφέρει λόγον τοῖς Αἰτωλοῖς φάσκων, ἐπειδὴ τὰς κακοπαθείας καὶ τοὺς κινδύνους αὐτὸς ἀναδέδεκται τοὺς κατὰ τὴν πολιορκίαν, δίκαιον εἶναι καὶ τὴν οἰκονομίαν τῶν λαφύρων, ἐπὰν κρατήσωσι, καὶ τὴν ἐπιγραφὴν τῶν ὅπλων ἑαυτῷ συγχωρεῖσθαι. τινῶν δέ, καὶ μάλιστα τῶν προϊόντων πρὸς τὴν ἀρχήν, ἀμφισβητούντων πρὸς τὰ λεγόμενα καὶ παρακαλούντων τὰ πλήθη μὴ προδιαλαμβάνειν, ἀλλ’ ἀκέραιον ἐᾶν, ᾧ ποτ’ ἂν ἡ τύχη βουληθῇ περιθεῖναι τοῦτον τὸν στέφανον, ἔδοξε τοῖς Αἰτωλοῖς, ὃς ἂν ἐπικατασταθεὶς στρατηγὸς κρατήσῃ τῆς πόλεως, κοινὴν ποιεῖν τῷ προϋπάρχοντι καὶ τὴν οἰκονομίαν τῶν λαφύρων καὶ τὴν ἐπιγραφὴν τῶν ὅπλων.", "st": "2.2"}, {"sp": "N", "t": "δεδογμένων δὲ τούτων, καὶ δέον τῇ κατὰ πόδας ἡμέρᾳ γενέσθαι τὴν αἵρεσιν καὶ τὴν παράληψιν τῆς ἀρχῆς, καθάπερ ἔθος ἐστὶν Αἰτωλοῖς, προσπλέουσιν τῆς νυκτὸς ἑκατὸν λέμβοι πρὸς τὴν Μεδιωνίαν κατὰ τοὺς ἔγγιστα τόπους τῆς πόλεως, ἐφ’ ὧν ἦσαν Ἰλλυριοὶ πεντακισχίλιοι. καθορμισθέντες δὲ καὶ τῆς ἡμέρας ἐπιγενομένης ἐνεργὸν καὶ λαθραίαν ποιησάμενοι τὴν ἀπόβασιν καὶ χρησάμενοι τῇ παρ’ αὐτοῖς εἰθισμένῃ τάξει προῆγον κατὰ σπείρας ἐπὶ τὴν τῶν Αἰτωλῶν στρατοπεδείαν. οἱ δ’ Αἰτωλοὶ συνέντες τὸ γινόμενον ἐπὶ μὲν τῷ παραδόξῳ καὶ τῇ τόλμῃ τῶν Ἰλλυριῶν ἦσαν ἐκπλαγεῖς· πεφρονηματισμένοι δ’ ἐκ πολλοῦ χρόνου καὶ καταπιστεύσαντες ταῖς ἰδίαις δυνάμεσιν κατὰ ποσὸν εὐθαρσῶς εἶχον. τὸ μὲν οὖν πολὺ μέρος τῶν ὁπλιτῶν καὶ τῶν ἱππέων αὐτοῦ πρὸ τῆς στρατοπεδείας ἐν τοῖς ἐπιπέδοις παρενέβαλλον, μέρει δέ τινι τῆς ἵππου καὶ τοῖς εὐζώνοις τοὺς ὑπερδεξίους καὶ πρὸ τοῦ χάρακος εὐφυῶς κειμένους τόπους προκατελάμβανον. οἱ δ’ Ἰλλυριοὶ τοὺς μὲν ἐλαφροὺς ἐξ ἐφόδου προσπεσόντες τῷ τε πλήθει καὶ τῷ βάρει τῆς συντάξεως ἐξέωσαν, τοὺς δὲ μετὰ τούτων ἱππεῖς συγκινδυνεύοντας ἠνάγκασαν ἀποχωρῆσαι πρὸς τὰ βαρέα τῶν ὅπλων. λοιπὸν ἐξ ὑπερδεξίου ποιούμενοι τὴν ἔφοδον ἐπὶ τοὺς ἐν τῷ πεδίῳ τεταγμένους ταχέως ἐτρέψαντο, συνεπιθεμένων τοῖς Αἰτωλοῖς ἅμα καὶ τῶν Μεδιωνίων ἐκ τῆς πόλεως. καὶ πολλοὺς μὲν αὐτῶν ἀπέκτειναν, ἔτι δὲ πλείους αἰχμαλώτους ἔλαβον· τῶν δ’ ὅπλων καὶ τῆς ἀποσκευῆς ἐγένοντο πάσης ἐγκρατεῖς. οἱ μὲν οὖν Ἰλλυριοὶ πράξαντες τὸ συνταχθὲν ὑπὸ τοῦ βασιλέως καὶ διακομίσαντες τὴν ἀποσκευὴν καὶ τὴν ἄλλην ὠφέλειαν ἐπὶ τοὺς λέμβους εὐθέως ἀνήγοντο, ποιούμενοι τὸν πλοῦν εἰς τὴν οἰκείαν.", "st": "2.3"}, {"sp": "N", "t": "οἱ δὲ Μεδιώνιοι τετευχότες ἀνελπίστου σωτηρίας, ἁθροισθέντες εἰς τὴν ἐκκλησίαν ἐβουλεύοντο περί τε τῶν ἄλλων καὶ περὶ τῆς τῶν ὅπλων ἐπιγραφῆς. ἔδοξεν οὖν αὐτοῖς κοινὴν ποιήσειν τὴν ἐπιγραφὴν ἀπό τε τοῦ τὴν ἀρχὴν τῶν Αἰτωλῶν ἔχοντος καὶ τῶν εἰς τὸ μέλλον προπορευομένων κατὰ τὸ τῶν Αἰτωλῶν δόγμα, τῆς τύχης ὥσπερ ἐπίτηδες καὶ τοῖς ἄλλοις ἀνθρώποις ἐπὶ τῶν ἐκείνοις συμβαινόντων ἐνδεικνυμένης τὴν αὑτῆς δύναμιν. ἃ γὰρ ὑπὸ τῶν ἐχθρῶν αὐτοὶ προσεδόκων ὅσον ἤδη πείσεσθαι, ταῦτα πράττειν αὐτοῖς ἐκείνοις παρέδωκεν ἐν πάνυ βραχεῖ χρόνῳ κατὰ τῶν πολεμίων. Αἰτωλοὶ δὲ τῇ παραδόξῳ χρησάμενοι συμφορᾷ πάντας ἐδίδαξαν μηδέποτε βουλεύεσθαι περὶ τοῦ μέλλοντος ὡς ἤδη γεγονότος, μηδὲ προκατελπίζειν βεβαιουμένους ὑπὲρ ὧν ἀκμὴν ἐνδεχόμενόν ἐστιν ἄλλως γενέσθαι, νέμειν δὲ μερίδα τῷ παραδόξῳ πανταχῇ μὲν ἀνθρώπους ὄντας, μάλιστα δ’ ἐν τοῖς πολεμικοῖς. ὁ δὲ βασιλεὺς Ἄγρων, ἐπεὶ κατέπλευσαν οἱ λέμβοι, διακούσας τῶν ἡγεμόνων τὰ κατὰ τὸν κίνδυνον καὶ περιχαρὴς γενόμενος ἐπὶ τῷ δοκεῖν Αἰτωλοὺς τοὺς μέγιστον ἔχοντας τὸ φρόνημα νενικηκέναι, πρὸς μέθας καί τινας τοιαύτας ἄλλας εὐωχίας τραπεὶς ἐνέπεσεν εἰς πλευρῖτιν· ἐκ δὲ ταύτης ἐν ὀλίγαις ἡμέραις μετήλλαξε τὸν βίον. τὴν δὲ βασιλείαν ἡ γυνὴ Τεύτα διαδεξαμένη τὸν κατὰ μέρος χειρισμὸν τῶν πραγμάτων ἐποιεῖτο διὰ τῆς τῶν φίλων πίστεως. χρωμένη δὲ λογισμοῖς γυναικείοις καὶ πρὸς αὐτὸ τὸ γεγονὸς εὐτύχημα μόνον ἀποβλέπουσα, τῶν δ’ ἐκτὸς οὐδὲν περισκεπτομένη πρῶτον μὲν συνεχώρησε τοῖς κατ’ ἰδίαν πλέουσι λῄζεσθαι τοὺς ἐντυγχάνοντας, δεύτερον δ’ ἁθροίσασα στόλον καὶ δύναμιν οὐκ ἐλάττω τῆς πρότερον ἐξέπεμψε, πᾶσαν παραλίαν ἀποδείξασα πολεμίαν τοῖς ἡγουμένοις.", "st": "2.4"}, {"sp": "N", "t": "οἱ δ’ ἐξαποσταλέντες τὴν μὲν πρώτην ἐπιβολὴν ἔσχον ἐπὶ τὴν Ἠλείαν καὶ τὴν Μεσσηνίαν· ταύτας γὰρ ἀεὶ τὰς χώρας Ἰλλυριοὶ πορθοῦντες διετέλουν. διὰ γὰρ τὸ μῆκος τῆς παραλίας καὶ διὰ τὸ μεσογαίους εἶναι τὰς δυναστευούσας ἐν αὐταῖς πόλεις μακραὶ καὶ βραδεῖαι λίαν ἐγίνοντο τοῖς προειρημένοις αἱ παραβοήθειαι πρὸς τὰς ἀποβάσεις τῶν Ἰλλυριῶν· ὅθεν ἀδεῶς ἐπέτρεχον καὶ κατέσυρον ἀεὶ ταύτας τὰς χώρας. οὐ μὴν ἀλλὰ τότε γενόμενοι τῆς Ἠπείρου κατὰ Φοινίκην προσέσχον ἐπισιτισμοῦ χάριν. συμμίξαντες δὲ τῶν Γαλατῶν τισιν, οἳ μισθοφοροῦντες παρὰ τοῖς Ἠπειρώταις διέτριβον ἐν τῇ Φοινίκῃ, τὸ πλῆθος ὄντες εἰς ὀκτακοσίους, καὶ κοινολογηθέντες τούτοις περὶ προδοσίας τῆς πόλεως ἐξέβησαν, συγκαταθεμένων σφίσι τῶν προειρημένων, καὶ τῆς πόλεως ἐξ ἐφόδου καὶ τῶν ἐν αὐτῇ κύριοι κατέστησαν, συνεργησάντων ἔσωθεν αὐτοῖς τῶν Γαλατῶν. οἱ δ’ Ἠπειρῶται πυθόμενοι τὸ γεγονὸς ἐβοήθουν πανδημεὶ μετὰ σπουδῆς. παραγενόμενοι δὲ πρὸς τὴν Φοινίκην καὶ προβαλόμενοι τὸν παρὰ τῇ πόλει ῥέοντα ποταμὸν ἐστρατοπέδευσαν, τῆς ἐπ’ αὐτῷ γεφύρας ἀνασπάσαντες τὰς σανίδας ἀσφαλείας χάριν. προσαγγελθέντος δ’ αὐτοῖς Σκερδιλαΐδαν ἔχοντα πεντακισχιλίους Ἰλλυριοὺς παραγίνεσθαι κατὰ γῆν διὰ τῶν παρ’ Ἀντιγόνειαν στενῶν, μερίσαντες αὑτῶν τινας ἐξαπέστειλαν παραφυλάξοντας τὴν Ἀντιγόνειαν· αὐτοὶ δὲ τά τε λοιπὰ ῥᾳθύμως διῆγον, ἀπολαύοντες τῶν ἐκ τῆς χώρας ἀνέδην, τῶν τε κατὰ τὰς φυλακὰς καὶ προκοιτίας ὠλιγώρουν. οἱ δ’ Ἰλλυριοὶ συνέντες τὸν μερισμὸν αὐτῶν καὶ τὴν λοιπὴν ῥᾳθυμίαν ἐκπορεύονται νυκτός· καὶ τῇ γεφύρᾳ σανίδας ἐπιβαλόντες τόν τε ποταμὸν ἀσφαλῶς διέβησαν καὶ λαβόντες ὀχυρὸν τόπον ἔμειναν τὸ λοιπὸν μέρος τῆς νυκτός. ἐπιγενομένης δὲ τῆς ἡμέρας, καὶ παραταξαμένων ἀμφοτέρων πρὸ τῆς πόλεως, συνέβη λειφθῆναι τοὺς Ἠπειρώτας, καὶ πολλοὺς μὲν αὐτῶν πεσεῖν, ἔτι δὲ πλείους ἁλῶναι, τοὺς δὲ λοιποὺς διαφυγεῖν ὡς ἐπ’ Ἀτιντάνων.", "st": "2.5"}, {"sp": "N", "t": "οὗτοι μὲν οὖν τοιούτοις περιπεσόντες ἀτυχήμασι καὶ πάσας ἀπολέσαντες τὰς ἐν αὑτοῖς ἐλπίδας ἐπρέσβευον πρὸς τοὺς Αἰτωλοὺς καὶ τὸ τῶν Ἀχαιῶν ἔθνος, δεόμενοι μεθ’ ἱκετηρίας σφίσι βοηθεῖν. οἱ δὲ κατελεήσαντες τὰς συμφορὰς αὐτῶν ὑπήκουσαν καὶ μετὰ ταῦτα παραβοηθοῦντες ἧκον εἰς Ἑλίκρανον. οἱ δὲ τὴν Φοινίκην κατασχόντες τὸ μὲν πρῶτον, παραγενόμενοι μετὰ Σκερδιλαΐδου πρὸς τὸ χωρίον, παρεστρατοπέδευσαν τοῖς βεβοηθηκόσι, βουλόμενοι συμβαλεῖν. δυσχρηστούμενοι δὲ διὰ τὰς δυσχωρίας τῶν τόπων, ἅμα δὲ καὶ προσπεσόντων παρὰ τῆς Τεύτας γραμμάτων, δι’ ὧν ᾤετο δεῖν αὐτοὺς τὴν ταχίστην εἰς οἶκον ἀναχωρεῖν διὰ τὸ τινὰς τῶν Ἰλλυριῶν ἀφεστηκέναι πρὸς τοὺς Δαρδανεῖς, οὕτω λεηλατήσαντες τὴν Ἤπειρον ἀνοχὰς ἐποιήσαντο πρὸς τοὺς Ἠπειρώτας. ἐν αἷς τὰ μὲν ἐλεύθερα σώματα καὶ τὴν πόλιν ἀπολυτρώσαντες αὐτοῖς, τὰ δὲ δουλικὰ καὶ τὴν λοιπὴν σκευὴν ἀναλαβόντες εἰς τοὺς λέμβους, οἱ μὲν ἀπέπλευσαν, οἱ δὲ περὶ τὸν Σκερδιλαΐδαν πεζῇ πάλιν ἀνεχώρησαν διὰ τῶν παρὰ τὴν Ἀντιγόνειαν στενῶν, οὐ μικρὰν οὐδὲ τὴν τυχοῦσαν κατάπληξιν καὶ φόβον ἐνεργασάμενοι τοῖς τὰς παραλίας οἰκοῦσι τῶν Ἑλλήνων. ἕκαστοι γὰρ θεωροῦντες τὴν ὀχυρωτάτην ἅμα καὶ δυνατωτάτην πόλιν τῶν ἐν Ἠπείρῳ παραλόγως οὕτως ἐξηνδραποδισμένην οὐκέτι περὶ τῶν ἀπὸ τῆς χώρας ἠγωνίων, καθάπερ ἐν τοῖς ἔμπροσθεν χρόνοις, ἀλλὰ περὶ σφῶν αὐτῶν καὶ τῶν πόλεων. οἱ δ’ Ἠπειρῶται παραδόξως διασεσωσμένοι τοσοῦτον ἀπεῖχον τοῦ πειράζειν ἀμύνεσθαι τοὺς ἠδικηκότας ἢ χάριν ἀποδιδόναι τοῖς βοηθήσασιν ὥστε τοὐναντίον διαπρεσβευσάμενοι πρὸς τὴν Τεύταν συμμαχίαν ἔθεντο μετ’ Ἀκαρνάνων πρὸς τοὺς Ἰλλυριούς, καθ’ ἣν ἐκείνοις μὲν κατὰ τοὺς ἑξῆς καιροὺς συνήργουν, τοῖς δ’ Ἀχαιοῖς καὶ τοῖς Αἰτωλοῖς ἀντέπραττον. ἐξ ὧν ἐγένοντο καταφανεῖς ἀκρίτως μὲν κεχρημένοι τότε τοῖς εὐεργέταις, ἀφρόνως δ’ ἐξ ἀρχῆς βεβουλευμένοι περὶ τῶν καθ’ αὑτοὺς πραγμάτων.", "st": "2.6"}, {"sp": "N", "t": "τὸ μὲν γὰρ ἀνθρώπους ὄντας παραλόγως περιπεσεῖν τινι τῶν δεινῶν οὐ τῶν παθόντων, τῆς τύχης δὲ καὶ τῶν πραξάντων ἐστὶν ἔγκλημα, τὸ δ’ ἀκρίτως καὶ προφανῶς περιβαλεῖν αὑτοὺς ταῖς μεγίσταις συμφοραῖς ὁμολογούμενόν ἐστι τῶν πασχόντων ἁμάρτημα. διὸ καὶ τοῖς μὲν ἐκ τύχης πταίουσιν ἔλεος ἕπεται μετὰ συγγνώμης καὶ ἐπικουρία, τοῖς δὲ διὰ τὴν αὑτῶν ἀβουλίαν ὄνειδος καὶ ἐπιτίμησις συνεξακολουθεῖ παρὰ τοῖς εὖ φρονοῦσιν. ἃ δὴ καὶ τότε παρὰ τῶν Ἑλλήνων εἰκότως ἂν τοῖς Ἠπειρώταις ἀπηντήθη. πρῶτον γὰρ τίς οὐκ ἂν τὴν κοινὴν περὶ Γαλατῶν φήμην ὑπιδόμενος εὐλαβηθείη τούτοις ἐγχειρίσαι πόλιν εὐδαίμονα καὶ πολλὰς ἀφορμὰς ἔχουσαν εἰς παρασπόνδησιν; δεύτερον τίς οὐκ ἂν ἐφυλάξατο τὴν αὐτοῦ τοῦ συστήματος ἐκείνου προαίρεσιν; οἵ γε τὴν μὲν ἀρχὴν ἐξέπεσον ἐκ τῆς ἰδίας, συνδραμόντων ἐπ’ αὐτοὺς τῶν ὁμοεθνῶν διὰ τὸ παρασπονδῆσαι τοὺς αὑτῶν οἰκείους καὶ συγγενεῖς· ὑποδεξαμένων γε μὴν αὐτοὺς Καρχηδονίων διὰ τὸ κατεπείγεσθαι πολέμῳ, τὸ μὲν πρῶτον γενομένης τινὸς ἀντιρρήσεως τοῖς στρατιώταις πρὸς τοὺς στρατηγοὺς ὑπὲρ ὀψωνίων ἐξ αὐτῆς ἐπεβάλοντο διαρπάζειν τὴν τῶν Ἀκραγαντίνων πόλιν, φυλακῆς χάριν εἰσαχθέντες εἰς αὐτήν, ὄντες τότε πλείους τῶν τρισχιλίων· μετὰ δὲ ταῦτα παρεισαγαγόντων αὐτοὺς πάλιν εἰς Ἔρυκα τῆς αὐτῆς χρείας ἕνεκεν, πολιορκούντων τὴν πόλιν Ῥωμαίων, ἐπεχείρησαν μὲν καὶ τὴν πόλιν καὶ τοὺς συμπολιορκουμένους προδοῦναι· τῆς δὲ πράξεως ταύτης ἀποτυχόντες ηὐτομόλησαν πρὸς τοὺς πολεμίους· παρ’ οἷς πιστευθέντες πάλιν ἐσύλησαν τὸ τῆς Ἀφροδίτης τῆς Ἐρυκίνης ἱερόν. διὸ σαφῶς ἐπεγνωκότες Ῥωμαῖοι τὴν ἀσέβειαν αὐτῶν ἅμα τῷ διαλύσασθαι τὸν πρὸς Καρχηδονίους πόλεμον οὐδὲν ἐποιήσαντο προυργιαίτερον τοῦ παροπλίσαντας αὐτοὺς ἐμβαλεῖν εἰς πλοῖα καὶ τῆς Ἰταλίας πάσης ἐξορίστους καταστῆσαι. οὓς Ἠπειρῶται τῆς δημοκρατίας καὶ τῶν νόμων φύλακας ποιησάμενοι καὶ τὴν εὐδαιμονεστάτην πόλιν ἐγχειρίσαντες, πῶς οὐκ ἂν εἰκότως φανείησαν αὐτοὶ τῶν συμπτωμάτων αὑτοῖς αἴτιοι γεγονότες; περὶ μὲν οὖν τῆς Ἠπειρωτῶν ἀγνοίας καὶ περὶ τοῦ μηδέποτε δεῖν τοὺς εὖ φρονοῦντας ἰσχυροτέραν εἰσάγεσθαι φυλακὴν ἄλλως τε καὶ βαρβάρων, ἐπὶ τοσοῦτον ἔκρινον ποιήσασθαι μνήμην.", "st": "2.7"}, {"sp": "N", "t": "οἱ δ’ Ἰλλυριοὶ καὶ κατὰ τοὺς ἀνωτέρω μὲν χρόνους συνεχῶς ἠδίκουν τοὺς πλοϊζομένους ἀπ’ Ἰταλίας· καθ’ οὓς δὲ καιροὺς περὶ τὴν Φοινίκην διέτριβον, καὶ πλείους ἀπὸ τοῦ στόλου χωριζόμενοι πολλοὺς τῶν Ἰταλικῶν ἐμπόρων ἔσθ’ οὓς μὲν ἐσύλησαν, οὓς δ’ ἀπέσφαξαν, οὐκ ὀλίγους δὲ καὶ ζωγρίᾳ τῶν ἁλισκομένων ἀνῆγον. οἱ δὲ Ῥωμαῖοι παρακούοντες τὸν πρὸ τοῦ χρόνον τῶν ἐγκαλούντων τοῖς Ἰλλυριοῖς, τότε καὶ πλειόνων ἐπελθόντων ἐπὶ τὴν σύγκλητον, κατέστησαν πρεσβευτὰς εἰς τὴν Ἰλλυρίδα τοὺς ἐπίσκεψιν ποιησομένους περὶ τῶν προειρημένων Γάϊον καὶ Λεύκιον Κορογκανίους. ἡ δὲ Τεύτα, καταπλευσάντων πρὸς αὐτὴν τῶν ἐκ τῆς Ἠπείρου λέμβων, καταπλαγεῖσα τὸ πλῆθος καὶ τὸ κάλλος τῆς ἀγομένης κατασκευῆς — πολὺ γὰρ ἡ Φοινίκη διέφερε τότε τῶν κατὰ τὴν Ἤπειρον πόλεων εὐδαιμονίᾳ — διπλασίως ἐπερρώσθη πρὸς τὴν κατὰ τῶν Ἑλλήνων ἀδικίαν. οὐ μὴν ἀλλὰ τότε μὲν ἐπέσχεν διὰ τὰς ἐγχωρίους ταραχάς, καταστησαμένη δὲ ταχέως τὰ κατὰ τοὺς ἀποστάντας Ἰλλυριοὺς ἐπολιόρκει τὴν Ἴσσαν διὰ τὸ ταύτην ἔτι μόνην ἀπειθεῖν αὐτῇ. κατὰ δὲ τὸν καιρὸν τοῦτον κατέπλευσαν οἱ τῶν Ῥωμαίων πρέσβεις· καὶ δοθέντος αὐτοῖς καιροῦ πρὸς ἔντευξιν διελέγοντο περὶ τῶν εἰς αὐτοὺς γεγονότων ἀδικημάτων. ἡ δὲ Τεύτα καθόλου μὲν παρ’ ὅλην τὴν κοινολογίαν ἀγερώχως καὶ λίαν ὑπερηφάνως αὐτῶν διήκουεν. καταπαυσάντων δὲ τὸν λόγον, κοινῇ μὲν ἔφη πειρᾶσθαι φροντίζειν ἵνα μηδὲν ἀδίκημα γίνηται Ῥωμαίοις ἐξ Ἰλλυριῶν· ἰδίᾳ γε μὴν οὐ νόμιμον εἶναι τοῖς βασιλεῦσι κωλύειν Ἰλλυριοῖς τὰς κατὰ θάλατταν ὠφελείας. ὁ δὲ νεώτερος τῶν πρεσβευτῶν δυσχεράνας ἐπὶ τοῖς εἰρημένοις ἐχρήσατο παρρησίᾳ καθηκούσῃ μέν, οὐδαμῶς δὲ πρὸς καιρόν. εἶπεν γὰρ ὅτι Ῥωμαίοις μέν, ὦ Τεύτα, κάλλιστον ἔθος ἐστὶ τὰ κατ’ ἰδίαν ἀδικήματα κοινῇ μεταπορεύεσθαι καὶ βοηθεῖν τοῖς ἀδικουμένοις· πειρασόμεθα δὴ θεοῦ βουλομένου σφόδρα καὶ ταχέως ἀναγκάσαι σε τὰ βασιλικὰ νόμιμα διορθώσασθαι πρὸς Ἰλλυριούς. ἡ δὲ γυναικοθύμως καὶ ἀλογίστως δεξαμένη τὴν παρρησίαν ἐπὶ τοσοῦτον ἐξωργίσθη πρὸς τὸ ῥηθὲν ὡς ὀλιγωρήσασα τῶν παρ’ ἀνθρώποις ὡρισμένων δικαίων ἀποπλέουσιν αὐτοῖς ἐπαποστεῖλαί τινας τὸν παρρησιασάμενον τῶν πρέσβεων ἀποκτεῖναι. προσπεσόντος δὲ τοῦ γεγονότος εἰς τὴν Ῥώμην, διοργισθέντες ἐπὶ τῇ παρανομίᾳ τῆς γυναικὸς εὐθέως περὶ παρασκευὴν ἐγίνοντο καὶ στρατόπεδα κατέγραφον καὶ στόλον συνήθροιζον.", "st": "2.8"}, {"sp": "N", "t": "ἡ δὲ Τεύτα, τῆς ὥρας ἐπιγενομένης, ἐπισκευάσασα λέμβους πλείους τῶν πρότερον ἐξαπέστειλε πάλιν εἰς τοὺς κατὰ τὴν Ἑλλάδα τόπους. ὧν οἱ μὲν διὰ πόρου τὸν πλοῦν ἐπὶ τὴν Κέρκυραν ἐποιοῦντο, μέρος δέ τι προσέσχε τὸν τῶν Ἐπιδαμνίων λιμένα, λόγῳ μὲν ὑδρείας καὶ ἐπισιτισμοῦ χάριν, ἔργῳ δ’ ἐπιβουλῆς καὶ πράξεως ἐπὶ τὴν πόλιν. τῶν δ’ Ἐπιδαμνίων ἀκάκως ἅμα καὶ ῥᾳθύμως αὐτοὺς παραδεξαμένων, εἰσελθόντες ἐν αὐτοῖς τοῖς περιζώμασιν ὡς ὑδρευσόμενοι, μαχαίρας ἔχοντες ἐν τοῖς κεραμίοις, οὕτως κατασφάξαντες τοὺς φυλάττοντας τὴν πύλην ταχέως ἐγκρατεῖς ἐγένοντο τοῦ πυλῶνος. ἐπιγενομένης δὲ κατὰ τὸ συντεταγμένον ἐνεργῶς τῆς ἀπὸ τῶν πλοίων βοηθείας, παραδεξάμενοι τούτους ῥᾳδίως κατεῖχον τὰ πλεῖστα τῶν τειχῶν. τῶν δ’ ἐκ τῆς πόλεως ἀπαρασκεύως μὲν διὰ τὸ παράδοξον, ἐκθύμως δὲ βοηθούντων καὶ διαγωνιζομένων, συνέβη τοὺς Ἰλλυριοὺς ἐπὶ πολὺν χρόνον ἀντιποιησαμένους τέλος ἐκπεσεῖν ἐκ τῆς πόλεως. Ἐπιδάμνιοι μὲν οὖν ἐν ταύτῃ τῇ πράξει διὰ μὲν τὴν ὀλιγωρίαν ἐκινδύνευσαν ἀποβαλεῖν τὴν πατρίδα, διὰ δὲ τὴν εὐψυχίαν ἀβλαβῶς ἐπαιδεύθησαν πρὸς τὸ μέλλον. τῶν δ’ Ἰλλυριῶν οἱ προεστῶτες κατὰ σπουδὴν ἀναχθέντες καὶ συνάψαντες τοῖς προπλέουσι κατῆραν εἰς τὴν Κέρκυραν· καὶ ποιησάμενοι καταπληκτικὴν τὴν ἀπόβασιν ἐνεχείρησαν πολιορκεῖν τὴν πόλιν. ὧν συμβαινόντων οἱ Κερκυραῖοι δυσχρηστούμενοι καὶ δυσελπίστως διακείμενοι τοῖς ὅλοις ἐπρεσβεύοντο πρός τε τοὺς Ἀχαιοὺς καὶ τοὺς Αἰτωλούς, ἅμα δὲ τούτοις Ἀπολλωνιᾶται καὶ Ἐπιδάμνιοι, δεόμενοι σφίσι βοηθεῖν κατὰ σπουδὴν καὶ μὴ περιιδεῖν σφᾶς αὐτοὺς ἀναστάτους γενομένους ὑπὸ τῶν Ἰλλυριῶν. οἱ δὲ διακούσαντες τῶν πρέσβεων καὶ προσδεξάμενοι τοὺς λόγους ἐπλήρωσαν κοινῇ τὰς τῶν Ἀχαιῶν δέκα ναῦς καταφράκτους, καταρτίσαντες δ’ ἐν ὀλίγαις ἡμέραις ἔπλεον ἐπὶ τῆς Κερκύρας, ἐλπίζοντες λύσειν τὴν πολιορκίαν.", "st": "2.9"}, {"sp": "N", "t": "οἱ δ’ Ἰλλυριοὶ συμπαραλαβόντες Ἀκαρνάνων ναῦς κατὰ τὴν συμμαχίαν, οὔσας ἑπτὰ καταφράκτους, ἀνταναχθέντες συνέβαλλον τοῖς τῶν Ἀχαιῶν σκάφεσιν περὶ τοὺς καλουμένους Παξούς. οἱ μὲν οὖν Ἀκαρνᾶνες καὶ τῶν Ἀχαϊκῶν νεῶν αἱ κατὰ τούτους ταχθεῖσαι πάρισον ἐποίουν τὸν ἀγῶνα καὶ διέμενον ἀκέραιοι κατὰ τὰς συμπλοκὰς πλὴν τῶν εἰς αὐτοὺς τοὺς ἄνδρας γινομένων τραυμάτων. οἱ δ’ Ἰλλυριοὶ ζεύξαντες τοὺς παρ’ αὑτῶν λέμβους ἀνὰ τέτταρας συνεπλέκοντο τοῖς πολεμίοις. καὶ τῶν μὲν ἰδίων ὠλιγώρουν καὶ παραβάλλοντες πλαγίους συνήργουν ταῖς ἐμβολαῖς τῶν ὑπεναντίων. ὅτε δὲ τρώσαντα καὶ δεθέντα κατὰ τὰς ἐμβολὰς δυσχρήστως διέκειτο πρὸς τὸ παρὸν τὰ τῶν ἀντιπάλων σκάφη, προσκρεμαμένων αὐτοῖς περὶ τοὺς ἐμβόλους τῶν ἐζευγμένων λέμβων, τότ’ ἐπιπηδῶντες ἐπὶ τὰ καταστρώματα τῶν Ἀχαϊκῶν νεῶν κατεκράτουν διὰ τὸ πλῆθος τῶν ἐπιβατῶν. καὶ τούτῳ τῷ τρόπῳ τεττάρων μὲν πλοίων ἐκυρίευσαν τετρηρικῶν, μίαν δὲ πεντήρη σὺν αὐτοῖς τοῖς ἀνδράσιν ἐβύθισαν, ἐφ’ ἧς ἔπλει Μάργος ὁ Καρυνεύς, ἀνὴρ πάντα τὰ δίκαια τῷ κοινῷ τῶν Ἀχαιῶν πολιτεύματι πεποιηκὼς μέχρι τῆς καταστροφῆς. οἱ δὲ πρὸς τοὺς Ἀκαρνᾶνας διαγωνιζόμενοι, συνιδόντες τὸ κατὰ τοὺς Ἰλλυριοὺς προτέρημα καὶ πιστεύοντες τῷ ταχυναυτεῖν, ἐπουρώσαντες ἀσφαλῶς τὴν ἀποχώρησιν εἰς τὴν οἰκείαν ἐποιήσαντο. τὸ δὲ τῶν Ἰλλυριῶν πλῆθος φρονηματισθὲν ἐπὶ τῷ προτερήματι λοιπὸν ἤδη ῥᾳδίως ἐχρήσατο τῇ πολιορκίᾳ καὶ τεθαρρηκότως. οἱ δὲ Κερκυραῖοι δυσελπιστήσαντες τοῖς ὅλοις ἐκ τῶν συμβεβηκότων, βραχὺν ἔτι χρόνον ὑπομείναντες τὴν πολιορκίαν συνέθεντο τοῖς Ἰλλυριοῖς καὶ παρεδέξαντο φρουρὰν καὶ μετὰ τῆς φρουρᾶς Δημήτριον τὸν Φάριον. τούτων δὲ πραχθέντων εὐθέως οἱ τῶν Ἰλλυριῶν προεστῶτες ἀνήγοντο· καὶ κατάραντες εἰς τὴν Ἐπίδαμνον ταύτην πάλιν ἐπεβάλοντο πολιορκεῖν τὴν πόλιν.", "st": "2.10"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς τῶν τὰς ὑπάτους ἀρχὰς ἐχόντων Γνάιος μὲν Φόλουιος ἐξέπλει ναυσὶ διακοσίαις ἐκ τῆς Ῥώμης, Αὖλος δὲ Ποστόμιος τὰς πεζικὰς ἔχων δυνάμεις ἐξώρμα. τὴν μὲν οὖν πρώτην ἐπιβολὴν ἔσχε πλεῖν ὁ Γνάιος ἐπὶ τῆς Κερκύρας, ὑπολαμβάνων ἔτι καταλήψεσθαι τὴν πολιορκίαν ἄκριτον· ὑστερήσας δὲ τῶν καιρῶν ὅμως ἐπὶ τὴν νῆσον ἔπλει, βουλόμενος ἅμα μὲν ἐπιγνῶναι σαφῶς τὰ γεγονότα περὶ τὴν πόλιν, ἅμα δὲ πεῖραν λαβεῖν τῶν παρὰ τοῦ Δημητρίου προσαγγελλομένων. ὁ γὰρ Δημήτριος ἐν διαβολαῖς ὢν καὶ φοβούμενος τὴν Τεύταν διεπέμπετο πρὸς τοὺς Ῥωμαίους, ἐπαγγελλόμενος τήν τε πόλιν ἐγχειριεῖν καὶ τὰ λοιπὰ πράγματα παραδώσειν, ὧν ἦν αὐτὸς κύριος. οἱ δὲ Κερκυραῖοι τὴν παρουσίαν τῶν Ῥωμαίων ἀσμένως ἰδόντες, τήν τε φρουρὰν παρέδοσαν τῶν Ἰλλυριῶν μετὰ τῆς τοῦ Δημητρίου γνώμης, αὐτοί τε σφᾶς ὁμοθυμαδὸν ἔδωκαν παρακληθέντες εἰς τὴν τῶν Ῥωμαίων πίστιν, μίαν ταύτην ὑπολαβόντες ἀσφάλειαν αὑτοῖς ὑπάρχειν εἰς τὸν μέλλοντα χρόνον πρὸς τὴν Ἰλλυριῶν παρανομίαν. Ῥωμαῖοι δὲ προσδεξάμενοι τοὺς Κερκυραίους εἰς τὴν φιλίαν ἔπλεον ἐπὶ τῆς Ἀπολλωνίας, ἔχοντες εἰς τὰ κατάλοιπα τῶν πραγμάτων ἡγεμόνα τὸν Δημήτριον. κατὰ δὲ τὸν αὐτὸν καιρὸν καὶ Ποστόμιος τὰς πεζικὰς διεβίβαζε δυνάμεις ἐκ τοῦ Βρεντεσίου, πεζοὺς μὲν εἰς δισμυρίους, ἱππεῖς δὲ περὶ δισχιλίους. ἅμα δὲ τῷ προσέχειν ἑκατέρας ὁμοῦ τὰς δυνάμεις πρὸς τὴν Ἀπολλωνίαν ὁμοίως καὶ τούτων ἀποδεξαμένων καὶ δόντων ἑαυτοὺς εἰς τὴν ἐπιτροπὴν παραχρῆμα πάλιν ἀνήχθησαν, ἀκούοντες πολιορκεῖσθαι τὴν Ἐπίδαμνον. οἱ δ’ Ἰλλυριοὶ συνέντες τὴν ἔφοδον τῶν Ῥωμαίων, οὐδενὶ κόσμῳ λύσαντες τὴν πολιορκίαν ἔφυγον. Ῥωμαῖοι δὲ καὶ τοὺς Ἐπιδαμνίους παραλαβόντες εἰς τὴν πίστιν προῆγον εἰς τοὺς εἴσω τόπους τῆς Ἰλλυρίδος, ἅμα καταστρεφόμενοι τοὺς Ἀρδιαίους. συμμιξάντων δὲ πρεσβευτῶν αὐτοῖς καὶ πλειόνων, ὧν οἱ παρὰ τῶν Παρθίνων ἧκον ἐπιτρέποντες τὰ καθ’ αὑτούς, δεξάμενοι τούτους εἰς τὴν φιλίαν, παραπλησίως δὲ καὶ τοὺς παρὰ τῶν Ἀτιντάνων προσεληλυθότας προῆγον ὡς ἐπὶ τὴν Ἴσσαν διὰ τὸ καὶ ταύτην ὑπὸ τῶν Ἰλλυριῶν πολιορκεῖσθαι τὴν πόλιν. ἀφικόμενοι δὲ καὶ λύσαντες τὴν πολιορκίαν προσεδέξαντο καὶ τοὺς Ἰσσαίους εἰς τὴν ἑαυτῶν πίστιν. εἷλον δὲ καὶ πόλεις τινὰς Ἰλλυρίδας ἐν τῷ παράπλῳ κατὰ κράτος· ἐν αἷς περὶ Νουτρίαν οὐ μόνον τῶν στρατιωτῶν ἀπέβαλον πολλούς, ἀλλὰ καὶ τῶν χιλιάρχων τινὰς καὶ τὸν ταμίαν. ἐκυρίευσαν δὲ καὶ λέμβων εἴκοσι τῶν ἀποκομιζόντων τὴν ἐκ τῆς χώρας ὠφέλειαν. τῶν δὲ πολιορκούντων τὴν Ἴσσαν οἱ μὲν ἐν τῇ Φάρῳ διὰ τὸν Δημήτριον ἀβλαβεῖς ἔμειναν, οἱ δ’ ἄλλοι πάντες ἔφυγον εἰς τὸν Ἄρβωνα σκεδασθέντες. ἡ δὲ Τεύτα πάνυ μετ’ ὀλίγων εἰς τὸν Ῥίζονα διεσώθη, πολισμάτιον εὖ πρὸς ὀχυρότητα κατεσκευασμένον, ἀνακεχωρηκὸς μὲν ἀπὸ τῆς θαλάττης, ἐπ’ αὐτῷ δὲ κείμενον τῷ Ῥίζονι ποταμῷ. ταῦτα δὲ πράξαντες καὶ τῷ Δημητρίῳ τοὺς πλείστους ὑποτάξαντες τῶν Ἰλλυριῶν καὶ μεγάλην αὐτῷ περιθέντες δυναστείαν ἀνεχώρησαν εἰς τὴν Ἐπίδαμνον ἅμα τῷ στόλῳ καὶ τῇ πεζικῇ δυνάμει.", "st": "2.11"}, {"sp": "N", "t": "Γνάιος μὲν οὖν Φόλουιος εἰς τὴν Ῥώμην ἀπέπλευσε, τὸ πλεῖον ἔχων μέρος τῆς τε ναυτικῆς καὶ πεζικῆς στρατιᾶς. ὁ δὲ Ποστόμιος ὑπολειπόμενος τετταράκοντα σκάφη καὶ στρατόπεδον ἐκ τῶν περικειμένων πόλεων ἁθροίσας παρεχείμαζε, συνεφεδρεύων τῷ τε τῶν Ἀρδιαίων ἔθνει καὶ τοῖς ἄλλοις τοῖς δεδωκόσιν ἑαυτοὺς εἰς τὴν πίστιν. ὑπὸ δὲ τὴν ἐαρινὴν ὥραν ἡ Τεύτα διαπρεσβευσαμένη πρὸς τοὺς Ῥωμαίους ποιεῖται συνθήκας, ἐν αἷς εὐδόκησε φόρους τε τοὺς διαταχθέντας οἴσειν πάσης τ’ ἀναχωρήσειν τῆς Ἰλλυρίδος πλὴν ὀλίγων τόπων, καὶ τὸ συνέχον, ὃ μάλιστα πρὸς τοὺς Ἕλληνας διέτεινε, μὴ πλεύσειν πλέον ἢ δυσὶ λέμβοις ἔξω τοῦ Λίσσου, καὶ τούτοις ἀνόπλοις. ὧν συντελεσθέντων ὁ Ποστόμιος μετὰ ταῦτα πρεσβευτὰς ἐξαπέστειλε πρός τε τοὺς Αἰτωλοὺς καὶ τὸ τῶν Ἀχαιῶν ἔθνος· οἳ καὶ παραγενόμενοι πρῶτον μὲν ἀπελογίσαντο τὰς αἰτίας τοῦ πολέμου καὶ τῆς διαβάσεως, ἑξῆς δὲ τούτοις τὰ πεπραγμένα διεξῆλθον καὶ τὰς συνθήκας παρανέγνωσαν, ἃς ἐπεποίηντο πρὸς τοὺς Ἰλλυριούς. τυχόντες δὲ παρ’ ἑκατέρου τῶν ἐθνῶν τῆς καθηκούσης φιλανθρωπίας αὖθις ἀπέπλευσαν εἰς τὴν Κέρκυραν, ἱκανοῦ τινος ἀπολελυκότες φόβου τοὺς Ἕλληνας διὰ τὰς προειρημένας συνθήκας. οὐ γὰρ τισὶν, ἀλλὰ πᾶσι τότε κοινοὺς ἐχθροὺς εἶναι συνέβαινε τοὺς Ἰλλυριούς. ἡ μὲν οὖν πρώτη διάβασις Ῥωμαίων μετὰ δυνάμεως εἰς τὴν Ἰλλυρίδα καὶ ταῦτα τὰ μέρη τῆς Εὐρώπης, ἔτι δ’ ἐπιπλοκὴ μετὰ πρεσβείας εἰς τοὺς κατὰ τὴν Ἑλλάδα τόπους τοιάδε καὶ διὰ ταύτας ἐγένετο τὰς αἰτίας. ἀπὸ δὲ ταύτης τῆς καταρχῆς Ῥωμαῖοι μὲν εὐθέως ἄλλους πρεσβευτὰς ἐξαπέστειλαν πρὸς Κορινθίους καὶ πρὸς Ἀθηναίους, ὅτε δὴ καὶ Κορίνθιοι πρῶτον ἀπεδέξαντο μετέχειν Ῥωμαίους τοῦ τῶν Ἰσθμίων ἀγῶνος.", "st": "2.12"}, {"sp": "N", "t": "Ἀσδρούβας δὲ κατὰ τοὺς αὐτοὺς χρόνους — ἐν γὰρ τούτοις ἀπελίπομεν τὰ κατὰ τὴν Ἰβηρίαν — νουνεχῶς καὶ πραγματικῶς χειρίζων τὰ κατὰ τὴν ἀρχὴν ἔν τε τοῖς ὅλοις μεγάλην ἐποιεῖτο προκοπήν, τήν τε παρὰ μὲν τισὶ Καρχηδόνα, παρὰ δὲ τισὶ Καινὴν πόλιν προσαγορευομένην κατασκευάσας οὐ μικρά, μεγάλα δὲ συνεβάλλετο Καρχηδονίοις εἰς πραγμάτων λόγον, καὶ μάλιστα διὰ τὴν εὐκαιρίαν τοῦ τόπου πρός τε τὰ κατὰ τὴν Ἰβηρίαν πράγματα καὶ πρὸς τὰ κατὰ τὴν Λιβύην, περὶ ἧς ἡμεῖς εὐφυέστερον καιρὸν λαβόντες ὑποδείξομεν τὴν θέσιν αὐτῆς καὶ τὴν χρείαν, ἣν ἀμφοτέραις δύναται παρέχεσθαι ταῖς εἰρημέναις χώραις. ὃν καὶ θεωροῦντες Ῥωμαῖοι μείζω καὶ φοβερωτέραν ἤδη συνιστάμενον δυναστείαν, ὥρμησαν ἐπὶ τὸ πολυπραγμονεῖν τὰ κατὰ τὴν Ἰβηρίαν. εὑρόντες δὲ σφᾶς ἐπικεκοιμημένους ἐν τοῖς ἔμπροσθεν χρόνοις καὶ προειμένους εἰς τὸ μεγάλην χεῖρα κατασκευάσασθαι Καρχηδονίους, ἀνατρέχειν ἐπειρῶντο κατὰ δύναμιν. αὐτόθεν μὲν οὖν ἐπιτάττειν ἢ πολεμεῖν οὐ κατετόλμων τοῖς Καρχηδονίοις διὰ τὸ τὸν ἀπὸ τῶν Κελτῶν φόβον ἐπικρέμασθαι τοῖς σφετέροις πράγμασιν καὶ μόνον οὐ καθ’ ἑκάστην ἡμέραν προσδοκᾶν τὴν ἔφοδον αὐτῶν. καταψήσαντες δὲ καὶ πραΰναντες τὸν Ἀσδρούβαν, οὕτως ἔκριναν ἐγχειρεῖν τοῖς Κελτοῖς καὶ διακινδυνεύειν πρὸς αὐτούς, οὐδέποτ’ ἂν ὑπολαμβάνοντες οὐχ οἷον δυναστεῦσαι τῶν κατὰ τὴν Ἰταλίαν, ἀλλ’ οὐδ’ ἀσφαλῶς οἰκῆσαι τὴν ἑαυτῶν πατρίδα, τούτους ἔχοντες ἐφέδρους τοὺς ἄνδρας. διόπερ ἅμα τῷ διαπρεσβευσάμενοι πρὸς τὸν Ἀσδρούβαν ποιήσασθαι συνθήκας, ἐν αἷς τὴν μὲν ἄλλην Ἰβηρίαν παρεσιώπων, τὸν δὲ καλούμενον Ἴβηρα ποταμὸν οὐκ ἔδει Καρχηδονίους ἐπὶ πολέμῳ διαβαίνειν, εὐθέως ἐξήνεγκαν τὸν πρὸς τοὺς κατὰ τὴν Ἰταλίαν Κελτοὺς πόλεμον.", "st": "2.13"}, {"sp": "N", "t": "ὑπὲρ ὧν δοκεῖ μοι χρήσιμον εἶναι κεφαλαιώδη μὲν ποιήσασθαι τὴν ἐξήγησιν, ἵνα τὸ τῆς προκατασκευῆς οἰκεῖον συσσώσωμεν κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν, ἀναδραμεῖν δὲ τοῖς χρόνοις ἐπὶ τὴν ἀρχήν, ἐξ ὅτου κατέσχον οἱ προειρημένοι τὴν χώραν· ἡγοῦμαι γὰρ τὴν περὶ αὐτῶν ἱστορίαν οὐ μόνον ἀξίαν εἶναι γνώσεως καὶ μνήμης, ἀλλὰ καὶ τελέως ἀναγκαίαν χάριν τοῦ μαθεῖν τίσι μετὰ ταῦτα πιστεύσας ἀνδράσι καὶ τόποις Ἀννίβας ἐπεβάλετο καταλύειν τὴν Ῥωμαίων δυναστείαν. πρῶτον δὲ περὶ τῆς χώρας ῥητέον ποία τίς ἐστιν καὶ πῶς κεῖται πρὸς τὴν ἄλλην Ἰταλίαν. οὕτως γὰρ ἔσται καὶ τὰ περὶ τὰς πράξεις διαφέροντα κατανοεῖν βέλτιον, ὑπογραφέντων τῶν περί τε τοὺς τόπους καὶ τὴν χώραν ἰδιωμάτων. τῆς δὴ συμπάσης Ἰταλίας τῷ σχήματι τριγωνοειδοῦς ὑπαρχούσης, τὴν μὲν μίαν ὁρίζει πλευρὰν αὐτῆς τὴν πρὸς τὰς ἀνατολὰς κεκλιμένην ὅ τ’ Ἰόνιος πόρος καὶ κατὰ τὸ συνεχὲς ὁ κατὰ τὸν Ἀδρίαν κόλπος, τὴν δὲ πρὸς μεσημβρίαν καὶ δυσμὰς τετραμμένην τὸ Σικελικὸν καὶ Τυρρηνικὸν πέλαγος. αὗται δ’ αἱ πλευραὶ συμπίπτουσαι πρὸς ἀλλήλας κορυφὴν ποιοῦσι τοῦ τριγώνου τὸ προκείμενον ἀκρωτήριον τῆς Ἰταλίας εἰς τὴν μεσημβρίαν, ὃ προσαγορεύεται μὲν Κόκυνθος, διαιρεῖ δὲ τὸν Ἰόνιον πόρον καὶ τὸ Σικελικὸν πέλαγος. τὴν δὲ λοιπὴν τὴν παρά τε τὰς ἄρκτους καὶ τὴν μεσόγαιαν παρατείνουσαν ὁρίζει κατὰ τὸ συνεχὲς ἡ τῶν Ἄλπεων παρώρεια, λαμβάνουσα τὴν μὲν ἀρχὴν ἀπὸ Μασσαλίας καὶ τῶν ὑπὲρ τὸ Σαρδῷον πέλαγος τόπων, παρήκουσα δὲ συνεχῶς μέχρι πρὸς τὸν τοῦ παντὸς Ἀδρίου μυχόν, πλὴν βραχέος, ὃ προκαταλήγουσα λείπει τοῦ μὴ συνάπτειν αὐτῷ. παρὰ δὲ τὴν προειρημένην παρώρειαν, ἣν δεῖ νοεῖν ὡσανεὶ βάσιν τοῦ τριγώνου, παρὰ ταύτην ἀπὸ μεσημβρίας ὑπόκειται πεδία τῆς συμπάσης Ἰταλίας τελευταῖα πρὸς τὰς ἄρκτους, ὑπὲρ ὧν ὁ νῦν δὴ λόγος, ἀρετῇ καὶ μεγέθει διαφέροντα τῶν κατὰ τὴν Εὐρώπην, ὅσα πέπτωκεν ὑπὸ τὴν ἡμετέραν ἱστορίαν. ἔστι δὲ τὸ μὲν ὅλον εἶδος καὶ τῆς ταῦτα τὰ πεδία περιγραφούσης γραμμῆς τριγωνοειδές. τούτου δὲ τοῦ σχήματος τὴν μὲν κορυφὴν ἥ τε τῶν Ἀπεννίνων καλουμένων ὀρῶν καὶ τῶν Ἀλπεινῶν σύμπτωσις οὐ μακρὰν ἀπὸ τοῦ Σαρδῴου πελάγους ὑπὲρ Μασσαλίας ἀποτελεῖ. τῶν δὲ πλευρῶν παρὰ μὲν τὴν ἀπὸ τῶν ἄρκτων, ὡς ἐπάνω προεῖπον, τὰς Ἄλπεις αὐτὰς ἐπὶ δισχιλίους καὶ διακοσίους σταδίους παρήκειν συμβαίνει, παρὰ δὲ τὴν ἀπὸ μεσημβρίας τὸν Ἀπεννῖνον ἐπὶ τρισχιλίους ἑξακοσίους. βάσεώς γε μὴν τάξιν λαμβάνει τοῦ παντὸς σχήματος ἡ παραλία τοῦ κατὰ τὸν Ἀδρίαν κόλπου· τὸ δὲ μέγεθος τῆς βάσεώς ἐστιν ἀπὸ πόλεως Σήνης ἕως ἐπὶ τὸν μυχὸν ὑπὲρ τοὺς δισχιλίους σταδίους καὶ πεντακοσίους, ὥστε τὴν πᾶσαν περίμετρον τῶν προειρημένων πεδίων μὴ πολὺ λείπειν τῶν μυρίων σταδίων.", "st": "2.14"}, {"sp": "N", "t": "περί γε μὴν τῆς ἀρετῆς οὐδ’ εἰπεῖν ῥᾴδιον. σίτου τε γὰρ τοσαύτην ἀφθονίαν ὑπάρχειν συμβαίνει κατὰ τοὺς τόπους ὥστ’ ἐν τοῖς καθ’ ἡμᾶς καιροῖς πολλάκις τεττάρων ὀβολῶν εἶναι τῶν πυρῶν τὸν Σικελικὸν μέδιμνον, τῶν δὲ κριθῶν δυεῖν, τοῦ δ’ οἴνου τὸν μετρητὴν ἰσόκριθον. ἐλύμου γε μὴν καὶ κέγχρου τελέως ὑπερβάλλουσα δαψίλεια γίνεται παρ’ αὐτοῖς. τὸ δὲ τῶν βαλάνων πλῆθος τὸ γινόμενον ἐκ τῶν κατὰ διάστημα δρυμῶν ἐν τοῖς πεδίοις ἐκ τούτων ἄν τις μάλιστα τεκμήραιτο· πλείστων γὰρ ὑϊκῶν ἱερείων κοπτομένων ἐν Ἰταλίᾳ διά τε τὰς εἰς τοὺς ἰδίους βίους καὶ τὰς εἰς τὰ στρατόπεδα παραθέσεις, τὴν ὁλοσχερεστάτην χορηγίαν ἐκ τούτων συμβαίνει τῶν πεδίων αὐτοῖς ὑπάρχειν. περὶ δὲ τῆς κατὰ μέρος εὐωνίας καὶ δαψιλείας τῶν πρὸς τὴν τροφὴν ἀνηκόντων οὕτως ἄν τις ἀκριβέστατα κατανοήσειεν· ποιοῦνται γὰρ τὰς καταλύσεις οἱ διοδεύοντες τὴν χώραν ἐν τοῖς πανδοκείοις, οὐ συμφωνοῦντες περὶ τῶν κατὰ μέρος ἐπιτηδείων, ἀλλ’ ἐρωτῶντες πόσου τὸν ἄνδρα δέχεται. ὡς μὲν οὖν ἐπὶ τὸ πολὺ παρίενται τοὺς καταλύτας οἱ πανδοκεῖς, ὡς ἱκανὰ πάντ’ ἔχειν τὰ πρὸς τὴν χρείαν, ἡμιασσαρίου· τοῦτο δ’ ἔστι τέταρτον μέρος ὀβολοῦ· σπανίως δὲ τοῦθ’ ὑπερβαίνουσι. τό γε μὴν πλῆθος τῶν ἀνδρῶν καὶ τὸ μέγεθος καὶ κάλλος τῶν σωμάτων, ἔτι δὲ τὴν ἐν τοῖς πολέμοις τόλμαν ἐξ αὐτῶν τῶν πράξεων σαφῶς ἔσται καταμαθεῖν. τῶν δ’ Ἄλπεων ἑκατέρας τῆς πλευρᾶς, τῆς ἐπὶ τὸν Ῥοδανὸν ποταμὸν καὶ τῆς ἐπὶ τὰ προειρημένα πεδία νευούσης, τοὺς βουνώδεις καὶ γεώδεις τόπους κατοικοῦσι τοὺς μὲν ἐπὶ τὸν Ῥοδανὸν καὶ τὰς ἄρκτους ἐστραμμένους Γαλάται Τρανσαλπῖνοι προσαγορευόμενοι, τοὺς δ’ ἐπὶ τὰ πεδία Ταυρίσκοι καὶ Ἄγωνες καὶ πλείω γένη βαρβάρων ἕτερα. Τρανσαλπῖνοί γε μὴν οὐ διὰ τὴν τοῦ γένους, ἀλλὰ διὰ τὴν τοῦ τόπου διαφορὰν προσαγορεύονται· τὸ γὰρ τρὰνς ἐξερμηνευόμενόν ἐστι πέραν, διὸ τοὺς ἐπέκεινα τῶν Ἄλπεων Τρανσαλπίνους καλοῦσι. τὰ δ’ ἄκρα διά τε τὴν τραχύτητα καὶ τὸ πλῆθος τῆς ἐπιμενούσης ἀεὶ χιόνος ἀοίκητα τελέως ἐστίν.", "st": "2.15"}, {"sp": "N", "t": "τὸν δ’ Ἀπεννῖνον ἀπὸ μὲν τῆς ἀρχῆς τῆς ὑπὲρ Μασσαλίαν καὶ τῆς πρὸς τὰς Ἄλπεις συμπτώσεως Λιγυστῖνοι κατοικοῦσιν, καὶ τὴν ἐπὶ τὸ Τυρρηνικὸν πέλαγος αὐτοῦ πλευρὰν κεκλιμένην καὶ τὴν ἐπὶ τὰ πεδία, παρὰ θάλατταν μὲν μέχρι πόλεως Πίσης, ἣ πρώτη κεῖται τῆς Τυρρηνίας ὡς πρὸς τὰς δυσμάς, κατὰ δὲ τὴν μεσόγαιον ἕως τῆς Ἀρρητίνων χώρας. ἑξῆς δὲ Τυρρηνοί· τούτοις δὲ συνεχεῖς ἑκάτερον τὸ κλίμα νέμονται τῶν προειρημένων ὀρῶν Ὄμβροι. λοιπὸν ὁ μὲν Ἀπεννῖνος ἀπέχων τῆς κατὰ τὸν Ἀδρίαν θαλάττης σταδίους ὡσανεὶ πεντακοσίους ἀπολείπει τὰ πεδία δεξιὸς ἀπονεύων, καὶ διὰ μέσης τῆς λοιπῆς Ἰταλίας διήκων εἰς τὸ Σικελικὸν κατατείνει πέλαγος. τὸ δ’ ἀπολειπόμενον μέρος πεδινὸν τῆς πλευρᾶς ἐπὶ θάλατταν καὶ πόλιν καθήκει Σήνην. ὁ δὲ Πάδος ποταμός, ὑπὸ δὲ τῶν ποιητῶν Ἠριδανὸς θρυλούμενος, ἔχει μὲν τὰς πηγὰς ἀπὸ τῶν Ἄλπεων ὡς πρὸς τὴν κορυφὴν μᾶλλον τοῦ προειρημένου σχήματος, καταφέρεται δ’ εἰς τὰ πεδία, ποιούμενος τὴν ῥύσιν ὡς ἐπὶ μεσημβρίαν. ἀφικόμενος δ’ εἰς τοὺς ἐπιπέδους τόπους, ἐκκλίνας τῷ ῥεύματι πρὸς ἕω φέρεται δι’ αὐτῶν· ποιεῖ δὲ τὴν ἐκβολὴν δυσὶ στόμασιν εἰς τοὺς κατὰ τὸν Ἀδρίαν τόπους· τὸ δὲ πλεῖον ἀποτέμνεται μέρος τῆς πεδιάδος χώρας εἰς τὰς Ἄλπεις καὶ τὸν Ἀδριατικὸν μυχόν. ἄγει δὲ πλῆθος ὕδατος οὐδενὸς ἔλαττον τῶν κατὰ τὴν Ἰταλίαν ποταμῶν διὰ τὸ τὰς ῥύσεις τὰς ἐπὶ τὰ πεδία νευούσας ἀπό τε τῶν Ἄλπεων καὶ τῶν Ἀπεννίνων ὀρῶν εἰς τοῦτον ἐμπίπτειν ἁπάσας καὶ πανταχόθεν. μεγίστῳ δὲ καὶ καλλίστῳ ῥεύματι φέρεται περὶ κυνὸς ἐπιτολήν, αὐξόμενος ὑπὸ τοῦ πλήθους τῶν ἀνατηκομένων χιόνων ἐν τοῖς προειρημένοις ὄρεσιν. ἀναπλεῖται δ’ ἐκ θαλάττης κατὰ τὸ στόμα τὸ καλούμενον Ὄλανα σχεδὸν ἐπὶ δισχιλίους σταδίους. τὴν μὲν γὰρ πρώτην ἐκ τῶν πηγῶν ἔχει ῥύσιν ἁπλῆν, σχίζεται δ’ εἰς δύο μέρη κατὰ τοὺς προσαγορευομένους Τριγαβόλους· τούτων δὲ τὸ μὲν ἕτερον στόμα προσονομάζεται Παδόα, τὸ δ’ ἕτερον Ὄλανα. κεῖται δ’ ἐπὶ τούτῳ λιμήν, οὐδενὸς τῶν κατὰ τὸν Ἀδρίαν ἥττω παρεχόμενος ἀσφάλειαν τοῖς ἐν αὐτῷ καθορμιζομένοις. παρά γε μὴν τοῖς ἐγχωρίοις ὁ ποταμὸς προσαγορεύεται Βόδεγκος. τἄλλα δὲ τὰ περὶ τὸν ποταμὸν τοῦτον ἱστορούμενα παρὰ τοῖς Ἕλλησι, λέγω δὴ τὰ περὶ Φαέθοντα καὶ τὴν ἐκείνου πτῶσιν, ἔτι δὲ τὰ δάκρυα τῶν αἰγείρων καὶ τοὺς μελανείμονας τοὺς περὶ τὸν ποταμὸν οἰκοῦντας, οὕς φασι τὰς ἐσθῆτας εἰσέτι νῦν φορεῖν τοιαύτας ἀπὸ τοῦ κατὰ Φαέθοντα πένθους, καὶ πᾶσαν δὴ τὴν τραγικὴν καὶ ταύτῃ προσεοικυῖαν ὕλην ἐπὶ μὲν τοῦ παρόντος ὑπερθησόμεθα διὰ τὸ μὴ λίαν καθήκειν τῷ τῆς προκατασκευῆς γένει τὴν περὶ τῶν τοιούτων ἀκριβολογίαν. μεταλαβόντες δὲ καιρὸν ἁρμόττοντα ποιησόμεθα τὴν καθήκουσαν μνήμην, καὶ μάλιστα διὰ τὴν Τιμαίου περὶ τοὺς προειρημένους τόπους ἄγνοιαν.", "st": "2.16"}, {"sp": "N", "t": "πλὴν ταῦτά γε τὰ πεδία τὸ παλαιὸν ἐνέμοντο Τυρρηνοί, καθ’ οὓς χρόνους καὶ τὰ Φλέγραιά ποτε καλούμενα τὰ περὶ Καπύην καὶ Νώλην· ἃ δὴ καὶ διὰ τὸ πολλοῖς ἐμποδὼν εἶναι καὶ γνωρίζεσθαι μεγάλην ἐπ’ ἀρετῇ δόξαν εἴληφεν. διὸ καὶ τοὺς ἱστοροῦντας τὰς Τυρρηνῶν δυναστείας οὐ χρὴ ποιεῖσθαι τὴν ἀναφορὰν ἐπὶ τὴν νῦν κατεχομένην ὑπ’ αὐτῶν χώραν, ἀλλ’ ἐπὶ τὰ προειρημένα πεδία καὶ τὰς ἐκ τούτων τῶν τόπων ἀφορμάς. οἷς ἐπιμιγνύμενοι κατὰ τὴν παράθεσιν Κελτοὶ καὶ περὶ τὸ κάλλος τῆς χώρας ὀφθαλμιάσαντες, ἐκ μικρᾶς προφάσεως μεγάλῃ στρατιᾷ παραδόξως ἐπελθόντες ἐξέβαλον ἐκ τῆς περὶ τὸν Πάδον χώρας Τυρρηνοὺς καὶ κατέσχον αὐτοὶ τὰ πεδία. τὰ μὲν οὖν πρῶτα καὶ περὶ τὰς ἀνατολὰς τοῦ Πάδου κείμενα Λάοι καὶ Λεβέκιοι, μετὰ δὲ τούτους Ἴνσοβρες κατῴκησαν, ὃ μέγιστον ἔθνος ἦν αὐτῶν· ἑξῆς δὲ τούτοις παρὰ τὸν ποταμὸν Γονομάνοι. τὰ δὲ πρὸς τὸν Ἀδρίαν ἤδη προσήκοντα γένος ἄλλο πάνυ παλαιὸν διακατέσχεν· προσαγορεύονται δ’ Οὐένετοι, τοῖς μὲν ἔθεσι καὶ τῷ κόσμῳ βραχεῖ διαφέροντες Κελτῶν, γλώττῃ δ’ ἀλλοίᾳ χρώμενοι. περὶ ὧν οἱ τραγῳδιογράφοι πολύν τινα πεποίηνται λόγον καὶ πολλὴν διατέθεινται τερατείαν. τὰ δὲ πέραν τοῦ Πάδου τὰ περὶ τὸν Ἀπεννῖνον πρῶτοι μὲν Ἄναρες, μετὰ δὲ τούτους Βοῖοι κατῴκησαν· ἑξῆς δὲ τούτων ὡς πρὸς τὸν Ἀδρίαν Λίγγονες, τὰ δὲ τελευταῖα πρὸς θαλάττῃ Σήνωνες. τὰ μὲν οὖν ἐπιφανέστατα τῶν κατασχόντων τοὺς προειρημένους τόπους ἐθνῶν ταῦθ’ ὑπῆρχεν. ᾤκουν δὲ κατὰ κώμας ἀτειχίστους, τῆς λοιπῆς κατασκευῆς ἄμοιροι καθεστῶτες. διὰ γὰρ τὸ στιβαδοκοιτεῖν καὶ κρεαφαγεῖν, ἔτι δὲ μηδὲν ἄλλο πλὴν τὰ πολεμικὰ καὶ τὰ κατὰ γεωργίαν· ἀσκεῖν ἁπλοῦς εἶχον τοὺς βίους, οὔτ’ ἐπιστήμης ἄλλης οὔτε τέχνης παρ’ αὐτοῖς τὸ παράπαν γινωσκομένης. ὕπαρξίς γε μὴν ἑκάστοις ἦν θρέμματα καὶ χρυσὸς διὰ τὸ μόνα ταῦτα κατὰ τὰς περιστάσεις ῥᾳδίως δύνασθαι πανταχῇ περιαγαγεῖν καὶ μεθιστάναι κατὰ τὰς αὑτῶν προαιρέσεις. περὶ δὲ τὰς ἑταιρείας μεγίστην σπουδὴν ἐποιοῦντο διὰ τὸ καὶ φοβερώτατον καὶ δυνατώτατον εἶναι παρ’ αὐτοῖς τοῦτον ὃς ἂν πλείστους ἔχειν δοκῇ τοὺς θεραπεύοντας καὶ συμπεριφερομένους αὐτῷ.", "st": "2.17"}, {"sp": "N", "t": "τὰς μὲν οὖν ἀρχὰς οὐ μόνον τῆς χώρας ἐπεκράτουν, ἀλλὰ καὶ τῶν σύνεγγυς πολλοὺς ὑπηκόους ἐπεποίηντο, τῇ τόλμῃ καταπεπληγμένοι. μετὰ δέ τινα χρόνον μάχῃ νικήσαντες Ῥωμαίους καὶ τοὺς μετὰ τούτων παραταξαμένους, ἑπόμενοι τοῖς φεύγουσι τρισὶ τῆς μάχης ἡμέραις ὕστερον κατέσχον αὐτὴν τὴν Ῥώμην πλὴν τοῦ Καπετωλίου. γενομένου δ’ ἀντισπάσματος, καὶ τῶν Οὐενέτων ἐμβαλόντων εἰς τὴν χώραν αὐτῶν, τότε μὲν ποιησάμενοι συνθήκας πρὸς Ῥωμαίους καὶ τὴν πόλιν ἀποδόντες ἐπανῆλθον εἰς τὴν οἰκείαν. μετὰ δὲ ταῦτα τοῖς ἐμφυλίοις συνείχοντο πολέμοις· ἔνιοι δὲ καὶ τῶν τὰς Ἄλπεις κατοικούντων ὁρμὰς ἐποιοῦντο καὶ συνηθροίζοντο πολλάκις ἐπ’ αὐτούς, θεωροῦντες ἐκ παραθέσεως τὴν παραγεγενημένην αὐτοῖς εὐδαιμονίαν. ἐν ᾧ καιρῷ Ῥωμαῖοι τήν τε σφετέραν δύναμιν ἀνέλαβον καὶ τὰ κατὰ τοὺς Λατίνους αὖθις πράγματα συνεστήσαντο. παραγενομένων δὲ πάλιν τῶν Κελτῶν εἰς Ἄλβαν στρατεύματι μεγάλῳ μετὰ τὴν τῆς πόλεως κατάληψιν ἔτει τριακοστῷ, τότε μὲν οὐκ ἐτόλμησαν ἀντεξαγαγεῖν Ῥωμαῖοι τὰ στρατόπεδα διὰ τὸ παραδόξου γενομένης τῆς ἐφόδου προκαταληφθῆναι καὶ μὴ καταταχῆσαι τὰς τῶν συμμάχων ἁθροίσαντας δυνάμεις. αὖθις δ’ ἐξ ἐπιβολῆς ἑτέρας ἔτει δωδεκάτῳ μετὰ μεγάλης στρατιᾶς ἐπιπορευομένων προαισθόμενοι καὶ συναγείραντες τοὺς συμμάχους μετὰ πολλῆς προθυμίας ἀπήντων, σπεύδοντες συμβαλεῖν καὶ διακινδυνεῦσαι περὶ τῶν ὅλων. οἱ δὲ Γαλάται καταπλαγέντες τὴν ἔφοδον αὐτῶν καὶ διαστασιάσαντες πρὸς σφᾶς νυκτὸς ἐπιγενομένης φυγῇ παραπλησίαν ἐποιήσαντο τὴν ἀποχώρησιν εἰς τὴν οἰκείαν. ἀπὸ δὲ τούτου τοῦ φόβου τριακαίδεκα μὲν ἔτη τὴν ἡσυχίαν ἔσχον, μετὰ δὲ ταῦτα συνορῶντες αὐξανομένην τὴν Ῥωμαίων δύναμιν εἰρήνην ἐποιήσαντο καὶ συνθήκας.", "st": "2.18"}, {"sp": "N", "t": "ἐν αἷς ἔτη τριάκοντα μείναντες ἐμπεδῶς, αὖθις γενομένου κινήματος ἐκ τῶν Τρανσαλπίνων, δείσαντες μὴ πόλεμος αὐτοῖς ἐγερθῇ βαρύς, ἀπὸ μὲν αὑτῶν ἔτρεψαν τὰς ὁρμὰς τῶν ἐξανισταμένων, δωροφοροῦντες καὶ προτιθέμενοι τὴν συγγένειαν, ἐπὶ δὲ Ῥωμαίους παρώξυναν καὶ μετέσχον αὐτοῖς τῆς στρατείας. ἐν ᾗ τὴν ἔφοδον ποιησάμενοι διὰ Τυρρηνίας, ὁμοῦ συστρατευσαμένων σφίσι Τυρρηνῶν, καὶ περιβαλόμενοι λείας πλῆθος ἐκ μὲν τῆς Ῥωμαίων ἐπαρχίας ἀσφαλῶς ἐπανῆλθον. εἰς δὲ τὴν οἰκείαν ἀφικόμενοι καὶ στασιάσαντες περὶ τὴν τῶν εἰλημμένων πλεονεξίαν τῆς τε λείας καὶ τῆς αὑτῶν δυνάμεως τὸ πλεῖστον μέρος διέφθειραν. τοῦτο δὲ σύνηθές ἐστι Γαλάταις πράττειν, ἐπειδὰν σφετερίσωνταί τι τῶν πέλας, καὶ μάλιστα διὰ τὰς ἀλόγους οἰνοφλυγίας καὶ πλησμονάς. μετὰ δὲ ταῦτα πάλιν ἔτει τετάρτῳ συμφρονήσαντες ἅμα Σαυνῖται καὶ Γαλάται παρετάξαντο Ῥωμαίοις ἐν τῇ Καμερτίων χώρᾳ καὶ πολλοὺς αὐτῶν ἐν τῷ κινδύνῳ διέφθειραν. ἐν ᾧ καιρῷ προσφιλονικήσαντες πρὸς τὸ γεγονὸς ἐλάττωμ’ αὐτοῖς Ῥωμαῖοι μετ’ ὀλίγας ἡμέρας ἐξῆλθον καὶ συμβαλόντες πᾶσι τοῖς στρατοπέδοις ἐν τῇ τῶν Σεντινατῶν χώρᾳ πρὸς τοὺς προειρημένους τοὺς μὲν πλείστους ἀπέκτειναν, τοὺς δὲ λοιποὺς ἠνάγκασαν προτροπάδην ἑκάστους εἰς τὴν οἰκείαν φυγεῖν. διαγενομένων δὲ πάλιν ἐτῶν δέκα παρεγένοντο Γαλάται μετὰ μεγάλης στρατιᾶς, πολιορκήσοντες τὴν Ἀρρητίνων πόλιν. Ῥωμαῖοι δὲ παραβοηθήσαντες καὶ συμβαλόντες πρὸ τῆς πόλεως ἡττήθησαν. ἐν δὲ τῇ μάχῃ ταύτῃ Λευκίου τοῦ στρατηγοῦ τελευτήσαντος Μάνιον ἐπικατέστησαν τὸν Κόριον. οὗ πρεσβευτὰς ἐκπέμψαντος εἰς Γαλατίαν ὑπὲρ τῶν αἰχμαλώτων, παρασπονδήσαντες ἐπανείλοντο τοὺς πρέσβεις. τῶν δὲ Ῥωμαίων ὑπὸ τὸν θυμὸν ἐκ χειρὸς ἐπιστρατευσαμένων, ἀπαντήσαντες συνέβαλλον οἱ Σήνωνες καλούμενοι Γαλάται. Ῥωμαῖοι δ’ ἐκ παρατάξεως κρατήσαντες αὐτῶν τοὺς μὲν πλείστους ἀπέκτειναν, τοὺς δὲ λοιποὺς ἐξέβαλον, τῆς δὲ χώρας ἐγένοντο πάσης ἐγκρατεῖς. εἰς ἣν καὶ πρώτην τῆς Γαλατίας ἀποικίαν ἔστειλαν τὴν Σήνην προσαγορευομένην πόλιν, ὁμώνυμον οὖσαν τοῖς πρότερον αὐτὴν κατοικοῦσι Γαλάταις, ὑπὲρ ἧς ἀρτίως διεσαφήσαμεν, φάσκοντες αὐτὴν παρὰ τὸν Ἀδρίαν ἐπὶ τῷ πέρατι κεῖσθαι τῶν περὶ τὸν Πάδον πεδίων.", "st": "2.19"}, {"sp": "N", "t": "οἱ δὲ Βοῖοι θεωροῦντες ἐκπεπτωκότας τοὺς Σήνωνας, καὶ δείσαντες περὶ σφῶν καὶ τῆς χώρας μὴ πάθωσι τὸ παραπλήσιον ἐξεστράτευσαν πανδημεὶ παρακαλέσαντες Τυρρηνούς. ἁθροισθέντες δὲ περὶ τὴν Ὀάδμονα προσαγορευομένην λίμνην παρετάξαντο Ῥωμαίοις. ἐν δὲ τῇ μάχῃ ταύτῃ Τυρρηνῶν μὲν οἱ πλεῖστοι κατεκόπησαν, τῶν δὲ Βοίων τελέως ὀλίγοι διέφυγον. οὐ μὴν ἀλλὰ τῷ κατὰ πόδας ἐνιαυτῷ συμφρονήσαντες αὖθις οἱ προειρημένοι καὶ τοὺς ἄρτι τῶν νέων ἡβῶντας καθοπλίσαντες παρετάξαντο πρὸς Ῥωμαίους. ἡττηθέντες δ’ ὁλοσχερῶς τῇ μάχῃ μόλις εἶξαν ταῖς ψυχαῖς καὶ διαπρεσβευσάμενοι περὶ σπονδῶν καὶ διαλύσεων συνθήκας ἔθεντο πρὸς Ῥωμαίους. ταῦτα δὲ συνέβαινεν γίνεσθαι τῷ τρίτῳ πρότερον ἔτει τῆς Πύρρου διαβάσεως εἰς τὴν Ἰταλίαν, πέμπτῳ δὲ τῆς Γαλατῶν περὶ Δελφοὺς διαφθορᾶς. ἐν γὰρ τούτοις ἡ τύχη τοῖς καιροῖς ὡσανεὶ λοιμικήν τινα πολέμου διάθεσιν ἐπέστησε πᾶσι Γαλάταις. ἐκ δὲ τῶν προειρημένων ἀγώνων δύο τὰ κάλλιστα συνεκύρησε Ῥωμαίοις· τοῦ γὰρ κατακόπτεσθαι συνήθειαν ἐσχηκότες ὑπὸ Γαλατῶν οὐδὲν ἠδύναντο δεινότερον ἰδεῖν οὐδὲ προσδοκῆσαι τῶν αὐτοῖς ἤδη πεπραγμένων· ἐξ ὧν πρός τε Πύρρον ἀθληταὶ τέλειοι γεγονότες τῶν κατὰ πόλεμον ἔργων συγκατέστησαν, τήν τε Γαλατῶν τόλμαν ἐν καιρῷ καταπληξάμενοι λοιπὸν ἀπερισπάστως τὸ μὲν πρῶτον πρὸς Πύρρον περὶ τῆς Ἰταλίας ἐπολέμουν, μετὰ δὲ ταῦτα πρὸς Καρχηδονίους ὑπὲρ τῆς Σικελιωτῶν ἀρχῆς διηγωνίζοντο.", "st": "2.20"}, {"sp": "N", "t": "Γαλάται δ’ ἐκ τῶν προειρημένων ἐλαττωμάτων ἔτη μὲν πέντε καὶ τετταράκοντα τὴν ἡσυχίαν ἔσχον, εἰρήνην ἄγοντες πρὸς Ῥωμαίους. ἐπεὶ δ’ οἱ μὲν αὐτόπται γεγονότες τῶν δεινῶν ἐκ τοῦ ζῆν ἐξεχώρησαν διὰ τὸν χρόνον, ἐπεγένοντο δὲ νέοι, θυμοῦ μὲν ἀλογίστου πλήρεις, ἄπειροι δὲ καὶ ἀόρατοι παντὸς κακοῦ καὶ πάσης περιστάσεως, αὖθις ἤρξαντο τὰ καθεστῶτα κινεῖν, ὃ φύσιν ἔχει γίνεσθαι καὶ τραχύνεσθαι μὲν ἐκ τῶν τυχόντων πρὸς Ῥωμαίους, ἐπισπᾶσθαι δὲ τοὺς ἐκ τῶν Ἄλπεων Γαλάτας. τὸ μὲν οὖν πρῶτον χωρὶς τοῦ πλήθους δι’ αὐτῶν τῶν ἡγουμένων ἐν ἀπορρήτοις ἐπράττετο τὰ προειρημένα. διὸ καὶ παραγενομένων τῶν Τρανσαλπίνων ἕως Ἀριμίνου μετὰ δυνάμεως, διαπιστήσαντα τὰ πλήθη τῶν Βοίων καὶ στασιάσαντα πρός τε τοὺς ἑαυτῶν προεστῶτας καὶ πρὸς τοὺς παραγεγονότας ἀνεῖλον μὲν τοὺς ἰδίους βασιλεῖς Ἄτιν καὶ Γάλατον, κατέκοψαν δ’ ἀλλήλους, συμβαλόντες ἐκ παρατάξεων. ὅτε δὴ καὶ Ῥωμαῖοι κατάφοβοι γενόμενοι τὴν ἔφοδον ἐξῆλθον μετὰ στρατοπέδου· συνέντες δὲ τὴν αὐθαίρετον καταφθορὰν τῶν Γαλατῶν αὖθις ἀνεχώρησαν εἰς τὴν οἰκείαν. μετὰ δὲ τοῦτον τὸν φόβον ἔτει πέμπτῳ, Μάρκου Λεπέδου στρατηγοῦντος, κατεκληρούχησαν ἐν Γαλατίᾳ Ῥωμαῖοι τὴν Πικεντίνην προσαγορευομένην χώραν, ἐξ ἧς νικήσαντες ἐξέβαλον τοὺς Σήνωνας προσαγορευομένους Γαλάτας, Γαΐου Φλαμινίου ταύτην τὴν δημαγωγίαν εἰσηγησαμένου καὶ πολιτείαν, ἣν δὴ καὶ Ῥωμαίοις ὡς ἔπος εἰπεῖν φατέον ἀρχηγὸν μὲν γενέσθαι τῆς ἐπὶ τὸ χεῖρον τοῦ δήμου διαστροφῆς, αἰτίαν δὲ καὶ τοῦ μετὰ ταῦτα πολέμου συστάντος αὐτοῖς πρὸς τοὺς προειρημένους. πολλοὶ μὲν γὰρ τῶν Γαλατῶν ὑπεδύοντο τὴν πρᾶξιν, μάλιστα δ’ οἱ Βοῖοι διὰ τὸ συντερμονεῖν τῇ τῶν Ῥωμαίων χώρᾳ, νομίσαντες οὐχ ὑπὲρ ἡγεμονίας ἔτι καὶ δυναστείας Ῥωμαίους τὸν πρὸς αὐτοὺς ποιήσασθαι πόλεμον, ἀλλ’ ὑπὲρ ὁλοσχεροῦς ἐξαναστάσεως καὶ καταφθορᾶς.", "st": "2.21"}, {"sp": "N", "t": "διόπερ εὐθέως τὰ μέγιστα τῶν ἐθνῶν, τό τε τῶν Ἰνσόμβρων καὶ Βοίων, συμφρονήσαντα διεπέμποντο πρὸς τοὺς κατὰ τὰς Ἄλπεις καὶ περὶ τὸν Ῥοδανὸν ποταμὸν κατοικοῦντας Γαλάτας, προσαγορευομένους δὲ διὰ τὸ μισθοῦ στρατεύειν Γαισάτους· ἡ γὰρ λέξις αὕτη τοῦτο σημαίνει κυρίως. ὧν τοῖς βασιλεῦσι Κογκολιτάνῳ καὶ Ἀνηροέστῳ παραυτίκα μὲν χρυσίου προτείναντες πλῆθος, εἰς τὸ μέλλον δ’ ὑποδεικνύντες τὸ μέγεθος τῆς Ῥωμαίων εὐδαιμονίας καὶ τὸ πλῆθος τῶν ὑπαρξόντων αὐτοῖς ἀγαθῶν, ἐὰν κρατήσωσι, προετρέποντο καὶ παρώξυνον πρὸς τὴν ἐπὶ Ῥωμαίους στρατείαν. ῥᾳδίως δ’ ἔπεισαν, ἅμα τοῖς προειρημένοις διδόντες μὲν τὰ πιστὰ περὶ τῆς αὑτῶν συμμαχίας, ἀναμιμνήσκοντες δὲ τῆς τῶν ἰδίων προγόνων πράξεως αὐτούς· ἐν ᾗ ’κεῖνοι στρατεύσαντες οὐ μόνον ἐνίκησαν μαχόμενοι Ῥωμαίους, ἀλλὰ καὶ μετὰ τὴν μάχην ἐξ ἐφόδου κατέσχον αὐτὴν τὴν Ῥώμην· γενόμενοι δὲ καὶ τῶν ὑπαρχόντων ἁπάντων ἐγκρατεῖς καὶ τῆς πόλεως αὐτῆς ἑπτὰ μῆνας κυριεύσαντες, τέλος ἐθελοντὶ καὶ μετὰ χάριτος παραδόντες τὴν πόλιν, ἄθραυστοι καὶ ἀσινεῖς ἔχοντες τὴν ὠφέλειαν εἰς τὴν οἰκείαν ἐπανῆλθον. ὧν ἀκούοντες οἱ περὶ αὐτοὺς ἡγεμόνες οὕτω παρωρμήθησαν ἐπὶ τὴν στρατείαν ὥστε μηδέποτε μήτε πλείους μήτ’ ἐνδοξοτέρους μήτε μαχιμωτέρους ἄνδρας ἐξελθεῖν ἐκ τούτων τῶν τόπων τῆς Γαλατίας. κατὰ δὲ τοὺς καιροὺς τούτους Ῥωμαῖοι τὰ μὲν ἀκούοντες τὰ δὲ καταμαντευόμενοι τὸ μέλλον εἰς φόβους ἐνέπιπτον συνεχεῖς καὶ ταραχὰς ἐπὶ τοσοῦτον, ὥστε ποτὲ μὲν στρατόπεδα καταγράφειν καὶ σίτου καὶ τῶν ἐπιτηδείων ποιεῖσθαι παρασκευάς, ποτὲ δὲ καὶ τὰς δυνάμεις ἐξάγειν ἐπὶ τοὺς ὅρους, ὡς ἤδη παρόντων εἰς τὴν χώραν τῶν πολεμίων, οὐδέπω κεκινηκότων ἐκ τῆς οἰκείας τῶν Κελτῶν. οὐκ ἐλάχιστα δὲ συνήργησεν καὶ Καρχηδονίοις τοῦτο τὸ κίνημα πρὸς τὸ κατασκευάσασθαι τὰ κατὰ τὴν Ἰβηρίαν ἀσφαλῶς. Ῥωμαῖοι γάρ, ὡς καὶ πρόσθεν ἡμῖν εἴρηται, κρίνοντες ἀναγκαιότερα ταῦτα διὰ τὸ πρὸς ταῖς πλευραῖς αὐτῶν ὑπάρχειν παρορᾶν ἠναγκάζοντο τὰ κατὰ τὴν Ἰβηρίαν, σπουδάζοντες πρότερον ἐν καλῷ θέσθαι τὰ κατὰ τοὺς Κελτούς. διόπερ ἀσφαλισάμενοι τὰ πρὸς τοὺς Καρχηδονίους διὰ τῶν πρὸς τὸν Ἀσδρούβαν ὁμολογιῶν, ὑπὲρ ὧν ἄρτι δεδηλώκαμεν, ἐνεχείρησαν ὁμοθυμαδὸν ἐν τούτοις τοῖς καιροῖς πρὸς τοὺς κατὰ τὴν Ἰταλίαν πολεμίους, νομίζοντες συμφέρειν σφίσι τὸ διακριθῆναι πρὸς τούτους.", "st": "2.22"}, {"sp": "N", "t": "οἱ δὲ Γαισάται Γαλάται συστησάμενοι δύναμιν πολυτελῆ καὶ βαρεῖαν ἧκον ὑπεράραντες τὰς Ἄλπεις εἰς τὸν Πάδον ποταμὸν ἔτει μετὰ τὴν τῆς χώρας διάδοσιν ὀγδόῳ. τὸ μὲν οὖν τῶν Ἰνσόμβρων καὶ Βοίων γένος ἔμεινε γενναίως ἐν ταῖς ἐξ ἀρχῆς ἐπιβολαῖς, οἱ δ’ Οὐένετοι καὶ Γονομάνοι, διαπρεσβευσαμένων Ῥωμαίων, τούτοις εἵλοντο συμμαχεῖν. διὸ καὶ μέρος τι τῆς δυνάμεως καταλιπεῖν ἠναγκάσθησαν οἱ βασιλεῖς τῶν Κελτῶν φυλακῆς χάριν τῆς χώρας πρὸς τὸν ἀπὸ τούτων φόβον. αὐτοὶ δ’ ἐξάραντες παντὶ τῷ στρατεύματι κατατεθαρρηκότως ὥρμησαν, ποιούμενοι τὴν πορείαν ὡς ἐπὶ Τυρρηνίας, ἔχοντες πεζοὺς μὲν εἰς πεντακισμυρίους, ἱππεῖς δὲ καὶ συνωρίδας εἰς δισμυρίους. Ῥωμαῖοι δ’ ὡς θᾶττον ἤκουσαν τοὺς Κελτοὺς ὑπερβεβληκέναι τὰς Ἄλπεις, Λεύκιον μὲν Αἰμίλιον ὕπατον μετὰ δυνάμεως ἐξαπέστειλαν ὡς ἐπ’ Ἀριμίνου, τηρήσοντα ταύτῃ τῶν ἐναντίων τὴν ἔφοδον, ἕνα δὲ τῶν ἑξαπελέκεων εἰς Τυρρηνίαν. ὁ μὲν γὰρ ἕτερος τῶν ὑπάτων Γάιος Ἀτίλιος προεξεληλυθὼς ἔτυχεν εἰς Σαρδόνα μετὰ τῶν στρατοπέδων, οἱ δ’ ἐν τῇ Ῥώμῃ πάντες περιδεεῖς ἦσαν, μέγαν καὶ φοβερὸν αὑτοῖς ὑπολαμβάνοντες ἐπιφέρεσθαι κίνδυνον. ἔπασχον δὲ τοῦτ’ εἰκότως, ἔτι περὶ Γαλατῶν ἐγκαθημένου ταῖς ψυχαῖς αὐτῶν τοῦ παλαιοῦ φόβου. διὸ καὶ πρὸς ταύτην ἀναφέροντες τὴν ἔννοιαν τὰ μὲν συνήθροιζον, τὰ δὲ κατέγραφον στρατόπεδα, τοῖς δ’ ἑτοίμοις εἶναι παρήγγελλον τῶν συμμάχων. καθόλου δὲ τοῖς ὑποτεταγμένοις ἀναφέρειν ἐπέταξαν ἀπογραφὰς τῶν ἐν ταῖς ἡλικίαις, σπουδάζοντες εἰδέναι τὸ σύμπαν πλῆθος τῆς ὑπαρχούσης αὐτοῖς δυνάμεως. σίτου δὲ καὶ βελῶν καὶ τῆς ἄλλης ἐπιτηδειότητος πρὸς πόλεμον τηλικαύτην ἐποιήσαντο κατασκευὴν ἡλίκην οὐδείς πω μνημονεύει πρότερον. συνηργεῖτο δ’ αὐτοῖς πάντα καὶ πανταχόθεν ἑτοίμως. καταπεπληγμένοι γὰρ οἱ τὴν Ἰταλίαν οἰκοῦντες τὴν τῶν Γαλατῶν ἔφοδον οὐκέτι Ῥωμαίοις ἡγοῦντο συμμαχεῖν οὐδὲ περὶ τῆς τούτων ἡγεμονίας γίνεσθαι τὸν πόλεμον, ἀλλὰ περὶ σφῶν ἐνόμιζον ἕκαστοι καὶ τῆς ἰδίας πόλεως καὶ χώρας ἐπιφέρεσθαι τὸν κίνδυνον. διόπερ ἑτοίμως τοῖς παραγγελλομένοις ὑπήκουον.", "st": "2.23"}, {"sp": "N", "t": "ἵνα δὲ συμφανὲς ἐπ’ αὐτῶν γένηται τῶν ἔργων ἡλίκοις Ἀννίβας ἐτόλμησε πράγμασιν ἐπιθέσθαι [μετὰ δὲ ταῦτα] καὶ πρὸς ἡλίκην δυναστείαν παραβόλως ἀντοφθαλμήσας ἐπὶ τοσοῦτο καθίκετο τῆς προθέσεως ὥστε τοῖς μεγίστοις συμπτώμασι περιβάλλειν Ῥωμαίους, ῥητέον ἂν εἴη τὴν παρασκευὴν καὶ τὸ πλῆθος τῆς ὑπαρχούσης αὐτοῖς τότε δυνάμεως. μετὰ μὲν δὴ τῶν ὑπάτων ἐξεληλύθει τέτταρα στρατόπεδα Ῥωμαϊκά, πεντάκις μὲν χιλίους καὶ διακοσίους πεζούς, ἱππεῖς δὲ τριακοσίους ἔχον ἕκαστον. σύμμαχοι δὲ μεθ’ ἑκατέρων ἦσαν οἱ συνάμφω πεζοὶ μὲν τρισμύριοι, δισχίλιοι δ’ ἱππεῖς. τῶν δ’ ἐκ τοῦ καιροῦ προσβοηθησάντων εἰς τὴν Ῥώμην Σαβίνων καὶ Τυρρηνῶν ἱππεῖς μὲν ἦσαν εἰς τετρακισχιλίους, πεζοὶ δὲ πλείους τῶν πεντακισμυρίων. τούτους μὲν ἁθροίσαντες ὡς ἐπὶ Τυρρηνίας προεκάθισαν, ἑξαπέλεκυν αὐτοῖς ἡγεμόνα συστήσαντες. οἱ δὲ τὸν Ἀπεννῖνον κατοικοῦντες Ὄμβροι καὶ Σαρσινάτοι συνήχθησαν εἰς δισμυρίους, μετὰ δὲ τούτων Οὐένετοι καὶ Γονομάνοι δισμύριοι. τούτους δ’ ἔταξαν ἐπὶ τῶν ὅρων τῆς Γαλατίας, ἵν’ ἐμβαλόντες εἰς τὴν τῶν Βοίων χώραν ἀντιπερισπῶσι τοὺς ἐξεληλυθότας. τὰ μὲν οὖν προκαθήμενα στρατόπεδα τῆς χώρας ταῦτ’ ἦν. ἐν δὲ τῇ Ῥώμῃ διέτριβον ἡτοιμασμένοι χάριν τῶν συμβαινόντων ἐν τοῖς πολέμοις, ἐφεδρείας ἔχοντες τάξιν, Ῥωμαίων μὲν αὐτῶν πεζοὶ δισμύριοι, μετὰ δὲ τούτων ἱππεῖς χίλιοι καὶ πεντακόσιοι, τῶν δὲ συμμάχων πεζοὶ μὲν τρισμύριοι, δισχίλιοι δ’ ἱππεῖς. καταγραφαὶ δ’ ἀνηνέχθησαν Λατίνων μὲν ὀκτακισμύριοι πεζοί, πεντακισχίλιοι δ’ ἱππεῖς, Σαυνιτῶν δὲ πεζοὶ μὲν ἑπτακισμύριοι, μετὰ δὲ τούτων ἱππεῖς ἑπτακισχίλιοι, καὶ μὴν Ἰαπύγων καὶ Μεσσαπίων συνάμφω πεζῶν μὲν πέντε μυριάδες, ἱππεῖς δὲ μύριοι σὺν ἑξακισχιλίοις, Λευκανῶν δὲ πεζοὶ μὲν τρισμύριοι, τρισχίλιοι δ’ ἱππεῖς, Μαρσῶν δὲ καὶ Μαρρουκίνων καὶ Φερεντάνων, ἔτι δ’ Οὐεστίνων πεζοὶ μὲν δισμύριοι, τετρακισχίλιοι δ’ ἱππεῖς. ἔτι γε μὴν καὶ ἐν Σικελίᾳ καὶ Τάραντι στρατόπεδα δύο παρεφήδρευεν, ὧν ἑκάτερον ἦν ἀνὰ τετρακισχιλίους καὶ διακοσίους πεζούς, ἱππεῖς δὲ διακοσίους. Ῥωμαίων δὲ καὶ Καμπανῶν ἡ πληθὺς πεζῶν μὲν εἰς εἴκοσι καὶ πέντε κατελέχθησαν μυριάδες, ἱππέων δ’ ἐπὶ ταῖς δύο μυριάσιν ἐπῆσαν ἔτι τρεῖς χιλιάδες. ὥστ’ εἶναι τὸ [κεφάλαιον τῶν μὲν προκαθημένων τῆς Ῥώμης δυνάμεων πεζοὶ μὲν ὑπὲρ πεντεκαίδεκα μυριάδες, ἱππεῖς δὲ πρὸς ἑξακισχιλίους, τὸ δὲ] σύμπαν πλῆθος τῶν δυναμένων ὅπλα βαστάζειν, αὐτῶν τε Ῥωμαίων καὶ τῶν συμμάχων, πεζῶν ὑπὲρ τὰς ἑβδομήκοντα μυριάδας, ἱππέων δ’ εἰς ἑπτὰ μυριάδας. ἐφ’ οὓς Ἀννίβας ἐλάττους ἔχων δισμυρίων ἐπέβαλεν εἰς τὴν Ἰταλίαν. περὶ μὲν οὖν τούτων ἐν τοῖς ἑξῆς σαφέστερον ἐκποιήσει κατανοεῖν.", "st": "2.24"}, {"sp": "N", "t": "οἱ δὲ Κελτοὶ κατάραντες εἰς τὴν Τυρρηνίαν ἐπεπορεύοντο τὴν χώραν, πορθοῦντες ἀδεῶς· οὐδενὸς δ’ αὐτοῖς ἀντιταττομένου, τέλος ἐπ’ αὐτὴν ὥρμησαν τὴν Ῥώμην. ἤδη δ’ αὐτῶν περὶ πόλιν ὄντων ἣ καλεῖται μὲν Κλούσιον, ἀπέχει δ’ ἡμερῶν τριῶν ὁδὸν ἀπὸ τῆς Ῥώμης, προσαγγέλλεται διότι κατόπιν αὐτοῖς ἕπονται καὶ συνάπτουσιν αἱ προκαθήμεναι τῶν Ῥωμαίων ἐν τῇ Τυρρηνίᾳ δυνάμεις. οἱ δ’ ἀκούσαντες ἐξ ὑποστροφῆς ἀπήντων, σπεύδοντες τούτοις συμβαλεῖν. ἐγγίσαντες δ’ ἀλλήλοις ἤδη περὶ δυσμὰς ἡλίου, τότε μὲν ἐν συμμέτρῳ διαστήματι καταστρατοπεδεύσαντες ηὐλίσθησαν ἀμφότεροι. τῆς δὲ νυκτὸς ἐπιγενομένης πῦρ ἀνακαύσαντες οἱ Κελτοὶ τοὺς μὲν ἱππεῖς ἀπέλιπον, συντάξαντες ἅμα τῷ φωτὶ συμφανεῖς γενομένους τοῖς πολεμίοις ὑποχωρεῖν κατὰ τὸν αὐτὸν στίβον. αὐτοὶ δὲ λαθραίαν ποιησάμενοι τὴν ἀποχώρησιν ὡς ἐπὶ πόλιν Φαισόλαν αὐτοῦ παρενέβαλον, πρόθεσιν ἔχοντες ἅμα μὲν ἐκδέχεσθαι τοὺς ἑαυτῶν ἱππεῖς, ἅμα δὲ παραδόξως ἐνοχλῆσαι τὴν τῶν ὑπεναντίων ἔφοδον. οἱ δὲ Ῥωμαῖοι τῆς ἡμέρας ἐπιγενομένης συνιδόντες τοὺς ἱππεῖς αὐτοὺς καὶ νομίσαντες τοὺς Κελτοὺς ἀποδεδρακέναι, κατὰ σπουδὴν ἠκολούθουν τοῖς ἱππεῦσιν κατὰ τὴν ἐκείνων ἀποχώρησιν. ἅμα δὲ τῷ συνεγγίζειν τοῖς πολεμίοις διαναστάντων τῶν Κελτῶν καὶ συμπεσόντων αὐτοῖς ἦν ἀγὼν τὰς ἀρχὰς ἐξ ἀμφοῖν βίαιος. τέλος δὲ καθυπερεχόντων τῶν Κελτῶν τῇ τόλμῃ καὶ τῷ πλήθει, συνέβη διαφθαρῆναι μὲν τῶν Ῥωμαίων οὐκ ἐλάττους ἑξακισχιλίων, τοὺς δὲ λοιποὺς φεύγειν· ὧν οἱ πλείους πρός τινα τόπον ἐρυμνὸν ἀποχωρήσαντες ἔμενον. οὓς τὸ μὲν πρῶτον οἱ Κελτοὶ πολιορκεῖν ἐπεβάλοντο· κακῶς δ’ ἀπαλλάττοντες ἐκ τῆς προγεγενημένης ἐν τῇ νυκτὶ πορείας καὶ κακοπαθείας καὶ ταλαιπωρίας ὥρμησαν πρὸς ἀνάπαυσιν καὶ θεραπείαν, φυλακὴν ἀπολιπόντες τῶν ἰδίων ἱππέων περὶ τὸν λόφον, πρόθεσιν ἔχοντες κατὰ τὴν ἐπιοῦσαν πολιορκεῖν τοὺς συμπεφευγότας, ἐὰν μὴ παραδῶσιν ἑαυτοὺς ἑκουσίως.", "st": "2.25"}, {"sp": "N", "t": "κατὰ δὲ τὸν καιρὸν τοῦτον Λεύκιος Αἰμίλιος ὁ προκαθήμενος ἐπὶ τῶν κατὰ τὸν Ἀδρίαν τόπων ἀκούσας τοὺς Κελτοὺς διὰ Τυρρηνίας ἐμβεβληκότας συνεγγίζειν τῇ Ῥώμῃ, παρῆν βοηθῶν κατὰ σπουδὴν εὐτυχῶς εἰς δέοντα καιρόν. καταστρατοπεδεύσαντος δ’ αὐτοῦ σύνεγγυς τῶν πολεμίων, κατιδόντες τὰ πυρὰ καὶ νοήσαντες τὸ γεγονὸς οἱ συμπεφευγότες ἐπὶ τὸν λόφον ταχέως ἀναθαρρήσαντες ἐξαπέστειλαν αὑτῶν τινας τῆς νυκτὸς ἀνόπλους διὰ τῆς ὕλης ἀναγγελοῦντας τῷ στρατηγῷ τὸ συμβεβηκός. ὁ δὲ διακούσας καὶ θεωρῶν οὐδὲ διαβούλιον αὑτῷ καταλειπόμενον ὑπὲρ τῶν ἐνεστώτων, τοῖς μὲν χιλιάρχοις ἅμα τῷ φωτὶ παρήγγειλε τοὺς πεζοὺς ἐξάγειν, αὐτὸς δὲ τοὺς ἱππεῖς ἀναλαβὼν καθηγεῖτο τῆς δυνάμεως, ποιούμενος τὴν πορείαν ἐπὶ τὸν προειρημένον βουνόν. οἱ δὲ τῶν Γαλατῶν ἡγεμόνες ἀφορῶντες τὰ πυρὰ τῆς νυκτὸς καὶ συλλογιζόμενοι τὴν παρουσίαν τῶν πολεμίων συνήδρευον. οἷς Ἀνηροέστης ὁ βασιλεὺς γνώμην εἰσέφερε λέγων ὅτι δεῖ τοσαύτης λείας ἐγκρατεῖς γεγονότας — ἦν γάρ, ὡς ἔοικε, καὶ τὸ τῶν σωμάτων καὶ θρεμμάτων πλῆθος, ἔτι δὲ τῆς ἀποσκευῆς ἧς εἶχον, ἀμύθητον — διόπερ ἔφη δεῖν μὴ κινδυνεύειν ἔτι μηδὲ παραβάλλεσθαι τοῖς ὅλοις, ἀλλ’ εἰς τὴν οἰκείαν ἀδεῶς ἐπανάγειν· ταῦτα δ’ ἀποσκευασαμένους καὶ γενομένους εὐζώνους αὖθις ἐγχειρεῖν ὁλοσχερῶς, ἐὰν δοκῇ, τοῖς Ῥωμαίων πράγμασιν. δόξαντος δὲ σφίσι κατὰ τὴν Ἀνηροέστου γνώμην χρήσασθαι τοῖς παροῦσιν, οὗτοι μὲν τῆς νυκτὸς ταῦτα βουλευσάμενοι, πρὸ φωτὸς ἀναζεύξαντες προῆγον παρὰ θάλατταν διὰ τῆς Τυρρηνῶν χώρας. ὁ δὲ Λεύκιος ἀναλαβὼν ἐκ τοῦ βουνοῦ τὸ διασῳζόμενον τοῦ στρατοπέδου μέρος ἅμα ταῖς ἰδίαις δυνάμεσι τὸ μὲν διακινδυνεύειν ἐκ παρατάξεως οὐδαμῶς ἔκρινε συμφέρειν, ἐπιτηρεῖν δὲ μᾶλλον καιροὺς καὶ τόπους εὐφυεῖς ἑπόμενος, ἐάν πού τι βλάψαι τοὺς πολεμίους ἢ τῆς λείας ἀποσπάσαι δυνηθῇ.", "st": "2.26"}, {"sp": "N", "t": "κατὰ δὲ τοὺς καιροὺς τούτους ἐκ Σαρδόνος μετὰ τῶν στρατοπέδων Γάιος Ἀτίλιος ὕπατος εἰς Πίσας καταπεπλευκὼς προῆγε μετὰ τῆς δυνάμεως εἰς Ῥώμην, ἐναντίαν ποιούμενος τοῖς πολεμίοις τὴν πορείαν. ἤδη δὲ περὶ Τελαμῶνα τῆς Τυρρηνίας τῶν Κελτῶν ὑπαρχόντων, οἱ προνομεύοντες ἐξ αὐτῶν ἐμπεσόντες εἰς τοὺς παρὰ τοῦ Γαΐου προπορευομένους ἑάλωσαν· καὶ τά τε προγεγονότα διεσάφουν ἀνακρινόμενοι τῷ στρατηγῷ καὶ τὴν παρουσίαν ἀμφοτέρων τῶν στρατοπέδων ἀνήγγελλον, σημαίνοντες διότι τελείως σύνεγγύς εἰσιν οἱ Κελτοὶ καὶ τούτων κατόπιν οἱ περὶ τὸν Λεύκιον. ὁ δὲ τὰ μὲν ξενισθεὶς ἐπὶ τοῖς προσπίπτουσι, τὰ δ’ εὔελπις γενόμενος ἐπὶ τῷ δοκεῖν μέσους κατὰ πορείαν ἀπειληφέναι τοὺς Κελτούς, τοῖς μὲν χιλιάρχοις παρήγγειλε τάττειν τὰ στρατόπεδα καὶ βάδην εἰς τοὔμπροσθεν προάγειν, καθ’ ὅσον ἂν οἱ τόποι προσδέχωνται τὴν μετωπηδὸν ἔφοδον. αὐτὸς δὲ συνθεωρήσας εὐκαίρως λόφον κείμενον ὑπὲρ τὴν ὁδόν, ὑφ’ ὃν ἔδει παραπορευθῆναι τοὺς Κελτούς, ἀναλαβὼν τοὺς ἱππεῖς ὥρμησε σπεύδων προκαταλαβέσθαι τὴν ἀκρολοφίαν καὶ πρῶτος κατάρξαι τοῦ κινδύνου, πεπεισμένος τῆς ἐπιγραφῆς τῶν ἐκβαινόντων πλεῖστον οὕτω κληρονομήσειν. οἱ δὲ Κελτοὶ τὸ μὲν πρῶτον τὴν παρουσίαν τῶν περὶ τὸν Ἀτίλιον ἀγνοοῦντες, ἐκ δὲ τοῦ συμβαίνοντος ὑπολαμβάνοντες τοὺς περὶ τὸν Αἰμίλιον περιπεπορεῦσθαι τὴν νύκτα τοῖς ἱππεῦσι καὶ προκαταλαμβάνεσθαι τοὺς τόπους, εὐθέως ἐξαπέστελλον τοὺς παρ’ αὑτῶν ἱππεῖς καί τινας τῶν εὐζώνων, ἀντιποιησομένους τῶν κατὰ τὸν βουνὸν τόπων. ταχὺ δὲ συνέντες τὴν τοῦ Γαΐου παρουσίαν ἔκ τινος τῶν ἀχθέντων αἰχμαλώτων σπουδῇ παρενέβαλον τοὺς πεζούς, ποιούμενοι τὴν ἔκταξιν ἅμα πρὸς ἑκατέραν τὴν ἐπιφάνειαν, καὶ τὴν ἀπ’ οὐρᾶς καὶ τὴν κατὰ πρόσωπον· οὓς μὲν γὰρ ᾔδεσαν ἑπομένους αὑτοῖς, οὓς δὲ κατὰ τὸ στόμα προσεδόκων ἀπαντήσειν, ἔκ τε τῶν προσαγγελλομένων τεκμαιρόμενοι καὶ τῶν κατ’ αὐτὸν τὸν καιρὸν συμβαινόντων.", "st": "2.27"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Αἰμίλιον ἀκηκοότες μὲν τὸν εἰς τὰς Πίσας κατάπλουν τῶν στρατοπέδων, οὔπω δὲ προσδοκῶντες αὐτὰ συνεγγίζειν, τότε σαφῶς ἐκ τοῦ περὶ τὸν λόφον ἀγῶνος ἔγνωσαν διότι τελέως ἐγγὺς εἶναι συμβαίνει τὰς οἰκείας αὐτῶν δυνάμεις. διὸ καὶ τοὺς μὲν ἱππεῖς παραυτίκα βοηθήσοντας ἐξαπέστελλον τοῖς ἐν τῷ λόφῳ διαγωνιζομένοις, αὐτοὶ δὲ κατὰ τὰς εἰθισμένας τάξεις διακοσμήσαντες τοὺς πεζοὺς προῆγον ἐπὶ τοὺς ὑπεναντίους. οἱ δὲ Κελτοὶ τοὺς μὲν ἐκ τῶν Ἄλπεων Γαισάτους προσαγορευομένους ἔταξαν πρὸς τὴν ἀπ’ οὐρᾶς ἐπιφάνειαν, ᾗ προσεδόκων τοὺς περὶ τὸν Αἰμίλιον, ἐπὶ δὲ τούτοις τοὺς Ἴνσομβρας· πρὸς δὲ τὴν κατὰ πρόσωπον τοὺς Ταυρίσκους καὶ τοὺς ἐπὶ τάδε τοῦ Πάδου κατοικοῦντας Βοίους παρενέβαλον, τὴν ἐναντίαν μὲν στάσιν ἔχοντας τοῖς προειρημένοις, βλέποντας δὲ πρὸς τὴν τῶν τοῦ Γαΐου στρατοπέδων ἔφοδον. τὰς δ’ ἁμάξας καὶ συνωρίδας ἐκτὸς ἑκατέρου τοῦ κέρατος παρέστησαν, τὴν δὲ λείαν εἴς τι τῶν παρακειμένων ὀρῶν φυλακὴν περιστήσαντες ἥθροιζον. γενομένης δ’ ἀμφιστόμου τῆς τῶν Κελτῶν δυνάμεως, οὐ μόνον καταπληκτικὴν ἀλλὰ καὶ πρακτικὴν εἶναι συνέβαινε τὴν τάξιν. οἱ μὲν οὖν Ἴνσομβρες καὶ Βοῖοι τὰς ἀναξυρίδας ἔχοντες καὶ τοὺς εὐπετεῖς τῶν σάγων περὶ αὑτοὺς ἐξέταξαν. οἱ δὲ Γαισάται διά τε τὴν φιλοδοξίαν καὶ τὸ θάρσος ταῦτ’ ἀπορρίψαντες γυμνοὶ μετ’ αὐτῶν τῶν ὅπλων πρῶτοι τῆς δυνάμεως κατέστησαν, ὑπολαβόντες οὕτως ἔσεσθαι πρακτικώτατοι διὰ τό τινας τῶν τόπων βατώδεις ὄντας ἐμπλέκεσθαι τοῖς ἐφάμμασι καὶ παραποδίζειν τὴν τῶν ὅπλων χρείαν. τὸ μὲν οὖν πρῶτον αὐτὸς ὁ κατὰ τὸν λόφον ἐνειστήκει κίνδυνος, ἅπασιν ὢν σύνοπτος, ὡς ἂν ἅμα τοσούτου πλήθους ἱππέων ἀφ’ ἑκάστου τῶν στρατοπέδων ἀναμὶξ ἀλλήλοις συμπεπτωκότος. ἐν δὲ τούτῳ τῷ καιρῷ συνέβη Γάιον μὲν τὸν ὕπατον παραβόλως ἀγωνιζόμενον ἐν χειρῶν νόμῳ τελευτῆσαι τὸν βίον, τὴν δὲ κεφαλὴν αὐτοῦ πρὸς τοὺς βασιλέας ἐπανενεχθῆναι τῶν Κελτῶν· τοὺς δὲ τῶν Ῥωμαίων ἱππεῖς κινδυνεύσαντας ἐρρωμένως τέλος ἐπικρατῆσαι τοῦ τόπου καὶ τῶν ὑπεναντίων. μετὰ δὲ ταῦτα τῶν πεζικῶν στρατοπέδων ἤδη σύνεγγυς ὄντων ἀλλήλοις ἴδιον ἦν καὶ θαυμαστὸν τὸ συμβαῖνον οὐ μόνον τοῖς ἐν αὐτῷ τῷ καιρῷ τότε παροῦσιν, ἀλλὰ καὶ τοῖς ποτε μετὰ ταῦτα δυναμένοις ὑπὸ τὴν ὄψιν λαμβάνειν ἐκ τῶν λεγομένων τὸ γεγονός.", "st": "2.28"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ ἐκ τριῶν στρατοπέδων τῆς μάχης συνισταμένης, δῆλον ὡς ξένην καὶ παρηλλαγμένην εἰκὸς καὶ τὴν ἐπιφάνειαν καὶ τὴν χρείαν φαίνεσθαι τοῦ συντεταγμένου. δεύτερον δὲ πῶς οὐκ ἂν ἀπορήσαι τις καὶ νῦν καὶ τότε παρ’ αὐτὸν ὢν τὸν καιρὸν πότερον οἱ Κελτοὶ τὴν ἐπισφαλεστάτην εἶχον χώραν, ἐξ ἀμφοῖν τοῖν μεροῖν ἅμα τῶν πολεμίων ἐπαγόντων αὐτοῖς, ἢ τοὐναντίον τὴν ἐπιτευκτικωτάτην, ἅμα μὲν ἀγωνιζόμενοι πρὸς ἀμφοτέρους, ἅμα δὲ τὴν ἀφ’ ἑκατέρων ἀσφάλειαν ἐκ τῶν ὄπισθεν αὑτοῖς παρασκευάζοντες, τὸ δὲ μέγιστον, ἀποκεκλειμένης πάσης τῆς εἰς τοὔπισθεν ἀναχωρήσεως καὶ τῆς ἐν τῷ λείπεσθαι σωτηρίας; ἡ γὰρ τῆς ἀμφιστόμου τάξεως ἰδιότης τοιαύτην ἔχει τὴν χρείαν. τούς γε μὴν Ῥωμαίους τὰ μὲν εὐθαρσεῖς ἐποίει τὸ μέσους καὶ πάντοθεν περιειληφέναι τοὺς πολεμίους, τὰ δὲ πάλιν ὁ κόσμος αὐτοὺς καὶ θόρυβος ἐξέπληττε τῆς τῶν Κελτῶν δυνάμεως. ἀναρίθμητον μὲν γὰρ ἦν τὸ τῶν βυκανητῶν καὶ σαλπιγκτῶν πλῆθος. οἷς ἅμα τοῦ παντὸς στρατοπέδου συμπαιανίζοντος τηλικαύτην καὶ τοιαύτην συνέβαινε γίνεσθαι κραυγὴν ὥστε μὴ μόνον τὰς σάλπιγγας καὶ τὰς δυνάμεις, ἀλλὰ καὶ τοὺς παρακειμένους τόπους συνηχοῦντας ἐξ αὑτῶν δοκεῖν προΐεσθαι φωνήν. ἐκπληκτικὴ δ’ ἦν καὶ τῶν γυμνῶν προεστώτων ἀνδρῶν ἥ τ’ ἐπιφάνεια καὶ κίνησις, ὡς ἂν διαφερόντων ταῖς ἀκμαῖς καὶ τοῖς εἴδεσι. πάντες δ’ οἱ τὰς πρώτας κατέχοντες σπείρας χρυσοῖς μανιάκαις καὶ περιχείροις ἦσαν κατακεκοσμημένοι. πρὸς ἃ βλέποντες οἱ Ῥωμαῖοι τὰ μὲν ἐξεπλήττοντο, τὰ δ’ ὑπὸ τῆς τοῦ λυσιτελοῦς ἐλπίδος ἀγόμενοι διπλασίως παρωξύνοντο πρὸς τὸν κίνδυνον.", "st": "2.29"}, {"sp": "N", "t": "πλὴν ἅμα τῷ τοὺς ἀκοντιστὰς προελθόντας ἐκ τῶν Ῥωμαϊκῶν στρατοπέδων κατὰ τὸν ἐθισμὸν εἰσακοντίζειν ἐνεργοῖς καὶ πυκνοῖς τοῖς βέλεσιν, τοῖς μὲν ὀπίσω τῶν Κελτῶν πολλὴν εὐχρηστίαν οἱ σάγοι μετὰ τῶν ἀναξυρίδων παρεῖχον· τοῖς δὲ γυμνοῖς προεστῶσι παρὰ τὴν προσδοκίαν τοῦ πράγματος συμβαίνοντος τἀναντία πολλὴν ἀπορίαν καὶ δυσχρηστίαν παρεῖχε τὸ γινόμενον. οὐ γὰρ δυναμένου τοῦ Γαλατικοῦ θυρεοῦ τὸν ἄνδρα περισκέπειν, ὅσῳ γυμνὰ καὶ μείζω τὰ σώματ’ ἦν, τοσούτῳ συνέβαινε μᾶλλον τὰ βέλη πίπτειν ἔνδον. τέλος δ’ οὐ δυνάμενοι μὲν ἀμύνασθαι τοὺς εἰσακοντίζοντας διὰ τὴν ἀπόστασιν καὶ τὸ πλῆθος τῶν πιπτόντων βελῶν, περικακοῦντες δὲ καὶ δυσχρηστούμενοι τοῖς παροῦσιν, οἱ μὲν εἰς τοὺς πολεμίους ὑπὸ τοῦ θυμοῦ καὶ τῆς ἀλογιστίας εἰκῇ προπίπτοντες καὶ διδόντες σφᾶς αὐτοὺς ἑκουσίως ἀπέθνησκον, οἱ δ’ εἰς τοὺς φίλους ἀναχωροῦντες ἐπὶ πόδα καὶ προδήλως ἀποδειλιῶντες διέστρεφον τοὺς κατόπιν. τὸ μὲν οὖν τῶν Γαισάτων φρόνημα παρὰ τοῖς ἀκοντισταῖς τούτῳ τῷ τρόπῳ κατελύθη, τὸ δὲ τῶν Ἰνσόμβρων καὶ Βοίων ἔτι δὲ Ταυρίσκων πλῆθος, ἅμα τῷ τοὺς Ῥωμαίους δεξαμένους τοὺς ἑαυτῶν ἀκοντιστὰς προσβάλλειν σφίσι τὰς σπείρας, συμπεσὸν τοῖς πολεμίοις ἐκ χειρὸς ἐποίει μάχην ἐχυράν. διακοπτόμενοι γὰρ ἔμενον ἐπ’ ἴσον ταῖς ψυχαῖς, αὐτῷ τούτῳ καὶ καθόλου καὶ κατ’ ἄνδρα λειπόμενοι, ταῖς τῶν ὅπλων κατασκευαῖς. οἱ μὲν οὖν θυρεοὶ πρὸς ἀσφάλειαν, αἱ δὲ μάχαιραι πρὸς πρᾶξιν μεγάλην διαφορὰν ἔχειν, τὴν δὲ Γαλατικὴν καταφορὰν ἔχειν μόνον. ἐπεὶ δ’ ἐξ ὑπερδεξίων καὶ κατὰ κέρας οἱ τῶν Ῥωμαίων ἱππεῖς ἐμβαλόντες ἀπὸ τοῦ λόφου προσέφερον τὰς χεῖρας ἐρρωμένως, τόθ’ οἱ μὲν πεζοὶ τῶν Κελτῶν ἐν αὐτῷ τῷ τῆς παρατάξεως τόπῳ κατεκόπησαν, οἱ δ’ ἱππεῖς πρὸς φυγὴν ὥρμησαν.", "st": "2.30"}, {"sp": "N", "t": "ἀπέθανον μὲν οὖν τῶν Κελτῶν εἰς τετρακισμυρίους, ἑάλωσαν δ’ οὐκ ἐλάττους μυρίων, ἐν οἷς καὶ τῶν βασιλέων Κογκολιτάνος. ὁ δ’ ἕτερος αὐτῶν Ἀνηρόεστος εἴς τινα τόπον συμφυγὼν μετ’ ὀλίγων προσήνεγκε τὰς χεῖρας αὑτῷ καὶ τοῖς ἀναγκαίοις. ὁ δὲ στρατηγὸς τῶν Ῥωμαίων τὰ μὲν σκῦλα συναθροίσας εἰς τὴν Ῥώμην ἀπέστειλε, τὴν δὲ λείαν ἀπέδωκε τοῖς προσήκουσιν. αὐτὸς δ’ ἀναλαβὼν τὰ στρατόπεδα καὶ διελθὼν παρ’ αὐτὴν τὴν Λιγυστικὴν εἰς τὴν τῶν Βοίων ἐνέβαλε χώραν. πληρώσας δὲ τὰς ὁρμὰς τῶν στρατοπέδων τῆς ὠφελείας, ἐν ὀλίγαις ἡμέραις ἧκεν μετὰ τῶν δυνάμεων εἰς τὴν Ῥώμην. καὶ τὸ μὲν Καπετώλιον ἐκόσμησε ταῖς τε σημείαις καὶ τοῖς μανιάκαις — τοῦτο δ’ ἔστι χρυσοῦν ψέλιον, ὃ φοροῦσι περὶ τὸν τράχηλον οἱ Γαλάται — τοῖς δὲ λοιποῖς σκύλοις καὶ τοῖς αἰχμαλώτοις πρὸς τὴν εἴσοδον ἐχρήσατο τὴν ἑαυτοῦ καὶ πρὸς τὴν τοῦ θριάμβου διακόσμησιν. ἡ μὲν οὖν βαρυτάτη τῶν Κελτῶν ἔφοδος οὕτω καὶ τούτῳ τῷ τρόπῳ διεφθάρη, πᾶσι μὲν Ἰταλιώταις, μάλιστα δὲ Ῥωμαίοις μέγαν καὶ φοβερὸν ἐπικρεμάσασα κίνδυνον. ἀπὸ δὲ τοῦ κατορθώματος τούτου κατελπίσαντες Ῥωμαῖοι δυνήσεσθαι τοὺς Κελτοὺς ἐκ τῶν τόπων τῶν περὶ τὸν Πάδον ὁλοσχερῶς ἐκβαλεῖν, τούς τε μετὰ ταῦτα κατασταθέντας ὑπάτους Κόϊντον Φόλουιον καὶ Τίτον Μάλιον ἀμφοτέρους καὶ τὰς δυνάμεις μετὰ παρασκευῆς μεγάλης ἐξαπέστειλαν ἐπὶ τοὺς Κελτούς. οὗτοι δὲ τοὺς μὲν Βοίους ἐξ ἐφόδου καταπληξάμενοι συνηνάγκασαν εἰς τὴν Ῥωμαίων ἑαυτοὺς δοῦναι πίστιν, τὸν δὲ λοιπὸν χρόνον τῆς στρατείας, ἐπιγενομένων ὄμβρων ἐξαισίων, ἔτι δὲ λοιμικῆς διαθέσεως ἐμπεσούσης αὐτοῖς, εἰς τέλος ἄπρακτον εἶχον.", "st": "2.31"}, {"sp": "N", "t": "μετὰ δὲ τούτους κατασταθέντες Πόπλιος Φούριος καὶ Γάιος Φλαμίνιος αὖθις ἐνέβαλον εἰς τὴν Κελτικὴν διὰ τῆς τῶν Ἀνάρων χώρας, οἷς συμβαίνει μὴ μακρὰν ἀπὸ Μασσαλίας ἔχειν τὴν οἴκησιν. οὓς εἰς τὴν φιλίαν προσαγαγόμενοι διέβησαν εἰς τὴν τῶν Ἰνσόμβρων γῆν κατὰ τὰς συρροίας τοῦ τ’ Ἀδόα καὶ Πάδου ποταμοῦ. λαβόντες δὲ πληγὰς περί τε τὴν διάβασιν καὶ περὶ τὴν στρατοπεδείαν παραυτίκα μὲν ἔμειναν, μετὰ δὲ ταῦτα σπεισάμενοι καθ’ ὁμολογίαν ἀνέλυσαν ἐκ τῶν τόπων. περιελθόντες δὲ πλείους ἡμέρας καὶ διελθόντες τὸν Κλούσιον ποταμὸν ἦλθον εἰς τὴν τῶν Γονομάνων χώραν καὶ προσλαβόντες τούτους, ὄντας συμμάχους, ἐνέβαλον πάλιν ἀπὸ τῶν κατὰ τὰς Ἄλπεις τόπων εἰς τὰ τῶν Ἰνσόμβρων πεδία καὶ τήν τε γῆν ἐδῄουν καὶ τὰς κατοικίας αὐτῶν ἐξεπόρθουν. οἱ δὲ τῶν Ἰνσόμβρων προεστῶτες θεωροῦντες ἀμετάθετον οὖσαν τὴν ἐπιβολὴν τῶν Ῥωμαίων, ἔκριναν τῆς τύχης λαβεῖν πεῖραν καὶ διακινδυνεῦσαι πρὸς αὐτοὺς ὁλοσχερῶς. συναθροίσαντες οὖν ἁπάσας τὰς ὑπαρχούσας δυνάμεις ἐπὶ ταὐτὸν καὶ τὰς χρυσᾶς σημείας τὰς ἀκινήτους λεγομένας καθελόντες ἐκ τοῦ τῆς Ἀθηνᾶς ἱεροῦ καὶ τἄλλα παρασκευασάμενοι δεόντως μετὰ ταῦτα τεθαρρηκότως καὶ καταπληκτικῶς ἀντεστρατοπέδευσαν τοῖς πολεμίοις, ὄντες τὸ πλῆθος εἰς πέντε μυριάδας. οἱ δὲ Ῥωμαῖοι τὰ μὲν ὁρῶντες σφᾶς ἐλάττους ὄντας παρὰ πολὺ τῶν ἐναντίων, ἐβούλοντο συγχρῆσθαι ταῖς τῶν συμμαχούντων αὐτοῖς Κελτῶν δυνάμεσι· τὰ δὲ συλλογισάμενοι τήν τε Γαλατικὴν ἀθεσίαν καὶ διότι πρὸς ὁμοφύλους τῶν προσλαμβανομένων μέλλουσι ποιεῖσθαι τὸν κίνδυνον, εὐλαβοῦντο τοιούτοις ἀνδράσιν τοιούτου καιροῦ καὶ πράγματος κοινωνεῖν. τέλος δ’ οὖν αὐτοὶ μὲν ὑπέμειναν ἐντὸς τοῦ ποταμοῦ, τοὺς δὲ τῶν Κελτῶν σφίσι συνόντας διαβιβάσαντες εἰς τὸ πέραν ἀνέσπασαν τὰς ἐπὶ τοῦ ῥείθρου γεφύρας, ἅμα μὲν ἀσφαλιζόμενοι τὰ πρὸς ἐκείνους, ἅμα δὲ μίαν ἑαυτοῖς ἀπολείποντες ἐλπίδα τῆς σωτηρίας τὴν ἐν τῷ νικᾶν διὰ τὸ κατόπιν αὐτοῖς ἄβατον ὄντα παρακεῖσθαι τὸν προειρημένον ποταμόν. πράξαντες δὲ ταῦτα πρὸς τῷ διακινδυνεύειν ἦσαν.", "st": "2.32"}, {"sp": "N", "t": "δοκοῦσι δ’ ἐμφρόνως κεχρῆσθαι τῇ μάχῃ ταύτῃ Ῥωμαῖοι, τῶν χιλιάρχων ὑποδειξάντων ὡς δεῖ ποιεῖσθαι τὸν ἀγῶνα κοινῇ καὶ κατ’ ἰδίαν ἑκάστους. συνεωρακότες γὰρ ἐκ τῶν προγεγονότων κινδύνων ὅτι τοῖς τε θυμοῖς κατὰ τὴν πρώτην ἔφοδον, ἕως ἂν ἀκέραιον ᾖ, φοβερώτατόν ἐστι πᾶν τὸ Γαλατικὸν φῦλον, αἵ τε μάχαιραι ταῖς κατασκευαῖς, καθάπερ εἴρηται πρότερον, μίαν ἔχουσι τὴν πρώτην καταφορὰν καιρίαν, ἀπὸ δὲ ταύτης εὐθέως ἀποξυστροῦνται, καμπτόμεναι κατὰ μῆκος καὶ κατὰ πλάτος ἐπὶ τοσοῦτον ὥστ’ ἐὰν μὴ δῷ τις ἀναστροφὴν τοῖς χρωμένοις ἐρείσαντας πρὸς τὴν γῆν ἀπευθῦναι τῷ ποδί, τελέως ἄπρακτον εἶναι τὴν δευτέραν πληγὴν αὐτῶν· ἀναδόντες οὖν οἱ χιλίαρχοι τὰ τῶν τριαρίων δόρατα τῶν κατόπιν ἐφεστώτων ταῖς πρώταις σπείραις καὶ παραγγείλαντες ἐκ μεταλήψεως τοῖς ξίφεσι χρῆσθαι συνέβαλον ἐκ παρατάξεως κατὰ πρόσωπον τοῖς Κελτοῖς. ἅμα δὲ τῷ πρὸς τὰ δόρατα ταῖς πρώταις καταφοραῖς χρωμένων τῶν Γαλατῶν ἀχρειωθῆναι τὰς μαχαίρας συνδραμόντες εἰς τὰς χεῖρας τοὺς μὲν Κελτοὺς ἀπράκτους ἐποίησαν, ἀφελόμενοι τὴν ἐκ διάρσεως αὐτῶν μάχην, ὅπερ ἴδιόν ἐστι Γαλατικῆς χρείας, διὰ τὸ μηδαμῶς κέντημα τὸ ξίφος ἔχειν· αὐτοὶ δ’ οὐκ ἐκ καταφορᾶς ἀλλ’ ἐκ διαλήψεως ὀρθαῖς χρώμενοι ταῖς μαχαίραις, πρακτικοῦ τοῦ κεντήματος περὶ αὐτὰς ὑπάρχοντος, τύπτοντες εἰς τὰ στέρνα καὶ τὰ πρόσωπα καὶ πληγὴν ἐπὶ πληγῇ φέροντες διέφθειραν τοὺς πλείστους τῶν παραταξαμένων διὰ τὴν τῶν χιλιάρχων πρόνοιαν. ὁ μὲν γὰρ στρατηγὸς Φλαμίνιος οὐκ ὀρθῶς δοκεῖ κεχρῆσθαι τῷ προειρημένῳ κινδύνῳ. παρ’ αὐτὴν γὰρ τὴν ὀφρὺν τοῦ ποταμοῦ ποιησάμενος τὴν ἔκταξιν διέφθειρε τὸ τῆς Ῥωμαϊκῆς μάχης ἴδιον, οὐχ ὑπολειπόμενος τόπον πρὸς τὴν ἐπὶ πόδα ταῖς σπείραις ἀναχώρησιν. εἰ γὰρ συνέβη βραχὺ μόνον πιεσθῆναι τῇ χώρᾳ τοὺς ἄνδρας κατὰ τὴν μάχην, ῥίπτειν ἂν εἰς τὸν ποταμὸν αὑτοὺς ἔδει διὰ τὴν ἀστοχίαν τοῦ προεστῶτος. οὐ μὴν ἀλλά γε πολλῷ νικήσαντες ταῖς σφετέραις ἀρεταῖς, καθάπερ εἶπον, καὶ παμπληθοῦς μὲν λείας, οὐκ ὀλίγων δὲ σκύλων κρατήσαντες ἐπανῆλθον εἰς τὴν Ῥώμην.", "st": "2.33"}, {"sp": "N", "t": "τῷ δ’ ἑξῆς ἔτει, διαπρεσβευσαμένων τῶν Κελτῶν ὑπὲρ εἰρήνης καὶ πᾶν ποιήσειν ὑπισχνουμένων, ἔσπευσαν οἱ κατασταθέντες ὕπατοι Μάρκος Κλαύδιος καὶ Γνάιος Κορνήλιος τοῦ μὴ συγχωρηθῆναι τὴν εἰρήνην αὐτοῖς. οἱ δ’ ἀποτυχόντες καὶ κρίναντες ἐξελέγξαι τὰς τελευταίας ἐλπίδας, αὖθις ὥρμησαν ἐπὶ τὸ μισθοῦσθαι τῶν περὶ τὸν Ῥοδανὸν Γαισάτων Γαλατῶν εἰς τρισμυρίους· οὓς παραλαβόντες εἶχον ἐν ἑτοίμῳ καὶ προσεδόκων τὴν τῶν πολεμίων ἔφοδον. οἱ δὲ τῶν Ῥωμαίων στρατηγοὶ τῆς ὥρας ἐπιγενομένης ἀναλαβόντες τὰς δυνάμεις ἦγον εἰς τὴν τῶν Ἰνσόμβρων χώραν. παραγενόμενοι δὲ καὶ περιστρατοπεδεύσαντες πόλιν Ἀχέρρας, ἣ μεταξὺ κεῖται τοῦ Πάδου καὶ τῶν Ἀλπεινῶν ὀρῶν, ἐπολιόρκουν ταύτην. οἱ δ’ Ἴνσομβρες βοηθεῖν μὲν οὐ δυνάμενοι διὰ τὸ προκαταληφθῆναι τοὺς εὐφυεῖς τόπους, σπεύδοντες δὲ λῦσαι τὴν πολιορκίαν τῶν Ἀχερρῶν, μέρος τι τῆς δυνάμεως διαβιβάσαντες τὸν Πάδον εἰς τὴν τῶν Ἀνάρων χώραν ἐπολιόρκουν τὸ προσαγορευόμενον Κλαστίδιον. προσπεσόντος δὲ τοῦ συμβαίνοντος τοῖς στρατηγοῖς, ἀναλαβὼν τοὺς ἱππεῖς Μάρκος Κλαύδιος καί τινας τῶν πεζικῶν ἠπείγετο, σπεύδων βοηθῆσαι τοῖς πολιορκουμένοις. οἱ δὲ Κελτοὶ πυθόμενοι τὴν παρουσίαν τῶν ὑπεναντίων, λύσαντες τὴν πολιορκίαν ὑπήντων καὶ παρετάξαντο. τῶν δὲ Ῥωμαίων αὐτοῖς τοῖς ἱππεῦσιν ἐξ ἐφόδου τολμηρῶς σφίσι προσπεσόντων, τὰς μὲν ἀρχὰς ἀντεῖχον· μετὰ δὲ ταῦτα περιισταμένων καὶ κατὰ νώτου καὶ κατὰ κέρας, δυσχρηστούμενοι τῇ μάχῃ τέλος ἐτράπησαν ὑπ’ αὐτῶν τῶν ἱππέων. καὶ πολλοὶ μὲν εἰς τὸν ποταμὸν ἐμπεσόντες ὑπὸ τοῦ ῥεύματος διεφθάρησαν, οἱ δὲ πλείους ὑπὸ τῶν πολεμίων κατεκόπησαν. ἔλαβον δὲ καὶ τὰς Ἀχέρρας οἱ Ῥωμαῖοι σίτου γεμούσας, ἐκχωρησάντων εἰς τὸ Μεδιόλανον τῶν Γαλατῶν, ὅσπερ ἐστὶ κυριώτατος τόπος τῆς τῶν Ἰνσόμβρων χώρας. οἷς ἐκ ποδὸς ἐπακολουθήσαντος τοῦ Γναΐου καὶ προσβαλόντος ἄφνω πρὸς τὸ Μεδιόλανον, τὸ μὲν πρῶτον ἡσυχίαν ἔσχον· ἀπολυομένου δ’ αὐτοῦ πάλιν εἰς τὰς Ἀχέρρας, ἐπεξελθόντες καὶ τῆς οὐραγίας ἁψάμενοι θρασέως πολλοὺς μὲν νεκροὺς ἐποίησαν, μέρος δέ τι καὶ φυγεῖν αὐτῶν ἠνάγκασαν, ἕως ὁ Γνάιος ἀνακαλεσάμενος τοὺς ἐκ τῆς πρωτοπορείας παρώρμησε στῆναι καὶ συμβαλεῖν τοῖς πολεμίοις. οἱ μὲν οὖν Ῥωμαῖοι πειθαρχήσαντες τῷ στρατηγῷ διεμάχοντο πρὸς τοὺς ἐπικειμένους εὐρώστως. οἱ δὲ Κελτοὶ διὰ τὸ παρὸν εὐτύχημα μείναντες ἐπὶ ποσὸν εὐθαρσῶς, μετ’ οὐ πολὺ τραπέντες ἔφευγον εἰς τὰς παρωρείας. ὁ δὲ Γνάιος ἐπακολουθήσας τήν τε χώραν ἐπόρθει καὶ τὸ Μεδιόλανον εἷλε κατὰ κράτος.", "st": "2.34"}, {"sp": "N", "t": "οὗ συμβαίνοντος οἱ προεστῶτες τῶν Ἰνσόμβρων ἀπογνόντες τὰς τῆς σωτηρίας ἐλπίδας πάντα τὰ καθ’ αὑτοὺς ἐπέτρεψαν τοῖς Ῥωμαίοις. ὁ μὲν οὖν πρὸς τοὺς Κελτοὺς πόλεμος τοιοῦτον ἔσχε τὸ τέλος, κατὰ μὲν τὴν ἀπόνοιαν καὶ τόλμαν τῶν ἀγωνιζομένων ἀνδρῶν, ἔτι δὲ κατὰ τὰς μάχας καὶ τὸ πλῆθος τῶν ἐν αὐταῖς ἀπολλυμένων καὶ παραταττομένων οὐδενὸς καταδεέστερος τῶν ἱστορημένων, κατὰ δὲ τὰς ἐπιβολὰς καὶ τὴν ἀκρισίαν τοῦ κατὰ μέρος χειρισμοῦ τελέως εὐκαταφρόνητος διὰ τὸ μὴ τὸ πλεῖον ἀλλὰ συλλήβδην ἅπαν τὸ γινόμενον ὑπὸ τῶν Γαλατῶν θυμῷ μᾶλλον ἢ λογισμῷ βραβεύεσθαι. περὶ ὧν ἡμεῖς συνθεωρήσαντες μετ’ ὀλίγον χρόνον αὐτοὺς ἐκ τῶν περὶ τὸν Πάδον πεδίων ἐξωσθέντας, πλὴν ὀλίγων τόπων τῶν ὑπ’ αὐτὰς τὰς Ἄλπεις κειμένων, οὐκ ᾠήθημεν δεῖν οὔτε τὴν ἐξ ἀρχῆς ἔφοδον αὐτῶν ἀμνημόνευτον παραλιπεῖν οὔτε τὰς μετὰ ταῦτα πράξεις οὔτε τὴν τελευταίαν ἐξανάστασιν, ὑπολαμβάνοντες οἰκεῖον ἱστορίας ὑπάρχειν τὰ τοιαῦτ’ ἐπεισόδια τῆς τύχης εἰς μνήμην ἄγειν καὶ παράδοσιν τοῖς ἐπιγινομένοις, ἵνα μὴ τελέως οἱ μεθ’ ἡμᾶς ἀνεννόητοι τούτων ὑπάρχοντες ἐκπλήττωνται τὰς αἰφνιδίους καὶ παραλόγους τῶν βαρβάρων ἐφόδους, ἀλλ’ ἐπὶ ποσὸν ἐν νῷ λαμβάνοντες ὡς ὀλιγοχρόνιόν ἐστι καὶ λίαν εὔφθαρτον τὸ τῶν βαρβάρων πλῆθος τοῖς σὺν νῷ κινδυνεύουσι τὴν ἔφοδον αὐτῶν ὑπομένωσι καὶ πάσας ἐξελέγχωσι τὰς σφετέρας ἐλπίδας πρότερον ἢ παραχωρῆσαί τινος τῶν ἀναγκαίων. καὶ γὰρ τοὺς τὴν Περσῶν ἔφοδον ἐπὶ τὴν Ἑλλάδα καὶ Γαλατῶν ἐπὶ Δελφοὺς εἰς μνήμην καὶ παράδοσιν ἡμῖν ἀγαγόντας οὐ μικρὰ μεγάλα δ’ οἴομαι συμβεβλῆσθαι πρὸς τοὺς ὑπὲρ τῆς κοινῆς τῶν Ἑλλήνων ἐλευθερίας ἀγῶνας. οὔτε γὰρ χορηγιῶν οὔθ’ ὅπλων οὔτ’ ἀνδρῶν πλῆθος καταπλαγεὶς ἄν τις ἀποσταίη τῆς τελευταίας ἐλπίδος, τοῦ διαγωνίζεσθαι περὶ τῆς σφετέρας χώρας καὶ πατρίδος, λαμβάνων πρὸ ὀφθαλμῶν τὸ παράδοξον τῶν τότε γενομένων καὶ μνημονεύσας ὅσας μυριάδας καὶ τίνας τόλμας καὶ πηλίκας παρασκευὰς ἡ τῶν σὺν νῷ καὶ μετὰ λογισμοῦ κινδυνευόντων αἵρεσις καὶ δύναμις καθεῖλεν. ὁ δ’ ἀπὸ Γαλατῶν φόβος οὐ μόνον τὸ παλαιὸν ἀλλὰ καὶ καθ’ ἡμᾶς ἤδη πλεονάκις ἐξέπληξε τοὺς Ἕλληνας. διὸ καὶ μᾶλλον ἔγωγε παρωρμήθην ἐπὶ τὸ κεφαλαιώδη μὲν ἀνέκαθεν δὲ ποιήσασθαι τὴν ὑπὲρ τούτων ἐξήγησιν.", "st": "2.35"}, {"sp": "N", "t": "Ἀσδρούβας δ’ ὁ τῶν Καρχηδονίων στρατηγός — ἀπὸ γὰρ τούτων παρεξέβημεν τῆς ἐξηγήσεως — ἔτη χειρίσας ὀκτὼ τὰ κατὰ τὴν Ἰβηρίαν ἐτελεύτησε, δολοφονηθεὶς ἐν τοῖς ἑαυτοῦ καταλύμασι νυκτὸς ὑπό τινος Κελτοῦ τὸ γένος ἰδίων ἕνεκεν ἀδικημάτων, οὐ μικρὰν ἀλλὰ μεγάλην ποιήσας ἐπίδοσιν τοῖς Καρχηδονίοις πράγμασιν, οὐχ οὕτω διὰ τῶν πολεμίων ἔργων ὡς διὰ τῆς πρὸς τοὺς δυνάστας ὁμιλίας. τὴν δὲ στρατηγίαν οἱ Καρχηδόνιοι τῶν κατὰ τὴν Ἰβηρίαν Ἀννίβᾳ περιέθεσαν, ὄντι νέῳ, διὰ τὴν ὑποφαινομένην ἐκ τῶν πράξεων ἀγχίνοιαν αὐτοῦ καὶ τόλμαν. ὃς παραλαβὼν τὴν ἀρχὴν εὐθέως δῆλος ἦν ἐκ τῶν ἐπινοημάτων πόλεμον ἐξοίσων Ῥωμαίοις. ὃ δὴ καὶ τέλος ἐποίησε, πάνυ βραχὺν ἐπισχὼν χρόνον. τὰ μὲν οὖν κατὰ Καρχηδονίους καὶ Ῥωμαίους ἀπὸ τούτων ἤδη τῶν καιρῶν ἐν ὑποψίαις ἦν πρὸς ἀλλήλους καὶ παρατριβαῖς. οἱ μὲν γὰρ ἐπεβούλευον, ἀμύνασθαι σπεύδοντες διὰ τὰς περὶ Σικελίαν ἐλαττώσεις, οἱ δὲ Ῥωμαῖοι διηπίστουν, θεωροῦντες αὐτῶν τὰς ἐπιβολάς. ἐξ ὧν δῆλον ἦν τοῖς ὀρθῶς σκοπουμένοις ὅτι μέλλουσι πολεμεῖν ἀλλήλοις οὐ μετὰ πολὺν χρόνον.", "st": "2.36"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Ἀχαιοὶ καὶ Φίλιππος ὁ βασιλεὺς ἅμα τοῖς ἄλλοις συμμάχοις συνίσταντο τὸν πρὸς Αἰτωλοὺς πόλεμον τὸν προσαγορευθέντα συμμαχικόν. ἡμεῖς δ’ ἐπειδὴ τάς τε περὶ Σικελίαν καὶ Λιβύην καὶ τὰς ἑξῆς πράξεις διεξιόντες κατὰ τὸ συνεχὲς τῆς προκατασκευῆς ἥκομεν ἐπὶ τὴν ἀρχὴν τοῦ τε συμμαχικοῦ καὶ τοῦ δευτέρου συστάντος μὲν Ῥωμαίοις καὶ Καρχηδονίοις πολέμου, προσαγορευθέντος δὲ παρὰ τοῖς πλείστοις Ἀννιβιακοῦ, κατὰ δὲ τὴν ἐξ ἀρχῆς πρόθεσιν ἀπὸ τούτων τῶν καιρῶν ἐπηγγειλάμεθα ποιήσασθαι τὴν ἀρχὴν τῆς ἑαυτῶν συντάξεως, πρέπον ἂν εἴη τούτων ἀφεμένους ἐπὶ τὰς κατὰ τὴν Ἑλλάδα μεταβαίνειν πράξεις, ἵνα πανταχόθεν ὁμοίαν ποιησάμενοι τὴν προκατασκευὴν καὶ τὴν ἔφοδον ἐπὶ τοὺς αὐτοὺς καιροὺς οὕτως ἤδη [τῆς Ἰταλίας καὶ] τῆς ἀποδεικτικῆς ἱστορίας ἀρχώμεθα. ἐπεὶ γὰρ οὐ τινὰς πράξεις, καθάπερ οἱ πρὸ ἡμῶν, οἷον τὰς Ἑλληνικὰς ἢ Περσικάς, ὁμοῦ δὲ τὰς ἐν τοῖς γνωριζομένοις μέρεσι τῆς οἰκουμένης ἀναγράφειν ἐπικεχειρήκαμεν διὰ τὸ πρὸς τοῦτο τὸ μέρος τῆς ὑποθέσεως ἴδιόν τι συμβεβλῆσθαι τοὺς καθ’ ἡμᾶς καιρούς, ὑπὲρ ὧν σαφέστερον ἐν ἑτέροις δηλώσομεν, δέον ἂν εἴη καὶ πρὸ τῆς κατασκευῆς ἐπὶ βραχὺ τῶν ἐπιφανεστάτων καὶ γνωριζομένων ἐθνῶν καὶ τόπων ἐφάψασθαι τῆς οἰκουμένης. περὶ μὲν οὖν τῶν κατὰ τὴν Ἀσίαν καὶ τῶν κατὰ τὴν Αἴγυπτον ἀρκούντως ἂν ἔχοι ποιεῖσθαι τὴν ἀνάμνησιν ἀπὸ τῶν νῦν ῥηθέντων καιρῶν διὰ τὸ τὴν μὲν ὑπὲρ τῶν προγεγονότων παρ’ αὐτοῖς ἱστορίαν ὑπὸ πλειόνων ἐκδεδόσθαι καὶ γνώριμον ὑπάρχειν ἅπασιν, ἐν δὲ τοῖς καθ’ ἡμᾶς καιροῖς μηδὲν αὐτοῖς ἐξηλλαγμένον ἀπηντῆσθαι μηδὲ παράλογον ὑπὸ τῆς τύχης ὥστε προσδεῖσθαι τῆς τῶν προγεγονότων ὑπομνήσεως. περὶ δὲ τοῦ τῶν Ἀχαιῶν ἔθνους καὶ περὶ τῆς Μακεδόνων οἰκίας ἁρμόσει διὰ βραχέων ἀναδραμεῖν τοῖς χρόνοις, ἐπειδὴ περὶ μὲν ταύτην ὁλοσχερὴς ἐπαναίρεσις, περὶ δὲ τοὺς Ἀχαιούς, καθάπερ ἐπάνω προεῖπον, παράδοξος αὔξησις καὶ συμφρόνησις ἐν τοῖς καθ’ ἡμᾶς καιροῖς γέγονε. πολλῶν γὰρ ἐπιβαλομένων ἐν τοῖς παρεληλυθόσι χρόνοις ἐπὶ ταὐτὸ συμφέρον ἀγαγεῖν Πελοποννησίους, οὐδενὸς δὲ καθικέσθαι δυνηθέντος διὰ τὸ μὴ τῆς κοινῆς ἐλευθερίας ἕνεκεν ἀλλὰ τῆς σφετέρας δυναστείας χάριν ἑκάστους ποιεῖσθαι τὴν σπουδήν, τοιαύτην καὶ τηλικαύτην ἐν τοῖς καθ’ ἡμᾶς καιροῖς ἔσχε προκοπὴν καὶ συντέλειαν τοῦτο τὸ μέρος ὥστε μὴ μόνον συμμαχικὴν καὶ φιλικὴν κοινωνίαν γεγονέναι πραγμάτων περὶ αὐτούς, ἀλλὰ καὶ νόμοις χρῆσθαι τοῖς αὐτοῖς καὶ σταθμοῖς καὶ μέτροις καὶ νομίσμασι, πρὸς δὲ τούτοις ἄρχουσι, βουλευταῖς, δικασταῖς, τοῖς αὐτοῖς, καθόλου δὲ τούτῳ μόνῳ διαλλάττειν τοῦ μὴ μιᾶς πόλεως διάθεσιν ἔχειν σχεδὸν τὴν σύμπασαν Πελοπόννησον, τῷ μὴ τὸν αὐτὸν περίβολον ὑπάρχειν τοῖς κατοικοῦσιν αὐτήν, τἄλλα δ’ εἶναι καὶ κοινῇ καὶ κατὰ πόλεις ἑκάστοις ταὐτὰ καὶ παραπλήσια.", "st": "2.37"}, {"sp": "N", "t": "πρῶτον δέ, πῶς ἐπεκράτησε καὶ τίνι τρόπῳ τὸ τῶν Ἀχαιῶν ὄνομα κατὰ πάντων Πελοποννησίων, οὐκ ἄχρηστον μαθεῖν. οὔτε γὰρ χώρας καὶ πόλεων πλήθει διαφέρουσιν οἱ πάτριον ἐξ ἀρχῆς ἔχοντες τὴν προσηγορίαν ταύτην οὔτε πλούτοις οὔτε ταῖς τῶν ἀνδρῶν ἀρεταῖς. τό τε γὰρ τῶν Ἀρκάδων ἔθνος, ὁμοίως δὲ καὶ τὸ τῶν Λακώνων πλήθει μὲν ἀνδρῶν καὶ χώρας οὐδὲ παρὰ μικρὸν ὑπερέχει· καὶ μὴν οὐδὲ τῶν τῆς ἀνδραγαθίας πρωτείων οὐδενὶ τῶν Ἑλλήνων οἷοί τ’ εἰσὶν οὐδέποτε παραχωρεῖν οἱ προειρημένοι. πῶς οὖν καὶ διὰ τί νῦν εὐδοκοῦσιν οὗτοί τε καὶ τὸ λοιπὸν πλῆθος τῶν Πελοποννησίων, ἅμα τὴν πολιτείαν τῶν Ἀχαιῶν καὶ τὴν προσηγορίαν μετειληφότες; δῆλον ὡς τύχην μὲν λέγειν οὐδαμῶς ἂν εἴη πρέπον· φαῦλον γάρ· αἰτίαν δὲ μᾶλλον ζητεῖν. χωρὶς γὰρ ταύτης οὔτε τῶν κατὰ λόγον οὔτε τῶν παρὰ λόγον εἶναι δοκούντων οὐδὲν οἷόν τε συντελεσθῆναι. ἔστι δ’ οὖν, ὡς ἐμὴ δόξα, τοιαύτη τις. ἰσηγορίας καὶ παρρησίας καὶ καθόλου δημοκρατίας ἀληθινῆς σύστημα καὶ προαίρεσιν εἰλικρινεστέραν οὐκ ἂν εὕροι τις τῆς παρὰ τοῖς Ἀχαιοῖς ὑπαρχούσης. αὕτη τινὰς μὲν ἐθελοντὴν αἱρετιστὰς εὗρε Πελοποννησίων, πολλοὺς δὲ πειθοῖ καὶ λόγῳ προσηγάγετο· τινὰς δὲ βιασαμένη σὺν καιρῷ παραχρῆμα πάλιν εὐδοκεῖν ἐποίησεν αὑτῇ τοὺς ἀναγκασθέντας. οὐδενὶ γὰρ οὐδὲν ὑπολειπομένη πλεονέκτημα τῶν ἐξ ἀρχῆς, ἴσα δὲ πάντα ποιοῦσα τοῖς ἀεὶ προσλαμβανομένοις ταχέως καθικνεῖτο τῆς προκειμένης ἐπιβολῆς, δύο συνεργοῖς χρωμένη τοῖς ἰσχυροτάτοις, ἰσότητι καὶ φιλανθρωπίᾳ. διὸ ταύτην ἀρχηγὸν καὶ παραίτιον ἡγητέον τοῦ συμφρονήσαντας Πελοποννησίους τὴν ὑπάρχουσαν αὐτοῖς εὐδαιμονίαν καταστήσασθαι. τὰ μὲν οὖν τῆς προαιρέσεως καὶ τὸ τῆς πολιτείας ἰδίωμα τὸ νῦν εἰρημένον καὶ πρότερον ὑπῆρχε παρὰ τοῖς Ἀχαιοῖς. δῆλον δὲ τοῦτο καὶ δι’ ἑτέρων μὲν πλειόνων, πρὸς δὲ τὸ παρὸν ἀρκέσει πίστεως χάριν ἓν ἢ καὶ δεύτερον ληφθὲν μαρτύριον.", "st": "2.38"}, {"sp": "N", "t": "καθ’ οὓς γὰρ καιροὺς ἐν τοῖς κατὰ τὴν Ἰταλίαν τόποις κατὰ τὴν Μεγάλην Ἑλλάδα τότε προσαγορευομένην ἐνεπρήσθη τὰ συνέδρια τῶν Πυθαγορείων, μετὰ ταῦτα γενομένου κινήματος ὁλοσχεροῦς περὶ τὰς πολιτείας, ὅπερ εἰκός, ὡς ἂν τῶν πρώτων ἀνδρῶν ἐξ ἑκάστης πόλεως οὕτω παραλόγως διαφθαρέντων, συνέβη τὰς κατ’ ἐκείνους τοὺς τόπους Ἑλληνικὰς πόλεις ἀναπλησθῆναι φόνου καὶ στάσεως καὶ παντοδαπῆς ταραχῆς. ἐν οἷς καιροῖς ἀπὸ τῶν πλείστων μερῶν τῆς Ἑλλάδος πρεσβευόντων ἐπὶ τὰς διαλύσεις, Ἀχαιοῖς καὶ τῇ τούτων πίστει συνεχρήσαντο πρὸς τὴν τῶν παρόντων κακῶν ἐξαγωγήν. οὐ μόνον δὲ κατὰ τούτους τοὺς καιροὺς ἀπεδέξαντο τὴν αἵρεσιν τῶν Ἀχαιῶν, ἀλλὰ καὶ μετά τινας χρόνους ὁλοσχερῶς ὥρμησαν ἐπὶ τὸ μιμηταὶ γενέσθαι τῆς πολιτείας αὐτῶν. παρακαλέσαντες γὰρ σφᾶς καὶ συμφρονήσαντες Κροτωνιᾶται, Συβαρῖται, Καυλωνιᾶται, πρῶτον μὲν ἀπέδειξαν Διὸς Ὁμαρίου κοινὸν ἱερὸν καὶ τόπον, ἐν ᾧ τάς τε συνόδους καὶ τὰ διαβούλια συνετέλουν, δεύτερον τοὺς ἐθισμοὺς καὶ νόμους ἐκλαβόντες τοὺς τῶν Ἀχαιῶν ἐπεβάλοντο χρῆσθαι καὶ διοικεῖν κατὰ τούτους τὴν πολιτείαν. ὑπὸ δὲ τῆς Διονυσίου Συρακοσίου δυναστείας, ἔτι δὲ τῆς τῶν περιοικούντων βαρβάρων ἐπικρατείας ἐμποδισθέντες οὐχ ἑκουσίως ἀλλὰ κατ’ ἀνάγκην αὐτῶν ἀπέστησαν. μετὰ δὲ ταῦτα Λακεδαιμονίων μὲν παραδόξως πταισάντων περὶ τὴν ἐν Λεύκτροις μάχην, Θηβαίων δ’ ἀνελπίστως ἀντιποιησαμένων τῆς τῶν Ἑλλήνων ἡγεμονίας, ἦν ἀκρισία περὶ πάντας μὲν τοὺς Ἕλληνας, μάλιστα δὲ περὶ τοὺς προειρημένους, ὡς ἂν τῶν μὲν μὴ συγχωρούντων ἡττῆσθαι, τῶν δὲ μὴ πιστευόντων ὅτι νενικήκασιν. οὐ μὴν ἀλλά γε περὶ τῶν ἀμφισβητουμένων ἐπέτρεψαν Θηβαῖοι καὶ Λακεδαιμόνιοι μόνοις τῶν Ἑλλήνων Ἀχαιοῖς, οὐ πρὸς τὴν δύναμιν ἀποβλέψαντες — σχεδὸν γὰρ ἐλαχίστην τότε δὴ τῶν Ἑλλήνων εἶχον — τὸ δὲ πλεῖον εἰς τὴν πίστιν καὶ τὴν ὅλην καλοκἀγαθίαν. ὁμολογουμένως γὰρ δὴ τότε ταύτην περὶ αὐτῶν πάντες εἶχον τὴν δόξαν. τότε μὲν οὖν ψιλῶς αὐτὰ τὰ κατὰ τὴν προαίρεσιν ὑπῆρχε παρ’ αὐτοῖς· ἀποτέλεσμα δ’ ἢ πρᾶξις ἀξιόλογος πρὸς αὔξησιν τῶν ἰδίων ἀνήκουσα πραγμάτων οὐκ ἐγίνετο, τῷ μὴ δύνασθαι φῦναι προστάτην ἄξιον τῆς προαιρέσεως, ἀεὶ δὲ τὸν ὑποδείξαντα ποτὲ μὲν ὑπὸ τῆς Λακεδαιμονίων ἀρχῆς ἐπισκοτεῖσθαι καὶ κωλύεσθαι, ποτὲ δὲ μᾶλλον ὑπὸ τῆς Μακεδόνων.", "st": "2.39"}, {"sp": "N", "t": "ἐπεὶ δέ ποτε σὺν καιρῷ προστάτας ἀξιόχρεως εὗρεν, ταχέως τὴν αὑτῆς δύναμιν ἐποίησε φανεράν, ἐπιτελεσαμένη τὸ κάλλιστον ἔργον, τὴν Πελοποννησίων ὁμόνοιαν. ἧς ἀρχηγὸν μὲν καὶ καθηγεμόνα τῆς ὅλης ἐπιβολῆς Ἄρατον νομιστέον τὸν Σικυώνιον, ἀγωνιστὴν δὲ καὶ τελεσιουργὸν τῆς πράξεως Φιλοποίμενα τὸν Μεγαλοπολίτην, βεβαιωτὴν δὲ τοῦ μόνιμον αὐτὴν ἐπὶ ποσὸν γενέσθαι Λυκόρταν καὶ τοὺς ταὐτὰ τούτῳ προελομένους ἄνδρας. τίνα δ’ ἦν ἑκάστοις τὰ πραχθέντα καὶ πῶς καὶ κατὰ ποίους καιροὺς πειρασόμεθα δηλοῦν, ἀεὶ κατὰ τὸ πρέπον τῇ γραφῇ ποιούμενοι τὴν ἐπίστασιν. τῶν μέντοι γ’ Ἀράτῳ διῳκημένων καὶ νῦν καὶ μετὰ ταῦτα πάλιν ἐπικεφαλαιούμενοι μνησθησόμεθα διὰ τὸ καὶ λίαν ἀληθινοὺς καὶ σαφεῖς ἐκεῖνον περὶ τῶν ἰδίων συντεταχέναι πράξεων ὑπομνηματισμούς, τῶν δὲ τοῖς ἄλλοις ἀκριβεστέραν καὶ μετὰ διαστολῆς ποιησόμεθα τὴν ἐξήγησιν. ὑπολαμβάνω δὲ ῥᾴστην ἐμοί τ’ ἂν γενέσθαι τὴν διήγησιν καὶ τοῖς ἐντυγχάνουσιν εὐπαρακολούθητον τὴν μάθησιν, εἰ ποιησαίμεθα τὴν ἐπίστασιν ἀπὸ τούτων τῶν καιρῶν, ἐν οἷς κατὰ πόλιν διαλυθέντος τοῦ τῶν Ἀχαιῶν ἔθνους ὑπὸ τῶν ἐκ Μακεδονίας βασιλέων ἀρχὴ πάλιν ἐγένετο καὶ σύννευσις τῶν πόλεων πρὸς ἀλλήλας. ἀφ’ ἧς αὐξανόμενον κατὰ τὸ συνεχὲς τὸ ἔθνος εἰς ταύτην ἦλθε τὴν συντέλειαν, ἐν ᾗ καθ’ ἡμᾶς ἦν, ὑπὲρ ἧς κατὰ μέρος ἀρτίως εἶπον.", "st": "2.40"}, {"sp": "N", "t": "Ὀλυμπιὰς μὲν ἦν εἰκοστὴ καὶ τετάρτη πρὸς ταῖς ἑκατόν, ὅτε Πατρεῖς ἤρξαντο συμφρονεῖν καὶ Δυμαῖοι, καιροὶ δὲ καθ’ οὓς Πτολεμαῖος ὁ Λάγου καὶ Λυσίμαχος, ἔτι δὲ Σέλευκος καὶ Πτολεμαῖος ὁ Κεραυνὸς μετήλλαξαν τὸν βίον. πάντες γὰρ οὗτοι περὶ τὴν προειρημένην ὀλυμπιάδα τὸ ζῆν ἐξέλιπον. τοὺς μὲν οὖν ἀνώτερον τούτων χρόνους τοιαύτη τις ἦν ἡ περὶ τὸ προειρημένον ἔθνος διάθεσις. ἀπὸ γὰρ Τισαμενοῦ βασιλευθέντες, ὃς ἦν Ὀρέστου μὲν υἱός, κατὰ δὲ τὴν τῶν Ἡρακλειδῶν κάθοδον ἐκπεσὼν τῆς Σπάρτης κατέσχε τοὺς περὶ Ἀχαΐαν τόπους, ἀπὸ τούτου κατὰ τὸ συνεχὲς καὶ κατὰ τὸ γένος ἕως Ὠγύγου βασιλευθέντες, μετὰ ταῦτα δυσαρεστήσαντες τοῖς τοῦ προειρημένου παισὶν ἐπὶ τῷ μὴ νομίμως ἀλλὰ δεσποτικῶς αὐτῶν ἄρχειν, μετέστησαν εἰς δημοκρατίαν τὴν πολιτείαν. λοιπὸν ἤδη τοὺς ἑξῆς χρόνους μέχρι τῆς Ἀλεξάνδρου καὶ Φιλίππου δυναστείας ἄλλοτε μὲν ἄλλως ἐχώρει τὰ πράγματ’ αὐτοῖς κατὰ τὰς περιστάσεις, τό γε μὴν κοινὸν πολίτευμα, καθάπερ εἰρήκαμεν, ἐν δημοκρατίᾳ συνέχειν ἐπειρῶντο. τοῦτο δ’ ἦν ἐκ δώδεκα πόλεων, ἃς ἔτι καὶ νῦν συμβαίνει διαμένειν, πλὴν Ὠλένου καὶ Ἑλίκης τῆς πρὸ τῶν Λευκτρικῶν ὑπὸ τῆς θαλάττης καταποθείσης· αὗται δ’ εἰσὶν Πάτραι, Δύμη, Φαραί, Τριταία, Λεόντιον, Αἴγιον, Αἴγειρα, Πελλήνη, Βοῦρα, Καρύνεια. κατὰ δὲ τοὺς ὑστέρους μὲν τῶν κατ’ Ἀλέξανδρον καιρῶν, προτέρους δὲ τῆς ἄρτι ῥηθείσης ὀλυμπιάδος, εἰς τοιαύτην διαφορὰν καὶ καχεξίαν ἐνέπεσον, καὶ μάλιστα διὰ τῶν ἐκ Μακεδονίας βασιλέων, ἐν ᾗ συνέβη πάσας τὰς πόλεις χωρισθείσας ἀφ’ αὑτῶν ἐναντίως τὸ συμφέρον ἄγειν ἀλλήλαις. ἐξ οὗ συνέπεσε τὰς μὲν ἐμφρούρους αὐτῶν γενέσθαι διά τε Δημητρίου καὶ Κασσάνδρου καὶ μετὰ ταῦτα δι’ Ἀντιγόνου τοῦ Γονατᾶ, τὰς δὲ καὶ τυραννεῖσθαι· πλείστους γὰρ δὴ μονάρχους οὗτος ἐμφυτεῦσαι δοκεῖ τοῖς Ἕλλησι. περὶ δὲ τὴν εἰκοστὴν καὶ τετάρτην ὀλυμπιάδα πρὸς ταῖς ἑκατόν, καθάπερ ἐπάνω προεῖπον, αὖθις ἤρξαντο μετανοήσαντες συμφρονεῖν. ταῦτα δ’ ἦν κατὰ τὴν Πύρρου διάβασιν εἰς Ἰταλίαν. καὶ πρῶτοι μὲν συνέστησαν Δυμαῖοι, Πατρεῖς, Τριταιεῖς, Φαραιεῖς· διόπερ οὐδὲ στήλην ὑπάρχειν συμβαίνει τῶν πόλεων τούτων περὶ τῆς συμπολιτείας. μετὰ δὲ ταῦτα μάλιστά πως ἔτει πέμπτῳ τὴν φρουρὰν ἐκβαλόντες Αἰγιεῖς μετέσχον τῆς συμπολιτείας· ἑξῆς δὲ τούτοις Βούριοι, τὸν τύραννον ἀποκτείναντες. ἅμα δὲ τούτοις Καρυνεῖς ἀποκατέστησαν. συνιδὼν γὰρ Ἰσέας ὁ τῆς Καρυνείας τότε τυραννεύων ἐκπεπτωκυῖαν μὲν ἐξ Αἰγίου τὴν φρουράν, ἀπολωλότα δὲ τὸν ἐν τῇ Βούρᾳ μόναρχον διὰ Μάργου καὶ τῶν Ἀχαιῶν, ἑαυτὸν δὲ πανταχόθεν ὁρῶν ὅσον οὐκ ἤδη πολεμηθησόμενον, ἀποθέμενος τὴν ἀρχὴν καὶ λαβὼν τὰ πιστὰ παρὰ τῶν Ἀχαιῶν ὑπὲρ τῆς ἀσφαλείας προσέθηκε τὴν πόλιν πρὸς τὸ τῶν Ἀχαιῶν σύστημα.", "st": "2.41"}, {"sp": "N", "t": "τίνος οὖν χάριν ἐπὶ τοὺς χρόνους τούτους ἀνέδραμον; ἵνα πρῶτον μὲν γένηται συμφανὲς πῶς καὶ κατὰ ποίους καιροὺς καὶ τίνες πρῶτοι τῶν ἐξ ἀρχῆς Ἀχαιῶν αὖθις ἐποιήσαντο τὴν ἐπιβολὴν τῆς νῦν συστάσεως, δεύτερον δ’ ἵνα καὶ τὰ τῆς προαιρέσεως μὴ μόνον διὰ τῆς ἡμετέρας ἀποφάσεως, ἀλλὰ καὶ δι’ αὐτῶν τῶν πραγμάτων πίστεως τυγχάνῃ, διότι μία τις ἀεὶ τῶν Ἀχαιῶν αἵρεσις ὑπῆρχε, καθ’ ἣν προτείνοντες μὲν τὴν παρ’ αὑτοῖς ἰσηγορίαν καὶ παρρησίαν, πολεμοῦντες δὲ καὶ καταγωνιζόμενοι συνεχῶς τοὺς ἢ δι’ αὑτῶν ἢ διὰ τῶν βασιλέων τὰς σφετέρας πατρίδας καταδουλουμένους, τούτῳ τῷ τρόπῳ καὶ ταύτῃ τῇ προθέσει τοῦτο τοὔργον ἐπετέλεσαν, τὰ μὲν δι’ αὑτῶν, τὰ δὲ καὶ διὰ τῶν συμμάχων. καὶ γὰρ τὰ δι’ ἐκείνων συνεργήματα γεγονότα πρὸς τοῦτο τὸ μέρος ἐν τοῖς ἑξῆς χρόνοις ἐπὶ τὴν τῶν Ἀχαιῶν προαίρεσιν ἀνοιστέον. πολλοῖς γὰρ κοινωνήσαντες πραγμάτων, πλείστων δὲ καὶ καλλίστων Ῥωμαίοις οὐδέποτε τὸ παράπαν ἐπεθύμησαν ἐκ τῶν κατορθωμάτων οὐδενὸς ἰδίᾳ λυσιτελοῦς, ἀλλ’ ἀντὶ πάσης τῆς ἑαυτῶν φιλοτιμίας, ἣν παρείχοντο τοῖς συμμάχοις, ἀντικατηλλάττοντο τὴν ἑκάστων ἐλευθερίαν καὶ τὴν κοινὴν ὁμόνοιαν Πελοποννησίων. σαφέστερον δ’ ὑπὲρ τούτων ἔσται διαλαμβάνειν ἐξ αὐτῶν τῶν περὶ τὰς πράξεις ἐνεργημάτων.", "st": "2.42"}, {"sp": "N", "t": "εἴκοσι μὲν οὖν ἔτη τὰ πρῶτα καὶ πέντε συνεπολιτεύσαντο μεθ’ ἑαυτῶν αἱ προειρημέναι πόλεις, γραμματέα κοινὸν ἐκ περιόδου προχειριζόμεναι καὶ δύο στρατηγούς. μετὰ δὲ ταῦτα πάλιν ἔδοξεν αὐτοῖς ἕνα καθιστάνειν καὶ τούτῳ πιστεύειν ὑπὲρ τῶν ὅλων. καὶ πρῶτος ἔτυχε τῆς τιμῆς ταύτης Μάργος ὁ Καρυνεύς. τετάρτῳ δ’ ὕστερον ἔτει τοῦ προειρημένου στρατηγοῦντος Ἄρατος ὁ Σικυώνιος, ἔτη μὲν ἔχων εἴκοσι, τυραννουμένην δ’ ἐλευθερώσας τὴν πατρίδα διὰ τῆς ἀρετῆς τῆς ἑαυτοῦ καὶ τόλμης προσένειμε πρὸς τὴν τῶν Ἀχαιῶν πολιτείαν, ἀρχῆθεν εὐθὺς ἐραστὴς γενόμενος τῆς προαιρέσεως αὐτῶν. ὀγδόῳ δὲ πάλιν ἔτει στρατηγὸς αἱρεθεὶς τὸ δεύτερον καὶ πραξικοπήσας τὸν Ἀκροκόρινθον, Ἀντιγόνου κυριεύοντος, καὶ γενόμενος ἐγκρατὴς μεγάλου μὲν ἀπέλυσε φόβου τοὺς τὴν Πελοπόννησον κατοικοῦντας, ἐλευθερώσας δὲ Κορινθίους προσηγάγετο πρὸς τὴν τῶν Ἀχαιῶν πολιτείαν. ἐπὶ δὲ τῆς αὐτῆς ἀρχῆς καὶ τὴν τῶν Μεγαρέων πόλιν διαπραξάμενος προσένειμε τοῖς Ἀχαιοῖς. ταῦτά τ’ ἐγίνετο τῷ πρότερον ἔτει τῆς Καρχηδονίων ἥττης, ἐν ᾗ καθόλου Σικελίας ἐκχωρήσαντες πρῶτον ὑπέμειναν τότε φόρους ἐνεγκεῖν Ῥωμαίοις. μεγάλην δὲ προκοπὴν ποιήσας τῆς ἐπιβολῆς ἐν ὀλίγῳ χρόνῳ λοιπὸν ἤδη διετέλει προστατῶν μὲν τοῦ τῶν Ἀχαιῶν ἔθνους, πάσας δὲ τὰς ἐπιβολὰς καὶ πράξεις πρὸς ἓν τέλος ἀναφέρων· τοῦτο δ’ ἦν τὸ Μακεδόνας μὲν ἐκβαλεῖν ἐκ Πελοποννήσου, τὰς δὲ μοναρχίας καταλῦσαι, βεβαιῶσαι δ’ ἑκάστοις τὴν κοινὴν καὶ πάτριον ἐλευθερίαν. μέχρι μὲν οὖν ἦν Ἀντίγονος ὁ Γονατᾶς, πρός τε τὴν ἐκείνου πολυπραγμοσύνην καὶ πρὸς τὴν Αἰτωλῶν πλεονεξίαν ἀντιταττόμενος διετέλει, πραγματικῶς ἕκαστα χειρίζων, καίπερ εἰς τοῦτο προβάντων ἀμφοτέρων ἀδικίας καὶ τόλμης ὥστε ποιήσασθαι συνθήκας πρὸς ἀλλήλους ὑπὲρ διαιρέσεως τοῦ τῶν Ἀχαιῶν ἔθνους.", "st": "2.43"}, {"sp": "N", "t": "Ἀντιγόνου δὲ μεταλλάξαντος, καὶ συνθεμένων τῶν Ἀχαιῶν καὶ συμμαχίαν πρὸς Αἰτωλοὺς καὶ μετασχόντων εὐγενῶς σφίσι τοῦ πρὸς Δημήτριον πολέμου, τὰ μὲν τῆς ἀλλοτριότητος καὶ δυσμενείας ἤρθη κατὰ τὸ παρόν, ὑπεγένετο δὲ κοινωνικὴ καὶ φιλική τις αὐτοῖς διάθεσις. Δημητρίου δὲ βασιλεύσαντος δέκα μόνον ἔτη καὶ μεταλλάξαντος τὸν βίον περὶ τὴν πρώτην διάβασιν εἰς τὴν Ἰλλυρίδα Ῥωμαίων, ἐγένετό τις εὔροια πραγμάτων πρὸς τὴν ἐξ ἀρχῆς ἐπιβολὴν τῶν Ἀχαιῶν. οἱ γὰρ ἐν τῇ Πελοποννήσῳ μόναρχοι δυσελπιστήσαντες ἐπὶ τῷ μετηλλαχέναι μὲν τὸν Δημήτριον, ὃς ἦν αὐτοῖς οἱονεὶ χορηγὸς καὶ μισθοδότης, ἐπικεῖσθαι δὲ τὸν Ἄρατον, οἰόμενον δεῖν σφᾶς ἀποτίθεσθαι τὰς τυραννίδας καὶ τοῖς μὲν πεισθεῖσι μεγάλας δωρεὰς καὶ τιμὰς προτείνοντα, τοῖς δὲ μὴ προσέχουσιν ἔτι μείζους ἐπανατεινόμενον φόβους καὶ κινδύνους διὰ τῶν Ἀχαιῶν, ὥρμησαν ἐπὶ τὸ πεισθέντες ἀποθέσθαι μὲν τὰς τυραννίδας, ἐλευθερῶσαι δὲ τὰς ἑαυτῶν πατρίδας, μετασχεῖν δὲ τῆς τῶν Ἀχαιῶν πολιτείας. Λυδιάδας μὲν οὖν ὁ Μεγαλοπολίτης ἔτι ζῶντος Δημητρίου, κατὰ τὴν αὑτοῦ προαίρεσιν, πάνυ πραγματικῶς καὶ φρονίμως προϊδόμενος τὸ μέλλον ἀπετέθειτο τὴν τυραννίδα καὶ μετεσχήκει τῆς ἐθνικῆς συμπολιτείας. Ἀριστόμαχος δ’ ὁ τῶν Ἀργείων τύραννος καὶ Ξένων ὁ τῶν Ἑρμιονέων καὶ Κλεώνυμος ὁ τῶν Φλιασίων τότ’ ἀποθέμενοι τὰς μοναρχίας ἐκοινώνησαν τῆς τῶν Ἀχαιῶν δημοκρατίας.", "st": "2.44"}, {"sp": "N", "t": "ὁλοσχερεστέρας δὲ γενομένης αὐξήσεως διὰ ταῦτα καὶ προκοπῆς περὶ τὸ ἔθνος, Αἰτωλοὶ διὰ τὴν ἔμφυτον ἀδικίαν καὶ πλεονεξίαν φθονήσαντες, τὸ δὲ πλεῖον ἐλπίσαντες καταδιελέσθαι τὰς πόλεις, καθάπερ καὶ πρότερον τὰς μὲν Ἀκαρνάνων διενείμαντο πρὸς Ἀλέξανδρον, τὰς δὲ τῶν Ἀχαιῶν ἐπεβάλοντο πρὸς Ἀντίγονον τὸν Γονατᾶν, καὶ τότε παραπλησίαις ἐλπίσιν ἐπαρθέντες ἀπετόλμησαν Ἀντιγόνῳ τε τῷ κατ’ ἐκείνους τοὺς καιροὺς προεστῶτι Μακεδόνων, ἐπιτροπεύοντι δὲ Φιλίππου παιδὸς ὄντος, καὶ Κλεομένει τῷ βασιλεῖ Λακεδαιμονίων κοινωνεῖν καὶ συμπλέκειν ἀμφοτέροις ἅμα τὰς χεῖρας. ὁρῶντες γὰρ τὸν Ἀντίγονον κυριεύοντα μὲν τῶν κατὰ Μακεδονίαν ἀσφαλῶς, ὁμολογούμενον δὲ καὶ πρόδηλον ἐχθρὸν ὄντα τῶν Ἀχαιῶν διὰ τὸ τὸν Ἀκροκόρινθον πραξικοπήσαντας καταλαβεῖν, ὑπέλαβον, εἰ τοὺς Λακεδαιμονίους προσλαβόντες ἔτι κοινωνοὺς σφίσι τῆς ἐπιβολῆς προεμβιβάσαιεν εἰς τὴν πρὸς τὸ ἔθνος ἀπέχθειαν, ῥᾳδίως ἂν καταγωνίσασθαι τοὺς Ἀχαιοὺς ἐν καιρῷ συνεπιθέμενοι καὶ πανταχόθεν περιστήσαντες αὐτοῖς τὸν πόλεμον. ὃ δὴ καὶ ταχέως ἂν ἐκ τῶν κατὰ λόγον ἐπετέλεσαν, εἰ μὴ τὸ κυριώτατον παρεῖδον τῆς προθέσεως, οὐ συλλογισάμενοι διότι ταῖς ἐπιβολαῖς Ἄρατον ἕξουσιν ἀνταγωνιστήν, ἄνδρα δυνάμενον πάσης εὐστοχεῖν περιστάσεως. τοιγαροῦν ὁρμήσαντες ἐπὶ τὸ πολυπραγμονεῖν καὶ χειρῶν ἄρχειν ἀδίκων οὐχ οἷον ἤνυσάν τι τῶν ἐπινοηθέντων, ἀλλὰ τοὐναντίον καὶ τὸν Ἄρατον τότε προεστῶτα καὶ τὸ ἔθνος ἐσωματοποίησαν, πραγματικῶς ἀντιπερισπάσαντος ἐκείνου καὶ λυμηναμένου τὰς ἐπιβολὰς αὐτῶν. ὡς δ’ ἐχειρίσθη τὰ ὅλα, δῆλον ἔσται διὰ τῶν λέγεσθαι μελλόντων.", "st": "2.45"}, {"sp": "N", "t": "θεωρῶν γὰρ τοὺς Αἰτωλοὺς ὁ προειρημένος ἀνὴρ τὸν μὲν πόλεμον τὸν πρὸς αὐτοὺς αἰσχυνομένους ἀναλαβεῖν ἐκ τοῦ φανεροῦ διὰ τὸ καὶ λίαν εἶναι προσφάτους τὰς ἐκ τῶν Ἀχαιῶν εὐεργεσίας περὶ τὸν Δημητριακὸν πόλεμον εἰς αὐτούς, συμβουλευομένους δὲ τοῖς Λακεδαιμονίοις καὶ φθονοῦντας τοῖς Ἀχαιοῖς ἐπὶ τοσοῦτον ὥστε Κλεομένους πεπραξικοπηκότος αὐτοὺς καὶ παρῃρημένου Τεγέαν, Μαντίνειαν, Ὀρχομενόν, τὰς Αἰτωλοῖς οὐ μόνον συμμαχίδας ὑπαρχούσας, ἀλλὰ καὶ συμπολιτευομένας τότε πόλεις, οὐχ οἷον ἀγανακτοῦντας ἐπὶ τούτοις, ἀλλὰ καὶ βεβαιοῦντας αὐτῷ τὴν παράληψιν, καὶ τοὺς πρότερον κατὰ τῶν μηδὲν ἀδικούντων πᾶσαν ἱκανὴν ποιουμένους πρόφασιν εἰς τὸ πολεμεῖν διὰ τὴν πλεονεξίαν τότε συνορῶν ἑκουσίως παρασπονδουμένους καὶ τὰς μεγίστας ἀπολλύντας πόλεις ἐθελοντὴν ἐφ’ ᾧ μόνον ἰδεῖν ἀξιόχρεων γενόμενον ἀνταγωνιστὴν Κλεομένη τοῖς Ἀχαιοῖς, ἔγνω δεῖν εἰς ταῦτα βλέπων οὗτός τε καὶ πάντες ὁμοίως οἱ προεστῶτες τοῦ τῶν Ἀχαιῶν πολιτεύματος πολέμου μὲν πρὸς μηδένα κατάρχειν, ἐνίστασθαι δὲ ταῖς τῶν Λακεδαιμονίων ἐπιβολαῖς. τὸ μὲν οὖν πρῶτον ἐπὶ τούτων ἦσαν τῶν διαλήψεων· θεωροῦντες δὲ κατὰ τοὺς ἑξῆς χρόνους τὸν Κλεομένη θρασέως ἐποικοδομοῦντα μὲν τὸ καλούμενον Ἀθήναιον ἐν τῇ τῶν Μεγαλοπολιτῶν χώρᾳ, πρόδηλον δὲ καὶ πικρὸν ἀναδεικνύντα σφίσι πολέμιον ἑαυτόν, τότε δὴ συναθροίσαντες τοὺς Ἀχαιοὺς ἔκριναν μετὰ τῆς βουλῆς ἀναλαμβάνειν φανερῶς τὴν πρὸς τοὺς Λακεδαιμονίους ἀπέχθειαν. ὁ μὲν οὖν Κλεομενικὸς προσαγορευθεὶς πόλεμος τοιαύτην ἔλαβε τὴν ἀρχὴν καὶ κατὰ τούτους τοὺς καιρούς.", "st": "2.46"}, {"sp": "N", "t": "οἱ δ’ Ἀχαιοὶ τὸ μὲν πρῶτον διὰ τῆς ἰδίας δυνάμεως ὥρμησαν ἀντοφθαλμεῖν τοῖς Λακεδαιμονίοις, ἅμα μὲν ὑπολαμβάνοντες κάλλιστον εἶναι τὸ μὴ δι’ ἑτέρων σφίσι πορίζεσθαι τὴν σωτηρίαν, ἀλλ’ αὐτοὺς δι’ αὑτῶν σῴζειν τὰς πόλεις καὶ τὴν χώραν, ἅμα δὲ βουλόμενοι καὶ τὴν πρὸς Πτολεμαῖον τηρεῖν φιλίαν διὰ τὰς προγεγενημένας εὐεργεσίας καὶ μὴ φαίνεσθαι πρὸς ἑτέρους ἐκτείνοντες τὰς χεῖρας, ἤδη δ’ ἐπὶ ποσὸν τοῦ πολέμου προβαίνοντος, καὶ τοῦ Κλεομένους τό τε πάτριον πολίτευμα καταλύσαντος καὶ τὴν ἔννομον βασιλείαν εἰς τυραννίδα μεταστήσαντος, χρωμένου δὲ καὶ τῷ πολέμῳ πρακτικῶς καὶ παραβόλως, προορώμενος Ἄρατος τὸ μέλλον καὶ δεδιὼς τήν τε τῶν Αἰτωλῶν ἀπόνοιαν καὶ τόλμαν ἔκρινε πρὸ πολλοῦ λυμαίνεσθαι τὴν ἐπιβολὴν αὐτῶν. κατανοῶν δὲ τὸν Ἀντίγονον καὶ πρᾶξιν ἔχοντα καὶ σύνεσιν καὶ πίστεως ἀντιποιούμενον, τοὺς δὲ βασιλεῖς σαφῶς εἰδὼς φύσει μὲν οὐδένα νομίζοντας οὔτε συνεργὸν οὔτε πολέμιον, ταῖς δὲ τοῦ συμφέροντος ψήφοις αἰεὶ μετροῦντας τὰς ἔχθρας καὶ τὰς φιλίας, ἐπεβάλετο λαλεῖν πρὸς τὸν εἰρημένον βασιλέα καὶ συμπλέκειν τὰς χεῖρας, ὑποδεικνύων αὐτῷ τὸ συμβησόμενον ἐκ τῶν πραγμάτων. προδήλως μὲν οὖν αὐτὸ πράττειν ἀσύμφορον ἡγεῖτο διὰ πλείους αἰτίας. τόν τε γὰρ Κλεομένη καὶ τοὺς Αἰτωλοὺς ἀνταγωνιστὰς παρασκευάζειν ἤμελλε πρὸς τὴν ἐπιβολήν, τούς τε πολλοὺς τῶν Ἀχαιῶν διατρέψειν, καταφεύγων ἐπὶ τοὺς ἐχθροὺς καὶ δοκῶν ὁλοσχερῶς ἀπεγνωκέναι τὰς ἐν αὐτοῖς ἐλπίδας· ὅπερ ἥκιστα φαίνεσθαι πράττων ἐβούλετο. διόπερ ἔχων τοιαύτην πρόθεσιν ἀδήλως αὐτὰ διενοεῖτο χειρίζειν. ἐξ οὗ πολλὰ παρὰ τὴν ἑαυτοῦ γνώμην ἠναγκάζετο καὶ λέγειν καὶ ποιεῖν πρὸς τοὺς ἐκτός, δι’ ὧν ἤμελλε τὴν ἐναντίαν ἔμφασιν ὑποδεικνύων ταύτην ἐπικρύψεσθαι τὴν οἰκονομίαν. ὧν χάριν ἔνια τούτων οὐδ’ ἐν τοῖς ὑπομνήμασι κατέταξεν.", "st": "2.47"}, {"sp": "N", "t": "εἰδὼς δὲ τοὺς Μεγαλοπολίτας κακοπαθοῦντας μὲν τῷ πολέμῳ διὰ τὸ παρακειμένους τῇ Λακεδαίμονι προπολεμεῖν τῶν ἄλλων, οὐ τυγχάνοντας δὲ τῆς καθηκούσης ἐπικουρίας ὑπὸ τῶν Ἀχαιῶν διὰ τὸ κἀκείνους δυσχρηστεῖσθαι θλιβομένους ὑπὸ τῆς περιστάσεως, σαφῶς δὲ γινώσκων οἰκείως διακειμένους αὐτοὺς πρὸς τὴν Μακεδόνων οἰκίαν ἐκ τῶν κατὰ τὸν Ἀμύντου Φίλιππον εὐεργεσιῶν, διειλήφει διότι ταχέως ἂν ὑπὸ τοῦ Κλεομένους πιεζόμενοι καταφύγοιεν ἐπὶ τὸν Ἀντίγονον καὶ τὰς Μακεδόνων ἐλπίδας· κοινολογηθεὶς οὖν δι’ ἀπορρήτων περὶ τῆς ὅλης ἐπιβολῆς Νικοφάνει καὶ Κερκιδᾷ τοῖς Μεγαλοπολίταις, οἵτινες ἦσαν αὐτοῦ πατρικοὶ ξένοι καὶ πρὸς τὴν ἐπιβολὴν εὐφυεῖς, ῥᾳδίως διὰ τούτων ὁρμὴν παρέστησε τοῖς Μεγαλοπολίταις εἰς τὸ πρεσβεύειν πρὸς τοὺς Ἀχαιοὺς καὶ παρακαλεῖν πέμπειν πρὸς τὸν Ἀντίγονον ὑπὲρ βοηθείας. οἱ μὲν οὖν Μεγαλοπολῖται κατέστησαν αὐτοὺς τοὺς περὶ τὸν Νικοφάνη καὶ τὸν Κερκιδᾶν πρεσβευτὰς πρός τε τοὺς Ἀχαιοὺς κἀκεῖθεν εὐθέως πρὸς τὸν Ἀντίγονον, ἂν αὐτοῖς συγκατάθηται τὸ ἔθνος. οἱ δ’ Ἀχαιοὶ συνεχώρησαν πρεσβεύειν τοῖς Μεγαλοπολίταις. σπουδῇ δὲ συμμίξαντες οἱ περὶ τὸν Νικοφάνη τῷ βασιλεῖ διελέγοντο περὶ μὲν τῆς ἑαυτῶν πατρίδος αὐτὰ τἀναγκαῖα διὰ βραχέων καὶ κεφαλαιωδῶς, τὰ δὲ πολλὰ περὶ τῶν ὅλων κατὰ τὰς ἐντολὰς τὰς Ἀράτου καὶ τὰς ὑποθέσεις.", "st": "2.48"}, {"sp": "N", "t": "αὗται δ’ ἦσαν ὑποδεικνύναι τὴν Αἰτωλῶν καὶ Κλεομένους κοινοπραγίαν τί δύναται καὶ ποῖ τείνει, καὶ δηλοῦν ὅτι πρώτοις μὲν αὐτοῖς Ἀχαιοῖς εὐλαβητέον, ἑξῆς δὲ καὶ μᾶλλον Ἀντιγόνῳ. τοῦτο μὲν γάρ, ὡς Ἀχαιοὶ τὸν ἐξ ἀμφοῖν πόλεμον οὐκ ἂν ὑπενέγκαιεν, εὐθεώρητον εἶναι πᾶσι, τοῦτο δ’, ὡς Αἰτωλοὶ καὶ Κλεομένης κρατήσαντες τούτων οὐκ εὐδοκήσουσιν οὐδὲ μὴ μείνωσιν ἐπὶ τῶν ὑποκειμένων, ἔτι τοῦ πρόσθεν ῥᾷον εἶναι τῷ νοῦν ἔχοντι συνιδεῖν. τήν τε γὰρ Αἰτωλῶν πλεονεξίαν οὐχ οἷον τοῖς Πελοποννησίων ὅροις εὐδοκῆσαί ποτ’ ἂν περιληφθεῖσαν, ἀλλ’ οὐδὲ τοῖς τῆς Ἑλλάδος, τήν τε Κλεομένους φιλοδοξίαν καὶ τὴν ὅλην ἐπιβολὴν κατὰ μὲν τὸ παρὸν αὐτῆς ἐφίεσθαι τῆς Πελοποννησίων ἀρχῆς, τυχόντα δὲ ταύτης τὸν προειρημένον κατὰ πόδας ἀνθέξεσθαι τῆς τῶν Ἑλλήνων ἡγεμονίας. ἧς οὐχ οἷόν τε καθικέσθαι μὴ οὐ πρόσθεν καταλύσαντα τὴν Μακεδόνων ἀρχήν. σκοπεῖν οὖν αὐτὸν ἠξίουν, προορώμενον τὸ μέλλον, πότερον συμφέρει τοῖς σφετέροις πράγμασι μετ’ Ἀχαιῶν καὶ Βοιωτῶν ἐν Πελοποννήσῳ πρὸς Κλεομένη πολεμεῖν ὑπὲρ τῆς τῶν Ἑλλήνων ἡγεμονίας ἢ προέμενον τὸ μέγιστον ἔθνος διακινδυνεύειν ἐν Θετταλίᾳ πρὸς Αἰτωλοὺς καὶ Βοιωτούς, ἔτι δ’ Ἀχαιοὺς καὶ Λακεδαιμονίους, ὑπὲρ τῆς Μακεδόνων ἀρχῆς. ἐὰν μὲν οὖν Αἰτωλοὶ τὴν ἐκ τῶν Ἀχαιῶν εἰς αὐτοὺς γεγενημένην εὔνοιαν ἐν τοῖς κατὰ Δημήτριον καιροῖς ἐντρεπόμενοι τὴν ἡσυχίαν ἄγειν ὑποκρίνωνται, καθάπερ καὶ νῦν, πολεμήσειν αὐτοὺς ἔφασαν τοὺς Ἀχαιοὺς πρὸς τὸν Κλεομένη· κἂν μὲν ἡ τύχη συνεπιλαμβάνηται, μὴ δεῖσθαι χρείας τῶν βοηθησόντων· ἂν δ’ ἀντιπίπτῃ τὰ τῆς τύχης, Αἰτωλοὶ δὲ συνεπιτίθωνται, προσέχειν αὐτὸν παρεκάλουν τοῖς πράγμασιν, ἵνα μὴ πρόηται τοὺς καιρούς, ἔτι δὲ δυναμένοις σῴζεσθαι Πελοποννησίοις ἐπαρκέσῃ· περὶ δὲ πίστεως καὶ χάριτος ἀποδόσεως ῥᾳθυμεῖν αὐτὸν ᾤοντο δεῖν· τῆς γὰρ χρείας ἐπιτελουμένης αὐτὸν εὑρήσειν τὸν Ἄρατον εὐδοκουμένας ἀμφοτέροις ὑπισχνοῦντο πίστεις. ὁμοίως δ’ ἔφασαν καὶ τὸν καιρὸν τῆς βοηθείας αὐτὸν ὑποδείξειν.", "st": "2.49"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀντίγονος ἀκούσας ταῦτα καὶ δόξας ἀληθινῶς καὶ πραγματικῶς ὑποδεικνύναι τὸν Ἄρατον, προσεῖχε τοῖς ἑξῆς πραττομένοις ἐπιμελῶς. ἔγραψε δὲ καὶ τοῖς Μεγαλοπολίταις, ἐπαγγελλόμενος βοηθήσειν, ἐὰν καὶ τοῖς Ἀχαιοῖς τοῦτο βουλομένοις ᾖ. τῶν δὲ περὶ τὸν Νικοφάνη καὶ Κερκιδᾶν ἐπανελθόντων εἰς οἶκον καὶ τάς τε παρὰ τοῦ βασιλέως ἐπιστολὰς ἀποδόντων καὶ τὴν λοιπὴν εὔνοιαν αὐτοῦ καὶ προθυμίαν διασαφούντων, μετεωρισθέντες οἱ Μεγαλοπολῖται προθύμως ἔσχον ἰέναι πρὸς τὴν σύνοδον τῶν Ἀχαιῶν καὶ παρακαλεῖν ἐπισπάσασθαι τὸν Ἀντίγονον καὶ τὰ πράγματα κατὰ σπουδὴν ἐγχειρίζειν αὐτῷ. ὁ δ’ Ἄρατος διακούσας κατ’ ἰδίαν τῶν περὶ τὸν Νικοφάνη τὴν τοῦ βασιλέως αἵρεσιν, ἣν ἔχοι πρός τε τοὺς Ἀχαιοὺς καὶ πρὸς αὐτόν, περιχαρὴς ἦν τῷ μὴ διὰ κενῆς πεποιῆσθαι τὴν ἐπίνοιαν μηδ’ εὑρῆσθαι κατὰ τὴν τῶν Αἰτωλῶν ἐλπίδα τὸν Ἀντίγονον εἰς τέλος ἀπηλλοτριωμένον ἑαυτοῦ. πάνυ δὲ πρὸς λόγον ἡγεῖτο γίνεσθαι καὶ τὸ τοὺς Μεγαλοπολίτας προθύμους εἶναι διὰ τῶν Ἀχαιῶν φέρειν ἐπὶ τὸν Ἀντίγονον τὰ πράγματα. μάλιστα μὲν γάρ, ὡς ἐπάνω προεῖπον, ἔσπευδεν μὴ προσδεηθῆναι τῆς βοηθείας· εἰ δ’ ἐξ ἀνάγκης ἐπὶ τοῦτο δέοι καταφεύγειν, οὐ μόνον ἠβούλετο δι’ αὑτοῦ γενέσθαι τὴν κλῆσιν, ἔτι δὲ μᾶλλον ἐξ ἁπάντων τῶν Ἀχαιῶν. ἠγωνία γάρ, εἰ παραγενόμενος ὁ βασιλεὺς καὶ κρατήσας τῷ πολέμῳ τοῦ Κλεομένους καὶ τῶν Λακεδαιμονίων ἀλλοιότερόν τι βουλεύσοιτο περὶ τῆς κοινῆς πολιτείας, μή ποθ’ ὁμολογουμένως τῶν συμβαινόντων αὐτὸς ἀναλάβῃ τὴν αἰτίαν, δόξαντος δικαίως τοῦτο πράττειν διὰ τὴν ἐξ αὐτοῦ προγεγενημένην ἀδικίαν περὶ τὸν Ἀκροκόρινθον εἰς τὴν Μακεδόνων οἰκίαν. διόπερ ἅμα τῷ παρελθόντας τοὺς Μεγαλοπολίτας εἰς τὸ κοινὸν βουλευτήριον τά τε γράμματα τοῖς Ἀχαιοῖς ἐπιδεικνύναι καὶ διασαφεῖν τὴν ὅλην εὔνοιαν τοῦ βασιλέως, πρὸς δὲ τούτοις ἀξιοῦν ἐπισπάσασθαι τὸν Ἀντίγονον τὴν ταχίστην, εἶναι δὲ καὶ τὸ πλῆθος ἐπὶ τῆς αὐτῆς ὁρμῆς, προελθὼν Ἄρατος καὶ τήν τε τοῦ βασιλέως προθυμίαν ἀποδεξάμενος καὶ τὴν τῶν πολλῶν διάληψιν ἐπαινέσας παρεκάλει διὰ πλειόνων μάλιστα μὲν πειρᾶσθαι δι’ αὑτῶν σῴζειν καὶ τὰς πόλεις καὶ τὴν χώραν· οὐδὲν γὰρ εἶναι τούτου κάλλιον οὐδὲ συμφορώτερον· ἐὰν δ’ ἄρα πρὸς τοῦτο τὸ μέρος ἀντιβαίνῃ τὰ τῆς τύχης, πρότερον ἔφη δεῖν ἐξελέγξαντας πάσας τὰς ἐν αὑτοῖς ἐλπίδας τότε καταφεύγειν ἐπὶ τὰς τῶν φίλων βοηθείας.", "st": "2.50"}, {"sp": "N", "t": "ἐπισημηναμένου δὲ τοῦ πλήθους, ἔδοξε μένειν ἐπὶ τῶν ὑποκειμένων καὶ δι’ αὑτῶν ἐπιτελεῖν τὸν ἐνεστῶτα πόλεμον. ἐπεὶ δὲ Πτολεμαῖος ἀπογνοὺς μὲν τὸ ἔθνος Κλεομένει χορηγεῖν ἐπεβάλετο, βουλόμενος αὐτὸν ἐπαλείφειν ἐπὶ τὸν Ἀντίγονον διὰ τὸ πλείους ἐλπίδας ἔχειν ἐν τοῖς Λακεδαιμονίοις ἤπερ ἐν τοῖς Ἀχαιοῖς τοῦ δύνασθαι διακατέχειν τὰς τῶν ἐν Μακεδονίᾳ βασιλέων ἐπιβολάς, οἱ δ’ Ἀχαιοὶ τὸ μὲν πρῶτον ἠλαττώθησαν περὶ τὸ Λύκαιον, συμπλακέντες κατὰ πορείαν τῷ Κλεομένει, τὸ δὲ δεύτερον ἐκ παρατάξεως ἡττήθησαν ἐν τοῖς Λαδοκείοις καλουμένοις τῆς Μεγαλοπολίτιδος, ὅτε καὶ Λυδιάδας ἔπεσε, τὸ δὲ τρίτον ὁλοσχερῶς ἔπταισαν ἐν τῇ Δυμαίᾳ περὶ τὸ καλούμενον Ἑκατόμβαιον, πανδημεὶ διακινδυνεύοντες, τότ’ ἤδη τῶν πραγμάτων οὐκέτι διδόντων ἀναστροφὴν ἠνάγκαζε τὰ περιεστῶτα καταφεύγειν ὁμοθυμαδὸν ἐπὶ τὸν Ἀντίγονον. ἐν ᾧ καιρῷ πρεσβευτὴν τὸν υἱὸν ἐξαποστείλας Ἄρατος πρὸς Ἀντίγονον ἐβεβαιώσατο τὰ περὶ τῆς βοηθείας. παρεῖχε δ’ αὐτοῖς ἀπορίαν καὶ δυσχρηστίαν μεγίστην τὸ μήτε τὸν βασιλέα δοκεῖν ἂν βοηθῆσαι χωρὶς τοῦ κομίσασθαι τὸν Ἀκροκόρινθον καὶ λαβεῖν ὁρμητήριον πρὸς τὸν ἐνεστῶτα πόλεμον τὴν τῶν Κορινθίων πόλιν, μήτε τοὺς Ἀχαιοὺς ἂν τολμῆσαι Κορινθίους ἄκοντας ἐγχειρίσαι Μακεδόσι. διὸ καὶ τὸ πρῶτον ὑπέρθεσιν ἔσχε τὸ διαβούλιον χάριν τῆς περὶ τῶν πίστεων ἐπισκέψεως.", "st": "2.51"}, {"sp": "N", "t": "ὁ δὲ Κλεομένης καταπληξάμενος τοῖς προειρημένοις εὐτυχήμασι λοιπὸν ἀδεῶς ἐπεπορεύετο τὰς πόλεις, ἃς μὲν πείθων αἷς δὲ τὸν φόβον ἀνατεινόμενος. προσλαβὼν δὲ τῷ τρόπῳ τούτῳ Καφύας, Πελλήνην, Φενεόν, Ἄργος, Φλιοῦντα, Κλεωνάς, Ἐπίδαυρον, Ἑρμιόνα, Τροίζηνα, τελευταῖον Κόρινθον, αὐτὸς μὲν προσεστρατοπέδευσε τῇ τῶν Σικυωνίων πόλει, τοὺς δ’ Ἀχαιοὺς ἀπέλυσε τοῦ μεγίστου προβλήματος. τῶν γὰρ Κορινθίων τῷ μὲν Ἀράτῳ στρατηγοῦντι καὶ τοῖς Ἀχαιοῖς παραγγειλάντων ἐκ τῆς πόλεως ἀπαλλάττεσθαι, πρὸς δὲ τὸν Κλεομένη διαπεμπομένων καὶ καλούντων, παρεδόθη τοῖς Ἀχαιοῖς ἀφορμὴ καὶ πρόφασις εὔλογος. ἧς ἐπιλαβόμενος Ἄρατος καὶ προτείνας Ἀντιγόνῳ τὸν Ἀκροκόρινθον, κατεχόντων Ἀχαιῶν τότε τὸν τόπον τοῦτον, ἔλυσε μὲν τὸ γεγονὸς ἔγκλημα πρὸς τὴν οἰκίαν, ἱκανὴν δὲ πίστιν παρέσχετο τῆς πρὸς τὰ μέλλοντα κοινωνίας, τὸ δὲ συνέχον, ὁρμητήριον παρεσκεύασεν Ἀντιγόνῳ πρὸς τὸν κατὰ Λακεδαιμονίων πόλεμον. ὁ δὲ Κλεομένης ἐπιγνοὺς τοὺς Ἀχαιοὺς συντιθεμένους τὰ πρὸς τὸν Ἀντίγονον, ἀναζεύξας ἀπὸ τοῦ Σικυῶνος κατεστρατοπέδευσε περὶ τὸν Ἰσθμόν, διαλαβὼν χάρακι καὶ τάφρῳ τὸν μεταξὺ τόπον τοῦ τ’ Ἀκροκορίνθου καὶ τῶν Ὀνείων καλουμένων ὀρῶν, πᾶσαν ἤδη βεβαίως περιειληφὼς ταῖς ἐλπίσι τὴν Πελοποννησίων ἀρχήν. Ἀντίγονος δὲ πάλαι μὲν ἦν ἐν παρασκευῇ, καραδοκῶν τὸ μέλλον κατὰ τὰς ὑποθέσεις τὰς Ἀράτου· τότε δὲ συλλογιζόμενος ἐκ τῶν προσπιπτόντων ὅσον οὔπω παρεῖναι τὸν Κλεομένη μετὰ τῆς δυνάμεως εἰς Θετταλίαν, διαπεμψάμενος πρός τε τὸν Ἄρατον καὶ τοὺς Ἀχαιοὺς ὑπὲρ τῶν ὡμολογημένων ἧκεν ἔχων τὰς δυνάμεις διὰ τῆς Εὐβοίας ἐπὶ τὸν Ἰσθμόν. οἱ γὰρ Αἰτωλοὶ πρὸς τοῖς ἄλλοις καὶ τότε βουλόμενοι κωλῦσαι τὸν Ἀντίγονον τῆς βοηθείας, ἀπεῖπον αὐτῷ πορεύεσθαι μετὰ δυνάμεως ἐντὸς Πυλῶν· εἰ δὲ μή, διότι κωλύσουσι μεθ’ ὅπλων αὐτοῦ τὴν δίοδον. ὁ μὲν οὖν Ἀντίγονος καὶ Κλεομένης ἀντεστρατοπέδευον ἀλλήλοις, ὁ μὲν εἰσελθεῖν σπουδάζων εἰς Πελοπόννησον, ὁ δὲ Κλεομένης κωλῦσαι τῆς εἰσόδου τὸν Ἀντίγονον.", "st": "2.52"}, {"sp": "N", "t": "οἱ δ’ Ἀχαιοί, καίπερ οὐ μετρίως ἠλαττωμένοι τοῖς ὅλοις, ὅμως οὐκ ἀφίσταντο τῆς προθέσεως οὐδ’ ἐγκατέλειπον τὰς ἐν αὑτοῖς ἐλπίδας, ἀλλ’ ἅμα τῷ τὸν Ἀριστοτέλη τὸν Ἀργεῖον ἐπαναστῆναι τοῖς Κλεομενισταῖς βοηθήσαντες καὶ παρεισπεσόντες μετὰ Τιμοξένου τοῦ στρατηγοῦ κατέλαβον τὴν τῶν Ἀργείων πόλιν. ὃ δὴ καὶ νομιστέον αἰτιώτατον γεγονέναι πραγμάτων κατορθώσεως. τὸ γὰρ ἐπιλαβόμενον τῆς ὁρμῆς τοῦ Κλεομένους καὶ προηττῆσαν τὰς ψυχὰς τῶν δυνάμεων τοῦτ’ ἦν, ὡς ἐξ αὐτῶν φανερὸν ἐγένετο τῶν πραγμάτων. καὶ γὰρ τόπους εὐφυεστέρους προκατέχων καὶ χορηγίαις δαψιλεστέραις Ἀντιγόνου χρώμενος καὶ τόλμῃ καὶ φιλοτιμίᾳ μείζονι παρωρμημένος, ὅμως ἅμα τῷ προσπεσεῖν αὐτῷ διότι κατειλῆφθαι συμβαίνει τὴν τῶν Ἀργείων πόλιν ὑπὸ τῶν Ἀχαιῶν, εὐθὺς ἀνάσπαστος, ἀπολιπὼν τὰ προδεδηλωμένα προτερήματα, φυγῇ παραπλησίαν ἐποιεῖτο τὴν ἀποχώρησιν, δείσας μὴ πανταχόθεν αὐτὸν περιστῶσιν οἱ πολέμιοι. παραπεσὼν δ’ εἰς Ἄργος καὶ κατὰ ποσὸν ἀντιποιησάμενος τῆς πόλεως, μετὰ ταῦτα γενναίως μὲν τῶν Ἀχαιῶν, φιλοτίμως δὲ τῶν Ἀργείων ἐκ μεταμελείας αὐτὸν ἀμυναμένων, ἀποπεσὼν καὶ ταύτης τῆς ἐπιβολῆς καὶ ποιησάμενος τὴν πορείαν διὰ Μαντινείας οὕτως ἐπανῆλθεν εἰς τὴν Σπάρτην.", "st": "2.53"}, {"sp": "N", "t": "ὁ δ’ Ἀντίγονος ἀσφαλῶς εἰς τὴν Πελοπόννησον εἰσελθὼν παρέλαβε τὸν Ἀκροκόρινθον, οὐδένα δὲ χρόνον μείνας εἴχετο τῶν προκειμένων καὶ παρῆν εἰς Ἄργος. ἐπαινέσας δὲ τοὺς Ἀργείους καὶ καταστησάμενος τὰ κατὰ τὴν πόλιν αὖθις ἐκ ποδὸς ἐκίνει, ποιούμενος τὴν πορείαν ὡς ἐπ’ Ἀρκαδίας. ἐκβαλὼν δὲ τὰς φρουρὰς ἐκ τῶν ἐποικοδομηθέντων χωρίων ὑπὸ Κλεομένους κατά τε τὴν Αἰγῦτιν καὶ Βελμινᾶτιν χώραν καὶ παραδοὺς τὰ φρούρια Μεγαλοπολίταις ἧκε πρὸς τὴν τῶν Ἀχαιῶν σύνοδον εἰς Αἴγιον. ἀπολογισάμενος δὲ περὶ τῶν καθ’ αὑτὸν καὶ χρηματίσας περὶ τῶν μελλόντων, ἔτι δὲ κατασταθεὶς ἡγεμὼν ἁπάντων τῶν συμμάχων, μετὰ ταῦτα χρόνον μέν τινα παραχειμάζων διέτριβε περὶ Σικυῶνα καὶ Κόρινθον. τῆς δ’ ἐαρινῆς ὥρας ἐνισταμένης ἀναλαβὼν τὰς δυνάμεις προῆγε. καὶ διανύσας τριταῖος πρὸς τὴν τῶν Τεγεατῶν πόλιν, ἀπηντηκότων καὶ τῶν Ἀχαιῶν ἐνταῦθα, περιστρατοπεδεύσας ἤρξατο πολιορκεῖν αὐτήν. τῶν δὲ Μακεδόνων ἐνεργῶς χρωμένων τῇ τε λοιπῇ πολιορκίᾳ καὶ τοῖς ὀρύγμασι, ταχέως ἀπελπίσαντες οἱ Τεγεᾶται τὴν σωτηρίαν παρέδοσαν αὑτούς. ὁ δ’ Ἀντίγονος ἀσφαλισάμενος τὰ κατὰ τὴν πόλιν εἴχετο κατὰ τὸ συνεχὲς τῶν ἑξῆς καὶ προῆγε κατὰ σπουδὴν εἰς τὴν Λακωνικήν. ἐγγίσας δὲ τῷ Κλεομένει προκαθημένῳ τῆς ἑαυτοῦ χώρας κατεπείραζε καὶ συνίστατό τινας ἀκροβολισμούς. προσπεσόντος δὲ διὰ τῶν κατασκόπων αὐτῷ τοὺς ἐξ Ὀρχομενοῦ στρατιώτας παραβεβοηθηκέναι πρὸς τὸν Κλεομένη, παραυτίκα ποιησάμενος ἀναζυγὴν ἠπείγετο. καὶ τὸν μὲν Ὀρχομενὸν ἐξ ἐφόδου κατὰ κράτος εἷλε· μετὰ δὲ ταῦτα περιστρατοπεδεύσας τὴν τῶν Μαντινέων ἐπολιόρκει πόλιν. ταχὺ δὲ καὶ ταύτην καταπληξαμένων τῶν Μακεδόνων καὶ λαβόντων ὑποχείριον, ἀναζεύξας προῆγε τὴν ἐφ’ Ἡραίας καὶ Τελφούσης. παραλαβὼν δὲ καὶ ταύτας τὰς πόλεις, ἐθελοντὴν προσχωρησάντων αὐτῷ τῶν κατοικούντων, οὕτως ἤδη συνάπτοντος τοῦ χειμῶνος παρῆν εἰς Αἴγιον πρὸς τὴν τῶν Ἀχαιῶν σύνοδον. καὶ τοὺς μὲν Μακεδόνας ἐπ’ οἴκου διαφῆκε πάντας εἰς τὴν χειμασίαν, αὐτὸς δὲ τοῖς Ἀχαιοῖς διελέγετο καὶ συνδιενοεῖτο περὶ τῶν ἐνεστώτων.", "st": "2.54"}, {"sp": "N", "t": "κατὰ δὲ τοὺς καιροὺς τούτους συνθεωρῶν ὁ Κλεομένης τὰς μὲν δυνάμεις διαφειμένας, τὸν δ’ Ἀντίγονον μετὰ τῶν μισθοφόρων ἐν Αἰγίῳ διατρίβοντα καὶ τριῶν ἡμερῶν ὁδὸν ἀφεστῶτα τῆς Μεγάλης πόλεως, τὴν δὲ πόλιν ταύτην εἰδὼς δυσφύλακτον οὖσαν διὰ τὸ μέγεθος καὶ τὴν ἐρημίαν, τότε δὲ καὶ ῥᾳθύμως τηρουμένην διὰ τὴν Ἀντιγόνου παρουσίαν, τὸ δὲ μέγιστον, ἀπολωλότας τοὺς πλείστους τῶν ἐν ταῖς ἡλικίαις ἔν τε τῇ περὶ τὸ Λύκαιον καὶ μετὰ ταῦτα τῇ περὶ Λαδόκεια μάχῃ, λαβὼν συνεργούς τινας τῶν ἐκ Μεσσήνης φυγάδων, οἳ διατρίβοντες ἐτύγχανον ἐν τῇ Μεγάλῃ πόλει, παρεισῆλθε διὰ τούτων λάθρᾳ νυκτὸς ἐντὸς τῶν τειχῶν. τῆς δ’ ἡμέρας ἐπιγενομένης παρ’ ὀλίγον ἦλθε τοῦ μὴ μόνον ἐκπεσεῖν, ἀλλὰ καὶ τοῖς ὅλοις κινδυνεῦσαι διὰ τὴν εὐψυχίαν τῶν Μεγαλοπολιτῶν. ὃ δὴ καὶ τρισὶ μησὶ πρότερον αὐτῷ συνέβη παθεῖν παρεισπεσόντι κατὰ τὸν Κωλαιὸν προσαγορευόμενον τόπον τῆς πόλεως. τότε δὲ τῷ πλήθει τῆς δυνάμεως καὶ τῷ προκαταλαμβάνεσθαι τοὺς εὐκαίρους τόπους καθίκετο τῆς ἐπιβολῆς καὶ πέρας ἐκβαλὼν τοὺς Μεγαλοπολίτας κατέσχε τὴν πόλιν. γενόμενος δ’ ἐγκρατὴς οὕτως αὐτὴν πικρῶς διέφθειρεν καὶ δυσμενῶς ὥστε μηδ’ ἐλπίσαι μηδένα διότι δύναιτ’ ἂν συνοικισθῆναι πάλιν. τοῦτο δὲ ποιῆσαί μοι δοκεῖ διὰ τὸ κατὰ τὰς τῶν καιρῶν περιστάσεις παρὰ μόνοις Μεγαλοπολίταις καὶ Στυμφαλίοις μηδέποτε δυνηθῆναι μήθ’ αἱρετιστὴν καὶ κοινωνὸν τῶν ἰδίων ἐλπίδων μήτε προδότην κατασκευάσασθαι. τὸ μὲν γὰρ Κλειτορίων φιλελεύθερον καὶ γενναῖον εἷς ἀνὴρ κατῄσχυνε διὰ τὴν ἑαυτοῦ κακίαν, Θεάρκης· ὃν εἰκότως ἐξαρνοῦνται Κλειτόριοι μὴ φῦναι παρὰ σφίσι, γενέσθαι δ’ ὑποβολιμαῖον ἐξ Ὀρχομενοῦ τῶν ἐπηλύδων τινὸς στρατιωτῶν.", "st": "2.55"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν κατὰ τοὺς αὐτοὺς καιροὺς Ἀράτῳ γεγραφότων παρ’ ἐνίοις ἀποδοχῆς ἀξιοῦται Φύλαρχος, ἐν πολλοῖς ἀντιδοξῶν καὶ τἀναντία γράφων αὐτῷ, χρήσιμον ἂν εἴη, μᾶλλον δ’ ἀναγκαῖον ἡμῖν, Ἀράτῳ προῃρημένοις κατακολουθεῖν περὶ τῶν Κλεομενικῶν, μὴ παραλιπεῖν ἄσκεπτον τοῦτο τὸ μέρος, ἵνα μὴ τὸ ψεῦδος ἐν τοῖς συγγράμμασιν ἰσοδυναμοῦν ἀπολείπωμεν πρὸς τὴν ἀλήθειαν. καθόλου μὲν οὖν ὁ συγγραφεὺς οὗτος πολλὰ παρ’ ὅλην τὴν πραγματείαν εἰκῇ καὶ ὡς ἔτυχεν εἴρηκεν. πλὴν περὶ μὲν τῶν ἄλλων ἴσως οὐκ ἀναγκαῖον ἐπιτιμᾶν κατὰ τὸ παρὸν οὐδ’ ἐξακριβοῦν· ὅσα δὲ συνεπιβάλλει τοῖς ὑφ’ ἡμῶν γραφομένοις καιροῖς — ταῦτα δ’ ἔστιν τὰ περὶ τὸν Κλεομενικὸν πόλεμον — ὑπὲρ τούτων ἀναγκαῖόν ἐστιν ἡμῖν διευκρινεῖν. ἔσται δὲ πάντως ἀρκοῦντα ταῦτα πρὸς τὸ καὶ τὴν ὅλην αὐτοῦ προαίρεσιν καὶ δύναμιν ἐν τῇ πραγματείᾳ καταμαθεῖν. βουλόμενος δὴ διασαφεῖν τὴν ὠμότητα τὴν Ἀντιγόνου καὶ Μακεδόνων, ἅμα δὲ τούτοις τὴν Ἀράτου καὶ τῶν Ἀχαιῶν, φησὶ τοὺς Μαντινέας γενομένους ὑποχειρίους μεγάλοις περιπεσεῖν ἀτυχήμασι, καὶ τὴν ἀρχαιοτάτην καὶ μεγίστην πόλιν τῶν κατὰ τὴν Ἀρκαδίαν τηλικαύταις παλαῖσαι συμφοραῖς ὥστε πάντας εἰς ἐπίστασιν καὶ δάκρυα τοὺς Ἕλληνας ἀγαγεῖν. σπουδάζων δ’ εἰς ἔλεον ἐκκαλεῖσθαι τοὺς ἀναγινώσκοντας καὶ συμπαθεῖς ποιεῖν τοῖς λεγομένοις, εἰσάγει περιπλοκὰς γυναικῶν καὶ κόμας διερριμμένας καὶ μαστῶν ἐκβολάς, πρὸς δὲ τούτοις δάκρυα καὶ θρήνους ἀνδρῶν καὶ γυναικῶν ἀναμὶξ τέκνοις καὶ γονεῦσι γηραιοῖς ἀπαγομένων. ποιεῖ δὲ τοῦτο παρ’ ὅλην τὴν ἱστορίαν, πειρώμενος ἐν ἑκάστοις ἀεὶ πρὸ ὀφθαλμῶν τιθέναι τὰ δεινά. τὸ μὲν οὖν ἀγεννὲς καὶ γυναικῶδες τῆς αἱρέσεως αὐτοῦ παρείσθω, τὸ δὲ τῆς ἱστορίας οἰκεῖον ἅμα καὶ χρήσιμον ἐξεταζέσθω. δεῖ τοιγαροῦν οὐκ ἐπιπλήττειν τὸν συγγραφέα τερατευόμενον διὰ τῆς ἱστορίας τοὺς ἐντυγχάνοντας οὐδὲ τοὺς ἐνδεχομένους λόγους ζητεῖν καὶ τὰ παρεπόμενα τοῖς ὑποκειμένοις ἐξαριθμεῖσθαι, καθάπερ οἱ τραγῳδιογράφοι, τῶν δὲ πραχθέντων καὶ ῥηθέντων κατ’ ἀλήθειαν αὐτῶν μνημονεύειν πάμπαν, κἂν πάνυ μέτρια τυγχάνωσιν ὄντα. τὸ γὰρ τέλος ἱστορίας καὶ τραγῳδίας οὐ ταὐτόν, ἀλλὰ τοὐναντίον. ἐκεῖ μὲν γὰρ δεῖ διὰ τῶν πιθανωτάτων λόγων ἐκπλῆξαι καὶ ψυχαγωγῆσαι κατὰ τὸ παρὸν τοὺς ἀκούοντας, ἐνθάδε δὲ διὰ τῶν ἀληθινῶν ἔργων καὶ λόγων εἰς τὸν πάντα χρόνον διδάξαι καὶ πεῖσαι τοὺς φιλομαθοῦντας, ἐπειδήπερ ἐν ἐκείνοις μὲν ἡγεῖται τὸ πιθανόν, κἂν ᾖ ψεῦδος, διὰ τὴν ἀπάτην τῶν θεωμένων, ἐν δὲ τούτοις τἀληθὲς διὰ τὴν ὠφέλειαν τῶν φιλομαθούντων. χωρίς τε τούτων τὰς πλείστας ἡμῖν ἐξηγεῖται τῶν περιπετειῶν, οὐχ ὑποτιθεὶς αἰτίαν καὶ τρόπον τοῖς γινομένοις, ὧν χωρὶς οὔτ’ ἐλεεῖν εὐλόγως οὔτ’ ὀργίζεσθαι καθηκόντως δυνατὸν ἐπ’ οὐδενὶ τῶν συμβαινόντων. ἐπεὶ τίς ἀνθρώπων οὐ δεινὸν ἡγεῖται τύπτεσθαι τοὺς ἐλευθέρους; ἀλλ’ ὅμως, ἐὰν μὲν ἄρχων ἀδίκων χειρῶν πάθῃ τις τοῦτο, δικαίως κρίνεται πεπονθέναι· ἐὰν δ’ ἐπὶ διορθώσει καὶ μαθήσει ταὐτὸ τοῦτο γίνηται, προσέτι καὶ τιμῆς καὶ χάριτος οἱ τύπτοντες τοὺς ἐλευθέρους ἀξιοῦνται. καὶ μὴν τό γε τοὺς πολίτας ἀποκτεινύναι μέγιστον ἀσέβημα τίθεται καὶ μεγίστων ἄξιον προστίμων· καίτοι γε προφανῶς ὁ μὲν τὸν κλέπτην ἢ μοιχὸν ἀποκτείνας ἀθῷός ἐστιν, ὁ δὲ τὸν προδότην ἢ τύραννον τιμῶν καὶ προεδρείας τυγχάνει παρὰ πᾶσιν. οὕτως ἐν παντὶ τὸ τέλος κεῖται τῆς διαλήψεως ὑπὲρ τούτων οὐκ ἐν τοῖς τελουμένοις, ἀλλ’ ἐν ταῖς αἰτίαις καὶ προαιρέσεσι τῶν πραττόντων καὶ ταῖς τούτων διαφοραῖς.", "st": "2.56"}, {"sp": "N", "t": "Μαντινεῖς τοίνυν τὸ μὲν πρῶτον ἐγκαταλιπόντες τὴν μετὰ τῶν Ἀχαιῶν πολιτείαν ἐθελοντὴν Αἰτωλοῖς ἐνεχείρισαν αὑτοὺς καὶ τὴν πατρίδα, μετὰ δὲ ταῦτα Κλεομένει. γεγονότες δ’ ἐπὶ τοιαύτης προαιρέσεως καὶ μετέχοντες τῆς Λακεδαιμονίων πολιτείας ἔτει τετάρτῳ πρότερον τῆς Ἀντιγόνου παρουσίας ἑάλωσαν κατὰ κράτος ὑπὸ τῶν Ἀχαιῶν, Ἀράτου πραξικοπήσαντος αὐτῶν τὴν πόλιν. ἐν ᾧ καιρῷ τοσοῦτον ἀπέσχον τοῦ παθεῖν τι δεινὸν διὰ τὴν προειρημένην ἁμαρτίαν ὡς καὶ περιβόητον συνέβη γενέσθαι τὸ πραχθὲν διὰ τὴν ὀξύτητα τῆς κατὰ τὴν προαίρεσιν ἀμφοτέρων μεταβολῆς. ἅμα γὰρ τῷ κατασχεῖν τὴν πόλιν Ἄρατος παραυτίκα μὲν τοῖς ὑφ’ αὑτὸν ταττομένοις παρήγγελλε μηδένα μηδενὸς ἅπτεσθαι τῶν ἀλλοτρίων, ἑξῆς δὲ τούτοις τοὺς Μαντινέας συναθροίσας παρεκάλεσε θαρρεῖν καὶ μένειν ἐπὶ τῶν ἰδίων· ὑπάρξειν γὰρ αὐτοῖς τὴν ἀσφάλειαν πολιτευομένοις μετὰ τῶν Ἀχαιῶν. τοῖς δὲ Μαντινεῦσιν ἀνυπονοήτου καὶ παραδόξου φανείσης τῆς ἐλπίδος, παραυτίκα πάντες ἐπὶ τῆς ἐναντίας ἐγένοντο γνώμης. καὶ πρὸς οὓς μικρῷ πρότερον μαχόμενοι πολλοὺς μὲν τῶν ἀναγκαίων ἐπεῖδον ἀπολλυμένους, οὐκ ὀλίγους δ’ αὐτῶν βιαίοις τραύμασι περιπεσόντας, τούτους εἰς τὰς ἰδίας οἰκίας εἰσαγόμενοι καὶ ποιησάμενοι σφίσι καὶ τοῖς ἄλλοις ἀναγκαίοις ὁμεστίους, οὐδὲν ἀπέλειπον τῆς μετ’ ἀλλήλων φιλοφροσύνης. καὶ τοῦτ’ εἰκότως ἐποίουν· οὐ γὰρ οἶδ’ εἴ τινες ἀνθρώπων εὐγνωμονεστέροις ἐνέτυχον πολεμίοις οὐδ’ εἴ τινες ἀβλαβέστερον ἐπάλαισαν τοῖς μεγίστοις δοκοῦσιν εἶναι συμπτώμασι Μαντινέων διὰ τὴν Ἀράτου καὶ τῶν Ἀχαιῶν εἰς αὐτοὺς φιλανθρωπίαν.", "st": "2.57"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα προορώμενοι τὰς ἐν αὑτοῖς στάσεις καὶ τὰς ὑπ’ Αἰτωλῶν καὶ Λακεδαιμονίων ἐπιβουλάς, πρεσβεύσαντες πρὸς τοὺς Ἀχαιοὺς ἠξίωσαν δοῦναι παραφυλακὴν αὑτοῖς. οἱ δὲ πεισθέντες ἀπεκλήρωσαν ἐξ αὑτῶν τριακοσίους ἄνδρας· ὧν οἱ λαχόντες ὥρμησαν, ἀπολιπόντες τὰς ἰδίας πατρίδας καὶ τοὺς βίους, καὶ διέτριβον ἐν Μαντινείᾳ, παραφυλάττοντες τὴν ἐκείνων ἐλευθερίαν ἅμα καὶ σωτηρίαν. σὺν δὲ τούτοις καὶ μισθοφόρους διακοσίους ἐξέπεμψαν, οἳ μετὰ τῶν Ἀχαιῶν συνδιετήρουν τὴν ὑποκειμένην αὐτοῖς κατάστασιν. μετ’ οὐ πολὺ δὲ στασιάσαντες πρὸς σφᾶς οἱ Μαντινεῖς καὶ Λακεδαιμονίους ἐπισπασάμενοι τήν τε πόλιν ἐνεχείρισαν καὶ τοὺς παρὰ τῶν Ἀχαιῶν διατρίβοντας παρ’ αὑτοῖς κατέσφαξαν· οὗ μεῖζον παρασπόνδημα καὶ δεινότερον οὐδ’ εἰπεῖν εὐμαρές. ἐπειδὴ γὰρ ἔδοξε σφίσι καθόλου τὴν πρὸς τὸ ἔθνος χάριν καὶ φιλίαν ἀθετεῖν, τῶν γε προειρημένων ἀνδρῶν ἐχρῆν δήπου φεισαμένους ἐᾶσαι πάντας ὑποσπόνδους ἀπελθεῖν· τοῦτο γὰρ καὶ τοῖς πολεμίοις ἔθος ἐστὶ συγχωρεῖσθαι κατὰ τοὺς κοινοὺς τῶν ἀνθρώπων νόμους. οἱ δ’ ἵνα Κλεομένει καὶ Λακεδαιμονίοις ἱκανὴν παράσχωνται πίστιν πρὸς τὴν ἐνεστῶσαν ἐπιβολήν, τὰ κοινὰ τῶν ἀνθρώπων δίκαια παραβάντες τὸ μέγιστον ἀσέβημα κατὰ προαίρεσιν ἐπετέλεσαν. τὸ γὰρ τούτων αὐτόχειρας γενέσθαι καὶ τιμωροὺς οἵτινες πρότερον μὲν κατὰ κράτος λαβόντες αὐτοὺς ἀθῴους ἀφῆκαν, τότε δὲ τὴν ἐκείνων ἐλευθερίαν καὶ σωτηρίαν ἐφύλαττον, πηλίκης ὀργῆς ἐστιν ἄξιον; τί δ’ ἂν παθόντες οὗτοι δίκην δόξαιεν ἁρμόζουσαν δεδωκέναι; τυχὸν ἴσως εἴποι τις ἄν, πραθέντες μετὰ τέκνων καὶ γυναικῶν, ἐπεὶ κατεπολεμήθησαν. ἀλλὰ τοῦτό γε καὶ τοῖς μηθὲν ἀσεβὲς ἐπιτελεσαμένοις κατὰ τοὺς τοῦ πολέμου νόμους ὑπόκειται παθεῖν. οὐκοῦν ὁλοσχερεστέρας τινὸς καὶ μείζονος τυχεῖν ἦσαν ἄξιοι τιμωρίας, ὥστ’ εἴπερ ἔπαθον ἃ Φύλαρχός φησιν, οὐκ ἔλεον εἰκὸς ἦν συνεξακολουθεῖν αὐτοῖς παρὰ τῶν Ἑλλήνων, ἔπαινον δὲ καὶ συγκατάθεσιν μᾶλλον τοῖς πράττουσι καὶ μεταπορευομένοις τὴν ἀσέβειαν αὐτῶν. ἀλλ’ ὅμως οὐδενὸς περαιτέρω συνεξακολουθήσαντος Μαντινεῦσι κατὰ τὴν περιπέτειαν πλὴν τοῦ διαρπαγῆναι τοὺς βίους καὶ πραθῆναι τοὺς ἐλευθέρους, ὁ συγγραφεὺς αὐτῆς τῆς τερατείας χάριν οὐ μόνον ψεῦδος εἰσήνεγκε τὸ ὅλον, ἀλλὰ καὶ τὸ ψεῦδος ἀπίθανον, καὶ διὰ τὴν ὑπερβολὴν τῆς ἀγνοίας οὐδὲ τὸ παρακείμενον ἠδυνήθη συνεπιστῆσαι, πῶς οἱ αὐτοὶ κατὰ τοὺς αὐτοὺς καιροὺς κυριεύσαντες Τεγεατῶν κατὰ κράτος οὐδὲν τῶν ὁμοίων ἔπραξαν. καίτοι γ’ εἰ μὲν ἡ τῶν πραττόντων ὠμότης ἦν αἰτία, καὶ τούτους εἰκὸς ἦν πεπονθέναι ταὐτὰ τοῖς ὑπὸ τὸν αὐτὸν ὑποπεπτωκόσι καιρόν. εἰ δὲ περὶ μόνους γέγονε Μαντινεῖς ἡ διαφορά, φανερὸν ὅτι καὶ τὴν αἰτίαν τῆς ὀργῆς ἀνάγκη διαφέρουσαν γεγονέναι περὶ τούτους.", "st": "2.58"}, {"sp": "N", "t": "πάλιν Ἀριστόμαχον τὸν Ἀργεῖόν φησιν, ἄνδρα τῆς ἐπιφανεστάτης οἰκίας ὑπάρχοντα καὶ τετυραννηκότα μὲν Ἀργείων, πεφυκότα δ’ ἐκ τυράννων, ὑποχείριον Ἀντιγόνῳ καὶ τοῖς Ἀχαιοῖς γενόμενον εἰς Κεγχρεὰς ἀπαχθῆναι καὶ στρεβλούμενον ἀποθανεῖν, ἀδικώτατα καὶ δεινότατα παθόντα πάντων ἀνθρώπων. τηρῶν δὲ καὶ περὶ ταύτην τὴν πρᾶξιν ὁ συγγραφεὺς τὸ καθ’ αὑτὸν ἰδίωμα φωνάς τινας πλάττει διὰ τῆς νυκτὸς αὐτοῦ στρεβλουμένου προσπιπτούσας τοῖς σύνεγγυς κατοικοῦσιν, ὧν τοὺς μὲν ἐκπληττομένους τὴν ἀσέβειαν, τοὺς δ’ ἀπιστοῦντας, τοὺς δ’ ἀγανακτοῦντας ἐπὶ τοῖς γινομένοις προστρέχειν πρὸς τὴν οἰκίαν φησίν. περὶ μὲν οὖν τῆς τοιαύτης τερατείας παρείσθω· δεδήλωται γὰρ ἀρκούντως. ἐγὼ δ’ Ἀριστόμαχον, εἰ καὶ μηδὲν εἰς τοὺς Ἀχαιοὺς ἕτερον ἥμαρτεν, κατά γε τὴν τοῦ βίου προαίρεσιν καὶ τὴν εἰς πατρίδα παρανομίαν τῆς μεγίστης ἄξιον κρίνω τιμωρίας. καίπερ ὁ συγγραφεὺς βουλόμενος αὔξειν αὐτοῦ τὴν δόξαν καὶ παραστήσασθαι τοὺς ἀκούοντας εἰς τὸ μᾶλλον αὐτῷ συναγανακτεῖν ἐφ’ οἷς ἔπαθεν οὐ μόνον αὐτόν φησι γεγονέναι τύραννον, ἀλλὰ καὶ ἐκ τυράννων πεφυκέναι. ταύτης δὲ μείζω κατηγορίαν ἢ πικροτέραν οὐδ’ ἂν εἰπεῖν ῥᾳδίως δύναιτ’ οὐδείς. αὐτὸ γὰρ τοὔνομα περιέχει τὴν ἀσεβεστάτην ἔμφασιν καὶ πάσας περιείληφε τὰς ἐν ἀνθρώποις ἀδικίας καὶ παρανομίας. Ἀριστόμαχος δ’ εἰ τὰς δεινοτάτας ὑπέμεινε τιμωρίας, ὡς οὗτός φησιν, ὅμως οὐχ ἱκανὴν ἔδωκεν δίκην μιᾶς ἡμέρας, ἐν ᾗ παρεισπεσόντος εἰς τὴν πόλιν Ἀράτου μετὰ τῶν Ἀχαιῶν καὶ μεγάλους ἀγῶνας καὶ κινδύνους ὑπομείναντος ὑπὲρ τῆς Ἀργείων ἐλευθερίας, τέλος δ’ ἐκπεσόντος διὰ τὸ μηδένα συγκινηθῆναι τῶν ἔσωθεν αὐτῷ ταξαμένων διὰ τὸν ἀπὸ τοῦ τυράννου φόβον, Ἀριστόμαχος ἀφορμῇ ταύτῃ καὶ προφάσει χρησάμενος, ὥς τινων συνειδότων τὰ περὶ τὴν εἴσοδον τῶν Ἀχαιῶν, ὀγδοήκοντα τοὺς πρώτους τῶν πολιτῶν οὐδὲν ἀδικήσαντας στρεβλώσας ἐναντίον τῶν ἀναγκαίων κατέσφαξεν. παρίημι τὰ παρ’ ὅλον τὸν βίον αὐτοῦ καὶ τῶν προγόνων ἀσεβήματα·", "st": "2.59"}, {"sp": "N", "t": "μακρὸν γάρ. διόπερ οὐκ εἴ τινι τῶν ὁμοίων περιέπεσε δεινὸν ἡγητέον, πολὺ δὲ δεινότερον, εἰ μηδενὸς τούτων πεῖραν λαβὼν ἀθῷος ἀπέθανεν. οὐδ’ Ἀντιγόνῳ προσαπτέον οὐδ’ Ἀράτῳ παρανομίαν, ὅτι λαβόντες κατὰ πόλεμον ὑποχείριον τύραννον στρεβλώσαντες ἀπέκτειναν, ὅν γε καὶ κατ’ αὐτὴν τὴν εἰρήνην τοῖς ἀνελοῦσι καὶ τιμωρησαμένοις ἔπαινος καὶ τιμὴ συνεξηκολούθει παρὰ τοῖς ὀρθῶς λογιζομένοις. ὅτε δὲ χωρὶς τῶν προειρημένων καὶ τοὺς Ἀχαιοὺς παρεσπόνδησεν, τί παθεῖν ἦν ἄξιος; ἐκεῖνος γὰρ ἀπέθετο μὲν τὴν τυραννίδα χρόνοις οὐ πολλοῖς πρότερον, ὑπὸ τῶν καιρῶν συγκλειόμενος διὰ τὸν Δημητρίου θάνατον, ἀνελπίστως δὲ τῆς ἀσφαλείας ἔτυχε περισταλεὶς ὑπὸ τῆς τῶν Ἀχαιῶν πρᾳότητος καὶ καλοκἀγαθίας· οἵτινες οὐ μόνον αὐτὸν τῶν ἐκ τῆς τυραννίδος ἀσεβημάτων ἀζήμιον ἐποίησαν, ἀλλὰ καὶ προσλαβόντες εἰς τὴν πολιτείαν τὴν μεγίστην τιμὴν περιέθεσαν, ἡγεμόνα καὶ στρατηγὸν καταστήσαντες σφῶν αὐτῶν. ὁ δ’ ἐπιλαθόμενος τῶν προειρημένων φιλανθρώπων παρὰ πόδας, ἐπεὶ μικρὸν ἐπικυδεστέρας ἔσχε τὰς ἐλπίδας ὑπὲρ τοῦ μέλλοντος ἐν Κλεομένει, τήν τε πατρίδα καὶ τὴν ἑαυτοῦ προαίρεσιν ἀποσπάσας ἀπὸ τῶν Ἀχαιῶν ἐν τοῖς ἀναγκαιοτάτοις καιροῖς προσένειμε τοῖς ἐχθροῖς. ὃν ὑποχείριον γενόμενον οὐκ ἐν Κεγχρεαῖς ἔδει τὴν νύκτα στρεβλούμενον ἀποθανεῖν, ὡς Φύλαρχός φησιν, περιαγόμενον δ’ εἰς τὴν Πελοπόννησον καὶ μετὰ τιμωρίας παραδειγματιζόμενον οὕτως ἐκλιπεῖν τὸ ζῆν. ἀλλ’ ὅμως τοιοῦτος ὢν οὐδενὸς ἔτυχε δεινοῦ πλὴν τοῦ καταποντισθῆναι διὰ τῶν ἐπὶ ταῖς Κεγχρεαῖς τεταγμένων.", "st": "2.60"}, {"sp": "N", "t": "χωρίς τε τούτων τὰς μὲν Μαντινέων ἡμῖν συμφορὰς μετ’ αὐξήσεως καὶ διαθέσεως ἐξηγήσατο, δῆλον ὅτι καθήκειν ὑπολαμβάνων τοῖς συγγραφεῦσι τὰς παρανόμους τῶν πράξεων ἐπισημαίνεσθαι, τῆς δὲ Μεγαλοπολιτῶν γενναιότητος, ᾗ περὶ τοὺς αὐτοὺς ἐχρήσαντο καιρούς, οὐδὲ κατὰ ποσὸν ἐποιήσατο μνήμην, ὥσπερ τὸ τὰς ἁμαρτίας ἐξαριθμεῖσθαι τῶν πραξάντων οἰκειότερον ὑπάρχον τῆς ἱστορίας τοῦ τὰ καλὰ καὶ δίκαια τῶν ἔργων ἐπισημαίνεσθαι, ἢ τοὺς ἐντυγχάνοντας τοῖς ὑπομνήμασιν ἧττόν τι διορθουμένους ὑπὸ τῶν σπουδαίων καὶ ζηλωτῶν ἔργων ἤπερ ὑπὸ τῶν παρανόμων καὶ φευκτῶν πράξεων. ὁ δὲ πῶς μὲν ἔλαβε Κλεομένης τὴν πόλιν καὶ πῶς ἀκέραιον διαφυλάξας ἐξαπέστειλε παραχρῆμα πρὸς τοὺς Μεγαλοπολίτας εἰς τὴν Μεσσήνην γραμματοφόρους, ἀξιῶν αὐτοὺς ἀβλαβῆ κομισαμένους τὴν ἑαυτῶν πατρίδα κοινωνῆσαι τῶν ἰδίων πραγμάτων, ταῦτα μὲν ἡμῖν ἐδήλωσε, βουλόμενος ὑποδεῖξαι τὴν Κλεομένους μεγαλοψυχίαν καὶ μετριότητα πρὸς τοὺς πολεμίους. ἔτι δὲ πῶς οἱ Μεγαλοπολῖται τῆς ἐπιστολῆς ἀναγινωσκομένης οὐκ ἐάσαιεν εἰς τέλος ἀναγνωσθῆναι, μικροῦ δὲ καταλεύσαιεν τοὺς γραμματοφόρους, ἕως τούτου διεσάφησε. τὸ δ’ ἀκόλουθον καὶ τὸ τῆς ἱστορίας ἴδιον ἀφεῖλεν, τὸν ἔπαινον καὶ τὴν ἐπ’ ἀγαθῷ μνήμην τῶν ἀξιολόγων προαιρέσεων. καίτοι γ’ ἐμποδὼν ἦν. εἰ γὰρ τοὺς λόγῳ καὶ δόγματι μόνον ὑπομείναντας πόλεμον ὑπὲρ φίλων καὶ συμμάχων ἄνδρας ἀγαθοὺς νομίζομεν, τοῖς δὲ καὶ χώρας καταφθορὰν καὶ πολιορκίαν ἀναδεξαμένοις οὐ μόνον ἔπαινον, ἀλλὰ καὶ χάριτας καὶ δωρεὰς τὰς μεγίστας ἀπονέμομεν, τίνα γε χρὴ περὶ Μεγαλοπολιτῶν ἔχειν διάληψιν; ἆρ’ οὐχὶ τὴν σεμνοτάτην καὶ βελτίστην; οἳ πρῶτον μὲν τὴν χώραν Κλεομένει προεῖντο, μετὰ δὲ ταῦτα πάλιν ὁλοσχερῶς ἔπταισαν τῇ πατρίδι διὰ τὴν πρὸς τοὺς Ἀχαιοὺς αἵρεσιν, τὸ δὲ τελευταῖον, δοθείσης ἀνελπίστως καὶ παραδόξως αὐτοῖς ἐξουσίας ἀβλαβῆ ταύτην ἀπολαβεῖν, προείλαντο στέρεσθαι χώρας, τάφων, ἱερῶν, πατρίδος, τῶν ὑπαρχόντων, ἁπάντων συλλήβδην τῶν ἐν ἀνθρώποις ἀναγκαιοτάτων χάριν τοῦ μὴ προδοῦναι τὴν πρὸς τοὺς συμμάχους πίστιν. οὗ τί κάλλιον ἔργον ἢ γέγονεν ἢ γένοιτ’ ἄν; ἐπὶ τί δ’ ἂν μᾶλλον συγγραφεὺς ἐπιστήσαι τοὺς ἀκούοντας; διὰ τίνος δ’ ἔργου μᾶλλον ἂν παρορμήσαι πρὸς φυλακὴν πίστεως καὶ πρὸς ἀληθινῶν πραγμάτων καὶ βεβαίων κοινωνίαν; ὧν οὐδεμίαν ἐποιήσατο μνήμην Φύλαρχος, τυφλώττων, ὥς γ’ ἐμοὶ δοκεῖ, περὶ τὰ κάλλιστα καὶ μάλιστα συγγραφεῖ καθήκοντα τῶν ἔργων.", "st": "2.61"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τούτοις ἑξῆς φησιν ἀπὸ τῶν ἐκ τῆς Μεγάλης πόλεως λαφύρων ἑξακισχίλια τάλαντα τοῖς Λακεδαιμονίοις πεσεῖν, ὧν τὰ δισχίλια Κλεομένει δοθῆναι κατὰ τοὺς ἐθισμούς. ἐν δὲ τούτοις πρῶτον μὲν τίς οὐκ ἂν θαυμάσειεν τὴν ἀπειρίαν καὶ τὴν ἄγνοιαν τῆς κοινῆς ἐννοίας ὑπὲρ τῆς τῶν Ἑλληνικῶν πραγμάτων χορηγίας καὶ δυνάμεως; ἣν μάλιστα δεῖ παρὰ τοῖς ἱστοριογράφοις ὑπάρχειν. ἐγὼ γὰρ οὐ λέγω κατ’ ἐκείνους τοὺς χρόνους, ἐν οἷς ὑπό τε τῶν ἐν Μακεδονίᾳ βασιλέων, ἔτι δὲ μᾶλλον ὑπὸ τῆς συνεχείας τῶν πρὸς ἀλλήλους πολέμων ἄρδην κατέφθαρτο τὰ Πελοποννησίων, ἀλλ’ ἐν τοῖς καθ’ ἡμᾶς καιροῖς, ἐν οἷς πάντες ἓν καὶ ταὐτὸ λέγοντες μεγίστην καρποῦσθαι δοκοῦσιν εὐδαιμονίαν, ὅμως ἐκ Πελοποννήσου πάσης ἐξ αὐτῶν τῶν ἐπίπλων χωρὶς σωμάτων οὐχ οἷόν τε συναχθῆναι τοσοῦτο πλῆθος χρημάτων. καὶ διότι τοῦτο νῦν οὐκ εἰκῇ, λόγῳ δέ τινι μᾶλλον ἀποφαινόμεθα, δῆλον ἐκ τούτων. τίς γὰρ ὑπὲρ Ἀθηναίων οὐχ ἱστόρηκε διότι καθ’ οὓς καιροὺς μετὰ Θηβαίων εἰς τὸν πρὸς Λακεδαιμονίους ἐνέβαινον πόλεμον καὶ μυρίους μὲν ἐξέπεμπον στρατιώτας, ἑκατὸν δ’ ἐπλήρουν τριήρεις, ὅτι τότε κρίναντες ἀπὸ τῆς ἀξίας ποιεῖσθαι τὰς εἰς τὸν πόλεμον εἰσφορὰς ἐτιμήσαντο τήν τε χώραν τὴν Ἀττικὴν ἅπασαν καὶ τὰς οἰκίας, ὁμοίως δὲ καὶ τὴν λοιπὴν οὐσίαν· ἀλλ’ ὅμως τὸ σύμπαν τίμημα τῆς ἀξίας ἐνέλιπε τῶν ἑξακισχιλίων διακοσίοις καὶ πεντήκοντα ταλάντοις. ἐξ ὧν οὐκ ἀπεοικὸς ἂν φανείη τὸ περὶ Πελοποννησίων ἄρτι ῥηθὲν ὑπ’ ἐμοῦ. κατὰ δ’ ἐκείνους τοὺς καιροὺς ἐξ αὐτῆς τῆς Μεγάλης πόλεως ὑπερβολικῶς ἀποφαινόμενος οὐκ ἄν τις εἰπεῖν τολμήσειεν πλείω γενέσθαι τριακοσίων, ἐπειδήπερ ὁμολογούμενόν ἐστι διότι καὶ τῶν ἐλευθέρων καὶ τῶν δουλικῶν σωμάτων τὰ πλεῖστα συνέβη διαφυγεῖν εἰς τὴν Μεσσήνην. μέγιστον δὲ τῶν προειρημένων τεκμήριον· οὐδενὸς γὰρ ὄντες δεύτεροι τῶν Ἀρκάδων Μαντινεῖς οὔτε κατὰ τὴν δύναμιν οὔτε κατὰ τὴν περιουσίαν, ὡς αὐτὸς οὗτός φησιν, ἐκ πολιορκίας δὲ καὶ παραδόσεως ἁλόντες, ὥστε μήτε διαφυγεῖν μηδένα μήτε διακλαπῆναι ῥᾳδίως μηδέν, ὅμως τὸ πᾶν λάφυρον ἐποίησαν μετὰ τῶν σωμάτων κατὰ τοὺς αὐτοὺς καιροὺς τάλαντα τριακόσια.", "st": "2.62"}, {"sp": "N", "t": "τὸ δὲ συνεχὲς τούτῳ τίς οὐκ ἂν ἔτι μᾶλλον θαυμάσειε; ταῦτα γὰρ ἀποφαινόμενος λέγει πρὸ τῆς παρατάξεως δέχ’ ἡμέραις μάλιστα τὸν παρὰ Πτολεμαίου πρεσβευτὴν ἐλθεῖν ἀγγέλλοντα πρὸς τὸν Κλεομένη διότι Πτολεμαῖος τὸ μὲν χορηγεῖν ἀπολέγει, διαλύεσθαι δὲ παρακαλεῖ πρὸς τὸν Ἀντίγονον. τὸν δ’ ἀκούσαντά φησι κρῖναι διότι δεῖ τὴν ταχίστην ἐκκυβεύειν τοῖς ὅλοις πρὸ τοῦ συνεῖναι τὰ προσπεπτωκότα τὰς δυνάμεις, διὰ τὸ μηδεμίαν ὑπάρχειν ἐν τοῖς ἰδίοις πράγμασιν ἐλπίδα τοῦ δύνασθαι μισθοδοτεῖν. ἀλλ’ εἴπερ ἑξακισχιλίων ἐγκρατὴς ἐγεγόνει ταλάντων κατὰ τοὺς αὐτοὺς καιρούς, τὸν Πτολεμαῖον αὐτὸν ἠδύνατο ταῖς χορηγίαις ὑπερθέσθαι. πρὸς δὲ τὸν Ἀντίγονον, εἰ μόνον τριακοσίων ὑπῆρχε κύριος, καὶ λίαν ἱκανὸς ἦν ἀσφαλῶς ὑπομένων τρίβειν τὸν πόλεμον. τὸ δ’ ἅμα μὲν πάσας ἀποφαίνειν τῷ Κλεομένει τὰς ἐλπίδας ἐν Πτολεμαίῳ διὰ τὰς χορηγίας, ἅμα δὲ τοσούτων χρημάτων αὐτὸν φάναι κύριον γεγονέναι κατὰ τοὺς αὐτοὺς καιρούς, πῶς οὐ τῆς μεγίστης ἀλογίας, ἔτι δ’ ἀσκεψίας ἐστὶ σημεῖον; πολλὰ δὲ καὶ ἕτερα τῷ συγγραφεῖ τοιαῦτα καὶ κατὰ τοὺς ὑποκειμένους καιροὺς καὶ παρ’ ὅλην τὴν πραγματείαν κατατέτακται, περὶ ὧν ἀρκεῖν ὑπολαμβάνω κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν καὶ τὰ νῦν εἰρημένα.", "st": "2.63"}, {"sp": "N", "t": "μετὰ δὲ τὴν τῆς Μεγάλης πόλεως ἅλωσιν Ἀντιγόνου παραχειμάζοντος ἐν τῇ τῶν Ἀργείων πόλει, συναγαγὼν Κλεομένης ἅμα τῷ τὴν ἐαρινὴν ὥραν ἐνίστασθαι καὶ παρακαλέσας τὰ πρέποντα τοῖς καιροῖς, ἐξαγαγὼν τὴν στρατιὰν ἐνέβαλεν εἰς τὴν τῶν Ἀργείων χώραν, ὡς μὲν τοῖς πολλοῖς ἐδόκει, παραβόλως καὶ τολμηρῶς διὰ τὴν ὀχυρότητα τῶν κατὰ τὰς εἰσόδους τόπων, ὡς δὲ τοῖς ὀρθῶς λογιζομένοις, ἀσφαλῶς καὶ νουνεχῶς. ὁρῶν γὰρ τὸν Ἀντίγονον διαφεικότα τὰς δυνάμεις, ᾔδει σαφῶς ὡς πρῶτον μὲν τὴν εἰσβολὴν ἀκινδύνως ποιήσεται, δεύτερον ἔτι τῆς χώρας καταφθειρομένης ἕως τῶν τειχῶν ἀνάγκη τοὺς Ἀργείους θεωροῦντας τὸ γινόμενον ἀσχάλλειν καὶ καταμέμφεσθαι τὸν Ἀντίγονον. εἰ μὲν οὖν συμβαίη μὴ δυνάμενον αὐτὸν ὑποφέρειν τὸν ἐπιρραπισμὸν τῶν ὄχλων ἐξελθεῖν καὶ διακινδυνεῦσαι τοῖς παροῦσιν, πρόδηλον ἐκ τῶν κατὰ λόγον ἦν αὐτῷ διότι νικήσει ῥᾳδίως. εἰ δ’ ἐμμείνας τοῖς λογισμοῖς ἀφησυχάζοι, καταπληξάμενος τοὺς ὑπεναντίους καὶ ταῖς ἰδίαις δυνάμεσι θάρσος ἐνεργασάμενος ἀσφαλῶς ὑπέλαβε ποιήσασθαι τὴν ἀναχώρησιν εἰς τὴν οἰκείαν. ὃ καὶ συνέβη γενέσθαι. τῆς γὰρ χώρας δῃουμένης οἱ μὲν ὄχλοι συστρεφόμενοι τὸν Ἀντίγονον ἐλοιδόρουν. ὁ δὲ καὶ λίαν ἡγεμονικῶς καὶ βασιλικῶς οὐδὲν περὶ πλείονος ποιούμενος τοῦ κατὰ λόγον χρήσασθαι τοῖς πράγμασιν ἦγε τὴν ἡσυχίαν. ὁ δὲ Κλεομένης κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν καταφθείρας μὲν τὴν χώραν, καταπληξάμενος δὲ τοὺς ὑπεναντίους, εὐθαρσεῖς δὲ πεποιηκὼς τὰς ἑαυτοῦ δυνάμεις πρὸς τὸν ἐπιφερόμενον κίνδυνον ἀσφαλῶς εἰς τὴν οἰκείαν ἐπανῆλθεν.", "st": "2.64"}, {"sp": "N", "t": "τοῦ δὲ θέρους ἐνισταμένου, καὶ συνελθόντων τῶν Μακεδόνων καὶ τῶν Ἀχαιῶν ἐκ τῆς χειμασίας, ἀναλαβὼν τὴν στρατιὰν Ἀντίγονος προῆγε μετὰ τῶν συμμάχων εἰς τὴν Λακωνικήν, ἔχων Μακεδόνας μὲν τοὺς εἰς τὴν φάλαγγα μυρίους, πελταστὰς δὲ τρισχιλίους, ἱππεῖς δὲ τριακοσίους, Ἀγριᾶνας δὲ σὺν τούτοις χιλίους καὶ Γαλάτας ἄλλους τοσούτους, μισθοφόρους δὲ τοὺς πάντας πεζοὺς μὲν τρισχιλίους, ἱππεῖς δὲ τριακοσίους, Ἀχαιῶν δ’ ἐπιλέκτους πεζοὺς μὲν τρισχιλίους, ἱππεῖς δὲ τριακοσίους, καὶ Μεγαλοπολίτας χιλίους εἰς τὸν Μακεδονικὸν τρόπον καθωπλισμένους, ὧν ἡγεῖτο Κερκιδᾶς Μεγαλοπολίτης, τῶν δὲ συμμάχων Βοιωτῶν μὲν πεζοὺς δισχιλίους, ἱππεῖς δὲ διακοσίους, Ἠπειρωτῶν πεζοὺς χιλίους, ἱππεῖς πεντήκοντα, Ἀκαρνάνων ἄλλους τοσούτους, Ἰλλυριῶν χιλίους ἑξακοσίους, ἐφ’ ὧν ἦν Δημήτριος ὁ Φάριος, ὥστ’ εἶναι πᾶσαν τὴν δύναμιν πεζοὺς μὲν εἰς δισμυρίους ὀκτακισχιλίους, ἱππεῖς δὲ χιλίους καὶ διακοσίους. ὁ δὲ Κλεομένης προσδοκῶν τὴν ἔφοδον τὰς μὲν ἄλλας τὰς εἰς τὴν χώραν εἰσβολὰς ἠσφαλίσατο φυλακαῖς καὶ τάφροις καὶ δένδρων ἐκκοπαῖς, αὐτὸς δὲ κατὰ τὴν Σελλασίαν καλουμένην μετὰ τῆς δυνάμεως ἐστρατοπέδευε, τῆς πάσης ὑπαρχούσης αὐτῷ στρατιᾶς εἰς δύο μυριάδας, στοχαζόμενος ἐκ τῶν κατὰ λόγον ταύτῃ ποιήσασθαι τοὺς ὑπεναντίους τὴν εἰσβολήν· ὃ καὶ συνεκύρησε. δύο δὲ λόφων ἐπ’ αὐτῆς τῆς εἰσόδου κειμένων, ὧν τὸν μὲν Εὔαν, τὸν δ’ ἕτερον Ὄλυμπον καλεῖσθαι συμβαίνει, τῆς δ’ ὁδοῦ μεταξὺ τούτων παρὰ τὸν Οἰνοῦντα ποταμὸν φερούσης εἰς τὴν Σπάρτην, ὁ μὲν Κλεομένης τῶν προειρημένων λόφων συνάμφω τάφρον καὶ χάρακα προβαλόμενος ἐπὶ μὲν τὸν Εὔαν ἔταξε τοὺς περιοίκους καὶ συμμάχους, ἐφ’ ὧν ἐπέστησε τὸν ἀδελφὸν Εὐκλείδαν, αὐτὸς δὲ τὸν Ὄλυμπον κατεῖχε μετὰ Λακεδαιμονίων καὶ τῶν μισθοφόρων. ἐν δὲ τοῖς ἐπιπέδοις παρὰ τὸν ποταμὸν ἐφ’ ἑκάτερα τῆς ὁδοῦ τοὺς ἱππεῖς μετὰ μέρους τινὸς τῶν μισθοφόρων παρενέβαλεν. Ἀντίγονος δὲ παραγενόμενος καὶ συνθεωρήσας τήν τε τῶν τόπων ὀχυρότητα καὶ τὸν Κλεομένη πᾶσι τοῖς οἰκείοις μέρεσι τῆς δυνάμεως οὕτως εὐστόχως προκατειληφότα τὰς εὐκαιρίας ὥστε παραπλήσιον εἶναι τὸ σύμπαν σχῆμα τῆς στρατοπεδείας τῆς τῶν ἀγαθῶν ὁπλομάχων προβολῆς· οὐδὲν γὰρ ἀπέλειπε τῶν πρὸς ἐπίθεσιν ἅμα καὶ φυλακήν, ἀλλ’ ἦν ὁμοῦ παράταξις ἐνεργὸς καὶ παρεμβολὴ δυσπρόσοδος· διὸ καὶ τὸ μὲν ἐξ ἐφόδου καταπειράζειν καὶ συμπλέκεσθαι", "st": "2.65"}, {"sp": "N", "t": "προχείρως ἀπέγνω, στρατοπεδεύσας δ’ ἐν βραχεῖ διαστήματι καὶ λαβὼν πρόβλημα τὸν Γοργύλον καλούμενον ποταμόν, τινὰς μὲν ἡμέρας ἐπιμένων συνεθεώρει τάς τε τῶν τόπων ἰδιότητας καὶ τὰς τῶν δυνάμεων διαφοράς, ἅμα δὲ καὶ προδεικνύων τινὰς ἐπιβολὰς πρὸς τὸ μέλλον ἐξεκαλεῖτο τὰς τῶν ὑπεναντίων ἐπινοίας. οὐ δυνάμενος δὲ λαβεῖν οὐδὲν ἀργὸν οὐδ’ ἔξοπλον διὰ τὸ πρὸς πᾶν ἑτοίμως ἀντικινεῖσθαι τὸν Κλεομένη, τῆς μὲν τοιαύτης ἐπινοίας ἀπέστη, τέλος δ’ ἐξ ὁμολόγου διὰ μάχης ἀμφότεροι προέθεντο κρίνειν τὰς πράξεις· πάνυ γὰρ εὐφυεῖς καὶ παραπλησίους ἡγεμόνας ἡ τύχη συνέβαλε τούτους τοὺς ἄνδρας. πρὸς μὲν οὖν τοὺς κατὰ τὸν Εὔαν ὁ βασιλεὺς ἀντέταξε τῶν τε Μακεδόνων τοὺς χαλκάσπιδας καὶ τοὺς Ἰλλυριούς, κατὰ σπείρας ἐναλλὰξ τεταγμένους, Ἀλέξανδρον τὸν Ἀκμήτου καὶ Δημήτριον τὸν Φάριον ἐπιστήσας. ἐπὶ δὲ τούτοις τοὺς Ἀκαρνᾶνας καὶ Ἠπειρώτας ἐπέβαλε· τούτων δὲ κατόπιν ἦσαν δισχίλιοι τῶν Ἀχαιῶν, ἐφεδρείας λαμβάνοντες τάξιν. τοὺς δ’ ἱππεῖς περὶ τὸν Οἰνοῦντα ποταμὸν ἀντέθηκε τῷ τῶν πολεμίων ἱππικῷ, συστήσας αὐτοῖς Ἀλέξανδρον ἡγεμόνα καὶ συμπαραθεὶς πεζοὺς τῶν Ἀχαϊκῶν χιλίους καὶ Μεγαλοπολίτας τοὺς ἴσους. αὐτὸς δὲ τοὺς μισθοφόρους ἔχων καὶ τοὺς Μακεδόνας κατὰ τὸν Ὄλυμπον πρὸς τοὺς περὶ τὸν Κλεομένη διέγνω ποιεῖσθαι τὴν μάχην. προτάξας οὖν τοὺς μισθοφόρους ἐπέστησε διφαλαγγίαν ἐπάλληλον τῶν Μακεδόνων· ἐποίει δὲ τοῦτο διὰ τὴν στενότητα τῶν τόπων. σύνθημα δ’ ἦν τοῖς μὲν Ἰλλυριοῖς τότε ποιεῖσθαι τὴν ἀρχὴν τῆς πρὸς τὸν λόφον προσβολῆς, ὅταν ἴδωσιν ἀρθεῖσαν ἀπὸ τῶν κατὰ τὸν Ὄλυμπον τόπων σινδόνα — προσηρτημένοι γὰρ ἦσαν οὗτοι νυκτὸς ἐν τῷ Γοργύλῳ ποταμῷ πρὸς αὐτῇ τῇ τοῦ λόφου ῥίζῃ — τοῖς δὲ Μεγαλοπολίταις καὶ τοῖς ἱππεῦσι παραπλησίως, ἐπειδὰν φοινικὶς ἐξαρθῇ παρὰ τοῦ βασιλέως.", "st": "2.66"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὁ μὲν καιρὸς ἧκε τῆς χρείας, τὸ δὲ σύνθημα τοῖς Ἰλλυριοῖς ἀπεδόθη, παρήγγειλαν δὲ ποιεῖν τὸ δέον οἷς ἦν ἐπιμελές, πάντες εὐθέως ἀναδείξαντες αὑτοὺς κατήρχοντο τῆς πρὸς τὸν βουνὸν προσβολῆς. οἱ δὲ μετὰ τῶν Κλεομένους ἱππέων ἐξ ἀρχῆς ταχθέντες εὔζωνοι, θεωροῦντες τὰς σπείρας τῶν Ἀχαιῶν ἐρήμους ἐκ τῶν κατόπιν οὔσας, κατ’ οὐρὰν προσπίπτοντες εἰς ὁλοσχερῆ κίνδυνον ἦγον τοὺς πρὸς τὸν λόφον βιαζομένους, ὡς ἂν τῶν μὲν περὶ τὸν Εὐκλείδαν ἐξ ὑπερδεξίου κατὰ πρόσωπον αὐτοῖς ἐφεστώτων, τῶν δὲ μισθοφόρων κατόπιν ἐπικειμένων καὶ προσφερόντων τὰς χεῖρας ἐρρωμένως. ἐν ᾧ καιρῷ συννοήσας τὸ γινόμενον, ἅμα δὲ προορώμενος τὸ μέλλον Φιλοποίμην ὁ Μεγαλοπολίτης τὸ μὲν πρῶτον ὑποδεικνύειν ἐπεβάλλετο τοῖς προεστῶσι τὸ συμβησόμενον· οὐδενὸς δὲ προσέχοντος αὐτῷ διὰ τὸ μήτ’ ἐφ’ ἡγεμονίας τετάχθαι μηδεπώποτε κομιδῇ τε νέον ὑπάρχειν αὐτόν, παρακαλέσας τοὺς ἑαυτοῦ πολίτας ἐνέβαλε τοῖς πολεμίοις τολμηρῶς. οὗ γενομένου ταχέως οἱ προσκείμενοι μισθοφόροι κατ’ οὐρὰν τοῖς προσβαίνουσιν, ἀκούσαντες τῆς κραυγῆς καὶ συνιδόντες τὴν τῶν ἱππέων συμπλοκήν, ἀφέμενοι τῶν προκειμένων ἀνέτρεχον εἰς τὰς ἐξ ἀρχῆς τάξεις καὶ προσεβοήθουν τοῖς παρ’ αὑτῶν ἱππεῦσι. τούτου δὲ συμβάντος ἀπερίσπαστον γενόμενον τό τε τῶν Ἰλλυριῶν καὶ Μακεδόνων καὶ τῶν ἅμα τούτοις προσβαινόντων πλῆθος ἐκθύμως ὥρμησε καὶ τεθαρρηκότως ἐπὶ τοὺς ὑπεναντίους. ἐξ οὗ καὶ μετὰ ταῦτα φανερὸν ἐγενήθη διότι τοῦ κατὰ τὸν Εὐκλείδαν προτερήματος αἴτιος ἐγίνετο Φιλοποίμην.", "st": "2.67"}, {"sp": "N", "t": "ὅθεν καὶ τὸν Ἀντίγονόν φασι μετὰ ταῦτα καταπειράζοντα πυνθάνεσθαι τοῦ ταχθέντος ἐπὶ τῶν ἱππέων Ἀλεξάνδρου διὰ τί πρὸ τοῦ παραδοθῆναι τὸ σύνθημα τοῦ κινδύνου κατάρξαιτο. τοῦ δ’ ἀρνουμένου, φάσκοντος δὲ μειράκιόν τι Μεγαλοπολιτικὸν προεγχειρῆσαι παρὰ τὴν ἑαυτοῦ γνώμην, εἰπεῖν διότι τὸ μὲν μειράκιον ἡγεμόνος ἔργον ἀγαθοῦ ποιήσαι, συνθεασάμενον τὸν καιρόν, ἐκεῖνος δ’ ἡγεμὼν ὑπάρχων μειρακίου τοῦ τυχόντος. οὐ μὴν ἀλλ’ οἵ γε περὶ τὸν Εὐκλείδαν ὁρῶντες προσβαινούσας τὰς σπείρας, ἀφέμενοι τοῦ χρῆσθαι ταῖς τῶν τόπων εὐκαιρίαις — τοῦτο δ’ ἦν ἐκ πολλοῦ συναντῶντας καὶ προσπίπτοντας τοῖς πολεμίοις τὰ μὲν ἐκείνων στίφη συνταράττειν καὶ διαλύειν, αὐτοὺς δ’ ὑποχωρεῖν ἐπὶ πόδα καὶ μεθίστασθαι πρὸς τοὺς ὑπερδεξίους ἀεὶ τόπους ἀσφαλῶς· οὕτω γὰρ ἂν προλυμηνάμενοι καὶ συγχέαντες τὸ τοῦ καθοπλισμοῦ καὶ τῆς συντάξεως ἰδίωμα τῶν ὑπεναντίων ῥᾳδίως αὐτοὺς ἐτρέψαντο διὰ τὴν τῶν τόπων εὐφυΐαν — τούτων μὲν οὐδὲν ἐποίησαν, καθάπερ δ’ ἐξ ἑτοίμου σφίσι τῆς νίκης ὑπαρχούσης τοὐναντίον ἔπραξαν. κατὰ γὰρ τὴν ἐξ ἀρχῆς στάσιν ἔμενον ἐπὶ τῶν ἄκρων, ὡς ἀνωτάτω σπεύδοντες λαβεῖν τοὺς ὑπεναντίους εἰς τὸ τὴν φυγὴν ἐπὶ πολὺ καταφερῆ καὶ κρημνώδη γενέσθαι τοῖς πολεμίοις. συνέβη δ’, ὅπερ εἰκὸς ἦν, τοὐναντίον· οὐ γὰρ ἀπολιπόντες αὑτοῖς ἀναχώρησιν, προσδεξάμενοι δ’ ἀκεραίους ἅμα καὶ συνεστώσας τὰς σπείρας, εἰς τοῦτο δυσχρηστίας ἦλθον ὥστε δι’ αὐτῆς τῆς τοῦ λόφου κορυφῆς διαμάχεσθαι πρὸς τοὺς βιαζομένους. λοιπὸν ὅσον ἐκ ποδὸς ἐπιέσθησαν τῷ βάρει τοῦ καθοπλισμοῦ καὶ τῆς συντάξεως, εὐθέως οἱ μὲν Ἰλλυριοὶ τὴν κατάστασιν ἐλάμβανον, οἱ δὲ περὶ τὸν Εὐκλείδαν τὴν ὑπὸ πόδα διὰ τὸ μὴ καταλείπεσθαι τόπον εἰς ἀναχώρησιν καὶ μετάστασιν ἑαυτοῖς. ἐξ οὗ ταχέως συνέβη τραπέντας αὐτοὺς ὀλεθρίῳ χρήσασθαι φυγῇ, κρημνώδη καὶ δύσβατον ἐχόντων ἐπὶ πολὺ τὴν ἀναχώρησιν τῶν τόπων.", "st": "2.68"}, {"sp": "N", "t": "ἅμα δὲ τούτοις ὁ περὶ τοὺς ἱππεῖς συνετελεῖτο κίνδυνος, ἐκπρεπῆ ποιουμένων τὴν χρείαν τῶν Ἀχαϊκῶν ἱππέων ἁπάντων, μάλιστα δὲ Φιλοποίμενος, διὰ τὸ περὶ τῆς αὐτῶν ἐλευθερίας συνεστάναι τὸν ὅλον ἀγῶνα. καθ’ ὃν καιρὸν τῷ προειρημένῳ συνέβη τὸν μὲν ἵππον πεσεῖν πληγέντα καιρίως, αὐτὸν δὲ πεζομαχοῦντα περιπεσεῖν τραύματι βιαίῳ δι’ ἀμφοῖν τοῖν μηροῖν. οἱ δὲ βασιλεῖς κατὰ τὸν Ὄλυμπον τὸ μὲν πρῶτον ἐποιοῦντο διὰ τῶν εὐζώνων καὶ μισθοφόρων τὴν συμπλοκήν, παρ’ ἑκατέροις σχεδὸν ὑπαρχόντων τούτων εἰς πεντακισχιλίους. ὧν ποτὲ μὲν κατὰ μέρη, ποτὲ δ’ ὁλοσχερῶς συμπιπτόντων, διαφέρουσαν συνέβαινε γίνεσθαι τὴν ἐξ ἀμφοῖν χρείαν, ὁμοῦ τῶν τε βασιλέων καὶ τῶν στρατοπέδων ἐν συνόψει ποιουμένων τὴν μάχην. ἡμιλλῶντο δὲ πρὸς ἑαυτοὺς καὶ κατ’ ἄνδρα καὶ κατὰ τάγμα ταῖς εὐψυχίαις. ὁ δὲ Κλεομένης ὁρῶν τοὺς μὲν περὶ τὸν ἀδελφὸν πεφευγότας, τοὺς δ’ ἐν τοῖς ἐπιπέδοις ἱππεῖς ὅσον οὔπω κλίνοντας, καταπλαγὴς ὢν μὴ πανταχόθεν προσδέξηται τοὺς πολεμίους, ἠναγκάζετο διασπᾶν τὰ προτειχίσματα καὶ πᾶσαν τὴν δύναμιν ἐξάγειν μετωπηδὸν κατὰ μίαν πλευρὰν τῆς στρατοπεδείας. ἀνακληθέντων δὲ τῶν παρ’ ἑκατέροις εὐζώνων ἐκ τοῦ μεταξὺ τόπου διὰ τῆς σάλπιγγος, συναλαλάξασαι καὶ καταβαλοῦσαι τὰς σαρίσας συνέβαλλον αἱ φάλαγγες ἀλλήλαις. ἀγῶνος δὲ γενομένου κραταιοῦ, καὶ ποτὲ μὲν ἐπὶ πόδα ποιουμένων τὴν ἀναχώρησιν καὶ πιεζομένων ἐπὶ πολὺ τῶν Μακεδόνων ὑπὸ τῆς τῶν Λακώνων εὐψυχίας, ποτὲ δὲ τῶν Λακεδαιμονίων ἐξωθουμένων ὑπὸ τοῦ βάρους τῆς τῶν Μακεδόνων τάξεως, τέλος οἱ περὶ τὸν Ἀντίγονον συμφράξαντες τὰς σαρίσας καὶ χρησάμενοι τῷ τῆς ἐπαλλήλου φάλαγγος ἰδιώματι, βίᾳ προσπεσόντες ἐξέωσαν ἐκ τῶν ὀχυρωμάτων τοὺς Λακεδαιμονίους. τὸ μὲν οὖν ἄλλο πλῆθος ἔφευγε προτροπάδην φονευόμενον· ὁ δὲ Κλεομένης ἱππεῖς τινας ἔχων περὶ ἑαυτὸν ἀπεχώρησε μετὰ τούτων ἀσφαλῶς εἰς τὴν Σπάρτην. ἐπιγενομένης δὲ τῆς νυκτὸς καταβὰς εἰς Γύθιον, ἡτοιμασμένων αὐτῷ τῶν πρὸς τὸν πλοῦν ἐκ πλείονος χρόνου πρὸς τὸ συμβαῖνον, ἀπῆρε μετὰ τῶν φίλων εἰς Ἀλεξάνδρειαν.", "st": "2.69"}, {"sp": "N", "t": "Ἀντίγονος δ’ ἐγκρατὴς γενόμενος ἐξ ἐφόδου τῆς Σπάρτης τά τε λοιπὰ μεγαλοψύχως καὶ φιλανθρώπως ἐχρήσατο τοῖς Λακεδαιμονίοις, τό τε πολίτευμα τὸ πάτριον αὐτοῖς ἀποκαταστήσας ἐν ὀλίγαις ἡμέραις ἀνέζευξε μετὰ τῶν δυνάμεων ἐκ τῆς πόλεως, προσαγγελθέντος αὐτῷ τοὺς Ἰλλυριοὺς εἰσβεβληκότας εἰς Μακεδονίαν πορθεῖν τὴν χώραν. οὕτως ἀεί ποθ’ ἡ τύχη τὰ μέγιστα τῶν πραγμάτων παρὰ λόγον εἴωθε κρίνειν. καὶ γὰρ τότε Κλεομένης, εἴτε τὰ κατὰ τὸν κίνδυνον παρείλκυσε τελέως ὀλίγας ἡμέρας, εἴτ’ ἀναχωρήσας ἀπὸ τῆς μάχης εἰς τὴν πόλιν ἐπὶ βραχὺ τῶν καιρῶν ἀντεποιήσατο, διακατέσχεν ἂν τὴν ἀρχήν. οὐ μὴν ἀλλ’ ὅ γ’ Ἀντίγονος παραγενόμενος εἰς Τεγέαν καὶ τούτοις ἀποδοὺς τὴν πάτριον πολιτείαν δευτεραῖος ἐντεῦθεν εἰς Ἄργος ἐπ’ αὐτὴν ἦλθε τὴν τῶν Νεμέων πανήγυριν. ἐν ᾗ τυχὼν πάντων τῶν πρὸς ἀθάνατον δόξαν καὶ τιμὴν ἀνηκόντων ὑπό τε τοῦ κοινοῦ τῶν Ἀχαιῶν καὶ κατ’ ἰδίαν ἑκάστης τῶν πόλεων ὥρμησε κατὰ σπουδὴν εἰς Μακεδονίαν. καταλαβὼν δὲ τοὺς Ἰλλυριοὺς ἐν τῇ χώρᾳ καὶ συμβαλὼν ἐκ παρατάξεως τῇ μὲν μάχῃ κατώρθωσε, τῇ δὲ παρακλήσει καὶ κραυγῇ τῇ κατ’ αὐτὸν τὸν κίνδυνον ἐκθύμως χρησάμενος εἰς αἵματος ἀναγωγὴν καί τινα τοιαύτην διάθεσιν ἐμπεσὼν μετ’ οὐ πολὺ νόσῳ τὸν βίον μετήλλαξε, καλὰς ἐλπίδας ὑποδείξας ἐν αὑτῷ πᾶσι τοῖς Ἕλλησιν, οὐ μόνον κατὰ τὴν ἐν τοῖς ὑπαίθροις χρείαν, ἔτι δὲ μᾶλλον κατὰ τὴν ὅλην αἵρεσιν καὶ καλοκἀγαθίαν. τὴν δὲ Μακεδόνων βασιλείαν ἀπέλιπε Φιλίππῳ τῷ Δημητρίου.", "st": "2.70"}, {"sp": "N", "t": "τίνος δὲ χάριν ἐποιησάμεθα τὴν ἐπὶ πλεῖον ὑπὲρ τοῦ προειρημένου πολέμου μνήμην; διότι τῶν καιρῶν τούτων συναπτόντων τοῖς ὑφ’ ὑμῶν ἱστορεῖσθαι μέλλουσι χρήσιμον ἐδόκει, μᾶλλον δ’ ἀναγκαῖον εἶναι κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν τὸ ποιῆσαι πᾶσιν ἐναργῆ καὶ γνώριμον τὴν ὑπάρχουσαν περὶ Μακεδόνας καὶ τοὺς Ἕλληνας τότε κατάστασιν. περὶ δὲ τοὺς αὐτοὺς καιροὺς καὶ Πτολεμαίου νόσῳ τὸν βίον μεταλλάξαντος Πτολεμαῖος ὁ κληθεὶς Φιλοπάτωρ διεδέξατο τὴν βασιλείαν. μετήλλαξε δὲ καὶ Σέλευκος ὁ Σελεύκου τοῦ Καλλινίκου καὶ Πώγωνος ἐπικληθέντος· Ἀντίοχος δὲ διεδέξατο τὴν ἐν Συρίᾳ βασιλείαν, ἀδελφὸς ὢν αὐτοῦ. παραπλήσιον γὰρ δή τι συνέβη τούτοις καὶ τοῖς πρώτοις μετὰ τὴν Ἀλεξάνδρου τελευτὴν κατασχοῦσι τὰς ἀρχὰς ταύτας, λέγω δὲ Σελεύκῳ, Πτολεμαίῳ, Λυσιμάχῳ. ἐκεῖνοί τε γὰρ πάντες περὶ τὴν εἰκοστὴν καὶ τετάρτην πρὸς ταῖς ἑκατὸν ὀλυμπιάδα μετήλλαξαν, καθάπερ ἐπάνω προεῖπον, οὗτοί τε περὶ τὴν ἐνάτην καὶ τριακοστήν. ἡμεῖς δ’ ἐπειδὴ τὴν ἐπίστασιν καὶ προκατασκευὴν τῆς ὅλης ἱστορίας διεληλύθαμεν, δι’ ἧς ὑποδέδεικται πότε καὶ πῶς καὶ δι’ ἃς αἰτίας τῶν κατὰ τὴν Ἰταλίαν κρατήσαντες Ῥωμαῖοι πρῶτον ἐγχειρεῖν ἤρξαντο τοῖς ἔξω πράγμασι καὶ πρῶτον ἐτόλμησαν ἀμφισβητεῖν Καρχηδονίοις τῆς θαλάττης, ἅμα δὲ τούτοις καὶ τὴν περὶ τοὺς Ἕλληνας καὶ Μακεδόνας, ὁμοίως δὲ καὶ περὶ Καρχηδονίους ὑπάρχουσαν τότε κατάστασιν δεδηλώκαμεν, καθῆκον ἂν εἴη παραγεγονότας ἐπὶ τοὺς καιροὺς τούτους κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν, ἐν οἷς ἔμελλον οἱ μὲν Ἕλληνες τὸν συμμαχικόν, Ῥωμαῖοι δὲ τὸν Ἀννιβιακόν, οἱ δὲ κατὰ τὴν Ἀσίαν βασιλεῖς τὸν περὶ Κοίλης Συρίας ἐνίστασθαι πόλεμον, καὶ τὴν βύβλον ταύτην ἀφορίζειν ἀκολούθως τῇ τε τῶν προγεγονότων πραγμάτων περιγραφῇ καὶ τῇ τῶν κεχειρικότων τὰ πρὸ τοῦ δυναστῶν καταστροφῇ.", "st": "2.71"}], []);})();
